// T_AXFER_VAR_BPP (SPEC-AXFER-BPP-AMENDMENT) — byte-for-byte mirror of
// T_AXFER_VAR (SPEC §5.7.9) except the opcode is 0x3D and the rangeproof
// is Bulletproofs+. The N=2 tightening, vout interleaving rule, and the
// mandatory OP_RETURN(80) recovery output are preserved verbatim — only
// the rangeproof bytes change. Indexers reject deviations from the §5.7.9
// tx layout identically.
function encodeAxferVarBppPayload({ assetId, kernelSig, outputs, rangeproof }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (!kernelSig || kernelSig.length !== 64) throw new Error('kernel_sig must be 64 bytes');
  if (outputs.length !== 2) throw new Error('T_AXFER_VAR_BPP outputs MUST be exactly 2 (recipient + maker change)');
  if (rangeproof.length > 0xffff) throw new Error('rangeproof too large');
  const parts = [
    new Uint8Array([T_AXFER_VAR_BPP]),
    assetId,
    new Uint8Array([1]),  // asset_input_count: exactly 1, mirrors §5.7.9
    kernelSig,
    new Uint8Array([2]),  // N: exactly 2, mirrors §5.7.9
  ];
  for (const o of outputs) {
    if (o.commitment.length !== 33) throw new Error('commitment 33 bytes');
    if (!o.encryptedAmount || o.encryptedAmount.length !== 8) throw new Error('encrypted_amount must be 8 bytes');
    parts.push(o.commitment, o.encryptedAmount);
  }
  const rpLen = new Uint8Array(2); new DataView(rpLen.buffer).setUint16(0, rangeproof.length, true);
  parts.push(rpLen, rangeproof);
  return concatBytes(...parts);
}

function decodeAxferVarBppPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_AXFER_VAR_BPP) return null;
  if (payload.length < 1 + 32 + 1 + 64 + 1 + 2 * (33 + 8) + 2) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const assetInputCount = payload[p]; p += 1;
  if (assetInputCount !== 1) return null;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const n = payload[p]; p += 1;
  if (n !== 2) return null;
  const outputs = [];
  for (let i = 0; i < n; i++) {
    if (p + 33 + 8 > payload.length) return null;
    const commitment = payload.slice(p, p + 33); p += 33;
    const encryptedAmount = payload.slice(p, p + 8); p += 8;
    outputs.push({ commitment, encryptedAmount });
  }
  if (p + 2 > payload.length) return null;
  const rpLen = payload[p] | (payload[p + 1] << 8); p += 2;
  if (p + rpLen !== payload.length) return null;
  const rangeproof = payload.slice(p, p + rpLen);
  return { kind: 'axfer_var_bpp', assetId, assetInputCount, kernelSig, outputs, rangeproof };
}

// T_PREAUTH_BID (SPEC §5.7.11) — buyer-offline preauth bid. Wire shape is
// T_AXFER with an extra 97-byte INLINE BID-CONTEXT section (bid_id +
// recipient_pubkey + amount_LE + blinding + price_sats_LE) between
// asset_input_count and kernel_sig. The inline section lets the validator
// recompute the OP_RETURN bid_context_hash chain-only, with no off-chain
// bid record ingestion. output[0] carries only the Pedersen commitment
// (no encryptedAmount — the amount is in cleartext above); seller's
// change output[1] (when present) keeps the standard self-keystream
// encryptedAmount per §5.7.6 self-blinding.
const PREAUTH_BID_INLINE_BYTES = 16 + 33 + 8 + 32 + 8;  // 97
function encodePreauthBidPayload({
  assetId, assetInputCount, bidId, recipientPubkey,
  amount, blinding, priceSats,
  kernelSig, outputs, rangeproof,
}) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (!Number.isInteger(assetInputCount) || assetInputCount < 1 || assetInputCount > 255) {
    throw new Error('asset_input_count must be integer in [1, 255]');
  }
  if (!bidId || bidId.length !== 16) throw new Error('bid_id 16 bytes');
  if (!recipientPubkey || recipientPubkey.length !== 33) throw new Error('recipient_pubkey 33 bytes');
  if (!blinding || blinding.length !== 32) throw new Error('blinding 32 bytes');
  if (!kernelSig || kernelSig.length !== 64) throw new Error('kernel_sig must be 64 bytes');
  if (![1, 2].includes(outputs.length)) throw new Error('T_PREAUTH_BID outputs must be 1 (exact-fill) or 2 (seller change)');
  if (rangeproof.length > 0xffff) throw new Error('rangeproof too large');
  const amountLE = new Uint8Array(8); new DataView(amountLE.buffer).setBigUint64(0, BigInt(amount), true);
  const priceLE = new Uint8Array(8); new DataView(priceLE.buffer).setBigUint64(0, BigInt(priceSats), true);
  const parts = [
    new Uint8Array([T_PREAUTH_BID]),
    assetId,
    new Uint8Array([assetInputCount]),
    bidId, recipientPubkey, amountLE, blinding, priceLE,   // inline bid-context
    kernelSig,
    new Uint8Array([outputs.length]),
  ];
  // output[0] is buyer's recipient: commitment only (amount is in cleartext above).
  if (outputs[0].commitment.length !== 33) throw new Error('output[0].commitment 33 bytes');
  parts.push(outputs[0].commitment);
  // output[1] (optional) is seller's change: commitment + self-keystream encryptedAmount.
  if (outputs.length === 2) {
    if (outputs[1].commitment.length !== 33) throw new Error('output[1].commitment 33 bytes');
    if (!outputs[1].encryptedAmount || outputs[1].encryptedAmount.length !== 8) {
      throw new Error('output[1].encrypted_amount must be 8 bytes');
    }
    parts.push(outputs[1].commitment, outputs[1].encryptedAmount);
  }
  const rpLen = new Uint8Array(2); new DataView(rpLen.buffer).setUint16(0, rangeproof.length, true);
  parts.push(rpLen, rangeproof);
  return concatBytes(...parts);
}

function decodePreauthBidPayload(payload) {
  if (!payload) return null;
  // Min size (N=1): opcode(1) + asset_id(32) + asset_input_count(1) + inline(97) +
  // kernel_sig(64) + N(1) + output[0].commitment(33) + rp_len(2) = 231 bytes.
  const MIN = 1 + 32 + 1 + PREAUTH_BID_INLINE_BYTES + 64 + 1 + 33 + 2;
  if (payload.length < MIN) return null;
  if (payload[0] !== T_PREAUTH_BID) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const assetInputCount = payload[p]; p += 1;
  if (assetInputCount < 1) return null;
  const bidId = payload.slice(p, p + 16); p += 16;
  const recipientPubkey = payload.slice(p, p + 33); p += 33;
  const amountLE = payload.slice(p, p + 8); p += 8;
  const amount = new DataView(amountLE.buffer, amountLE.byteOffset, 8).getBigUint64(0, true);
  const blinding = payload.slice(p, p + 32); p += 32;
  const priceLE = payload.slice(p, p + 8); p += 8;
  const priceSats = new DataView(priceLE.buffer, priceLE.byteOffset, 8).getBigUint64(0, true);
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const n = payload[p]; p += 1;
  if (n !== 1 && n !== 2) return null;
  const outputs = [];
  if (p + 33 > payload.length) return null;
  outputs.push({ commitment: payload.slice(p, p + 33) }); p += 33;
  if (n === 2) {
    if (p + 33 + 8 > payload.length) return null;
    const commitment = payload.slice(p, p + 33); p += 33;
    const encryptedAmount = payload.slice(p, p + 8); p += 8;
    outputs.push({ commitment, encryptedAmount });
  }
  if (p + 2 > payload.length) return null;
  const rpLen = payload[p] | (payload[p + 1] << 8); p += 2;
  if (p + rpLen !== payload.length) return null;
  const rangeproof = payload.slice(p, p + rpLen);
  return {
    kind: 'preauth_bid',
    assetId, assetInputCount,
    bidId, recipientPubkey, amount, blinding, priceSats,
    kernelSig, outputs, rangeproof,
  };
}

// Domain-tagged bid_context_hash binding (the 32-byte hash the buyer's
// SIGHASH_SINGLE_ACP signature pins to the OP_RETURN vout). Recomputable
// chain-only from the inline bid-context section + envelope's asset_id.
function computePreauthBidContextHash({
  assetId, bidId, recipientPubkey, amount, blinding, priceSats,
}) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (bidId.length !== 16) throw new Error('bid_id 16 bytes');
  if (recipientPubkey.length !== 33) throw new Error('recipient_pubkey 33 bytes');
  if (blinding.length !== 32) throw new Error('blinding 32 bytes');
  const amountLE = new Uint8Array(8); new DataView(amountLE.buffer).setBigUint64(0, BigInt(amount), true);
  const priceLE = new Uint8Array(8); new DataView(priceLE.buffer).setBigUint64(0, BigInt(priceSats), true);
  return sha256(concatBytes(
    new TextEncoder().encode('tacit-preauth-bid-context-v1'),
    assetId, bidId, recipientPubkey, amountLE, blinding, priceLE,
  ));
}

// T_PREAUTH_BID_VAR (SPEC §5.7.12) — buyer-offline partial-fill preauth bid.
// Extends §5.7.11 inline section with the variable-fill parameters
// (price_per_unit, max_fill, fill_increment, fill_amount) and replaces the
// fixed (amount, blinding, price_sats) trio. refund_script_hash is the
// hash160 of the buyer's reclaim P2WPKH, pinning where the unfilled
// portion's sats go. recipient_blinding stays in cleartext for the same
// reason §5.7.11 keeps blinding in cleartext: chain-only recovery via
// Pedersen opening of output[0].commitment.
//
// Inline layout: bid_id(16) + recipient_pubkey(33) + price_per_unit_LE(8) +
//   max_fill_LE(8) + fill_increment_LE(8) + fill_amount_LE(8) +
//   recipient_blinding(32) + refund_script_hash(20) + decimals_scale(1)
//   = 134 bytes.
//
// fill_amount is the seller's chosen ratio at settlement time;
// min_fill lives in the off-chain bid record (derivable as
// fill_amount_min_in_record) and is implicitly proven on chain via the
// OP_RETURN binding (only pre-signed ratios produce a matching hash).
const PREAUTH_BID_VAR_INLINE_BYTES = 16 + 33 + 8 + 8 + 8 + 8 + 32 + 20 + 1;  // 134
// decimals_scale upper bound. asset.decimals tops out at 8 per T_CETCH;
// we cap higher to accommodate future high-decimal asset classes. ≤ 32
// keeps 10^decimals_scale × max_fill from overflowing u64 with
// reasonable max_fill values.
const PREAUTH_BID_VAR_MAX_DECIMALS_SCALE = 32;
function encodePreauthBidVarPayload({
  assetId, assetInputCount,
  bidId, recipientPubkey,
  pricePerUnit, maxFill, fillIncrement, fillAmount,
  recipientBlinding, refundScriptHash, decimalsScale,
  kernelSig, outputs, rangeproof,
}) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (!Number.isInteger(assetInputCount) || assetInputCount < 1 || assetInputCount > 255) {
    throw new Error('asset_input_count must be integer in [1, 255]');
  }
  if (!bidId || bidId.length !== 16) throw new Error('bid_id 16 bytes');
  if (!recipientPubkey || recipientPubkey.length !== 33) throw new Error('recipient_pubkey 33 bytes');
  if (!recipientBlinding || recipientBlinding.length !== 32) throw new Error('recipient_blinding 32 bytes');
  if (!refundScriptHash || refundScriptHash.length !== 20) throw new Error('refund_script_hash 20 bytes');
  if (!kernelSig || kernelSig.length !== 64) throw new Error('kernel_sig must be 64 bytes');
  if (![1, 2].includes(outputs.length)) {
    throw new Error('T_PREAUTH_BID_VAR outputs must be 1 (no seller change) or 2 (seller change)');
  }
  if (rangeproof.length > 0xffff) throw new Error('rangeproof too large');
  const pBig = BigInt(pricePerUnit);
  const mBig = BigInt(maxFill);
  const iBig = BigInt(fillIncrement);
  const fBig = BigInt(fillAmount);
  if (pBig <= 0n) throw new Error('price_per_unit must be positive');
  if (mBig <= 0n) throw new Error('max_fill must be positive');
  if (iBig <= 0n) throw new Error('fill_increment must be positive');
  if (fBig <= 0n) throw new Error('fill_amount must be positive');
  if (fBig > mBig) throw new Error('fill_amount must be <= max_fill');
  if (!Number.isInteger(decimalsScale) || decimalsScale < 0 || decimalsScale > PREAUTH_BID_VAR_MAX_DECIMALS_SCALE) {
    throw new Error(`decimals_scale must be integer in [0, ${PREAUTH_BID_VAR_MAX_DECIMALS_SCALE}]`);
  }
  const u64LE = (n) => {
    const b = new Uint8Array(8);
    new DataView(b.buffer).setBigUint64(0, BigInt(n), true);
    return b;
  };
  const parts = [
    new Uint8Array([T_PREAUTH_BID_VAR]),
    assetId,
    new Uint8Array([assetInputCount]),
    bidId, recipientPubkey,
    u64LE(pricePerUnit), u64LE(maxFill), u64LE(fillIncrement), u64LE(fillAmount),
    recipientBlinding, refundScriptHash,
    new Uint8Array([decimalsScale & 0xff]),
    kernelSig,
    new Uint8Array([outputs.length]),
  ];
  if (outputs[0].commitment.length !== 33) throw new Error('output[0].commitment 33 bytes');
  parts.push(outputs[0].commitment);
  if (outputs.length === 2) {
    if (outputs[1].commitment.length !== 33) throw new Error('output[1].commitment 33 bytes');
    if (!outputs[1].encryptedAmount || outputs[1].encryptedAmount.length !== 8) {
      throw new Error('output[1].encrypted_amount must be 8 bytes');
    }
    parts.push(outputs[1].commitment, outputs[1].encryptedAmount);
  }
  const rpLen = new Uint8Array(2);
  new DataView(rpLen.buffer).setUint16(0, rangeproof.length, true);
  parts.push(rpLen, rangeproof);
  return concatBytes(...parts);
}

function decodePreauthBidVarPayload(payload) {
  if (!payload) return null;
  // Min size (N=1): opcode(1) + asset_id(32) + asset_input_count(1) +
  //   inline(133) + kernel_sig(64) + N(1) + output[0].commitment(33) +
  //   rp_len(2) = 267 bytes.
  const MIN = 1 + 32 + 1 + PREAUTH_BID_VAR_INLINE_BYTES + 64 + 1 + 33 + 2;
  if (payload.length < MIN) return null;
  if (payload[0] !== T_PREAUTH_BID_VAR) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const assetInputCount = payload[p]; p += 1;
  if (assetInputCount < 1) return null;
  const bidId = payload.slice(p, p + 16); p += 16;
  const recipientPubkey = payload.slice(p, p + 33); p += 33;
  const readU64 = () => {
    const v = new DataView(payload.buffer, payload.byteOffset + p, 8).getBigUint64(0, true);
    p += 8;
    return v;
  };
  const pricePerUnit = readU64();
  const maxFill = readU64();
  const fillIncrement = readU64();
  const fillAmount = readU64();
  const recipientBlinding = payload.slice(p, p + 32); p += 32;
  const refundScriptHash = payload.slice(p, p + 20); p += 20;
  const decimalsScale = payload[p]; p += 1;
  if (decimalsScale > PREAUTH_BID_VAR_MAX_DECIMALS_SCALE) return null;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const n = payload[p]; p += 1;
  if (n !== 1 && n !== 2) return null;
  const outputs = [];
  if (p + 33 > payload.length) return null;
  outputs.push({ commitment: payload.slice(p, p + 33) }); p += 33;
  if (n === 2) {
    if (p + 33 + 8 > payload.length) return null;
    const commitment = payload.slice(p, p + 33); p += 33;
    const encryptedAmount = payload.slice(p, p + 8); p += 8;
    outputs.push({ commitment, encryptedAmount });
  }
  if (p + 2 > payload.length) return null;
  const rpLen = payload[p] | (payload[p + 1] << 8); p += 2;
  if (p + rpLen !== payload.length) return null;
  const rangeproof = payload.slice(p, p + rpLen);
  if (fillAmount === 0n || fillAmount > maxFill) return null;
  // Grid + overflow discipline: a zero increment has no grid, an increment above max_fill makes the
  // grid degenerate, and price·max_fill (the seller's sats receivable, the value the refund-vout math
  // and any u64 consumer relies on) must not overflow u64. JS BigInt is safe here, but the worker's
  // refund-vout arithmetic is u64 — reject the envelope rather than letting it wrap downstream.
  if (fillIncrement === 0n || fillIncrement > maxFill) return null;
  if (pricePerUnit * maxFill >= (1n << 64n)) return null;
  return {
    kind: 'preauth_bid_var',
    assetId, assetInputCount,
    bidId, recipientPubkey,
    pricePerUnit, maxFill, fillIncrement, fillAmount,
    recipientBlinding, refundScriptHash, decimalsScale,
    kernelSig, outputs, rangeproof,
  };
}

// Per-ratio bid_context_hash binding for T_PREAUTH_BID_VAR. The buyer's
// K SIGHASH_SINGLE_ACP pre-signatures each pin a different output of this
// shape (one per allowed fill_amount_i ∈ {min_fill, min_fill + increment,
// …, max_fill}). Domain tag is distinct from §5.7.11 to keep the per-ratio
// binding cleanly separated from the exact-fill version.
//
// recipient_blinding deliberately is NOT in this hash — the inline-section
// blinding is bound to chain via the Pedersen consistency rule (validator
// rule 1), not via the OP_RETURN. Dropping it from the hash saves 32 bytes
// of K-sig preimage and keeps the canonical hash compact.
function computePreauthBidVarContextHash({
  assetId, bidId, recipientPubkey,
  pricePerUnit, maxFill, fillIncrement, fillAmount,
  refundScriptHash, decimalsScale,
}) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (bidId.length !== 16) throw new Error('bid_id 16 bytes');
  if (recipientPubkey.length !== 33) throw new Error('recipient_pubkey 33 bytes');
  if (refundScriptHash.length !== 20) throw new Error('refund_script_hash 20 bytes');
  if (!Number.isInteger(decimalsScale) || decimalsScale < 0 || decimalsScale > PREAUTH_BID_VAR_MAX_DECIMALS_SCALE) {
    throw new Error(`decimals_scale must be integer in [0, ${PREAUTH_BID_VAR_MAX_DECIMALS_SCALE}]`);
  }
  const u64LE = (n) => {
    const b = new Uint8Array(8);
    new DataView(b.buffer).setBigUint64(0, BigInt(n), true);
    return b;
  };
  return sha256(concatBytes(
    new TextEncoder().encode('tacit-preauth-bid-var-context-v1'),
    assetId, bidId, recipientPubkey,
    u64LE(pricePerUnit), u64LE(maxFill), u64LE(fillIncrement), u64LE(fillAmount),
    refundScriptHash,
    new Uint8Array([decimalsScale & 0xff]),
  ));
}

// ---- Kernel message: binds the sig to (asset_id, input outpoints, output commitments) ----
// Anyone replaying this sig in a different tx (different inputs or outputs) gets a different msg
// and cannot produce a valid kernel.
function computeKernelMsg(assetId, inputOutpoints, outputCommitments, burnedAmount = 0n) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  // The wire format encodes counts as a single byte (SPEC §5.2 / §5.4). With
  // a hard reject above 255 we keep the spec literally true and close the
  // count-truncation hardening gap: silently truncating with `& 0xff` would
  // let two distinct input lists (length L and L+256) share a kernel msg.
  // In practice the dApp never builds more than 8 outputs and a handful of
  // inputs, but the encoder + validator should refuse the boundary case
  // explicitly rather than rely on length disambiguation in the hash.
  if (inputOutpoints.length > 255) throw new Error('kernel msg: input count > 255');
  if (outputCommitments.length > 255) throw new Error('kernel msg: output count > 255');
  const parts = [new TextEncoder().encode('tacit-kernel-v1'), assetId, new Uint8Array([inputOutpoints.length])];
  for (const op of inputOutpoints) {
    parts.push(reverseBytes(hexToBytes(op.txid)));
    const voutLE = new Uint8Array(4);
    new DataView(voutLE.buffer).setUint32(0, op.vout >>> 0, true);
    parts.push(voutLE);
  }
  parts.push(new Uint8Array([outputCommitments.length]));
  for (const c of outputCommitments) parts.push(c);
  // Backwards-compatible: pure CXFER (no burn) sets burnedAmount=0 and the burn
  // bytes are still appended but their content is zero. This keeps kernel
  // verification consistent across CXFER and BURN paths.
  const burnLE = new Uint8Array(8);
  const view = new DataView(burnLE.buffer);
  view.setUint32(0, Number(burnedAmount & 0xffffffffn), true);
  view.setUint32(4, Number((burnedAmount >> 32n) & 0xffffffffn), true);
  parts.push(burnLE);
  return sha256(concatBytes(...parts));
}

// MINT (issue more supply on a mintable asset):
//   T_MINT(1) || asset_id(32) || etch_txid(32) ||
//   mint_commitment(33) || mint_amount_ct(8) ||
//   rp_len(2 LE) || rangeproof(rp_len) || issuer_sig(64)
//
// etch_txid is included so the validator can fetch the CETCH envelope by txid
// and verify (a) mint_authority is non-zero (asset is mintable), (b) sig was
// signed by mint_authority. asset_id must equal sha256(etch_txid_BE || vout=0).
//
// issuer_sig is a BIP-340 Schnorr signature over
//   sha256("tacit-mint-v1" || asset_id || commit_anchor(36B) || mint_commitment || mint_amount_ct)
// signed by the mint_authority private key. New mint output goes to vout=0 of
// the reveal tx (P2WPKH to issuer wallet), holding mint_commitment. The
// commit_anchor field binds the signature to a specific commit/reveal pair —
// without it, an attacker could rewrap the on-chain envelope into their own
// commit/reveal flow at their own address (see computeMintMsg below).
function encodeCMintPayload({ assetId, etchTxid, commitment, encryptedAmount, rangeproof, issuerSig }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (etchTxid.length !== 32) throw new Error('etch_txid 32 bytes');
  if (commitment.length !== 33) throw new Error('commitment 33 bytes');
  if (!encryptedAmount || encryptedAmount.length !== 8) throw new Error('encrypted_amount must be 8 bytes');
  if (rangeproof.length > 0xffff) throw new Error('rangeproof too large');
  if (!issuerSig || issuerSig.length !== 64) throw new Error('issuer_sig must be 64 bytes');
  const rpLen = new Uint8Array(2); new DataView(rpLen.buffer).setUint16(0, rangeproof.length, true);
  return concatBytes(
    new Uint8Array([T_MINT]), assetId, etchTxid,
    commitment, encryptedAmount, rpLen, rangeproof, issuerSig,
  );
}

function decodeCMintPayload(payload) {
  if (!payload) return null;
  if (payload.length < 1 + 32 + 32 + 33 + 8 + 2 + 64) return null;
  if (payload[0] !== T_MINT) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const etchTxid = payload.slice(p, p + 32); p += 32;
  const commitment = payload.slice(p, p + 33); p += 33;
  const encryptedAmount = payload.slice(p, p + 8); p += 8;
  const rpLen = payload[p] | (payload[p + 1] << 8); p += 2;
  if (p + rpLen + 64 > payload.length) return null;
  const rangeproof = payload.slice(p, p + rpLen); p += rpLen;
  const issuerSig = payload.slice(p, p + 64); p += 64;
  if (p !== payload.length) return null;
  return { kind: 'cmint', assetId, etchTxid, commitment, encryptedAmount, rangeproof, issuerSig };
}

// Mint message must bind the *transaction-specific* commit-input anchor so a
// witnessed mint envelope can't be replayed into a different commit/reveal pair
// at an attacker's address. Without anchor binding, the validator only checks
// (asset_id, commitment, amount_ct) — all observable on chain — and an attacker
// who reads any past T_MINT can clone the envelope into their own UTXO. With
// anchor binding the issuer's signature is tied to the specific commit_tx.vin[0]
// outpoint that funds the reveal, which the attacker cannot reproduce.
//
// commit_anchor = commit_tx.vin[0].txid_BE(32) || commit_tx.vin[0].vout_LE(4)
// (same anchor the issuer already uses for the mint blinding/keystream HMAC).
function computeMintMsg(assetId, commitAnchor, commitment, encryptedAmount) {
  if (!commitAnchor || commitAnchor.length !== 36) throw new Error('commit_anchor must be 36 bytes');
  return sha256(concatBytes(
    new TextEncoder().encode('tacit-mint-v1'),
    assetId, commitAnchor, commitment, encryptedAmount,
  ));
}

// BURN (destroy supply, emit a public burned_amount):
//   T_BURN(1) || asset_id(32) || burned_amount(8 LE u64) ||
//   kernel_sig(64) || N(1) ||
//   (commitment(33) || amount_ct(8)) * N ||
//   rp_len(2 LE) || rangeproof(rp_len)
//
// Validator equation: Σ C_in == burned_amount·H + Σ C_out (in commitment space).
// Kernel sig binds (asset_id, inputs, outputs, burned_amount) — replay-safe.
// N ∈ {0, 1, 2, 4, 8}: zero outputs allowed (burn everything to nothing).
function encodeCBurnPayload({ assetId, burnedAmount, kernelSig, outputs, rangeproof }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (burnedAmount < 0n || burnedAmount >= (1n << BigInt(N_BITS))) throw new Error('burned_amount out of range');
  if (!kernelSig || kernelSig.length !== 64) throw new Error('kernel_sig must be 64 bytes');
  if (![0, 1, 2, 4, 8].includes(outputs.length)) throw new Error('outputs.length must be in {0,1,2,4,8}');
  if (outputs.length > 0 && rangeproof.length > 0xffff) throw new Error('rangeproof too large');
  if (outputs.length === 0 && rangeproof && rangeproof.length > 0) throw new Error('rangeproof must be empty when outputs.length === 0');
  const burnLE = new Uint8Array(8);
  {
    const view = new DataView(burnLE.buffer);
    view.setUint32(0, Number(burnedAmount & 0xffffffffn), true);
    view.setUint32(4, Number((burnedAmount >> 32n) & 0xffffffffn), true);
  }
  const parts = [new Uint8Array([T_BURN]), assetId, burnLE, kernelSig, new Uint8Array([outputs.length])];
  for (const o of outputs) {
    if (o.commitment.length !== 33) throw new Error('commitment 33 bytes');
    if (!o.encryptedAmount || o.encryptedAmount.length !== 8) throw new Error('encrypted_amount must be 8 bytes');
    parts.push(o.commitment, o.encryptedAmount);
  }
  if (outputs.length > 0) {
    const rpLen = new Uint8Array(2); new DataView(rpLen.buffer).setUint16(0, rangeproof.length, true);
    parts.push(rpLen, rangeproof);
  }
  return concatBytes(...parts);
}

function decodeCBurnPayload(payload) {
  if (!payload) return null;
  if (payload.length < 1 + 32 + 8 + 64 + 1) return null;
  if (payload[0] !== T_BURN) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const burnedLE = payload.slice(p, p + 8); p += 8;
  const view = new DataView(burnedLE.buffer, burnedLE.byteOffset, 8);
  const burnedAmount = (BigInt(view.getUint32(4, true)) << 32n) | BigInt(view.getUint32(0, true));
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const n = payload[p]; p += 1;
  if (![0, 1, 2, 4, 8].includes(n)) return null;
  const outputs = [];
  for (let i = 0; i < n; i++) {
    if (p + 33 + 8 > payload.length) return null;
    const commitment = payload.slice(p, p + 33); p += 33;
    const encryptedAmount = payload.slice(p, p + 8); p += 8;
    outputs.push({ commitment, encryptedAmount });
  }
  let rangeproof = new Uint8Array(0);
  if (n > 0) {
    if (p + 2 > payload.length) return null;
    const rpLen = payload[p] | (payload[p + 1] << 8); p += 2;
    if (p + rpLen !== payload.length) return null;
    rangeproof = payload.slice(p, p + rpLen);
  } else {
    if (p !== payload.length) return null;
  }
  return { kind: 'cburn', assetId, burnedAmount, kernelSig, outputs, rangeproof };
}

// ============== PERMISSIONLESS MINT (T_PETCH / T_PMINT) ==============
// SPEC §5.8 / §5.9. Permissionless fair-launch issuance:
//   - T_PETCH (0x27): deployment record. Declares ticker, decimals, lifetime
//     cap, fixed per-mint amount, and a height window. NO supply UTXO is
//     produced — the deployer receives zero tokens; to hold any, they (or
//     anyone else) must broadcast T_PMINT.
//   - T_PMINT (0x28): permissionless mint event. Anyone may broadcast.
//     Reveals (amount, blinding) so any chain reader can audit the cap; cap
//     is enforced by indexers summing canonically-ordered T_PMINTs at
//     confirmation depth ≥ 3 (SPEC §5.9 *Confirmation depth*).
//
// Wire format kept verbatim parity with worker/src/index.js's
// decodeCPetchPayload / decodeCPmintPayload — any drift here breaks
// indexer interop. The worker-decoder.test.mjs / dapp-parity.test.mjs
// pair pins this contract on every push.

// T_PETCH(1) || tlen(1) || ticker(tlen) || decimals(1) ||
//   cap_amount(8 LE) || mint_limit(8 LE) || mint_start_height(4 LE) ||
//   mint_end_height(4 LE) || img_len(2 LE) || image_uri(img_len)
function encodeCPetchPayload({ ticker, decimals, capAmount, mintLimit, mintStartHeight = 0, mintEndHeight = 0, imageUri = null }) {
  const tk = new TextEncoder().encode(ticker);
  if (tk.length < 1 || tk.length > 16) throw new Error('ticker length must be 1..16');
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 8) throw new Error('decimals must be 0..8');
  const cap = BigInt(capAmount);
  const lim = BigInt(mintLimit);
  if (cap <= 0n || cap >= (1n << BigInt(N_BITS))) throw new Error('cap_amount out of range');
  if (lim <= 0n || lim > cap) throw new Error('mint_limit out of range');
  if (cap % lim !== 0n) throw new Error('cap_amount must be evenly divisible by mint_limit');
  if (!Number.isInteger(mintStartHeight) || mintStartHeight < 0 || mintStartHeight > 0xffffffff) throw new Error('mint_start_height out of range');
  if (!Number.isInteger(mintEndHeight) || mintEndHeight < 0 || mintEndHeight > 0xffffffff) throw new Error('mint_end_height out of range');
  if (mintStartHeight !== 0 && mintEndHeight !== 0 && mintEndHeight <= mintStartHeight) {
    throw new Error('mint_end_height must exceed mint_start_height when both nonzero');
  }
  const img = imageUri ? new TextEncoder().encode(imageUri) : new Uint8Array(0);
  if (img.length > 256) throw new Error('image_uri too long');
  const capLE = new Uint8Array(8);
  const limLE = new Uint8Array(8);
  {
    const cv = new DataView(capLE.buffer);
    cv.setUint32(0, Number(cap & 0xffffffffn), true);
    cv.setUint32(4, Number((cap >> 32n) & 0xffffffffn), true);
    const lv = new DataView(limLE.buffer);
    lv.setUint32(0, Number(lim & 0xffffffffn), true);
    lv.setUint32(4, Number((lim >> 32n) & 0xffffffffn), true);
  }
  const startLE = new Uint8Array(4); new DataView(startLE.buffer).setUint32(0, mintStartHeight >>> 0, true);
  const endLE = new Uint8Array(4); new DataView(endLE.buffer).setUint32(0, mintEndHeight >>> 0, true);
  const imgLen = new Uint8Array(2); new DataView(imgLen.buffer).setUint16(0, img.length, true);
  return concatBytes(
    new Uint8Array([T_PETCH]), new Uint8Array([tk.length]), tk,
    new Uint8Array([decimals]), capLE, limLE, startLE, endLE, imgLen, img,
  );
}

function decodeCPetchPayload(payload) {
  if (!payload) return null;
  if (payload.length < 1 + 1 + 1 + 1 + 8 + 8 + 4 + 4 + 2) return null;
  if (payload[0] !== T_PETCH) return null;
  let p = 1;
  const tlen = payload[p]; p += 1;
  if (tlen < 1 || tlen > 16) return null;
  if (p + tlen > payload.length) return null;
  let ticker;
  try { ticker = new TextDecoder('utf-8', { fatal: true }).decode(payload.slice(p, p + tlen)); } catch { return null; }
  p += tlen;
  const decimals = payload[p]; p += 1;
  if (decimals > 8) return null;
  if (p + 8 + 8 + 4 + 4 + 2 > payload.length) return null;
  const capView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const capAmount = (BigInt(capView.getUint32(4, true)) << 32n) | BigInt(capView.getUint32(0, true));
  p += 8;
  const limView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const mintLimit = (BigInt(limView.getUint32(4, true)) << 32n) | BigInt(limView.getUint32(0, true));
  p += 8;
  if (capAmount <= 0n) return null;
  if (mintLimit <= 0n) return null;
  if (mintLimit > capAmount) return null;
  if (capAmount % mintLimit !== 0n) return null;
  const startView = new DataView(payload.buffer, payload.byteOffset + p, 4);
  const mintStartHeight = startView.getUint32(0, true); p += 4;
  const endView = new DataView(payload.buffer, payload.byteOffset + p, 4);
  const mintEndHeight = endView.getUint32(0, true); p += 4;
  if (mintStartHeight !== 0 && mintEndHeight !== 0 && mintEndHeight <= mintStartHeight) return null;
  const imgLen = payload[p] | (payload[p + 1] << 8); p += 2;
  if (imgLen > 256) return null;
  if (p + imgLen !== payload.length) return null;
  let imageUri = null;
  if (imgLen > 0) {
    try { imageUri = new TextDecoder('utf-8', { fatal: true }).decode(payload.slice(p, p + imgLen)); } catch { return null; }
  }
  return { kind: 'cpetch', ticker, decimals, capAmount, mintLimit, mintStartHeight, mintEndHeight, imageUri };
}

// T_PMINT(1) || asset_id(32) || etch_txid(32) || commitment(33) ||
//   amount(8 LE) || blinding(32). Total: 138 bytes exactly.
function encodeCPmintPayload({ assetId, etchTxid, commitment, amount, blinding }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (etchTxid.length !== 32) throw new Error('etch_txid 32 bytes');
  if (commitment.length !== 33) throw new Error('commitment 33 bytes');
  const amt = BigInt(amount);
  if (amt <= 0n || amt >= (1n << BigInt(N_BITS))) throw new Error('amount out of range');
  if (!blinding || blinding.length !== 32) throw new Error('blinding must be 32 bytes');
  let blindingNonZero = false;
  for (let i = 0; i < 32; i++) if (blinding[i] !== 0) { blindingNonZero = true; break; }
  if (!blindingNonZero) throw new Error('blinding must be non-zero');
  const amtLE = new Uint8Array(8);
  {
    const v = new DataView(amtLE.buffer);
    v.setUint32(0, Number(amt & 0xffffffffn), true);
    v.setUint32(4, Number((amt >> 32n) & 0xffffffffn), true);
  }
  return concatBytes(
    new Uint8Array([T_PMINT]), assetId, etchTxid, commitment, amtLE, blinding,
  );
}

function decodeCPmintPayload(payload) {
  if (!payload) return null;
  if (payload.length !== 1 + 32 + 32 + 33 + 8 + 32) return null;
  if (payload[0] !== T_PMINT) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const etchTxid = payload.slice(p, p + 32); p += 32;
  const commitment = payload.slice(p, p + 33); p += 33;
  const amtView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const amount = (BigInt(amtView.getUint32(4, true)) << 32n) | BigInt(amtView.getUint32(0, true));
  p += 8;
  if (amount <= 0n || amount >= (1n << BigInt(N_BITS))) return null;
  const blinding = payload.slice(p, p + 32); p += 32;
  let blindingNonZero = false;
  for (let i = 0; i < 32; i++) if (blinding[i] !== 0) { blindingNonZero = true; break; }
  if (!blindingNonZero) return null;
  if (p !== payload.length) return null;
  return { kind: 'cpmint', assetId, etchTxid, commitment, amount, blinding };
}

// ============== PUBLIC-CLAIM POOL (T_DROP / T_DCLAIM) ==============
// SPEC §5.12 / §5.13. Two new opcodes implement a permissionless claim pool
// over existing tacit supply — the existing-supply analog of T_PETCH/T_PMINT.
//
//   T_DROP (0x2B): supply-locking deposit. Spends Σ asset UTXOs of asset_id
//     summing to cap_amount; declares (per_claim, cap_amount, merkle_root,
//     expiry_height). Produces no asset UTXO. Kernel sig under
//     (Σ C_in − cap_amount·H).x_only() proves balance (Mimblewimble, same as
//     T_DEPOSIT). drop_id derives from the reveal tx the same way asset_id
//     does for CETCH: SHA256(reveal_txid_BE || 0_LE).
//
//   T_DCLAIM (0x2C): permissionless claim event. Anyone may broadcast
//     (subject to drop.merkle_root eligibility gate). Mints exactly
//     drop.per_claim tokens at vout[0]; reveals (amount, blinding) in
//     plaintext so chain readers audit cumulative claims against cap. Cap
//     enforced by indexer counting prior valid T_DCLAIMs at depth ≥ 3 (same
//     posture as T_PMINT). For merkle-gated drops, the witness carries
//     (recipient_pub, leaf_index, eth_address, eth_sig, merkle_proof) and
//     the canonical claim msg is byte-for-byte the existing §8 airdrop msg
//     (using merkle_root, not drop_id, so sigs are portable between the
//     on-chain flow and the worker-mediated airdrop).

// T_DROP payload — standard shape (per_claim > 0):
//   T_DROP(1) || asset_id(32) || cap_amount_LE(8) || per_claim_LE(8) ||
//   merkle_root(32) || expiry_height_LE(4) || ticker_len(1) || ticker(tlen) ||
//   decimals(1) || asset_input_count(1) || kernel_sig(64)
//
// Reclaim shape (per_claim = 0 sentinel; SPEC §5.12.1):
//   T_DROP(1) || asset_id(32) || cap_amount_LE(8) || per_claim_LE(8) = 0 ||
//   reclaim_drop_id(32) || reclaim_sig(64) || cap_blinding(32)
// `cap_blinding` here opens the synthetic OUTPUT commitment for the
// reclaim-produced UTXO at vout[0] — distinct from the standard-drop case
// where no blinding appears (the kernel sig closes the balance equation
// without a published opening).
function encodeCDropPayload({ assetId, capAmount, perClaim, merkleRoot, expiryHeight, ticker, decimals, assetInputCount, kernelSig }) {
  if (!(assetId instanceof Uint8Array) || assetId.length !== 32) throw new Error('asset_id must be 32 bytes');
  const cap = BigInt(capAmount);
  const per = BigInt(perClaim);
  if (cap <= 0n || cap >= (1n << 64n)) throw new Error('cap_amount out of u64 range');
  if (per <= 0n || per >= (1n << 64n)) throw new Error('per_claim out of u64 range');
  if (cap % per !== 0n) throw new Error('cap_amount must be divisible by per_claim');
  if (!(merkleRoot instanceof Uint8Array) || merkleRoot.length !== 32) throw new Error('merkle_root must be 32 bytes');
  const exp = Number(expiryHeight);
  if (!Number.isInteger(exp) || exp < 0 || exp > 0xffffffff) throw new Error('expiry_height must be u32');
  const tk = ticker ? new TextEncoder().encode(String(ticker)) : new Uint8Array(0);
  if (tk.length > 16) throw new Error('ticker too long (max 16 bytes UTF-8)');
  const dec = Number(decimals) || 0;
  if (!Number.isInteger(dec) || dec < 0 || dec > 8) throw new Error('decimals must be 0..8');
  const aic = Number(assetInputCount);
  if (!Number.isInteger(aic) || aic < 1 || aic > 16) throw new Error('asset_input_count must be 1..16');
  if (!(kernelSig instanceof Uint8Array) || kernelSig.length !== 64) throw new Error('kernel_sig must be 64 bytes');
  const capLE = new Uint8Array(8);
  {
    const v = new DataView(capLE.buffer);
    v.setUint32(0, Number(cap & 0xffffffffn), true);
    v.setUint32(4, Number((cap >> 32n) & 0xffffffffn), true);
  }
  const perLE = new Uint8Array(8);
  {
    const v = new DataView(perLE.buffer);
    v.setUint32(0, Number(per & 0xffffffffn), true);
    v.setUint32(4, Number((per >> 32n) & 0xffffffffn), true);
  }
  const expLE = new Uint8Array(4); new DataView(expLE.buffer).setUint32(0, exp >>> 0, true);
  return concatBytes(
    new Uint8Array([T_DROP]), assetId, capLE, perLE, merkleRoot, expLE,
    new Uint8Array([tk.length]), tk, new Uint8Array([dec]),
    new Uint8Array([aic]), kernelSig,
  );
}

function encodeCDropReclaimPayload({ assetId, capAmount, reclaimDropId, reclaimSig, capBlinding }) {
  if (!(assetId instanceof Uint8Array) || assetId.length !== 32) throw new Error('asset_id must be 32 bytes');
  const cap = BigInt(capAmount);
  if (cap <= 0n || cap >= (1n << 64n)) throw new Error('cap_amount out of u64 range');
  if (!(reclaimDropId instanceof Uint8Array) || reclaimDropId.length !== 32) throw new Error('reclaim_drop_id must be 32 bytes');
  if (!(reclaimSig instanceof Uint8Array) || reclaimSig.length !== 64) throw new Error('reclaim_sig must be 64 bytes');
  if (!(capBlinding instanceof Uint8Array) || capBlinding.length !== 32) throw new Error('cap_blinding must be 32 bytes');
  let bNonZero = false;
  for (let i = 0; i < 32; i++) if (capBlinding[i] !== 0) { bNonZero = true; break; }
  if (!bNonZero) throw new Error('cap_blinding must be non-zero');
  const capLE = new Uint8Array(8);
  {
    const v = new DataView(capLE.buffer);
    v.setUint32(0, Number(cap & 0xffffffffn), true);
    v.setUint32(4, Number((cap >> 32n) & 0xffffffffn), true);
  }
  const perZeroLE = new Uint8Array(8);   // per_claim = 0 sentinel
  return concatBytes(
    new Uint8Array([T_DROP]), assetId, capLE, perZeroLE,
    reclaimDropId, reclaimSig, capBlinding,
  );
}

function decodeCDropPayload(payload) {
  if (!payload) return null;
  // Minimum size (standard shape, ticker_len = 0):
  //   1 + 32 + 8 + 8 + 32 + 4 + 1 + 0 + 1 + 1 + 64 = 152
  // Reclaim shape size: 1 + 32 + 8 + 8 + 32 + 64 + 32 = 177 (always exact)
  if (payload.length < 152) return null;
  if (payload[0] !== T_DROP) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const capView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const capAmount = (BigInt(capView.getUint32(4, true)) << 32n) | BigInt(capView.getUint32(0, true));
  p += 8;
  const perView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const perClaim = (BigInt(perView.getUint32(4, true)) << 32n) | BigInt(perView.getUint32(0, true));
  p += 8;
  if (capAmount <= 0n) return null;
  // Reclaim shape: per_claim == 0 sentinel.
  if (perClaim === 0n) {
    if (payload.length !== 1 + 32 + 8 + 8 + 32 + 64 + 32) return null;
    const reclaimDropId = payload.slice(p, p + 32); p += 32;
    const reclaimSig = payload.slice(p, p + 64); p += 64;
    const capBlinding = payload.slice(p, p + 32); p += 32;
    if (p !== payload.length) return null;
    let bNonZero = false;
    for (let i = 0; i < 32; i++) if (capBlinding[i] !== 0) { bNonZero = true; break; }
    if (!bNonZero) return null;
    return {
      kind: 'cdrop-reclaim',
      assetId, capAmount, reclaimDropId, reclaimSig, capBlinding,
    };
  }
  // Standard drop shape.
  if (perClaim >= (1n << 64n)) return null;
  if (capAmount % perClaim !== 0n) return null;
  const merkleRoot = payload.slice(p, p + 32); p += 32;
  const expView = new DataView(payload.buffer, payload.byteOffset + p, 4);
  const expiryHeight = expView.getUint32(0, true); p += 4;
  if (p + 1 > payload.length) return null;
  const tlen = payload[p]; p += 1;
  if (tlen > 16) return null;
  if (p + tlen + 1 + 1 + 64 > payload.length) return null;
  let ticker = null;
  if (tlen > 0) {
    try { ticker = new TextDecoder('utf-8', { fatal: true }).decode(payload.slice(p, p + tlen)); } catch { return null; }
  }
  p += tlen;
  const decimals = payload[p]; p += 1;
  if (decimals > 8) return null;
  const assetInputCount = payload[p]; p += 1;
  if (assetInputCount < 1 || assetInputCount > 16) return null;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  if (p !== payload.length) return null;
  return {
    kind: 'cdrop',
    assetId, capAmount, perClaim, merkleRoot, expiryHeight,
    ticker, decimals, assetInputCount, kernelSig,
  };
}

// T_DCLAIM payload:
//   T_DCLAIM(1) || asset_id(32) || drop_reveal_txid(32) || commitment(33) ||
//   amount_LE(8) || blinding(32) || witness_len_LE(2) || witness(witness_len)
//
// drop_reveal_txid is the raw txid of the originating T_DROP reveal tx —
// validators fetch the parent envelope by this txid, matching T_PMINT's
// etch_txid pattern (§5.9). The "drop_id" KV-key concept (the SHA256 hash
// used for indexer state) is derived locally via dropIdFromRevealTxid;
// the wire format does NOT carry the hashed form.
//
// Witness for merkle-gated drops (witness_len > 0):
//   recipient_pub(33) || leaf_index_LE(4) || eth_address(20) || eth_sig(65) ||
//   proof_len(1) || proof_path(proof_len * 32)
//
// Witness for open drops: empty (witness_len == 0).
function encodeCDClaimPayload({ assetId, dropRevealTxid, commitment, amount, blinding, witness }) {
  if (!(assetId instanceof Uint8Array) || assetId.length !== 32) throw new Error('asset_id must be 32 bytes');
  if (!(dropRevealTxid instanceof Uint8Array) || dropRevealTxid.length !== 32) throw new Error('drop_reveal_txid must be 32 bytes');
  if (!(commitment instanceof Uint8Array) || commitment.length !== 33) throw new Error('commitment must be 33 bytes');
  const amt = BigInt(amount);
  if (amt <= 0n || amt >= (1n << 64n)) throw new Error('amount out of u64 range');
  if (!(blinding instanceof Uint8Array) || blinding.length !== 32) throw new Error('blinding must be 32 bytes');
  let bNonZero = false;
  for (let i = 0; i < 32; i++) if (blinding[i] !== 0) { bNonZero = true; break; }
  if (!bNonZero) throw new Error('blinding must be non-zero');
  const witnessBytes = witness instanceof Uint8Array ? witness : new Uint8Array(0);
  if (witnessBytes.length > 65535) throw new Error('witness too large (max 64 KB)');
  const amtLE = new Uint8Array(8);
  {
    const v = new DataView(amtLE.buffer);
    v.setUint32(0, Number(amt & 0xffffffffn), true);
    v.setUint32(4, Number((amt >> 32n) & 0xffffffffn), true);
  }
  const wLen = new Uint8Array(2); new DataView(wLen.buffer).setUint16(0, witnessBytes.length, true);
  return concatBytes(
    new Uint8Array([T_DCLAIM]), assetId, dropRevealTxid, commitment, amtLE, blinding,
    wLen, witnessBytes,
  );
}

// Helper to construct the witness blob for merkle-gated T_DCLAIM. Pass the
// returned Uint8Array as `witness` to encodeCDClaimPayload.
function encodeCDClaimWitness({ recipientPub, leafIndex, ethAddress, ethSig, proofPath }) {
  if (!(recipientPub instanceof Uint8Array) || recipientPub.length !== 33) throw new Error('recipient_pub 33');
  if (recipientPub[0] !== 0x02 && recipientPub[0] !== 0x03) throw new Error('recipient_pub must start with 02 or 03');
  if (!Number.isInteger(leafIndex) || leafIndex < 0 || leafIndex > 0xffffffff) throw new Error('leaf_index u32');
  if (!(ethAddress instanceof Uint8Array) || ethAddress.length !== 20) throw new Error('eth_address 20');
  if (!(ethSig instanceof Uint8Array) || ethSig.length !== 65) throw new Error('eth_sig 65');
  if (!Array.isArray(proofPath)) throw new Error('proof_path must be an array');
  if (proofPath.length > 32) throw new Error('proof_path too deep (max 32)');
  for (const s of proofPath) {
    if (!(s instanceof Uint8Array) || s.length !== 32) throw new Error('proof_path entries must be 32-byte');
  }
  const liLE = new Uint8Array(4); new DataView(liLE.buffer).setUint32(0, leafIndex >>> 0, true);
  return concatBytes(
    recipientPub, liLE, ethAddress, ethSig,
    new Uint8Array([proofPath.length]),
    ...proofPath,
  );
}

function decodeCDClaimPayload(payload) {
  if (!payload) return null;
  // Minimum size (witness_len = 0): 1 + 32 + 32 + 33 + 8 + 32 + 2 = 140
  if (payload.length < 140) return null;
  if (payload[0] !== T_DCLAIM) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const dropRevealTxid = payload.slice(p, p + 32); p += 32;
  const commitment = payload.slice(p, p + 33); p += 33;
  const amtView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const amount = (BigInt(amtView.getUint32(4, true)) << 32n) | BigInt(amtView.getUint32(0, true));
  p += 8;
  if (amount <= 0n || amount >= (1n << 64n)) return null;
  const blinding = payload.slice(p, p + 32); p += 32;
  let bNonZero = false;
  for (let i = 0; i < 32; i++) if (blinding[i] !== 0) { bNonZero = true; break; }
  if (!bNonZero) return null;
  const wView = new DataView(payload.buffer, payload.byteOffset + p, 2);
  const witnessLen = wView.getUint16(0, true); p += 2;
  if (p + witnessLen !== payload.length) return null;
  const witnessBytes = payload.slice(p, p + witnessLen); p += witnessLen;
  // Parse witness if non-empty. Per SPEC §5.13, the only valid witness shape
  // is the merkle-gated form; open drops MUST carry witness_len = 0.
  let witness = null;
  if (witnessLen > 0) {
    const headerSize = 33 + 4 + 20 + 65 + 1;
    if (witnessLen < headerSize) return null;
    let wp = 0;
    const recipientPub = witnessBytes.slice(wp, wp + 33); wp += 33;
    if (recipientPub[0] !== 0x02 && recipientPub[0] !== 0x03) return null;
    const liView = new DataView(witnessBytes.buffer, witnessBytes.byteOffset + wp, 4);
    const leafIndex = liView.getUint32(0, true); wp += 4;
    const ethAddress = witnessBytes.slice(wp, wp + 20); wp += 20;
    const ethSig = witnessBytes.slice(wp, wp + 65); wp += 65;
    const proofLen = witnessBytes[wp]; wp += 1;
    if (proofLen > 32) return null;
    if (wp + proofLen * 32 !== witnessBytes.length) return null;
    const proofPath = [];
    for (let i = 0; i < proofLen; i++) {
      proofPath.push(witnessBytes.slice(wp, wp + 32));
      wp += 32;
    }
    witness = { recipientPub, leafIndex, ethAddress, ethSig, proofPath };
  }
  return {
    kind: 'cdclaim',
    assetId, dropRevealTxid, commitment, amount, blinding, witness,
  };
}

// drop_id derives from the reveal tx the same way asset_id does for CETCH:
// SHA256(reveal_txid_BE || 0_LE) — the 0_LE is the vout-position sentinel
// for the canonical first output (the pool marker for T_DROP, vout 0).
function dropIdFromRevealTxid(revealTxidHex) {
  const txidBE = reverseBytes(hexToBytes(revealTxidHex));
  const voutLE = new Uint8Array(4);   // vout = 0
  return sha256(concatBytes(txidBE, voutLE));
}

// Kernel msg for T_DROP. Binds asset_id, cap/per_claim/merkle_root/expiry,
// asset_input_count, AND each asset input's outpoint — so two T_DROPs
// spending different inputs produce different kernel msgs, preventing a
// rewrap attack (the rewrapped tx would have to spend the same already-
// consumed inputs as the original, which is impossible after the original
// confirms).
function dropKernelMsg({ assetId, capAmount, perClaim, merkleRoot, expiryHeight, assetInputCount, assetInputs }) {
  if (!(assetId instanceof Uint8Array) || assetId.length !== 32) throw new Error('asset_id 32');
  if (!(merkleRoot instanceof Uint8Array) || merkleRoot.length !== 32) throw new Error('merkle_root 32');
  const cap = BigInt(capAmount);
  const per = BigInt(perClaim);
  const capLE = new Uint8Array(8);
  {
    const v = new DataView(capLE.buffer);
    v.setUint32(0, Number(cap & 0xffffffffn), true);
    v.setUint32(4, Number((cap >> 32n) & 0xffffffffn), true);
  }
  const perLE = new Uint8Array(8);
  {
    const v = new DataView(perLE.buffer);
    v.setUint32(0, Number(per & 0xffffffffn), true);
    v.setUint32(4, Number((per >> 32n) & 0xffffffffn), true);
  }
  const expLE = new Uint8Array(4); new DataView(expLE.buffer).setUint32(0, Number(expiryHeight) >>> 0, true);
  const aicByte = new Uint8Array([assetInputCount & 0xff]);
  const inputsBytes = [];
  if (!Array.isArray(assetInputs) || assetInputs.length !== assetInputCount) {
    throw new Error('assetInputs.length must equal assetInputCount');
  }
  for (const inp of assetInputs) {
    if (typeof inp.txid !== 'string' || !/^[0-9a-f]{64}$/i.test(inp.txid)) throw new Error('input.txid 64-hex');
    if (!Number.isInteger(inp.vout) || inp.vout < 0 || inp.vout > 0xffffffff) throw new Error('input.vout u32');
    inputsBytes.push(reverseBytes(hexToBytes(inp.txid)));
    const voutLE = new Uint8Array(4); new DataView(voutLE.buffer).setUint32(0, inp.vout >>> 0, true);
    inputsBytes.push(voutLE);
  }
  return sha256(concatBytes(
    new TextEncoder().encode('tacit-drop-v1'),
    assetId, capLE, perLE, merkleRoot, expLE, aicByte,
    ...inputsBytes,
  ));
}

// Reclaim msg for the T_DROP per_claim=0 sentinel shape (SPEC §5.12.1).
// Signed under the original depositor's x-only pubkey, binds the reclaim
// to a specific original drop_id AND the exact remaining cap_amount the
// indexer canonically owes back.
function dropReclaimMsg({ reclaimDropId, assetId, capAmount }) {
  if (!(reclaimDropId instanceof Uint8Array) || reclaimDropId.length !== 32) throw new Error('reclaim_drop_id 32');
  if (!(assetId instanceof Uint8Array) || assetId.length !== 32) throw new Error('asset_id 32');
  const cap = BigInt(capAmount);
  const capLE = new Uint8Array(8);
  {
    const v = new DataView(capLE.buffer);
    v.setUint32(0, Number(cap & 0xffffffffn), true);
    v.setUint32(4, Number((cap >> 32n) & 0xffffffffn), true);
  }
  return sha256(concatBytes(
    new TextEncoder().encode('tacit-drop-reclaim-v1'),
    reclaimDropId, assetId, capLE,
  ));
}

// ============== MIXER POOL (T_DEPOSIT / T_WITHDRAW) ==============
// SPEC §5.10 / §5.11. Two new opcodes implement a Tornado-Cash-style
// shielded pool over any tacit asset:
//
//   T_DEPOSIT  — consume a UTXO of denomination `D` into pool `(asset_id, D)`.
//                The depositor's leaf is poseidon(secret, nullifier_preimage, D).
//                Two payload shapes share opcode 0x29: a `denomination = 0`
//                sentinel marks a POOL_INIT (declares a pool's vk + ceremony
//                CIDs); any `denomination > 0` is a standard deposit.
//
//   T_WITHDRAW — anonymously mint a fresh UTXO of denomination `D` to a
//                recipient pubkey, gated on a Groth16 proof against the pool
//                merkle tree. Public inputs: merkle_root, nullifier_hash,
//                denomination, recipient_commitment.x|y, bind_hash.
//
// Pool state (registry, merkle trees, nullifier sets) is maintained by a
// chain-scan path keyed off canonical chain order — NOT by validateOutpoint,
// which can be called in arbitrary orders during ancestry walks.

// Encode a standard deposit (denomination > 0) payload.
//   T_DEPOSIT(1) || asset_id(32) || denomination(8 LE)
//                || leaf_commitment(32) || kernel_sig(64). Total: 137 bytes.
function encodeTDepositPayload({ assetId, denomination, leafCommitment, kernelSig }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (leafCommitment.length !== 32) throw new Error('leaf_commitment 32 bytes');
  if (kernelSig.length !== 64) throw new Error('kernel_sig 64 bytes');
  const d = BigInt(denomination);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denomination out of range');
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  return concatBytes(new Uint8Array([T_DEPOSIT]), assetId, denomLE, leafCommitment, kernelSig);
}

// Encode a POOL_INIT (denomination = 0 sentinel) payload.
//   T_DEPOSIT(1) || asset_id(32) || denomination(8 = 0)
//                || pool_denom(8 LE) || vk_cid_len(1) || vk_cid
//                || ceremony_cid_len(1) || ceremony_cid || init_sig(64)
function encodeTPoolInitPayload({ assetId, poolDenom, vkCid, ceremonyCid, initSig }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (initSig.length !== 64) throw new Error('init_sig 64 bytes');
  const d = BigInt(poolDenom);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('pool_denom out of range');
  const vkBytes = (typeof vkCid === 'string') ? new TextEncoder().encode(vkCid) : vkCid;
  const ceBytes = (typeof ceremonyCid === 'string') ? new TextEncoder().encode(ceremonyCid) : ceremonyCid;
  if (vkBytes.length < 1 || vkBytes.length > 64) throw new Error('vk_cid len 1..64');
  if (ceBytes.length < 1 || ceBytes.length > 64) throw new Error('ceremony_cid len 1..64');
  const denomZero = new Uint8Array(8);
  const poolDenomLE = new Uint8Array(8);
  {
    const v = new DataView(poolDenomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  return concatBytes(
    new Uint8Array([T_DEPOSIT]),
    assetId, denomZero,
    poolDenomLE,
    new Uint8Array([vkBytes.length]), vkBytes,
    new Uint8Array([ceBytes.length]), ceBytes,
    initSig,
  );
}

// Decode either a standard deposit or a POOL_INIT envelope. Returned shape's
// `kind` is 'deposit' or 'pool_init'.
function decodeTDepositPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_DEPOSIT) return null;
  if (payload.length < 1 + 32 + 8) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomination = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomination === 0n) {
    // POOL_INIT sentinel
    if (payload.length < p + 8 + 1) return null;
    const pdView = new DataView(payload.buffer, payload.byteOffset + p, 8);
    const poolDenom = (BigInt(pdView.getUint32(4, true)) << 32n) | BigInt(pdView.getUint32(0, true));
    p += 8;
    if (poolDenom <= 0n || poolDenom >= (1n << BigInt(N_BITS))) return null;
    if (p + 1 > payload.length) return null;
    const vkLen = payload[p]; p += 1;
    if (vkLen < 1 || vkLen > 64) return null;
    if (p + vkLen > payload.length) return null;
    const vkCid = payload.slice(p, p + vkLen); p += vkLen;
    if (p + 1 > payload.length) return null;
    const ceLen = payload[p]; p += 1;
    if (ceLen < 1 || ceLen > 64) return null;
    if (p + ceLen > payload.length) return null;
    const ceremonyCid = payload.slice(p, p + ceLen); p += ceLen;
    if (p + 64 !== payload.length) return null;
    const initSig = payload.slice(p, p + 64); p += 64;
    return { kind: 'pool_init', assetId, poolDenom, vkCid, ceremonyCid, initSig };
  }
  // Standard deposit
  if (payload.length !== 1 + 32 + 8 + 32 + 64) return null;
  if (denomination >= (1n << BigInt(N_BITS))) return null;
  const leafCommitment = payload.slice(p, p + 32); p += 32;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  return { kind: 'deposit', assetId, denomination, leafCommitment, kernelSig };
}

// Encode a withdraw envelope.
//   T_WITHDRAW(1) || asset_id(32) || denomination(8) || merkle_root(32)
//                 || nullifier_hash(32) || recipient_commitment(33)
//                 || r_leaf(32) || bind_hash(32)
//                 || proof_len(2 LE) || proof(proof_len)
//
// SPEC §5.11. r_leaf is a public Pedersen blinding scalar deterministically
// derived in-circuit from (secret, nullifier_preimage). Validator does an
// external secp256k1 Pedersen check: pedersenCommit(denomination, r_leaf)
// == recipient_commitment. Closes the inflation-attack vector documented
// in SPEC §5.11.1.
function encodeTWithdrawPayload({ assetId, denomination, merkleRoot, nullifierHash, recipientCommitment, rLeaf, bindHash, proof }) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (merkleRoot.length !== 32) throw new Error('merkle_root 32 bytes');
  if (nullifierHash.length !== 32) throw new Error('nullifier_hash 32 bytes');
  if (recipientCommitment.length !== 33) throw new Error('recipient_commitment 33 bytes');
  if (rLeaf.length !== 32) throw new Error('r_leaf 32 bytes');
  if (bindHash.length !== 32) throw new Error('bind_hash 32 bytes');
  if (proof.length === 0 || proof.length > 0xffff) throw new Error('proof len 1..65535');
  const d = BigInt(denomination);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denomination out of range');
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const proofLen = new Uint8Array(2);
  new DataView(proofLen.buffer).setUint16(0, proof.length, true);
  return concatBytes(
    new Uint8Array([T_WITHDRAW]),
    assetId, denomLE, merkleRoot, nullifierHash, recipientCommitment,
    rLeaf, bindHash, proofLen, proof,
  );
}

function decodeTWithdrawPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_WITHDRAW) return null;
  const HEADER = 1 + 32 + 8 + 32 + 32 + 33 + 32 + 32 + 2;
  if (payload.length < HEADER) return null;
  let p = 1;
  const assetId = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomination = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomination <= 0n || denomination >= (1n << BigInt(N_BITS))) return null;
  const merkleRoot = payload.slice(p, p + 32); p += 32;
  const nullifierHash = payload.slice(p, p + 32); p += 32;
  const recipientCommitment = payload.slice(p, p + 33); p += 33;
  const rLeaf = payload.slice(p, p + 32); p += 32;
  const bindHash = payload.slice(p, p + 32); p += 32;
  const proofLen = new DataView(payload.buffer, payload.byteOffset + p, 2).getUint16(0, true);
  p += 2;
  if (proofLen === 0) return null;
  if (p + proofLen !== payload.length) return null;
  const proof = payload.slice(p, p + proofLen);
  // Re-derive bind_hash and check consistency. SPEC §5.11: bind_hash MUST
  // equal SHA256(WITHDRAW_BIND_DOMAIN || asset_id || denom_LE || nullifier_hash || recipient_commitment || r_leaf).
  const expected = computeWithdrawBindHash(assetId, denomination, nullifierHash, recipientCommitment, rLeaf);
  for (let i = 0; i < 32; i++) if (expected[i] !== bindHash[i]) return null;
  return {
    kind: 'withdraw',
    assetId, denomination, merkleRoot, nullifierHash,
    recipientCommitment, rLeaf, bindHash, proof,
  };
}

// ============== SLOT WRAPPER (T_SLOT_MINT / T_SLOT_BURN / T_SLOT_ROTATE) ==============
// SPEC-CBTC-ZK-AMENDMENT §5.21–§5.23. Self-custody slot wrapper:
//   K_btc = recipient_commit − denomination · H = r_leaf · G
// Anyone who can withdraw the mixer note (knows r_leaf) can spend the slot UTXO.
// No federation, no co-signer, no escape path. Lost notes lock backing BTC
// permanently — same property native Bitcoin has.

const SLOT_MINT_DOMAIN    = new TextEncoder().encode('tacit-slot-mint-v1');
const SLOT_ROTATE_DOMAIN  = new TextEncoder().encode('tacit-slot-rotate-v1');
const SLOT_SPLIT_DOMAIN   = new TextEncoder().encode('tacit-slot-split-v1');
const SLOT_MERGE_DOMAIN   = new TextEncoder().encode('tacit-slot-merge-v1');
// Domain tag for the v2 BTC-spending-key derivation. r_btc = Poseidon₂(
// secret, ν || "btc"), separate from r_pedersen = Poseidon₂(secret, ν). The
// two scalars are computationally independent (inverting Poseidon is hard),
// so revealing r_pedersen at fractionalize does NOT compromise r_btc. The
// suffix is appended to the nullifier-preimage input before hashing.
const SLOT_BTC_KEY_DOMAIN = new TextEncoder().encode('tacit-slot-btc-key-v1');

function deriveSlotKbtc(recipientCommitmentBytes, denomination) {
  if (!(recipientCommitmentBytes instanceof Uint8Array) || recipientCommitmentBytes.length !== 33) {
    throw new Error('recipient_commitment must be 33 bytes');
  }
  const recipientPoint = bytesToPoint(recipientCommitmentBytes);
  const denomBig = BigInt(denomination);
  const denomTimesH = denomBig === 0n ? ZERO : H.multiply(modN(denomBig));
  return recipientPoint.add(denomTimesH.negate());
}
function slotXOnly(kBtcPoint) {
  return kBtcPoint.toRawBytes(true).slice(1);
}
function slotScriptPubKeyFromKbtc(kBtcPoint) {
  return p2trScript(slotXOnly(kBtcPoint));
}

// Canonical slot_mint_msg per SPEC-CBTC-ZK §5.21 (revised: §5.24.0 amount-
// amendment two-key fix folded in). Single shape, single domain tag —
// k_btc_xonly is always part of the signed preimage. cBTC.zk hasn't shipped
// to mainnet yet, so there's no v1 single-key envelope to maintain
// backward-compat with; the original single-key derivation was flagged
// fractionalize-unsafe and never made it past test fixtures.
function computeSlotMintMsg(networkTag, assetId, denomination, recipientCommit, leafHash, paymentAssetId, paymentAmount, kBtcXOnly) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (recipientCommit.length !== 33) throw new Error('recipient_commit 33 bytes');
  if (leafHash.length !== 32) throw new Error('leaf_hash 32 bytes');
  if (paymentAssetId.length !== 32) throw new Error('payment_asset_id 32 bytes');
  if (!(kBtcXOnly instanceof Uint8Array) || kBtcXOnly.length !== 32) {
    throw new Error('k_btc_xonly must be 32 bytes (explicit BTC spending key per §5.24.0)');
  }
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    const d = BigInt(denomination);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const payLE = new Uint8Array(8);
  {
    const v = new DataView(payLE.buffer);
    const p = BigInt(paymentAmount);
    v.setUint32(0, Number(p & 0xffffffffn), true);
    v.setUint32(4, Number((p >> 32n) & 0xffffffffn), true);
  }
  const parts = [
    SLOT_MINT_DOMAIN, new Uint8Array([networkTag & 0xff]),
    assetId, denomLE, recipientCommit, leafHash, paymentAssetId, payLE,
    kBtcXOnly,
  ];
  return sha256(concatBytes(...parts));
}

// SPEC-CBTC-ZK-AMOUNT-AMENDMENT §5.24.0: derive the two-key slot's BTC
// spending scalar from the mixer note's (secret, ν). Domain-separated from
// the Pedersen blinding r_pedersen = Poseidon₂(secret, ν) so the two scalars
// are computationally independent. Inverting Poseidon to recover r_btc from
// r_pedersen alone is hard (Poseidon's one-wayness).
function deriveSlotRBtc(secretBytes, nullifierPreimageBytes) {
  if (secretBytes.length !== 32 || nullifierPreimageBytes.length !== 32) {
    throw new Error('secret + nullifier_preimage must each be 32 bytes');
  }
  // Use SHA256 over (domain || secret || ν) instead of Poseidon₃ because
  // Poseidon₃ requires circomlibjs setup the dapp avoids at this layer.
  // The cryptographic property we need (Poseidon₂(secret, ν) and
  // h(secret, ν) computationally independent) holds under random-oracle
  // assumption for SHA256 vs Poseidon₂ over distinct domain tags.
  const out = sha256(concatBytes(
    SLOT_BTC_KEY_DOMAIN, secretBytes, nullifierPreimageBytes,
  ));
  // Reduce into secp256k1 scalar field (n_secp ~ 2^256, output ~ 2^256, so
  // reduction is ~50% probability of trim — random within the field).
  let bn = bytes32ToBigint(out) % SECP_N;
  if (bn === 0n) bn = 1n;
  return bigintToBytes32(bn);
}

// Deterministic cBTC.tac variant asset_id per denomination tier.
// Mirrors the worker's ctacVariantAssetId; both sides MUST compute the
// same value byte-for-byte or holdings/transfers diverge silently.
const CTAC_VARIANT_DOMAIN = new TextEncoder().encode('tacit-cbtc-tac-variant-v1');
function ctacVariantAssetId(denomSats) {
  const denomLE = new Uint8Array(8);
  const v = new DataView(denomLE.buffer);
  const d = BigInt(denomSats);
  v.setUint32(0, Number(d & 0xffffffffn), true);
  v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  return bytesToHex(sha256(concatBytes(CTAC_VARIANT_DOMAIN, denomLE)));
}

// §5.24.0 + §5.23: rotate_msg binds the NEW slot's k_btc_xonly so the old
// owner attests to the new BTC spending key. Two-key: K_btc is independent
// from recipient_commit, so we must publish + sign it explicitly.
function computeSlotRotateMsg(networkTag, assetId, denomination, oldNullifierHash, newRecipientCommit, newLeafHash, paymentAssetId, paymentAmount, newKBtcXOnly) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (oldNullifierHash.length !== 32) throw new Error('old_nullifier_hash 32 bytes');
  if (newRecipientCommit.length !== 33) throw new Error('new_recipient_commit 33 bytes');
  if (newLeafHash.length !== 32) throw new Error('new_leaf_hash 32 bytes');
  if (paymentAssetId.length !== 32) throw new Error('payment_asset_id 32 bytes');
  if (!(newKBtcXOnly instanceof Uint8Array) || newKBtcXOnly.length !== 32) {
    throw new Error('new_k_btc_xonly must be 32 bytes (§5.24.0 two-key)');
  }
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    const d = BigInt(denomination);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const payLE = new Uint8Array(8);
  {
    const v = new DataView(payLE.buffer);
    const p = BigInt(paymentAmount);
    v.setUint32(0, Number(p & 0xffffffffn), true);
    v.setUint32(4, Number((p >> 32n) & 0xffffffffn), true);
  }
  return sha256(concatBytes(
    SLOT_ROTATE_DOMAIN, new Uint8Array([networkTag & 0xff]),
    assetId, denomLE, oldNullifierHash,
    newRecipientCommit, newLeafHash, paymentAssetId, payLE,
    newKBtcXOnly,
  ));
}

// SPEC-CBTC-ZK §5.21 (with §5.24.0 two-key foundation folded in). Canonical
// 276-byte payload — k_btc_xonly is mandatory. cBTC.zk hasn't shipped to
// mainnet yet, so there's no legacy single-key variant to maintain back-
// compat with. The original recipient_commit-derived K_btc scheme was
// flagged fractionalize-unsafe and never made it past test fixtures.
//
// Reviewer-noted alternative: a `mixer_fractionalize` circuit that keeps the
// single-key derivation but treats r_leaf as a private witness. Academically
// cleaner crypto but requires a new trusted-setup ceremony. Deferred as a
// future v1.x amendment.
function encodeTSlotMintPayload({ networkTag, assetId, denomination, recipientCommit, leafHash, paymentAssetId, paymentAmount, minterPubkey, minterSig, kBtcXOnly, encryptedNote = null }) {
  if ((networkTag & 0xff) > 2) throw new Error('network_tag must be 0|1|2');
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (recipientCommit.length !== 33) throw new Error('recipient_commit 33 bytes');
  if (leafHash.length !== 32) throw new Error('leaf_hash 32 bytes');
  if (paymentAssetId.length !== 32) throw new Error('payment_asset_id 32 bytes (zeros if no payment)');
  if (minterPubkey.length !== 33) throw new Error('minter_pubkey 33 bytes');
  if (minterSig.length !== 64) throw new Error('minter_sig 64 bytes');
  if (!(kBtcXOnly instanceof Uint8Array) || kBtcXOnly.length !== 32) {
    throw new Error('k_btc_xonly must be 32 bytes (explicit BTC spending key per §5.24.0)');
  }
  const d = BigInt(denomination);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denomination out of range');
  const pAmt = BigInt(paymentAmount);
  if (pAmt < 0n || pAmt >= (1n << BigInt(N_BITS))) throw new Error('payment_amount out of range');
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const payLE = new Uint8Array(8);
  {
    const v = new DataView(payLE.buffer);
    v.setUint32(0, Number(pAmt & 0xffffffffn), true);
    v.setUint32(4, Number((pAmt >> 32n) & 0xffffffffn), true);
  }
  const parts = [
    new Uint8Array([T_SLOT_MINT, networkTag & 0xff]),
    assetId, denomLE,
    recipientCommit, leafHash,
    paymentAssetId, payLE,
    minterPubkey, minterSig,
    kBtcXOnly,
  ];
  // §5.26.4 optional encrypted-note tail (mint paid distribution: minter
  // encrypts (secret, ν) to the recipient's viewing key so the recipient's
  // dapp can scan-and-claim without out-of-band coordination).
  if (encryptedNote !== null) {
    if (encryptedNote === false || encryptedNote === 0) {
      parts.push(new Uint8Array([0x00]));
    } else {
      if (!(encryptedNote instanceof Uint8Array) || encryptedNote.length !== 122) {
        throw new Error('encryptedNote must be a 122-byte Uint8Array (or null/false)');
      }
      parts.push(new Uint8Array([0x01]), encryptedNote);
    }
  }
  return concatBytes(...parts);
}

function decodeTSlotMintPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_SLOT_MINT) return null;
  // Canonical 276-byte payload — k_btc_xonly is mandatory.
  // §5.26.4 optional note tail allows 277 (has_note=0) or 399 (has_note=1+122).
  if (payload.length !== 276 && payload.length !== 277 && payload.length !== 399) return null;
  let p = 1;
  const networkTag = payload[p]; p += 1;
  if (networkTag > 2) return null;
  const assetId = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomination = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomination <= 0n || denomination >= (1n << BigInt(N_BITS))) return null;
  const recipientCommit = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(recipientCommit); } catch { return null; }
  const leafHash = payload.slice(p, p + 32); p += 32;
  const paymentAssetId = payload.slice(p, p + 32); p += 32;
  const payView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const paymentAmount = (BigInt(payView.getUint32(4, true)) << 32n) | BigInt(payView.getUint32(0, true));
  p += 8;
  if (paymentAmount >= (1n << BigInt(N_BITS))) return null;
  const minterPubkey = payload.slice(p, p + 33); p += 33;
  const minterSig = payload.slice(p, p + 64); p += 64;
  const kBtcXOnly = payload.slice(p, p + 32); p += 32;
  // §5.26.4 optional note tail.
  let encryptedNote = null;
  if (payload.length === 277) {
    if (payload[p] !== 0x00) return null;
  } else if (payload.length === 399) {
    if (payload[p] !== 0x01) return null;
    encryptedNote = payload.slice(p + 1, p + 1 + 122);
  }
  return {
    kind: 'slot_mint',
    networkTag, assetId, denomination,
    recipientCommit, leafHash,
    paymentAssetId, paymentAmount,
    minterPubkey, minterSig,
    kBtcXOnly,
    encryptedNote,
  };
}

function encodeTSlotBurnPayload({ networkTag, assetId, denomination, merkleRoot, nullifierHash, recipientCommitment, rLeaf, bindHash, proof }) {
  if ((networkTag & 0xff) > 2) throw new Error('network_tag must be 0|1|2');
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (merkleRoot.length !== 32) throw new Error('merkle_root 32 bytes');
  if (nullifierHash.length !== 32) throw new Error('nullifier_hash 32 bytes');
  if (recipientCommitment.length !== 33) throw new Error('recipient_commitment 33 bytes');
  if (rLeaf.length !== 32) throw new Error('r_leaf 32 bytes');
  if (bindHash.length !== 32) throw new Error('bind_hash 32 bytes');
  if (proof.length === 0 || proof.length > 0xffff) throw new Error('proof len 1..65535');
  const d = BigInt(denomination);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denomination out of range');
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const proofLen = new Uint8Array(2);
  new DataView(proofLen.buffer).setUint16(0, proof.length, true);
  return concatBytes(
    new Uint8Array([T_SLOT_BURN, networkTag & 0xff]),
    assetId, denomLE,
    merkleRoot, nullifierHash, recipientCommitment, rLeaf, bindHash,
    proofLen, proof,
  );
}

function decodeTSlotBurnPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_SLOT_BURN) return null;
  const HEADER = 1 + 1 + 32 + 8 + 32 + 32 + 33 + 32 + 32 + 2;
  if (payload.length < HEADER) return null;
  let p = 1;
  const networkTag = payload[p]; p += 1;
  if (networkTag > 2) return null;
  const assetId = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomination = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomination <= 0n || denomination >= (1n << BigInt(N_BITS))) return null;
  const merkleRoot = payload.slice(p, p + 32); p += 32;
  const nullifierHash = payload.slice(p, p + 32); p += 32;
  const recipientCommitment = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(recipientCommitment); } catch { return null; }
  const rLeaf = payload.slice(p, p + 32); p += 32;
  const bindHash = payload.slice(p, p + 32); p += 32;
  const proofLen = new DataView(payload.buffer, payload.byteOffset + p, 2).getUint16(0, true);
  p += 2;
  if (proofLen === 0) return null;
  if (p + proofLen !== payload.length) return null;
  const proof = payload.slice(p, p + proofLen);
  const expected = computeWithdrawBindHash(assetId, denomination, nullifierHash, recipientCommitment, rLeaf);
  for (let i = 0; i < 32; i++) if (expected[i] !== bindHash[i]) return null;
  return {
    kind: 'slot_burn',
    networkTag, assetId, denomination,
    merkleRoot, nullifierHash, recipientCommitment, rLeaf, bindHash, proof,
  };
}

function encodeTSlotRotatePayload({
  networkTag, assetId, denomination,
  oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof,
  newRecipientCommit, newLeafHash, newKBtcXOnly,
  paymentAssetId, paymentAmount,
  oldOwnerPubkey, oldOwnerSig,
}) {
  if ((networkTag & 0xff) > 2) throw new Error('network_tag must be 0|1|2');
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (oldMerkleRoot.length !== 32) throw new Error('old_merkle_root 32 bytes');
  if (oldNullifierHash.length !== 32) throw new Error('old_nullifier_hash 32 bytes');
  if (oldRecipientCommitment.length !== 33) throw new Error('old_recipient_commitment 33 bytes');
  if (oldRLeaf.length !== 32) throw new Error('old_r_leaf 32 bytes');
  if (oldBindHash.length !== 32) throw new Error('old_bind_hash 32 bytes');
  if (oldProof.length === 0 || oldProof.length > 0xffff) throw new Error('old_proof len 1..65535');
  if (newRecipientCommit.length !== 33) throw new Error('new_recipient_commit 33 bytes');
  if (newLeafHash.length !== 32) throw new Error('new_leaf_hash 32 bytes');
  if (!(newKBtcXOnly instanceof Uint8Array) || newKBtcXOnly.length !== 32) {
    throw new Error('new_k_btc_xonly must be 32 bytes (§5.24.0 two-key — explicit BTC spending key for new slot)');
  }
  if (paymentAssetId.length !== 32) throw new Error('payment_asset_id 32 bytes (zeros if no payment)');
  if (oldOwnerPubkey.length !== 33) throw new Error('old_owner_pubkey 33 bytes');
  if (oldOwnerSig.length !== 64) throw new Error('old_owner_sig 64 bytes');
  const d = BigInt(denomination);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denomination out of range');
  const pAmt = BigInt(paymentAmount);
  if (pAmt < 0n || pAmt >= (1n << BigInt(N_BITS))) throw new Error('payment_amount out of range');
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const payLE = new Uint8Array(8);
  {
    const v = new DataView(payLE.buffer);
    v.setUint32(0, Number(pAmt & 0xffffffffn), true);
    v.setUint32(4, Number((pAmt >> 32n) & 0xffffffffn), true);
  }
  const oldProofLen = new Uint8Array(2);
  new DataView(oldProofLen.buffer).setUint16(0, oldProof.length, true);
  return concatBytes(
    new Uint8Array([T_SLOT_ROTATE, networkTag & 0xff]),
    assetId, denomLE,
    oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash,
    oldProofLen, oldProof,
    newRecipientCommit, newLeafHash, newKBtcXOnly,
    paymentAssetId, payLE,
    oldOwnerPubkey, oldOwnerSig,
  );
}

function decodeTSlotRotatePayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_SLOT_ROTATE) return null;
  const HEADER = 1 + 1 + 32 + 8;
  if (payload.length < HEADER + 32 + 32 + 33 + 32 + 32 + 2) return null;
  let p = 1;
  const networkTag = payload[p]; p += 1;
  if (networkTag > 2) return null;
  const assetId = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomination = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomination <= 0n || denomination >= (1n << BigInt(N_BITS))) return null;
  const oldMerkleRoot = payload.slice(p, p + 32); p += 32;
  const oldNullifierHash = payload.slice(p, p + 32); p += 32;
  const oldRecipientCommitment = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(oldRecipientCommitment); } catch { return null; }
  const oldRLeaf = payload.slice(p, p + 32); p += 32;
  const oldBindHash = payload.slice(p, p + 32); p += 32;
  const oldProofLen = new DataView(payload.buffer, payload.byteOffset + p, 2).getUint16(0, true);
  p += 2;
  if (oldProofLen === 0) return null;
  // SPEC-CBTC-ZK-FUNGIBILITY §5.26: payload MAY carry an optional encrypted-
  // note tail: 1-byte `has_note` (0x00 or 0x01) + 122-byte note if 0x01.
  // Accept all three lengths; reject any other.
  // Wire layout (§5.24.0 two-key): host payload now includes a 32-byte
  // new_k_btc_xonly field right after new_leaf_hash. hostEnd factors in
  // that extra 32.
  const hostEnd = p + oldProofLen + 33 + 32 + 32 + 32 + 8 + 33 + 64;
  let encryptedNote = null;
  if (payload.length === hostEnd) {
    // canonical, no tail
  } else if (payload.length === hostEnd + 1 && payload[hostEnd] === 0x00) {
    // explicit has_note=0
  } else if (payload.length === hostEnd + 1 + 122 && payload[hostEnd] === 0x01) {
    encryptedNote = payload.slice(hostEnd + 1, hostEnd + 1 + 122);
  } else {
    return null;
  }
  const oldProof = payload.slice(p, p + oldProofLen); p += oldProofLen;
  const expectedOldBind = computeWithdrawBindHash(assetId, denomination, oldNullifierHash, oldRecipientCommitment, oldRLeaf);
  for (let i = 0; i < 32; i++) if (expectedOldBind[i] !== oldBindHash[i]) return null;
  const newRecipientCommit = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(newRecipientCommit); } catch { return null; }
  const newLeafHash = payload.slice(p, p + 32); p += 32;
  const newKBtcXOnly = payload.slice(p, p + 32); p += 32;
  const paymentAssetId = payload.slice(p, p + 32); p += 32;
  const payView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const paymentAmount = (BigInt(payView.getUint32(4, true)) << 32n) | BigInt(payView.getUint32(0, true));
  p += 8;
  if (paymentAmount >= (1n << BigInt(N_BITS))) return null;
  const oldOwnerPubkey = payload.slice(p, p + 33); p += 33;
  const oldOwnerSig = payload.slice(p, p + 64); p += 64;
  return {
    kind: 'slot_rotate',
    networkTag, assetId, denomination,
    oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof,
    newRecipientCommit, newLeafHash, newKBtcXOnly,
    paymentAssetId, paymentAmount,
    oldOwnerPubkey, oldOwnerSig,
    encryptedNote,
  };
}

// SPEC-CBTC-ZK-FUNGIBILITY-AMENDMENT §5.24 — T_SLOT_SPLIT.
// Atomically consumes one slot of denom D_old and produces N new slots
// whose denominations sum to D_old (Bitcoin pays its own miner fee from
// the difference). Each new slot has fresh (secret_i, ν_i) generated by
// the splitter; the splitter holds them if self-fungibility, or encrypts
// to recipient viewing keys via §5.26 notes for paid distribution. The
// old r_leaf becomes public (revealed on chain) — the old slot is
// REDEEMED and can never be reused.
function computeSlotSplitMsg(networkTag, assetIdOld, denomOld, oldNullifierHash, outputs) {
  if (assetIdOld.length !== 32) throw new Error('asset_id_old 32 bytes');
  if (oldNullifierHash.length !== 32) throw new Error('old_nullifier_hash 32 bytes');
  if (!Array.isArray(outputs) || outputs.length < 2 || outputs.length > 16) {
    throw new Error('outputs must be an array of 2..16');
  }
  const denomOldLE = new Uint8Array(8);
  {
    const v = new DataView(denomOldLE.buffer);
    const d = BigInt(denomOld);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const parts = [
    SLOT_SPLIT_DOMAIN, new Uint8Array([networkTag & 0xff]),
    assetIdOld, denomOldLE, oldNullifierHash,
    new Uint8Array([outputs.length & 0xff]),
  ];
  for (const o of outputs) {
    if (!(o.assetIdNew instanceof Uint8Array) || o.assetIdNew.length !== 32) {
      throw new Error('each output.assetIdNew must be 32 bytes');
    }
    if (!(o.newRecipientCommit instanceof Uint8Array) || o.newRecipientCommit.length !== 33) {
      throw new Error('each output.newRecipientCommit must be 33 bytes');
    }
    if (!(o.newLeafHash instanceof Uint8Array) || o.newLeafHash.length !== 32) {
      throw new Error('each output.newLeafHash must be 32 bytes');
    }
    const dn = BigInt(o.denomNew);
    if (dn <= 0n || dn >= (1n << BigInt(N_BITS))) throw new Error('output denom_new out of range');
    const denomNewLE = new Uint8Array(8);
    {
      const v = new DataView(denomNewLE.buffer);
      v.setUint32(0, Number(dn & 0xffffffffn), true);
      v.setUint32(4, Number((dn >> 32n) & 0xffffffffn), true);
    }
    parts.push(o.assetIdNew, denomNewLE, o.newRecipientCommit, o.newLeafHash);
  }
  return sha256(concatBytes(...parts));
}

function encodeTSlotSplitPayload({
  networkTag, assetIdOld, denomOld,
  oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof,
  outputs,                              // array of { assetIdNew, denomNew, newRecipientCommit, newLeafHash }
  oldOwnerPubkey, oldOwnerSig,
  encryptedNotes = null,                // optional array length === outputs.length;
                                        // each element either null (no note for that
                                        // output) or 122-byte Uint8Array; if every
                                        // element is null, emits bitmap-only tail.
                                        // Pass null to omit the tail entirely.
}) {
  if ((networkTag & 0xff) > 2) throw new Error('network_tag must be 0|1|2');
  if (assetIdOld.length !== 32) throw new Error('asset_id_old 32 bytes');
  if (oldMerkleRoot.length !== 32) throw new Error('old_merkle_root 32 bytes');
  if (oldNullifierHash.length !== 32) throw new Error('old_nullifier_hash 32 bytes');
  if (oldRecipientCommitment.length !== 33) throw new Error('old_recipient_commitment 33 bytes');
  if (oldRLeaf.length !== 32) throw new Error('old_r_leaf 32 bytes');
  if (oldBindHash.length !== 32) throw new Error('old_bind_hash 32 bytes');
  if (oldProof.length === 0 || oldProof.length > 0xffff) throw new Error('old_proof len 1..65535');
  if (!Array.isArray(outputs) || outputs.length < 2 || outputs.length > 16) {
    throw new Error('outputs must be an array of 2..16');
  }
  if (oldOwnerPubkey.length !== 33) throw new Error('old_owner_pubkey 33 bytes');
  if (oldOwnerSig.length !== 64) throw new Error('old_owner_sig 64 bytes');
  const d = BigInt(denomOld);
  if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('denom_old out of range');
  const denomOldLE = new Uint8Array(8);
  {
    const v = new DataView(denomOldLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const oldProofLen = new Uint8Array(2);
  new DataView(oldProofLen.buffer).setUint16(0, oldProof.length, true);
  const parts = [
    new Uint8Array([T_SLOT_SPLIT, networkTag & 0xff]),
    assetIdOld, denomOldLE,
    oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash,
    oldProofLen, oldProof,
    new Uint8Array([outputs.length & 0xff]),
  ];
  // §5.24.6 cross-asset-id rule: caller must ensure all new asset_ids declare
  // the same underlying + peg as the old. Encoder does not check metadata
  // (that's a wrapper-registry lookup at validation time); it only emits the
  // bytes the validator will verify.
  for (const o of outputs) {
    if (!(o.assetIdNew instanceof Uint8Array) || o.assetIdNew.length !== 32) {
      throw new Error('output.assetIdNew must be 32 bytes');
    }
    if (!(o.newRecipientCommit instanceof Uint8Array) || o.newRecipientCommit.length !== 33) {
      throw new Error('output.newRecipientCommit must be 33 bytes');
    }
    if (!(o.newLeafHash instanceof Uint8Array) || o.newLeafHash.length !== 32) {
      throw new Error('output.newLeafHash must be 32 bytes');
    }
    const dn = BigInt(o.denomNew);
    if (dn <= 0n || dn >= (1n << BigInt(N_BITS))) throw new Error('output denom_new out of range');
    const denomNewLE = new Uint8Array(8);
    {
      const v = new DataView(denomNewLE.buffer);
      v.setUint32(0, Number(dn & 0xffffffffn), true);
      v.setUint32(4, Number((dn >> 32n) & 0xffffffffn), true);
    }
    parts.push(o.assetIdNew, denomNewLE, o.newRecipientCommit, o.newLeafHash);
  }
  parts.push(oldOwnerPubkey, oldOwnerSig);
  // §5.26.4 optional encrypted-notes tail. Layout when present:
  //   has_note_per_output:  ⌈n/8⌉ bytes  (LSB first; bit i = note for output i)
  //   encrypted_note[k]:    122 bytes per output with has_note bit set
  if (encryptedNotes !== null) {
    if (!Array.isArray(encryptedNotes) || encryptedNotes.length !== outputs.length) {
      throw new Error('encryptedNotes must be an array of length === outputs.length (or null to omit tail)');
    }
    const bitmapBytes = Math.ceil(outputs.length / 8);
    const bitmap = new Uint8Array(bitmapBytes);
    const notes = [];
    for (let i = 0; i < encryptedNotes.length; i++) {
      const note = encryptedNotes[i];
      if (note === null) continue;
      if (!(note instanceof Uint8Array) || note.length !== 122) {
        throw new Error(`encryptedNotes[${i}] must be null or a 122-byte Uint8Array`);
      }
      bitmap[Math.floor(i / 8)] |= 1 << (i % 8);
      notes.push(note);
    }
    parts.push(bitmap, ...notes);
  }
  return concatBytes(...parts);
}

function decodeTSlotSplitPayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_SLOT_SPLIT) return null;
  // Minimum size with n=2 outputs + 1-byte proof:
  // opcode(1) + network_tag(1) + asset_id_old(32) + denom_old_LE(8)
  // + old_merkle_root(32) + old_nullifier_hash(32) + old_recipient_commit(33)
  // + old_r_leaf(32) + old_bind_hash(32) + old_proof_length(2) + min proof(1)
  // + n_outputs(1) + 2 outputs(2*105) + pubkey(33) + sig(64) = 304 + 1
  const FIXED_PRE_PROOF = 1 + 1 + 32 + 8 + 32 + 32 + 33 + 32 + 32 + 2;
  if (payload.length < FIXED_PRE_PROOF + 1 + 1 + 2 * 105 + 33 + 64) return null;
  let p = 1;
  const networkTag = payload[p]; p += 1;
  if (networkTag > 2) return null;
  const assetIdOld = payload.slice(p, p + 32); p += 32;
  const denomView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomOld = (BigInt(denomView.getUint32(4, true)) << 32n) | BigInt(denomView.getUint32(0, true));
  p += 8;
  if (denomOld <= 0n || denomOld >= (1n << BigInt(N_BITS))) return null;
  const oldMerkleRoot = payload.slice(p, p + 32); p += 32;
  const oldNullifierHash = payload.slice(p, p + 32); p += 32;
  const oldRecipientCommitment = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(oldRecipientCommitment); } catch { return null; }
  const oldRLeaf = payload.slice(p, p + 32); p += 32;
  const oldBindHash = payload.slice(p, p + 32); p += 32;
  const oldProofLen = new DataView(payload.buffer, payload.byteOffset + p, 2).getUint16(0, true);
  p += 2;
  if (oldProofLen === 0) return null;
  if (p + oldProofLen + 1 + 2 * 105 + 33 + 64 > payload.length) return null;
  const oldProof = payload.slice(p, p + oldProofLen); p += oldProofLen;
  // Bind-hash check: reuses tacit-withdraw-bind-v1 domain per §5.24.3 (full
  // T_SLOT_BURN-equivalent validation of old leaf, minus the BTC payout step).
  const expectedOldBind = computeWithdrawBindHash(assetIdOld, denomOld, oldNullifierHash, oldRecipientCommitment, oldRLeaf);
  for (let i = 0; i < 32; i++) if (expectedOldBind[i] !== oldBindHash[i]) return null;
  const nOutputs = payload[p]; p += 1;
  if (nOutputs < 2 || nOutputs > 16) return null;
  // Validate length tolerating optional §5.26.4 notes tail.
  const hostEnd = p + nOutputs * 105 + 33 + 64;
  if (hostEnd > payload.length) return null;
  let sumDenomNew = 0n;
  const outputs = [];
  for (let i = 0; i < nOutputs; i++) {
    const assetIdNew = payload.slice(p, p + 32); p += 32;
    const dnView = new DataView(payload.buffer, payload.byteOffset + p, 8);
    const denomNew = (BigInt(dnView.getUint32(4, true)) << 32n) | BigInt(dnView.getUint32(0, true));
    p += 8;
    if (denomNew <= 0n || denomNew >= (1n << BigInt(N_BITS))) return null;
    // §5.24.6 cross-asset rule: each output wrapper MUST be the canonical
    // self-custody variant for its own denomination. This permits re-tiering
    // within the family (1M → 10×100k, each a valid variant) but rejects
    // relabeling the slot's BTC-backed value onto a foreign or wrong-denom
    // asset. The input is canonical by mint construction (slots mint at
    // asset_id = ctacVariantAssetId(denom)); the family shares one underlying.
    if (bytesToHex(assetIdNew) !== ctacVariantAssetId(denomNew)) return null;
    const newRecipientCommit = payload.slice(p, p + 33); p += 33;
    try { bytesToPoint(newRecipientCommit); } catch { return null; }
    const newLeafHash = payload.slice(p, p + 32); p += 32;
    sumDenomNew += denomNew;
    outputs.push({ assetIdNew, denomNew, newRecipientCommit, newLeafHash });
  }
  // §5.24.3 conservation check: denom_old ≥ Σ denom_new (Bitcoin pays its own
  // fee from the difference). Equality means user funded the Bitcoin fee from
  // a separate vin[1+]; strict inequality means the fee comes from the slot's
  // own value.
  if (sumDenomNew > denomOld) return null;
  const oldOwnerPubkey = payload.slice(p, p + 33); p += 33;
  const oldOwnerSig = payload.slice(p, p + 64); p += 64;
  // §5.26.4 optional encrypted-notes tail:
  //   has_note_per_output: ⌈n/8⌉ bytes (LSB-first bitmap)
  //   encrypted_note[k]:   122 bytes per output with has_note bit set
  let encryptedNotes = null;
  if (payload.length > p) {
    const bitmapBytes = Math.ceil(nOutputs / 8);
    if (p + bitmapBytes > payload.length) return null;
    const bitmap = payload.slice(p, p + bitmapBytes); p += bitmapBytes;
    // Reject bitmap bits set beyond nOutputs (would be ambiguous).
    if (nOutputs % 8 !== 0) {
      const lastByteMask = (1 << (nOutputs % 8)) - 1;
      if ((bitmap[bitmapBytes - 1] & ~lastByteMask) !== 0) return null;
    }
    let notesCount = 0;
    for (let i = 0; i < bitmapBytes; i++) {
      let b = bitmap[i];
      while (b) { notesCount += b & 1; b >>>= 1; }
    }
    if (p + notesCount * 122 !== payload.length) return null;
    encryptedNotes = new Array(nOutputs).fill(null);
    for (let i = 0; i < nOutputs; i++) {
      const bit = (bitmap[Math.floor(i / 8)] >> (i % 8)) & 1;
      if (bit) {
        encryptedNotes[i] = payload.slice(p, p + 122);
        p += 122;
      }
    }
  }
  return {
    kind: 'slot_split',
    networkTag, assetIdOld, denomOld,
    oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof,
    nOutputs, outputs,
    oldOwnerPubkey, oldOwnerSig,
    encryptedNotes,
  };
}

// SPEC-CBTC-ZK-FUNGIBILITY-AMENDMENT §5.25 — T_SLOT_MERGE.
// Structural inverse of SPLIT: atomically consumes N (2..16) old slots
// and produces one new slot. Each old r_leaf revealed on chain. The
// new slot's (secret_new, ν_new) is generated by whoever constructs
// the envelope (the receiving owner). Multi-owner merges (§5.25.4)
// require each contributor to sign vin[i] under SIGHASH_ALL; the
// new_owner_sig binds the destination terms collectively.
function computeSlotMergeMsg(networkTag, inputs, assetIdNew, denomNew, newRecipientCommit, newLeafHash) {
  if (!Array.isArray(inputs) || inputs.length < 2 || inputs.length > 16) {
    throw new Error('inputs must be an array of 2..16');
  }
  if (assetIdNew.length !== 32) throw new Error('asset_id_new 32 bytes');
  if (newRecipientCommit.length !== 33) throw new Error('new_recipient_commit 33 bytes');
  if (newLeafHash.length !== 32) throw new Error('new_leaf_hash 32 bytes');
  const denomNewLE = new Uint8Array(8);
  {
    const v = new DataView(denomNewLE.buffer);
    const dn = BigInt(denomNew);
    v.setUint32(0, Number(dn & 0xffffffffn), true);
    v.setUint32(4, Number((dn >> 32n) & 0xffffffffn), true);
  }
  const parts = [
    SLOT_MERGE_DOMAIN, new Uint8Array([networkTag & 0xff]),
    new Uint8Array([inputs.length & 0xff]),
  ];
  for (const inp of inputs) {
    if (!(inp.assetIdOld instanceof Uint8Array) || inp.assetIdOld.length !== 32) {
      throw new Error('each input.assetIdOld must be 32 bytes');
    }
    if (!(inp.oldNullifierHash instanceof Uint8Array) || inp.oldNullifierHash.length !== 32) {
      throw new Error('each input.oldNullifierHash must be 32 bytes');
    }
    const d = BigInt(inp.denomOld);
    if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('input denom_old out of range');
    const denomOldLE = new Uint8Array(8);
    {
      const v = new DataView(denomOldLE.buffer);
      v.setUint32(0, Number(d & 0xffffffffn), true);
      v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
    }
    parts.push(inp.assetIdOld, denomOldLE, inp.oldNullifierHash);
  }
  parts.push(assetIdNew, denomNewLE, newRecipientCommit, newLeafHash);
  return sha256(concatBytes(...parts));
}

function encodeTSlotMergePayload({
  networkTag,
  inputs,                              // array of { assetIdOld, denomOld, oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof }
  assetIdNew, denomNew, newRecipientCommit, newLeafHash,
  newOwnerPubkey, newOwnerSig,
  encryptedNote = null,                // optional 122-byte SPEC-CBTC-ZK-FUNGIBILITY §5.26 note
}) {
  if ((networkTag & 0xff) > 2) throw new Error('network_tag must be 0|1|2');
  if (!Array.isArray(inputs) || inputs.length < 2 || inputs.length > 16) {
    throw new Error('inputs must be an array of 2..16');
  }
  if (assetIdNew.length !== 32) throw new Error('asset_id_new 32 bytes');
  if (newRecipientCommit.length !== 33) throw new Error('new_recipient_commit 33 bytes');
  if (newLeafHash.length !== 32) throw new Error('new_leaf_hash 32 bytes');
  if (newOwnerPubkey.length !== 33) throw new Error('new_owner_pubkey 33 bytes');
  if (newOwnerSig.length !== 64) throw new Error('new_owner_sig 64 bytes');
  const dn = BigInt(denomNew);
  if (dn <= 0n || dn >= (1n << BigInt(N_BITS))) throw new Error('denom_new out of range');
  const denomNewLE = new Uint8Array(8);
  {
    const v = new DataView(denomNewLE.buffer);
    v.setUint32(0, Number(dn & 0xffffffffn), true);
    v.setUint32(4, Number((dn >> 32n) & 0xffffffffn), true);
  }
  const parts = [
    new Uint8Array([T_SLOT_MERGE, networkTag & 0xff]),
    new Uint8Array([inputs.length & 0xff]),
  ];
  // Per-input fixed bytes (without proof): 32+8+32+32+33+32+32+2 = 203
  for (const inp of inputs) {
    if (!(inp.assetIdOld instanceof Uint8Array) || inp.assetIdOld.length !== 32) {
      throw new Error('input.assetIdOld must be 32 bytes');
    }
    if (!(inp.oldMerkleRoot instanceof Uint8Array) || inp.oldMerkleRoot.length !== 32) {
      throw new Error('input.oldMerkleRoot must be 32 bytes');
    }
    if (!(inp.oldNullifierHash instanceof Uint8Array) || inp.oldNullifierHash.length !== 32) {
      throw new Error('input.oldNullifierHash must be 32 bytes');
    }
    if (!(inp.oldRecipientCommitment instanceof Uint8Array) || inp.oldRecipientCommitment.length !== 33) {
      throw new Error('input.oldRecipientCommitment must be 33 bytes');
    }
    if (!(inp.oldRLeaf instanceof Uint8Array) || inp.oldRLeaf.length !== 32) {
      throw new Error('input.oldRLeaf must be 32 bytes');
    }
    if (!(inp.oldBindHash instanceof Uint8Array) || inp.oldBindHash.length !== 32) {
      throw new Error('input.oldBindHash must be 32 bytes');
    }
    if (!(inp.oldProof instanceof Uint8Array) || inp.oldProof.length === 0 || inp.oldProof.length > 0xffff) {
      throw new Error('input.oldProof must be 1..65535 bytes');
    }
    const d = BigInt(inp.denomOld);
    if (d <= 0n || d >= (1n << BigInt(N_BITS))) throw new Error('input denom_old out of range');
    const denomOldLE = new Uint8Array(8);
    {
      const v = new DataView(denomOldLE.buffer);
      v.setUint32(0, Number(d & 0xffffffffn), true);
      v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
    }
    const proofLen = new Uint8Array(2);
    new DataView(proofLen.buffer).setUint16(0, inp.oldProof.length, true);
    parts.push(
      inp.assetIdOld, denomOldLE,
      inp.oldMerkleRoot, inp.oldNullifierHash, inp.oldRecipientCommitment,
      inp.oldRLeaf, inp.oldBindHash,
      proofLen, inp.oldProof,
    );
  }
  parts.push(assetIdNew, denomNewLE, newRecipientCommit, newLeafHash);
  parts.push(newOwnerPubkey, newOwnerSig);
  // §5.26.4 optional encrypted-note tail. Three valid post-host layouts:
  //   (a) no tail               — historical / no recipient detection wanted
  //   (b) has_note=0 (1 byte)   — explicit "no note" marker
  //   (c) has_note=1 (1+122)    — note for the new slot
  if (encryptedNote === null) {
    // emit (a) — no tail
  } else if (encryptedNote === false || encryptedNote === 0) {
    parts.push(new Uint8Array([0x00]));
  } else {
    if (!(encryptedNote instanceof Uint8Array) || encryptedNote.length !== 122) {
      throw new Error('encryptedNote must be a 122-byte Uint8Array (or null/false)');
    }
    parts.push(new Uint8Array([0x01]), encryptedNote);
  }
  return concatBytes(...parts);
}

function decodeTSlotMergePayload(payload) {
  if (!payload) return null;
  if (payload[0] !== T_SLOT_MERGE) return null;
  // Minimum: opcode(1) + net(1) + n_inputs(1) + 2 inputs(2*(203+1 min proof))
  // + asset_id_new(32) + denom_new(8) + new_recipient_commit(33) + new_leaf_hash(32)
  // + new_owner_pubkey(33) + new_owner_sig(64).
  const PER_INPUT_FIXED = 32 + 8 + 32 + 32 + 33 + 32 + 32 + 2;
  const POST_INPUTS = 32 + 8 + 33 + 32 + 33 + 64;
  if (payload.length < 1 + 1 + 1 + 2 * (PER_INPUT_FIXED + 1) + POST_INPUTS) return null;
  let p = 1;
  const networkTag = payload[p]; p += 1;
  if (networkTag > 2) return null;
  const nInputs = payload[p]; p += 1;
  if (nInputs < 2 || nInputs > 16) return null;
  const inputs = [];
  let sumDenomOld = 0n;
  for (let i = 0; i < nInputs; i++) {
    if (p + PER_INPUT_FIXED + 1 + POST_INPUTS > payload.length) return null;
    const assetIdOld = payload.slice(p, p + 32); p += 32;
    const dView = new DataView(payload.buffer, payload.byteOffset + p, 8);
    const denomOld = (BigInt(dView.getUint32(4, true)) << 32n) | BigInt(dView.getUint32(0, true));
    p += 8;
    if (denomOld <= 0n || denomOld >= (1n << BigInt(N_BITS))) return null;
    const oldMerkleRoot = payload.slice(p, p + 32); p += 32;
    const oldNullifierHash = payload.slice(p, p + 32); p += 32;
    const oldRecipientCommitment = payload.slice(p, p + 33); p += 33;
    try { bytesToPoint(oldRecipientCommitment); } catch { return null; }
    const oldRLeaf = payload.slice(p, p + 32); p += 32;
    const oldBindHash = payload.slice(p, p + 32); p += 32;
    const proofLen = new DataView(payload.buffer, payload.byteOffset + p, 2).getUint16(0, true);
    p += 2;
    if (proofLen === 0) return null;
    if (p + proofLen + POST_INPUTS > payload.length) return null;
    const oldProof = payload.slice(p, p + proofLen); p += proofLen;
    // Bind-hash recompute per §5.25.3 (each input is full T_SLOT_BURN-equivalent).
    const expectedBind = computeWithdrawBindHash(assetIdOld, denomOld, oldNullifierHash, oldRecipientCommitment, oldRLeaf);
    for (let j = 0; j < 32; j++) if (expectedBind[j] !== oldBindHash[j]) return null;
    sumDenomOld += denomOld;
    inputs.push({
      assetIdOld, denomOld, oldMerkleRoot, oldNullifierHash, oldRecipientCommitment,
      oldRLeaf, oldBindHash, oldProof,
    });
  }
  // §5.26.4 optional note tail — allow hostEnd, hostEnd+1, hostEnd+123.
  const hostEnd = p + POST_INPUTS;
  let encryptedNote = null;
  if (payload.length === hostEnd) {
    // canonical, no tail
  } else if (payload.length === hostEnd + 1 && payload[hostEnd] === 0x00) {
    // explicit has_note=0
  } else if (payload.length === hostEnd + 1 + 122 && payload[hostEnd] === 0x01) {
    encryptedNote = payload.slice(hostEnd + 1, hostEnd + 1 + 122);
  } else {
    return null;
  }
  const assetIdNew = payload.slice(p, p + 32); p += 32;
  const dnView = new DataView(payload.buffer, payload.byteOffset + p, 8);
  const denomNew = (BigInt(dnView.getUint32(4, true)) << 32n) | BigInt(dnView.getUint32(0, true));
  p += 8;
  if (denomNew <= 0n || denomNew >= (1n << BigInt(N_BITS))) return null;
  // §5.24.6 cross-asset rule (MERGE): the output wrapper MUST be the canonical
  // self-custody variant for its denomination — re-tiering within the family is
  // allowed, relabeling onto a foreign/wrong-denom asset is rejected.
  if (bytesToHex(assetIdNew) !== ctacVariantAssetId(denomNew)) return null;
  const newRecipientCommit = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(newRecipientCommit); } catch { return null; }
  const newLeafHash = payload.slice(p, p + 32); p += 32;
  // §5.25.3 conservation: Σ denom_old ≥ denom_new (Bitcoin fee from difference).
  if (sumDenomOld < denomNew) return null;
  const newOwnerPubkey = payload.slice(p, p + 33); p += 33;
  const newOwnerSig = payload.slice(p, p + 64); p += 64;
  return {
    kind: 'slot_merge',
    networkTag, nInputs, inputs,
    assetIdNew, denomNew, newRecipientCommit, newLeafHash,
    newOwnerPubkey, newOwnerSig,
    encryptedNote,
  };
}

// T_SLOT_FRACTIONALIZE / T_SLOT_RECONSOLIDATE wire format and builders deferred.
// The unbonded fractionalize path is not shipping on mainnet; arbitrary-amount
// wrapped BTC is tacBTC, minted against cBTC.zk Bitcoin locks + CollateralEngine
// ETH escrow under the fixed CBTC_ZK_ASSET_ID. See SPEC-CBTC-ZK-AMOUNT-AMENDMENT.md
// for the cryptographic machinery (Pedersen sum identity, two-key construction,
// share commit semantics).

// SPEC-CBTC-ZK §5.21 + §5.24.0 builder. The two-key derivation: r_pedersen
// is the standard mixer Poseidon(secret, ν) used as the leaf's Pedersen
// blinding; r_btc is a separate scalar derived from the same (secret, ν)
// via a distinct domain tag. K_btc = r_btc · G is the BTC spending key,
// independent of the Pedersen commitment. This lets r_pedersen be revealed
// safely at fractionalize time without compromising the slot's BTC.
async function buildSlotMintEnvelope({
  networkTag, assetId, denomination,
  secret, nullifierPreimage,
  paymentAssetId, paymentAmount,
  minterPriv,
}) {
  if (secret.length !== 32) throw new Error('secret 32 bytes');
  if (nullifierPreimage.length !== 32) throw new Error('nullifier_preimage 32 bytes');
  const leafCommitment = computePoolLeafCommitment(secret, nullifierPreimage, denomination);
  const rPedersenBytes = poseidonHash(secret, nullifierPreimage);
  const rPedersenBig = bytes32ToBigint(rPedersenBytes) % SECP_N;
  const recipientCommit = pedersenCommit(BigInt(denomination), rPedersenBig).toRawBytes(true);
  // Derive the independent BTC spending key. K_btc = r_btc · G is published
  // as an explicit envelope field; recipient_commit no longer determines it.
  const rBtcBytes = deriveSlotRBtc(secret, nullifierPreimage);
  const rBtcBig = bytes32ToBigint(rBtcBytes) % SECP_N;
  const kBtcPoint = G.multiply(rBtcBig === 0n ? 1n : rBtcBig);
  const kBtcXOnly = slotXOnly(kBtcPoint);
  const slotSpk = slotScriptPubKeyFromKbtc(kBtcPoint);
  const minterPubkey = secp.getPublicKey(minterPriv, true);
  const minterMsg = computeSlotMintMsg(
    networkTag, assetId, denomination, recipientCommit, leafCommitment,
    paymentAssetId, paymentAmount, kBtcXOnly,
  );
  const minterSig = signSchnorr(minterMsg, minterPriv);
  const payload = encodeTSlotMintPayload({
    networkTag, assetId, denomination,
    recipientCommit, leafHash: leafCommitment,
    paymentAssetId, paymentAmount,
    minterPubkey, minterSig, kBtcXOnly,
  });
  return {
    payload,
    K_btc: kBtcPoint,
    slotScriptPubKey: slotSpk,
    recipientCommit,
    // Legacy "rLeaf" naming retained for callers (= r_pedersen); rBtc is the
    // new field for the BTC spending key.
    rLeaf: rPedersenBytes,
    rPedersen: rPedersenBytes,
    rBtc: rBtcBytes,
    slotRecord: {
      assetIdHex: bytesToHex(assetId),
      denomination: BigInt(denomination).toString(),
      secretHex: bytesToHex(secret),
      nullifierPreimageHex: bytesToHex(nullifierPreimage),
      leafCommitmentHex: bytesToHex(leafCommitment),
      recipientCommitHex: bytesToHex(recipientCommit),
      rLeafHex: bytesToHex(rPedersenBytes),       // alias for r_pedersen
      rPedersenHex: bytesToHex(rPedersenBytes),
      rBtcHex: bytesToHex(rBtcBytes),
      kBtcXOnlyHex: bytesToHex(kBtcXOnly),
      slotScriptPubKeyHex: bytesToHex(slotSpk),
      mintedAt: Date.now(),
    },
  };
}

async function buildSlotBurnEnvelope({ networkTag, slotRecord, merkleRoot, proof }) {
  const assetId = hexToBytes(slotRecord.assetIdHex);
  const denomination = BigInt(slotRecord.denomination);
  const secret = hexToBytes(slotRecord.secretHex);
  const nullifierPreimage = hexToBytes(slotRecord.nullifierPreimageHex);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const rLeaf = poseidonHash(secret, nullifierPreimage);
  const rLeafBigint = bytes32ToBigint(rLeaf) % SECP_N;
  const recipientCommitment = pedersenCommit(denomination, rLeafBigint).toRawBytes(true);
  const bindHash = computeWithdrawBindHash(assetId, denomination, nullifierHash, recipientCommitment, rLeaf);
  const payload = encodeTSlotBurnPayload({
    networkTag, assetId, denomination, merkleRoot, nullifierHash,
    recipientCommitment, rLeaf, bindHash, proof,
  });
  return {
    payload,
    rLeaf,
    rLeafBigint,
    recipientCommitment,
    nullifierHash,
  };
}

async function buildSlotRotateEnvelope({
  networkTag,
  oldSlotRecord, oldMerkleRoot, oldProof,
  newSecret, newNullifierPreimage,
  paymentAssetId, paymentAmount,
  oldOwnerPriv,
}) {
  if (newSecret.length !== 32) throw new Error('new_secret 32 bytes');
  if (newNullifierPreimage.length !== 32) throw new Error('new_nullifier_preimage 32 bytes');
  const assetId = hexToBytes(oldSlotRecord.assetIdHex);
  const denomination = BigInt(oldSlotRecord.denomination);
  const oldSecret = hexToBytes(oldSlotRecord.secretHex);
  const oldNullifierPreimage = hexToBytes(oldSlotRecord.nullifierPreimageHex);
  const oldNullifierHash = computeNullifierHash(oldNullifierPreimage);
  const oldRLeaf = poseidonHash(oldSecret, oldNullifierPreimage);
  const oldRLeafBigint = bytes32ToBigint(oldRLeaf) % SECP_N;
  const oldRecipientCommitment = pedersenCommit(denomination, oldRLeafBigint).toRawBytes(true);
  const oldBindHash = computeWithdrawBindHash(assetId, denomination, oldNullifierHash, oldRecipientCommitment, oldRLeaf);
  const newLeafCommitment = computePoolLeafCommitment(newSecret, newNullifierPreimage, denomination);
  const newRLeaf = poseidonHash(newSecret, newNullifierPreimage);   // = r_pedersen for the new slot
  const newRLeafBigint = bytes32ToBigint(newRLeaf) % SECP_N;
  const newRecipientCommit = pedersenCommit(denomination, newRLeafBigint).toRawBytes(true);
  // §5.24.0 two-key: derive the new slot's r_btc independently from
  // (newSecret, newNullifierPreimage). K_btc = r_btc · G is the new BTC
  // spending key, not derived from recipient_commit.
  const newRBtcBytes = deriveSlotRBtc(newSecret, newNullifierPreimage);
  const newRBtcBig = bytes32ToBigint(newRBtcBytes) % SECP_N;
  const newKBtcPoint = G.multiply(newRBtcBig === 0n ? 1n : newRBtcBig);
  const newSlotSpk = slotScriptPubKeyFromKbtc(newKBtcPoint);
  const oldOwnerPubkey = secp.getPublicKey(oldOwnerPriv, true);
  const newKBtcXOnly = slotXOnly(newKBtcPoint);
  const rotateMsg = computeSlotRotateMsg(
    networkTag, assetId, denomination, oldNullifierHash,
    newRecipientCommit, newLeafCommitment, paymentAssetId, paymentAmount,
    newKBtcXOnly,
  );
  const oldOwnerSig = signSchnorr(rotateMsg, oldOwnerPriv);
  const payload = encodeTSlotRotatePayload({
    networkTag, assetId, denomination,
    oldMerkleRoot, oldNullifierHash, oldRecipientCommitment, oldRLeaf, oldBindHash, oldProof,
    newRecipientCommit, newLeafHash: newLeafCommitment, newKBtcXOnly,
    paymentAssetId, paymentAmount,
    oldOwnerPubkey, oldOwnerSig,
  });
  return {
    payload,
    oldRLeaf,
    oldRLeafBigint,
    newSlotKbtc: newKBtcPoint,
    newSlotScriptPubKey: newSlotSpk,
    newRecipientCommit,
    newSlotRecord: {
      assetIdHex: bytesToHex(assetId),
      denomination: denomination.toString(),
      secretHex: bytesToHex(newSecret),
      nullifierPreimageHex: bytesToHex(newNullifierPreimage),
      leafCommitmentHex: bytesToHex(newLeafCommitment),
      recipientCommitHex: bytesToHex(newRecipientCommit),
      rLeafHex: bytesToHex(newRLeaf),               // = r_pedersen
      rPedersenHex: bytesToHex(newRLeaf),
      rBtcHex: bytesToHex(newRBtcBytes),
      kBtcXOnlyHex: bytesToHex(slotXOnly(newKBtcPoint)),
      slotScriptPubKeyHex: bytesToHex(newSlotSpk),
      mintedAt: Date.now(),
      rotatedFromNullifier: bytesToHex(oldNullifierHash),
    },
  };
}

// SPEC-CBTC-ZK-FUNGIBILITY-AMENDMENT §5.24 T_SLOT_SPLIT envelope builder.
// Atomic 1→N split of a cBTC.zk slot: consumes one old slot and produces
// 2..16 new slots whose denominations sum ≤ denom_old (the difference funds
// the Bitcoin miner fee, OR the user funds the fee from a separate vin).
// Each new slot has fresh (secret_i, ν_i) generated here unless the caller
// supplies one; the slotRecords returned contain the full recovery material.
async function buildSlotSplitEnvelope({
  networkTag,
  oldSlotRecord,
  oldMerkleRoot,
  oldProof,
  outputs,                       // array of { assetIdHex?, denomNew, secret?, nullifierPreimage? }
                                 // assetIdHex defaults to old slot's; secret/ν generated if omitted
  oldOwnerPriv,
  encryptedNotes = null,         // optional array length === outputs.length; passed through
                                 // to encodeTSlotSplitPayload's §5.26.4 tail
}) {
  if (!Array.isArray(outputs) || outputs.length < 2 || outputs.length > 16) {
    throw new Error('outputs must be an array of 2..16');
  }
  const oldAssetId = hexToBytes(oldSlotRecord.assetIdHex);
  const oldDenom = BigInt(oldSlotRecord.denomination);
  const oldSecret = hexToBytes(oldSlotRecord.secretHex);
  const oldNullifierPreimage = hexToBytes(oldSlotRecord.nullifierPreimageHex);
  const oldNullifierHash = computeNullifierHash(oldNullifierPreimage);
  const oldRLeaf = poseidonHash(oldSecret, oldNullifierPreimage);
  const oldRLeafBig = bytes32ToBigint(oldRLeaf) % SECP_N;
  const oldRecipientCommitment = pedersenCommit(oldDenom, oldRLeafBig).toRawBytes(true);
  const oldBindHash = computeWithdrawBindHash(
    oldAssetId, oldDenom, oldNullifierHash, oldRecipientCommitment, oldRLeaf,
  );

  const newSlotRecords = [];
  const envelopeOutputs = [];
  let sumDenomNew = 0n;
  for (let i = 0; i < outputs.length; i++) {
    const out = outputs[i];
    const denomNew = BigInt(out.denomNew);
    if (denomNew <= 0n || denomNew >= (1n << BigInt(N_BITS))) {
      throw new Error(`outputs[${i}].denomNew out of range`);
    }
    sumDenomNew += denomNew;
    // §5.24.6: an output wrapper is the canonical self-custody variant for its
    // OWN denomination — default to it (re-tiering within the family), not the
    // input's asset. A caller-supplied asset must satisfy the same binding or
    // the envelope is dead-on-arrival (the decoder rejects it).
    const assetIdNew = out.assetIdHex ? hexToBytes(out.assetIdHex) : hexToBytes(ctacVariantAssetId(denomNew));
    if (assetIdNew.length !== 32) throw new Error(`outputs[${i}].assetIdHex must be 64 hex chars`);
    if (bytesToHex(assetIdNew) !== ctacVariantAssetId(denomNew)) {
      throw new Error(`outputs[${i}].assetIdHex must equal ctacVariantAssetId(denomNew) per §5.24.6`);
    }
    const secret = out.secret
      || (() => { const b = new Uint8Array(32); crypto.getRandomValues(b); return b; })();
    const nullifierPreimage = out.nullifierPreimage
      || (() => { const b = new Uint8Array(32); crypto.getRandomValues(b); return b; })();
    if (secret.length !== 32 || nullifierPreimage.length !== 32) {
      throw new Error(`outputs[${i}] secret/nullifierPreimage must each be 32 bytes`);
    }
    const newLeafHash = computePoolLeafCommitment(secret, nullifierPreimage, denomNew);
    const newRLeaf = poseidonHash(secret, nullifierPreimage);
    const newRLeafBig = bytes32ToBigint(newRLeaf) % SECP_N;
    const newRecipientCommit = pedersenCommit(denomNew, newRLeafBig).toRawBytes(true);
    const newRBtcBytes = deriveSlotRBtc(secret, nullifierPreimage);
    const newRBtcBig = bytes32ToBigint(newRBtcBytes) % SECP_N;
    const newKBtcPoint = G.multiply(newRBtcBig === 0n ? 1n : newRBtcBig);
    const newSlotSpk = slotScriptPubKeyFromKbtc(newKBtcPoint);
    envelopeOutputs.push({
      assetIdNew, denomNew, newRecipientCommit, newLeafHash,
    });
    newSlotRecords.push({
      assetIdHex: bytesToHex(assetIdNew),
      denomination: denomNew.toString(),
      secretHex: bytesToHex(secret),
      nullifierPreimageHex: bytesToHex(nullifierPreimage),
      leafCommitmentHex: bytesToHex(newLeafHash),
      recipientCommitHex: bytesToHex(newRecipientCommit),
      rLeafHex: bytesToHex(newRLeaf),
      rPedersenHex: bytesToHex(newRLeaf),
      rBtcHex: bytesToHex(newRBtcBytes),
      kBtcXOnlyHex: bytesToHex(slotXOnly(newKBtcPoint)),
      slotScriptPubKeyHex: bytesToHex(newSlotSpk),
      slotScriptPubKey: newSlotSpk,
      mintedAt: Date.now(),
      splitFromNullifier: bytesToHex(oldNullifierHash),
      splitVoutIndex: i,
    });
  }
  if (sumDenomNew > oldDenom) {
    throw new Error(
      `Σ denom_new (${sumDenomNew}) > denom_old (${oldDenom}) — §5.24.3 conservation`,
    );
  }

  const oldOwnerPubkey = secp.getPublicKey(oldOwnerPriv, true);
  const splitMsg = computeSlotSplitMsg(
    networkTag, oldAssetId, oldDenom, oldNullifierHash, envelopeOutputs,
  );
  const oldOwnerSig = signSchnorr(splitMsg, oldOwnerPriv);

  const payload = encodeTSlotSplitPayload({
    networkTag,
    assetIdOld: oldAssetId,
    denomOld: oldDenom,
    oldMerkleRoot,
    oldNullifierHash,
    oldRecipientCommitment,
    oldRLeaf,
    oldBindHash,
    oldProof,
    outputs: envelopeOutputs,
    oldOwnerPubkey,
    oldOwnerSig,
    encryptedNotes,
  });
  return {
    payload,
    newSlotRecords,
    oldNullifierHash,
    oldRLeaf,
    sumDenomNew,
    feeFromSlot: oldDenom - sumDenomNew,    // sats the slot itself contributes to miner fee
  };
}

// SPEC-CBTC-ZK-FUNGIBILITY-AMENDMENT §5.25 T_SLOT_MERGE envelope builder.
// Atomic N→1 merge of cBTC.zk slots: consumes 2..16 old slots and produces
// one new slot at denom_new ≤ Σ denom_old. Each input contributes its own
// (secret, ν, merkleRoot, proof) for the burn-side validation; the new slot
// owner signs slot_merge_msg binding the destination terms collectively.
// For single-owner merges (the common case), oldSlotRecords[i] and
// newOwnerPriv are all the same wallet; for multi-owner merges, each old
// owner's r_btc signs their vin under SIGHASH_ALL (handled at buildAndBroadcast).
async function buildSlotMergeEnvelope({
  networkTag,
  oldSlotRecords,                  // array of N (2..16) slot records
  oldMerkleRoots,                  // array length N
  oldProofs,                       // array length N (Groth16 bytes per input)
  assetIdNewHex = null,            // default = first input's asset_id
  denomNew,                        // ≤ Σ denom_old
  newSecret = null,
  newNullifierPreimage = null,
  newOwnerPriv,
  encryptedNote = null,            // optional 122-byte SPEC §5.26 note for the new slot
}) {
  if (!Array.isArray(oldSlotRecords) || oldSlotRecords.length < 2 || oldSlotRecords.length > 16) {
    throw new Error('oldSlotRecords must be 2..16');
  }
  if (!Array.isArray(oldMerkleRoots) || oldMerkleRoots.length !== oldSlotRecords.length) {
    throw new Error('oldMerkleRoots count must match oldSlotRecords');
  }
  if (!Array.isArray(oldProofs) || oldProofs.length !== oldSlotRecords.length) {
    throw new Error('oldProofs count must match oldSlotRecords');
  }
  const dNew = BigInt(denomNew);
  if (dNew <= 0n || dNew >= (1n << BigInt(N_BITS))) {
    throw new Error('denomNew out of range');
  }

  let sumDenomOld = 0n;
  const inputsForMsg = [];
  const inputsForEnvelope = [];
  const inputNullifierHashes = [];
  for (let i = 0; i < oldSlotRecords.length; i++) {
    const rec = oldSlotRecords[i];
    const assetIdOld = hexToBytes(rec.assetIdHex);
    const denomOld = BigInt(rec.denomination);
    sumDenomOld += denomOld;
    const oldSecret = hexToBytes(rec.secretHex);
    const oldNullifierPreimage = hexToBytes(rec.nullifierPreimageHex);
    const oldNullifierHash = computeNullifierHash(oldNullifierPreimage);
    const oldRLeaf = poseidonHash(oldSecret, oldNullifierPreimage);
    const oldRLeafBig = bytes32ToBigint(oldRLeaf) % SECP_N;
    const oldRecipientCommitment = pedersenCommit(denomOld, oldRLeafBig).toRawBytes(true);
    const oldBindHash = computeWithdrawBindHash(
      assetIdOld, denomOld, oldNullifierHash, oldRecipientCommitment, oldRLeaf,
    );
    inputsForMsg.push({ assetIdOld, denomOld, oldNullifierHash });
    inputsForEnvelope.push({
      assetIdOld, denomOld,
      oldMerkleRoot: oldMerkleRoots[i],
      oldNullifierHash,
      oldRecipientCommitment,
      oldRLeaf,
      oldBindHash,
      oldProof: oldProofs[i],
    });
    inputNullifierHashes.push(oldNullifierHash);
  }
  if (sumDenomOld < dNew) {
    throw new Error(
      `Σ denom_old (${sumDenomOld}) < denom_new (${dNew}) — §5.25.3 conservation`,
    );
  }

  // §5.24.6: the merged output wrapper is the canonical self-custody variant
  // for its OWN denomination, not the first input's asset. A caller-supplied
  // asset must satisfy the same binding (the decoder rejects it otherwise).
  const aidNew = assetIdNewHex
    ? hexToBytes(assetIdNewHex)
    : hexToBytes(ctacVariantAssetId(dNew));
  if (aidNew.length !== 32) throw new Error('assetIdNewHex must be 64 hex chars');
  if (bytesToHex(aidNew) !== ctacVariantAssetId(dNew)) {
    throw new Error('assetIdNewHex must equal ctacVariantAssetId(denomNew) per §5.24.6');
  }
  const newSec = newSecret
    || (() => { const b = new Uint8Array(32); crypto.getRandomValues(b); return b; })();
  const newNu = newNullifierPreimage
    || (() => { const b = new Uint8Array(32); crypto.getRandomValues(b); return b; })();
  if (newSec.length !== 32 || newNu.length !== 32) {
    throw new Error('new (secret, ν) must each be 32 bytes');
  }
  const newLeafHash = computePoolLeafCommitment(newSec, newNu, dNew);
  const newRLeaf = poseidonHash(newSec, newNu);
  const newRLeafBig = bytes32ToBigint(newRLeaf) % SECP_N;
  const newRecipientCommit = pedersenCommit(dNew, newRLeafBig).toRawBytes(true);
  const newRBtcBytes = deriveSlotRBtc(newSec, newNu);
  const newRBtcBig = bytes32ToBigint(newRBtcBytes) % SECP_N;
  const newKBtcPoint = G.multiply(newRBtcBig === 0n ? 1n : newRBtcBig);
  const newSlotSpk = slotScriptPubKeyFromKbtc(newKBtcPoint);

  const newOwnerPubkey = secp.getPublicKey(newOwnerPriv, true);
  const mergeMsg = computeSlotMergeMsg(
    networkTag, inputsForMsg, aidNew, dNew, newRecipientCommit, newLeafHash,
  );
  const newOwnerSig = signSchnorr(mergeMsg, newOwnerPriv);

  const payload = encodeTSlotMergePayload({
    networkTag,
    inputs: inputsForEnvelope,
    assetIdNew: aidNew,
    denomNew: dNew,
    newRecipientCommit,
    newLeafHash,
    newOwnerPubkey,
    newOwnerSig,
    encryptedNote,
  });
  return {
    payload,
    newSlotKbtc: newKBtcPoint,
    newSlotScriptPubKey: newSlotSpk,
    newSlotRecord: {
      assetIdHex: bytesToHex(aidNew),
      denomination: dNew.toString(),
      secretHex: bytesToHex(newSec),
      nullifierPreimageHex: bytesToHex(newNu),
      leafCommitmentHex: bytesToHex(newLeafHash),
      recipientCommitHex: bytesToHex(newRecipientCommit),
      rLeafHex: bytesToHex(newRLeaf),
      rPedersenHex: bytesToHex(newRLeaf),
      rBtcHex: bytesToHex(newRBtcBytes),
      kBtcXOnlyHex: bytesToHex(slotXOnly(newKBtcPoint)),
      slotScriptPubKeyHex: bytesToHex(newSlotSpk),
      mintedAt: Date.now(),
      mergedFromNullifiers: inputNullifierHashes.map(h => bytesToHex(h)),
    },
    inputNullifierHashes,
    sumDenomOld,
    feeFromSlots: sumDenomOld - dNew,
  };
}

// ============== tETH BRIDGE (T_BRIDGE_DEPOSIT / T_BRIDGE_BURN / T_BRIDGE_ROTATE) ==============
// SPEC-TETH-BRIDGE-AMENDMENT §5.60–§5.63. Trustless ETH↔Tacit bridge using
// Tornado-shape mixer on Ethereum + ZK Bitcoin inclusion proof for withdrawal.

const T_BRIDGE_DEPOSIT = 0x60;
const T_BRIDGE_BURN    = 0x61;
const T_BRIDGE_ROTATE  = 0x62;
const T_BRIDGE_EXPORT  = 0x63;
const T_BRIDGE_IMPORT  = 0x64;

const BRIDGE_DEPOSIT_DOMAIN = new TextEncoder().encode('tacit-bridge-deposit-v1');
const BRIDGE_BURN_DOMAIN    = new TextEncoder().encode('tacit-bridge-burn-v1');
const BRIDGE_ROTATE_DOMAIN  = new TextEncoder().encode('tacit-bridge-rotate-v1');
const BRIDGE_EXPORT_DOMAIN  = new TextEncoder().encode('tacit-bridge-export-v1');
const BRIDGE_IMPORT_DOMAIN  = new TextEncoder().encode('tacit-bridge-import-v1');

const BN254_FIELD_SIZE = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;

function _reduceModField(hash32) {
  const raw = bytes32ToBigint(hash32);
  const reduced = raw % BN254_FIELD_SIZE;
  return bigintToBytes32(reduced);
}

// Each bind hash commits to (chain_id, mixer_address) — the generation the
// envelope is for. `gctx` selects that generation; default = the active one.
function computeBridgeDepositBindHash(networkTag, assetId, denomWei, ethRoot, nullifierHash, recipientCommit, leafHash, rLeaf, gctx) {
  const _g = gctx || TETH_BRIDGE;
  const chainId32 = bigintToBytes32Strict(BigInt(_g.chainId || 1));
  const mixerAddr = hexToBytes(_g.address.replace(/^0x/i, '').padStart(40, '0'));
  const raw = sha256(concatBytes(
    BRIDGE_DEPOSIT_DOMAIN,
    chainId32,
    mixerAddr,
    new Uint8Array([networkTag & 0xff]),
    assetId,
    denomWei,
    ethRoot,
    nullifierHash,
    recipientCommit,
    leafHash,
    rLeaf,
  ));
  return _reduceModField(raw);
}

function computeBridgeBurnBindHash(networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, ethRecipient, burnNonce, gctx) {
  const _g = gctx || TETH_BRIDGE;
  const chainId32 = bigintToBytes32Strict(BigInt(_g.chainId || 1));
  const mixerAddr = hexToBytes(_g.address.replace(/^0x/i, '').padStart(40, '0'));
  const raw = sha256(concatBytes(
    BRIDGE_BURN_DOMAIN,
    chainId32,
    mixerAddr,
    new Uint8Array([networkTag & 0xff]),
    assetId,
    denomWei,
    merkleRoot,
    nullifierHash,
    recipientCommit,
    rLeaf,
    ethRecipient,
    burnNonce,
  ));
  return _reduceModField(raw);
}

function computeBridgeRotateBindHash(networkTag, assetId, denomWei, merkleRoot, nullifierHash, newCommitment, rLeaf, gctx) {
  const _g = gctx || TETH_BRIDGE;
  const chainId32 = bigintToBytes32Strict(BigInt(_g.chainId || 1));
  const mixerAddr = hexToBytes(_g.address.replace(/^0x/i, '').padStart(40, '0'));
  const raw = sha256(concatBytes(
    BRIDGE_ROTATE_DOMAIN,
    chainId32,
    mixerAddr,
    new Uint8Array([networkTag & 0xff]),
    assetId,
    denomWei,
    merkleRoot,
    nullifierHash,
    newCommitment,
    rLeaf,
  ));
  return _reduceModField(raw);
}

function encodeTBridgeRotatePayload({ networkTag, assetId, denomWei, merkleRoot, nullifierHash, newCommitment, rLeaf, bindHash, proof }) {
  return concatBytes(
    new Uint8Array([T_BRIDGE_ROTATE, networkTag & 0xff]),
    assetId,          // 32
    denomWei,         // 32
    merkleRoot,       // 32
    nullifierHash,    // 32
    newCommitment,    // 32
    rLeaf,            // 32
    bindHash,         // 32
    new Uint8Array([proof.length & 0xff, (proof.length >> 8) & 0xff]),
    proof,            // 256
  );
}

function computeBridgeExportBindHash(networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, gctx) {
  const _g = gctx || TETH_BRIDGE;
  const chainId32 = bigintToBytes32Strict(BigInt(_g.chainId || 1));
  const mixerAddr = hexToBytes(_g.address.replace(/^0x/i, '').padStart(40, '0'));
  const raw = sha256(concatBytes(
    BRIDGE_EXPORT_DOMAIN, chainId32, mixerAddr,
    new Uint8Array([networkTag & 0xff]),
    assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf,
  ));
  return _reduceModField(raw);
}

function computeBridgeImportBindHash(networkTag, assetId, denomWei, newCommitment, prevTxid, prevVout, gctx) {
  const _g = gctx || TETH_BRIDGE;
  const chainId32 = bigintToBytes32Strict(BigInt(_g.chainId || 1));
  const mixerAddr = hexToBytes(_g.address.replace(/^0x/i, '').padStart(40, '0'));
  const voutBytes = new Uint8Array(2);
  voutBytes[0] = prevVout & 0xff; voutBytes[1] = (prevVout >> 8) & 0xff;
  const raw = sha256(concatBytes(
    BRIDGE_IMPORT_DOMAIN, chainId32, mixerAddr,
    new Uint8Array([networkTag & 0xff]),
    assetId, denomWei, newCommitment, prevTxid, voutBytes,
  ));
  return _reduceModField(raw);
}

function encodeTBridgeExportPayload({ networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, bindHash, proof }) {
  return concatBytes(
    new Uint8Array([T_BRIDGE_EXPORT, networkTag & 0xff]),
    assetId,          // 32
    denomWei,         // 32
    merkleRoot,       // 32
    nullifierHash,    // 32
    recipientCommit,  // 33
    rLeaf,            // 32
    bindHash,         // 32
    new Uint8Array([proof.length & 0xff, (proof.length >> 8) & 0xff]),
    proof,            // 256
  );
}

function encodeTBridgeImportPayload({ networkTag, assetId, denomWei, newCommitment, bindHash, prevTxid, prevVout }) {
  const voutBytes = new Uint8Array(2);
  voutBytes[0] = prevVout & 0xff; voutBytes[1] = (prevVout >> 8) & 0xff;
  return concatBytes(
    new Uint8Array([T_BRIDGE_IMPORT, networkTag & 0xff]),
    assetId,        // 32
    denomWei,       // 32
    newCommitment,  // 32
    bindHash,       // 32
    prevTxid,       // 32
    voutBytes,      // 2
  );
}

function encodeTBridgeDepositPayload({ networkTag, assetId, denomWei, ethRoot, nullifierHash, recipientCommit, leafHash, rLeaf, bindHash, proof }) {
  return concatBytes(
    new Uint8Array([T_BRIDGE_DEPOSIT, networkTag & 0xff]),
    assetId,         // 32
    denomWei,        // 32 (u256 LE)
    ethRoot,         // 32
    nullifierHash,   // 32
    recipientCommit, // 33
    leafHash,        // 32
    rLeaf,           // 32
    bindHash,        // 32
    new Uint8Array([(proof.length) & 0xff, (proof.length >> 8) & 0xff]),
    proof,
  );
}

function decodeTBridgeDepositPayload(payload) {
  if (!payload || payload.length < 261 || payload[0] !== T_BRIDGE_DEPOSIT) return null;
  let o = 1;
  const networkTag = payload[o++];
  const assetId = payload.slice(o, o + 32); o += 32;
  const denomWei = payload.slice(o, o + 32); o += 32;
  const ethRoot = payload.slice(o, o + 32); o += 32;
  const nullifierHash = payload.slice(o, o + 32); o += 32;
  const recipientCommit = payload.slice(o, o + 33); o += 33;
  const leafHash = payload.slice(o, o + 32); o += 32;
  const rLeaf = payload.slice(o, o + 32); o += 32;
  const bindHash = payload.slice(o, o + 32); o += 32;
  const proofLen = payload[o] | (payload[o + 1] << 8); o += 2;
  const proof = payload.slice(o, o + proofLen);
  return { networkTag, assetId, denomWei, ethRoot, nullifierHash, recipientCommit, leafHash, rLeaf, bindHash, proof };
}

function encodeTBridgeBurnPayload({ networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, ethRecipient, burnNonce, bindHash, proof }) {
  return concatBytes(
    new Uint8Array([T_BRIDGE_BURN, networkTag & 0xff]),
    assetId,       // 32
    denomWei,      // 32
    merkleRoot,    // 32
    nullifierHash, // 32
    recipientCommit, // 33
    rLeaf,         // 32
    ethRecipient,  // 20
    burnNonce,     // 32
    bindHash,      // 32
    new Uint8Array([(proof.length) & 0xff, (proof.length >> 8) & 0xff]),
    proof,
  );
}

function decodeTBridgeBurnPayload(payload) {
  if (!payload || payload.length < 281 || payload[0] !== T_BRIDGE_BURN) return null;
  let o = 1;
  const networkTag = payload[o++];
  const assetId = payload.slice(o, o + 32); o += 32;
  const denomWei = payload.slice(o, o + 32); o += 32;
  const merkleRoot = payload.slice(o, o + 32); o += 32;
  const nullifierHash = payload.slice(o, o + 32); o += 32;
  const recipientCommit = payload.slice(o, o + 33); o += 33;
  const rLeaf = payload.slice(o, o + 32); o += 32;
  const ethRecipient = payload.slice(o, o + 20); o += 20;
  const burnNonce = payload.slice(o, o + 32); o += 32;
  const bindHash = payload.slice(o, o + 32); o += 32;
  const proofLen = payload[o] | (payload[o + 1] << 8); o += 2;
  const proof = payload.slice(o, o + proofLen);
  return { networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, ethRecipient, burnNonce, bindHash, proof };
}

async function buildBridgeDepositEnvelope({
  networkTag, assetId, denomWei,
  ethRoot,
  secretEth, nullifierPreimageEth,
  secretPool, nullifierPreimagePool,
  ethTreePathElements, ethTreePathIndices,
  denomination,
}) {
  if (secretEth.length !== 32) throw new Error('secretEth 32 bytes');
  if (nullifierPreimageEth.length !== 32) throw new Error('nullifierPreimageEth 32 bytes');
  if (secretPool.length !== 32) throw new Error('secretPool 32 bytes');
  if (nullifierPreimagePool.length !== 32) throw new Error('nullifierPreimagePool 32 bytes');

  // Two separate secret pairs: (secretEth, ν_eth) for the Ethereum deposit
  // Groth16 proof; (secretPool, ν_pool) for the bridge pool note.
  // The deposit nullifier (Poseidon₁(ν_eth)) prevents double-minting from
  // the same Ethereum deposit. The pool note nullifier (Poseidon₁(ν_pool))
  // is used later for burn/export/rotate — a distinct value, so SP1's
  // null_set does not block subsequent operations on the pool note.
  const nullifierHashEth = computeNullifierHash(nullifierPreimageEth);
  const rLeaf = poseidonHash(secretEth, nullifierPreimageEth);
  const rLeafBigint = bytes32ToBigint(rLeaf) % SECP_N;
  const recipientCommit = pedersenCommit(BigInt(denomination), rLeafBigint).toRawBytes(true);

  const poolLeaf = computePoolLeafCommitment(secretPool, nullifierPreimagePool, denomination);

  const denomTacitBH = bigintToBytes32Strict(BigInt(denomination));
  const bindHash = computeBridgeDepositBindHash(
    networkTag, assetId, denomTacitBH, ethRoot, nullifierHashEth, recipientCommit, poolLeaf, rLeaf,
  );

  const proofInput = {
    root: bytes32ToBigint(ethRoot).toString(),
    nullifier_hash: bytes32ToBigint(nullifierHashEth).toString(),
    denomination: denomination.toString(),
    r_leaf: bytes32ToBigint(rLeaf).toString(),
    bind_hash: bytes32ToBigint(bindHash).toString(),
    secret: bytes32ToBigint(secretEth).toString(),
    nullifier_preimage: bytes32ToBigint(nullifierPreimageEth).toString(),
    path_elements: ethTreePathElements.map(e => (typeof e === 'bigint' ? e : bytes32ToBigint(e)).toString()),
    path_indices: ethTreePathIndices,
  };

  const denomTacitBytes = bigintToBytes32Strict(BigInt(denomination));
  const payload = encodeTBridgeDepositPayload({
    networkTag, assetId, denomWei: denomTacitBytes, ethRoot, nullifierHash: nullifierHashEth,
    recipientCommit, leafHash: poolLeaf, rLeaf, bindHash,
    proof: new Uint8Array(0),
  });

  return {
    payload,
    proofInput,
    nullifierHash: nullifierHashEth,
    leafHash: poolLeaf,
    recipientCommit,
    rLeaf,
    tacitNoteRecord: {
      assetIdHex: bytesToHex(assetId),
      denomination: denomination.toString(),
      secretHex: bytesToHex(secretPool),
      nullifierPreimageHex: bytesToHex(nullifierPreimagePool),
      nullifierHashHex: bytesToHex(computeNullifierHash(nullifierPreimagePool)),
      leafCommitmentHex: bytesToHex(poolLeaf),
      recipientCommitHex: bytesToHex(recipientCommit),
      rLeafHex: bytesToHex(rLeaf),
      mintedAt: Date.now(),
      source: 'bridge_deposit',
    },
  };
}

async function buildBridgeBurnEnvelope({
  networkTag, assetId, denomWei,
  noteRecord, merkleRoot, proof,
  ethRecipient,
}) {
  const secret = hexToBytes(noteRecord.secretHex);
  const nullifierPreimage = hexToBytes(noteRecord.nullifierPreimageHex);
  const denomination = BigInt(noteRecord.denomination);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const rLeaf = poseidonHash(secret, nullifierPreimage);
  const rLeafBigint = bytes32ToBigint(rLeaf) % SECP_N;
  const recipientCommit = pedersenCommit(denomination, rLeafBigint).toRawBytes(true);
  const burnNonce = crypto.getRandomValues(new Uint8Array(32));

  const bindHash = computeBridgeBurnBindHash(
    networkTag, assetId, denomWei, merkleRoot, nullifierHash, recipientCommit, rLeaf, ethRecipient, burnNonce,
  );

  const payload = encodeTBridgeBurnPayload({
    networkTag, assetId, denomWei, merkleRoot, nullifierHash,
    recipientCommit, rLeaf, ethRecipient, burnNonce, bindHash, proof,
  });

  return {
    payload,
    nullifierHash,
    recipientCommit,
    rLeaf,
    burnNonce,
    ethRecipient,
    bindHash,
  };
}

