    deployBlock: '0xa7586c',
    etchTxid: 'afbc72e037f1fce51e90a37c6329782a2aeba0adfddc38859688e2f79542e49b',
    imageUri: 'ipfs://bafkreihmbs7c6hg2q5zu3kl65f65irwmleuxdw6jfop44lwtzc4ijta53q',
