// ─── Cross-lane (confidential-pool) bridge — TAC + ETH/future assets, STAGED (inert) ───
// ConfidentialPool is the forward path for ETH and all cross-lane assets
// (bridge_mint/bridge_burn, one anonymity set, any asset). The standalone tETH
// mixer above is legacy alpha only: existing-note redemption/migration remains,
// but new ETH ops should land here once the pool config is live.
// STAGED: the pool is not yet production-deployed and the reflection ETH↔BTC loop is not
// operational, so `pool` is null and every asset is live:false — _crosslaneConfigured() keeps the UI
// off until both are set, so nothing surfaces in the live dapp.
// See ops/PLAN-confidential-cross-chain.md §12. Flip-on = set `pool`, mark an asset live:true, register
// the cross-chain link on-chain, and wire the asset-aware bridge UI.
// CROSSLANE_DEPLOYMENTS is imported from confidential-deployments.js (the single source the deploy sync
// patches; 'signet' = Sepolia EVM testnet, chainId 11155111). Confidential surfaces resolve the same record.
function _crosslaneConfigured(net) {
  const d = CROSSLANE_DEPLOYMENTS[net || currentNetworkName()];
  return !!(d && d.pool && d.assets.some((a) => a.live));
}

// ─── Persistent bridge pipeline state ──────────────────────────────
// Lives at module level so pollers survive modal close/reopen.
// The modal reads _bridgePipeline on open and syncs its UI.
const _bridgePipeline = {
  stage: null,       // null | 'eth_confirm' | 'minting' | 'btc_confirm' | 'withdrawing' | 'done' | 'error'
  message: '',       // human-readable status
  depth: 0,          // confirmation depth (for btc_confirm stage)
  ethTxHash: null,
  mintTxid: null,
  note: null,
  error: null,
  _pollerIds: [],
};

function _bridgePipelineUpdate(stage, message) {
  _bridgePipeline.stage = stage;
  _bridgePipeline.message = message || '';
  _updateBridgeBadge();
}

function _updateBridgeBadge() {
  const btn = typeof $ === 'function' ? $('#btn-bridge-eth') : document.getElementById('btn-bridge-eth');
  if (!btn) return;
  let badge = btn.querySelector('.bridge-badge');
  const s = _bridgePipeline.stage;
  if (!s || s === 'done' || s === 'error') {
    if (badge) badge.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement('span');
    badge.className = 'bridge-badge';
    badge.style.cssText = 'display:inline-block;margin-left:6px;padding:2px 8px;font-size:10px;background:#fff;color:#627eea;font-weight:600;border-radius:8px;vertical-align:middle;animation:pulse 2s infinite;letter-spacing:0.02em;';
    btn.appendChild(badge);
  }
  const labels = {
    eth_confirm: 'ETH confirming',
    minting: 'minting',
    btc_confirm: `${_bridgePipeline.depth}/3`,
    withdrawing: 'withdrawing',
    error: 'retry',
  };
  badge.textContent = labels[s] || s;
}

const _ETH_PUBLIC_RPCS = {
  1: [
    'https://ethereum-rpc.publicnode.com',
    'https://eth.llamarpc.com',
    'https://1rpc.io/eth',
    'https://eth.drpc.org',
  ],
  11155111: [
    'https://ethereum-sepolia-rpc.publicnode.com',
    'https://1rpc.io/sepolia',
    'https://sepolia.drpc.org',
    'https://sepolia.gateway.tenderly.co',
  ],
};

// Memoized check: is the user's connected wallet provider on the bridge's
// chain? Cached 30s so the per-call eth_chainId round-trip doesn't tax the
// pre-broadcast loop (which fires NUM_DENOMS eth_calls).
let _ethProviderChainOkUntil = 0;
let _ethProviderChainOk = false;
async function _ethProviderOnBridgeChain() {
  const now = Date.now();
  if (now < _ethProviderChainOkUntil) return _ethProviderChainOk;
  _ethProviderChainOkUntil = now + 30_000;
  _ethProviderChainOk = false;
  try {
    const p = (typeof _ethProvider === 'function') ? _ethProvider() : null;
    if (p && typeof p.request === 'function' && TETH_BRIDGE.chainId) {
      const cid = await p.request({ method: 'eth_chainId' });
      _ethProviderChainOk = !!cid && parseInt(cid, 16) === Number(TETH_BRIDGE.chainId);
    }
  } catch { _ethProviderChainOk = false; }
  return _ethProviderChainOk;
}

// Read-only Ethereum calls. Prefer the user's own connected wallet provider
// (their chosen node — possibly their own full node) so reads aren't bound to
// the bundled public-RPC list; fall back to the public RPCs only when no wallet
// is connected, it's on the wrong chain, or it errors. The solvency-critical
// backing check is on-chain (verifier ↔ mixer.getRootAccumulator), so a flaky
// or hostile RPC here is a liveness/privacy concern, never a conservation one.
async function _ethRpcCall(method, params) {
  if (await _ethProviderOnBridgeChain()) {
    try { return await _ethProvider().request({ method, params }); }
    catch { /* provider failed this call — fall through to public RPCs */ }
  }
  const rpcs = _ETH_PUBLIC_RPCS[TETH_BRIDGE.chainId] || _ETH_PUBLIC_RPCS[1];
  for (const rpc of rpcs) {
    try {
      const resp = await fetch(rpc, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
      });
      const json = await resp.json();
      if (json.error) continue;
      return json.result;
    } catch { continue; }
  }
  throw new Error('all Ethereum RPCs failed');
}

const TETH_BRIDGE = {
  address: null,
  chainId: null,
  assetId: null,
  depositSelector: '1de26e16',
  withdrawSelector: null, // withdrawFromBurn(bytes,bytes,uint256,bytes32[],uint256)
  depositEventTopic: null, // keccak256("Deposit(bytes32,bytes32,uint256,uint256)") — computed lazily
};

function _bridgeConfigured() {
  return TETH_BRIDGE.address && TETH_BRIDGE.chainId && TETH_BRIDGE.assetId;
}

// ── tETH generation registry ────────────────────────────────────────────────
// One tETH asset spans an ordered list of immutable mixer generations
// (TETH_DEPLOYMENTS[net].generations). TETH_BRIDGE binds the ACTIVE
// generation (where new deposits go); every escrow-touching op resolves a
// generation context — {gen, address, chainId, deployBlock} — and threads it
// through bind hashes, pool-tree keys, worker ?gen= fetches, and mixer
// eth_calls, so notes from earlier generations stay redeemable after the
// active one advances.
function tethGenList() {
  const dep = TETH_DEPLOYMENTS[currentNetworkName()];
  if (!dep) return [];
  if (Array.isArray(dep.generations)) return dep.generations;
  return [{ gen: '', label: 'pilot', address: dep.address, chainId: dep.chainId, deployBlock: dep.deployBlock, live: dep.live !== false }];
}
function tethGenByAddress(addr) {
  const a = String(addr || '').toLowerCase();
  return tethGenList().find(g => String(g.address).toLowerCase() === a) || null;
}
function tethGenCtx(g) {
  if (!g) return null;
  return { gen: g.gen || '', label: g.label, address: String(g.address).toLowerCase(), chainId: g.chainId, deployBlock: g.deployBlock || '0x0' };
}
function tethActiveCtx() {
  if (!_bridgeConfigured()) return null;
  return { gen: TETH_BRIDGE.gen || '', label: TETH_BRIDGE.label, address: TETH_BRIDGE.address, chainId: TETH_BRIDGE.chainId, deployBlock: TETH_BRIDGE.deployBlock || '0x0' };
}
// Which generation does a stored bridge record belong to? Explicit stamp
// first, then its mixer address, else the active generation (every record
// written before stamping landed lives under the active mixer's storage key).
function tethCtxForRecord(rec) {
  if (rec && rec.gen != null) {
    const g = tethGenList().find(x => (x.gen || '') === (rec.gen || ''));
    if (g) return tethGenCtx(g);
  }
  if (rec && rec.mixerAddress) {
    const g = tethGenByAddress(rec.mixerAddress);
    if (g) return tethGenCtx(g);
  }
  return tethActiveCtx();
}

function configureTethBridge({ address, chainId, assetIdHex, deployBlock }) {
  TETH_BRIDGE.address = address.toLowerCase();
  TETH_BRIDGE.chainId = chainId;
  TETH_BRIDGE.assetId = hexToBytes(assetIdHex);
  TETH_BRIDGE.deployBlock = deployBlock || '0x0';
  const _g = tethGenByAddress(address);
  TETH_BRIDGE.gen = _g ? (_g.gen || '') : '';
  TETH_BRIDGE.label = _g ? _g.label : 'pilot';
  _ethRpcCall('eth_call', [{ to: address.toLowerCase(), data: '0x' + bytesToHex(keccak_256(new TextEncoder().encode('UNIT_SCALE()'))).slice(0, 8) }, 'latest'])
    .then(r => { if (r && r !== '0x') BRIDGE_UNIT_SCALE = BigInt(r); })
    .catch(() => {});
  registerAsset({
    assetIdHex: assetIdHex,
    asset_id: assetIdHex,
    ticker: 'tETH',
    decimals: 8,
    image_uri: 'ipfs://bafkreihmbs7c6hg2q5zu3kl65f65irwmleuxdw6jfop44lwtzc4ijta53q',
    kind: 'bridge',
  });
}

function _cleanStaleBridgeRecords() {
  if (!_bridgeConfigured()) return;
  for (const g of (tethGenList().length ? tethGenList() : [{ address: TETH_BRIDGE.address }])) {
    const key = _BRIDGE_TETH_NOTES_KEY_FOR(g.address);
    const notes = _getBridgeRecords(key);
    const seen = new Map();
    let changed = false;
    for (const n of notes) {
      if (!n.nullifierHashHex) continue;
      const prev = seen.get(n.nullifierHashHex);
      if (prev) {
        if ((n.status === 'withdrawn' || n.withdrawTxid) && prev.status !== 'withdrawn') {
          prev.status = 'withdrawn';
          prev.withdrawTxid = prev.withdrawTxid || n.withdrawTxid;
          changed = true;
        }
      } else {
        seen.set(n.nullifierHashHex, n);
      }
    }
    if (changed) {
      localStorage.setItem(key, JSON.stringify([...seen.values()]));
    }
  }
}

function _markBurnSpentIfNullifierUsed(burnRecord) {
  if (!burnRecord?.burnTxid) return false;
  return _updateBridgeRecordAtHome(_BRIDGE_BURN_RECORDS_KEY_FOR, burnRecord,
    r => r.burnTxid === burnRecord.burnTxid,
    r => { r.status = 'spent'; });
}

function _isNullifierSpentError(err) {
  const msg = (err?.message || err?.toString() || '').toLowerCase();
  return msg.includes('nullifier') || msg.includes('already spent') || msg.includes('already been used')
    || msg.includes('execution reverted');
}

function _pad32(hex) { return hex.replace(/^0x/i, '').padStart(64, '0'); }

let _bridgeSupplyCache = null;
let _bridgeSupplyCacheAt = 0;
async function bridgeGetSupplyStats() {
  if (_bridgeSupplyCache && Date.now() - _bridgeSupplyCacheAt < 60000) return _bridgeSupplyCache;
  if (!_bridgeConfigured()) return null;
  try {
    // Each mixer's totalBalance is deposits − withdrawals (deposit() does
    // `totalBalance += denomination`, withdrawFromBurn() `-= denomination`).
    // tETH etched supply is 0, so every tETH is bridge-backed 1:1 by locked
    // ETH; the unified asset spans every generation's mixer, so the
    // circulating figure is the SUM of generation balances. One call per
    // generation — no full-history log scan; mints/burns move tETH within
    // the locked pools on Bitcoin without changing the total.
    const balSel = '0x' + bytesToHex(keccak_256(new TextEncoder().encode('totalBalance()'))).slice(0, 8);
    let ethLocked = 0n;
    const gens = tethGenList();
    const addrs = gens.length ? gens.map(g => String(g.address).toLowerCase()) : [TETH_BRIDGE.address];
    for (const addr of addrs) {
      const balHex = await _ethRpcCall('eth_call', [{ to: addr, data: balSel }, 'latest']);
      if (balHex && balHex !== '0x') ethLocked += BigInt(balHex);
    }
    _bridgeSupplyCache = {
      ethLocked,
      inCirculation: ethLocked / BRIDGE_UNIT_SCALE,
    };
    _bridgeSupplyCacheAt = Date.now();
    return _bridgeSupplyCache;
  } catch { return null; }
}

function bridgeSupplyHTML() {
  const s = _bridgeSupplyCache;
  if (!s) return '';
  const fmtWei = (wei) => ((Number(wei) / 1e18).toFixed(6).replace(/\.?0+$/, '') || '0');
  // tETH circulating ≡ ETH locked, 1:1 scaled — the same on-chain figure.
  return `<div style="display:flex;gap:16px;font-size:11px;color:var(--ink-mid);margin-top:8px;">` +
    `<span>${fmtAssetAmount(s.inCirculation, 8)} tETH circulating · backed 1:1 by ${fmtWei(s.ethLocked)} ETH locked</span>` +
    `</div>`;
}

let BRIDGE_UNIT_SCALE = 10000000000n; // default ETH: 10^(18-8)

// Must match the on-chain mixer's `denominations` array (deploy script). Order
// is largest → smallest so bridgeDecompose greedily allocates the fewest chunks.
// Smallest = 0.00001 ETH (10^13 wei = 1000 tacit-units) — finer granularity
// for whole-note fractional sends without CXFER.
const BRIDGE_DENOMINATIONS = [
  100n   * 10n**18n,  // 100 ETH
  10n    * 10n**18n,  // 10 ETH
  1n     * 10n**18n,  // 1 ETH
  10n**17n,           // 0.1 ETH
  10n**16n,           // 0.01 ETH
  10n**15n,           // 0.001 ETH
  10n**14n,           // 0.0001 ETH
  10n**13n,           // 0.00001 ETH
];

// Cautious-launch cap: on Ethereum mainnet the dapp on-ramps at most this much
// per deposit. The smaller denoms (0.0001 / 0.00001 ETH) stay available so
// fractional CXFER amounts remain redeemable — only the larger pools are gated
// off (the contracts support all 8). Raise this to lift the cap.
const BRIDGE_MAINNET_MAX_DENOM_WEI = 10n ** 15n; // 0.001 ETH (per-deposit, launch)
const BRIDGE_MAINNET_MAX_TOTAL_WEI = 10n * (10n ** 18n); // 10 ETH (aggregate pilot ceiling)

function bridgeDecompose(weiAmount) {
  let remaining = BigInt(weiAmount);
  const chunks = [];
  for (const denom of BRIDGE_DENOMINATIONS) {
    while (remaining >= denom) {
      chunks.push(denom);
      remaining -= denom;
    }
  }
  return { chunks, dust: remaining };
}

async function bridgeBatchDepositETH({ provider, weiAmount, onProgress }) {
  if (!_bridgeConfigured()) throw new Error('tETH bridge not configured');
  const _p = (s) => { try { onProgress?.(s); } catch {} };
  const { chunks, dust } = bridgeDecompose(weiAmount);
  if (chunks.length === 0) throw new Error('amount too small — minimum 0.00001 ETH');

  _p(`decomposing ${chunks.length} denomination chunks (dust: ${dust} wei)`);

  await ensurePrivkey();
  let depositIndex = parseInt(localStorage.getItem(_BRIDGE_DEPOSIT_COUNT_KEY()) || '0', 10);
  const records = [];
  const commitments = [];
  const denominations = [];
  for (const denomWei of chunks) {
    const denomTacit = denomWei / BRIDGE_UNIT_SCALE;
    const { secretEth, nullifierPreimageEth, secretPool, nullifierPreimagePool } = _deriveBridgeDepositKeys(wallet.priv, depositIndex++);
    const ethCommitment = computePoolLeafCommitment(secretEth, nullifierPreimageEth, denomTacit);
    commitments.push('0x' + bytesToHex(ethCommitment));
    denominations.push('0x' + denomWei.toString(16));
    const poolLeaf = computePoolLeafCommitment(secretPool, nullifierPreimagePool, denomTacit);
    records.push({
      secretEthHex: bytesToHex(secretEth),
      nullifierPreimageEthHex: bytesToHex(nullifierPreimageEth),
      ethCommitmentHex: bytesToHex(ethCommitment),
      secretPoolHex: bytesToHex(secretPool),
      nullifierPreimagePoolHex: bytesToHex(nullifierPreimagePool),
      poolLeafHex: bytesToHex(poolLeaf),
      nullifierHashHex: bytesToHex(computeNullifierHash(nullifierPreimagePool)),
      denomination: denomTacit.toString(),
      denominationWei: denomWei.toString(),
      assetIdHex: bytesToHex(TETH_BRIDGE.assetId),
      gen: TETH_BRIDGE.gen || '',
      mixerAddress: TETH_BRIDGE.address,
      timestamp: Date.now(),
      status: 'deposited',
    });
  }

  const totalWei = chunks.reduce((a, b) => a + b, 0n);
  const abiCoder = new TextEncoder();
  const selector = 'a4b135c1';
  const calldata = '0x' + selector
    + _pad32((64).toString(16))
    + _pad32((64 + 32 + commitments.length * 32).toString(16))
    + _pad32(commitments.length.toString(16))
    + commitments.map(c => _pad32(c.replace(/^0x/, ''))).join('')
    + _pad32(denominations.length.toString(16))
    + denominations.map(d => _pad32(d.replace(/^0x/, ''))).join('');

  _p('awaiting wallet signature');
  const [account] = await provider.request({ method: 'eth_requestAccounts' });
  const txHash = await provider.request({
    method: 'eth_sendTransaction',
    params: [{
      from: account,
      to: TETH_BRIDGE.address,
      value: '0x' + totalWei.toString(16),
      data: calldata,
    }],
  });

  _p(`batch deposit submitted: ${txHash}`);
  for (const r of records) {
    r.ethTxHash = txHash;
    r.ethAddress = account;
    _saveBridgeRecord(_BRIDGE_DEPOSIT_RECORDS_KEY(), r);
  }
  localStorage.setItem(_BRIDGE_DEPOSIT_COUNT_KEY(), String(depositIndex));
  return { txHash, records, dust };
}

function bridgeGetDepositStatus(record) {
  if (!record) return 'unknown';
  return record.status || 'deposited';
}

// Merged views across generations. Records partition by mixer address in
// their storage keys; each loaded record is annotated (in memory) with its
// generation so flows can resolve a context via tethCtxForRecord.
function _bridgeRecordsAcrossGens(keyFor) {
  const out = [];
  for (const g of tethGenList()) {
    const addr = String(g.address).toLowerCase();
    for (const r of _getBridgeRecords(keyFor(addr))) {
      if (r.gen == null) r.gen = g.gen || '';
      if (!r.mixerAddress) r.mixerAddress = addr;
      out.push(r);
    }
  }
  return out;
}

function bridgeGetAllDeposits() {
  return _bridgeRecordsAcrossGens(_BRIDGE_DEPOSIT_RECORDS_KEY_FOR);
}

function bridgeGetAllNotes() {
  return _bridgeRecordsAcrossGens(_BRIDGE_TETH_NOTES_KEY_FOR);
}

function bridgeGetAllBurns() {
  return _bridgeRecordsAcrossGens(_BRIDGE_BURN_RECORDS_KEY_FOR);
}

const _BRIDGE_DEPOSIT_RECORDS_KEY_FOR = (addr) => `tacit-bridge-eth-deposits-v2:${currentNetworkName()}:${String(addr || '').toLowerCase()}`;
const _BRIDGE_TETH_NOTES_KEY_FOR = (addr) => `tacit-bridge-teth-notes-v2:${currentNetworkName()}:${String(addr || '').toLowerCase()}`;
const _BRIDGE_BURN_RECORDS_KEY_FOR = (addr) => `tacit-bridge-burn-records-v2:${currentNetworkName()}:${String(addr || '').toLowerCase()}`;
const _BRIDGE_DEPOSIT_RECORDS_KEY = () => _BRIDGE_DEPOSIT_RECORDS_KEY_FOR(TETH_BRIDGE.address);
const _BRIDGE_TETH_NOTES_KEY = () => _BRIDGE_TETH_NOTES_KEY_FOR(TETH_BRIDGE.address);
const _BRIDGE_BURN_RECORDS_KEY = () => _BRIDGE_BURN_RECORDS_KEY_FOR(TETH_BRIDGE.address);

function _saveBridgeRecord(storageKey, record) {
  const all = JSON.parse(localStorage.getItem(storageKey) || '[]');
  all.push(record);
  localStorage.setItem(storageKey, JSON.stringify(all));
}
function _getBridgeRecords(storageKey) {
  return JSON.parse(localStorage.getItem(storageKey) || '[]');
}
// Read-modify-write a stored bridge record in its HOME generation's storage
// (resolved from the record's stamp; legacy records fall back to the active
// key, where they live). `match` picks the stored record, `mutate` edits it
// in place. Returns true when a record was updated.
function _updateBridgeRecordAtHome(keyFor, rec, match, mutate) {
  const ctx = tethCtxForRecord(rec);
  const key = keyFor(ctx ? ctx.address : TETH_BRIDGE.address);
  const all = _getBridgeRecords(key);
  const i = all.findIndex(match);
  if (i < 0) return false;
  mutate(all[i]);
  localStorage.setItem(key, JSON.stringify(all));
  return true;
}

// --- tETH CETCH (first deposit creates the asset) ---

function bridgeFindTethAssetId() {
  const reg = JSON.parse(localStorage.getItem(`${REG_KEY_BASE}:${NET.name}`) || '{}');
  for (const [aid, meta] of Object.entries(reg)) {
    if (String(meta?.ticker || '').toLowerCase() === 'teth') return aid;
  }
  return null;
}

async function bridgeEnsureTethEtched({ supplyBase, onProgress } = {}) {
  const _p = (s) => { try { onProgress?.(s); } catch {} };
  const existing = bridgeFindTethAssetId();
  if (existing) {
    _p('tETH already etched');
    return existing;
  }
  _p('tETH not found — etching new asset on first deposit');
  const result = await buildAndBroadcastCEtch({
    ticker: TETH_ASSET.ticker,
    supplyBase: supplyBase || 100000n,
    decimals: TETH_ASSET.decimals,
    imageUri: TETH_ASSET.imageUri,
    mintable: false,
    onProgress,
  });
  _p(`tETH etched: ${result.assetIdHex}`);
  return result.assetIdHex;
}

// --- Ethereum deposit (step 1: lock ETH in mixer contract) ---

const _BRIDGE_DEPOSIT_SECRET_DOMAIN    = new TextEncoder().encode('tacit-bridge-deposit-secret-v1');
const _BRIDGE_DEPOSIT_NULLIFIER_DOMAIN = new TextEncoder().encode('tacit-bridge-deposit-nullifier-v1');
const _BRIDGE_POOL_SECRET_DOMAIN       = new TextEncoder().encode('tacit-bridge-pool-secret-v1');
const _BRIDGE_POOL_NULLIFIER_DOMAIN    = new TextEncoder().encode('tacit-bridge-pool-nullifier-v1');
const _BRIDGE_IMPORT_SECRET_DOMAIN     = new TextEncoder().encode('tacit-bridge-import-secret-v1');
const _BRIDGE_IMPORT_NULLIFIER_DOMAIN  = new TextEncoder().encode('tacit-bridge-import-nullifier-v1');
const _BRIDGE_DEPOSIT_COUNT_KEY = () => `tacit-bridge-deposit-count-v1:${currentNetworkName()}`;

function _deriveBridgeDepositKeys(privkey, index) {
  const idxBytes = new Uint8Array(4);
  new DataView(idxBytes.buffer).setUint32(0, index, false);
  return {
    secretEth: hmac(sha256, privkey, concatBytes(_BRIDGE_DEPOSIT_SECRET_DOMAIN, idxBytes)),
    nullifierPreimageEth: hmac(sha256, privkey, concatBytes(_BRIDGE_DEPOSIT_NULLIFIER_DOMAIN, idxBytes)),
    secretPool: hmac(sha256, privkey, concatBytes(_BRIDGE_POOL_SECRET_DOMAIN, idxBytes)),
    nullifierPreimagePool: hmac(sha256, privkey, concatBytes(_BRIDGE_POOL_NULLIFIER_DOMAIN, idxBytes)),
  };
}

function _deriveBridgeImportKeys(privkey, prevTxidInternal, prevVout) {
  const voutBytes = new Uint8Array(4);
  new DataView(voutBytes.buffer).setUint32(0, prevVout >>> 0, false);
  const salt = concatBytes(prevTxidInternal, voutBytes);
  return {
    secret: hmac(sha256, privkey, concatBytes(_BRIDGE_IMPORT_SECRET_DOMAIN, salt)),
    nullifierPreimage: hmac(sha256, privkey, concatBytes(_BRIDGE_IMPORT_NULLIFIER_DOMAIN, salt)),
  };
}

async function bridgeDepositETH({ provider, denomination, onProgress }) {
  if (!_bridgeConfigured()) throw new Error('tETH bridge not configured. Set contract address first.');
  const _p = (s) => { try { onProgress?.(s); } catch {} };
  const denomWei = BigInt(denomination);
  if (TETH_BRIDGE.chainId === 1) {
    if (denomWei > BRIDGE_MAINNET_MAX_DENOM_WEI) {
      throw new Error('Mainnet tETH deposits are capped at 0.001 ETH during launch.');
    }
    // Aggregate pilot ceiling: the mixer's totalBalance is the circulating tETH
    // (the asset etched supply 0, so all tETH is bridge-backed). Refuse a deposit
    // that would push total locked ETH past the cap. Soft (dapp-side) bound on
    // pilot exposure; the operator also monitors totalBalance for direct-call deposits.
    const totalSel = bytesToHex(keccak_256(new TextEncoder().encode('totalBalance()'))).slice(0, 8);
    const balHex = await _ethRpcCall('eth_call', [{ to: TETH_BRIDGE.address, data: '0x' + totalSel }, 'latest']);
    const totalLocked = (balHex && balHex !== '0x') ? BigInt(balHex) : 0n;
    if (totalLocked + denomWei > BRIDGE_MAINNET_MAX_TOTAL_WEI) {
      throw new Error(`Mainnet tETH bridge is at its launch cap (${BRIDGE_MAINNET_MAX_TOTAL_WEI / (10n ** 18n)} ETH total locked). Deposits are paused — please try again later.`);
    }
  }
  const denomTacit = denomWei / BRIDGE_UNIT_SCALE;

  _p('generating commitment');
  await ensurePrivkey();
  const depositIndex = parseInt(localStorage.getItem(_BRIDGE_DEPOSIT_COUNT_KEY()) || '0', 10);
  const { secretEth, nullifierPreimageEth, secretPool, nullifierPreimagePool } = _deriveBridgeDepositKeys(wallet.priv, depositIndex);
  const ethCommitment = computePoolLeafCommitment(secretEth, nullifierPreimageEth, denomTacit);

  const calldata = '0x' + TETH_BRIDGE.depositSelector + bytesToHex(ethCommitment) + _pad32(denomWei.toString(16));

  _p('awaiting wallet signature');
  const [account] = await provider.request({ method: 'eth_requestAccounts' });
  const txHash = await provider.request({
    method: 'eth_sendTransaction',
    params: [{
      from: account,
      to: TETH_BRIDGE.address,
      value: '0x' + denomWei.toString(16),
      data: calldata,
    }],
  });

  const poolLeaf = computePoolLeafCommitment(secretPool, nullifierPreimagePool, denomTacit);
  _p('deposit submitted — waiting for confirmation');
  const record = {
    secretEthHex: bytesToHex(secretEth),
    nullifierPreimageEthHex: bytesToHex(nullifierPreimageEth),
    ethCommitmentHex: bytesToHex(ethCommitment),
    secretPoolHex: bytesToHex(secretPool),
    nullifierPreimagePoolHex: bytesToHex(nullifierPreimagePool),
    poolLeafHex: bytesToHex(poolLeaf),
    nullifierHashHex: bytesToHex(computeNullifierHash(nullifierPreimagePool)),
    denomination: denomTacit.toString(),
    denominationWei: denomWei.toString(),
    ethTxHash: txHash,
    ethAddress: account,
    assetIdHex: bytesToHex(TETH_BRIDGE.assetId),
    gen: TETH_BRIDGE.gen || '',
    mixerAddress: TETH_BRIDGE.address,
    timestamp: Date.now(),
    status: 'deposited',
  };
  _saveBridgeRecord(_BRIDGE_DEPOSIT_RECORDS_KEY(), record);
  localStorage.setItem(_BRIDGE_DEPOSIT_COUNT_KEY(), String(depositIndex + 1));
  return record;
}

// --- Bridge recovery: rebuild notes from privkey + Sepolia deposit events ---

async function bridgeRecoverNotes({ onProgress } = {}) {
  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  await ensurePrivkey();
  const _p = (s) => { try { onProgress?.(s); } catch {} };

  _p('fetching mixer deposits');
  // Sweep every generation's mixer — a recovered wallet may hold deposits
  // across generations; each match is stamped + stored under its home key.
  const depositTopic = '0x' + bytesToHex(keccak_256(new TextEncoder().encode('Deposit(bytes32,bytes32,uint256,uint256)')));
  const _recoverGens = tethGenList().length ? tethGenList().map(tethGenCtx) : [tethActiveCtx()].filter(Boolean);
  const commitmentSet = new Map();
  for (const g of _recoverGens) {
    const logs = await _ethRpcCall('eth_getLogs', [{
      address: g.address, fromBlock: g.deployBlock || '0x0', toBlock: 'latest',
      topics: [depositTopic],
    }]) || [];
    for (const log of logs) {
      const commitment = log.topics[2].replace(/^0x/, '');
      const poolId = log.topics[1].replace(/^0x/, '');
      commitmentSet.set(commitment, { poolId, block: parseInt(log.blockNumber, 16), txHash: log.transactionHash, gen: g.gen || '', mixerAddress: g.address });
    }
  }
  if (!commitmentSet.size) { _p('no deposits found'); return { recovered: 0 }; }
  _p(`${commitmentSet.size} mixer deposits found — scanning keys`);

  const existing = loadMixerDeposits();
  const existingNulls = new Set(existing.map(r => r.nullifierHashHex).filter(Boolean));
  const existingTethNotes = bridgeGetAllNotes();
  const existingTethNulls = new Set(existingTethNotes.map(r => r.nullifierHashHex).filter(Boolean));
  let recovered = 0;
  const MAX_INDEX = Math.max(50, commitmentSet.size * 3);

  for (let idx = 0; idx < MAX_INDEX; idx++) {
    const { secretEth, nullifierPreimageEth, secretPool, nullifierPreimagePool } = _deriveBridgeDepositKeys(wallet.priv, idx);
    for (const denomWei of BRIDGE_DENOMINATIONS) {
      const denomTacit = denomWei / BRIDGE_UNIT_SCALE;
      const ethCommitment = computePoolLeafCommitment(secretEth, nullifierPreimageEth, denomTacit);
      const commitHex = bytesToHex(ethCommitment);
      const match = commitmentSet.get(commitHex);
      if (!match) continue;

      const poolLeaf = computePoolLeafCommitment(secretPool, nullifierPreimagePool, denomTacit);
      const poolNullHash = computeNullifierHash(nullifierPreimagePool);
      const nullHex = bytesToHex(poolNullHash);
      const inMixer = existingNulls.has(nullHex);
      const inTethNotes = existingTethNulls.has(nullHex);
      if (inMixer && inTethNotes) { commitmentSet.delete(commitHex); continue; }

      const noteRecord = {
        assetIdHex: bytesToHex(TETH_BRIDGE.assetId),
        denomination: denomTacit.toString(),
        denominationWei: denomWei.toString(),
        secretHex: bytesToHex(secretPool),
        nullifierPreimageHex: bytesToHex(nullifierPreimagePool),
        leafCommitmentHex: bytesToHex(poolLeaf),
        nullifierHashHex: nullHex,
        secretEthHex: bytesToHex(secretEth),
        nullifierPreimageEthHex: bytesToHex(nullifierPreimageEth),
        ethCommitmentHex: commitHex,
        ethTxHash: match.txHash,
        gen: match.gen || '',
        mixerAddress: match.mixerAddress,
        status: 'deposited',
        timestamp: Date.now(),
        source: 'bridge_deposit',
        recoveredAt: Date.now(),
      };
      if (!inMixer) saveMixerDepositRecord(noteRecord);
      if (!inMixer) _saveBridgeRecord(_BRIDGE_DEPOSIT_RECORDS_KEY_FOR(match.mixerAddress), noteRecord);
      if (!inTethNotes) _saveBridgeRecord(_BRIDGE_TETH_NOTES_KEY_FOR(match.mixerAddress), { ...noteRecord, status: 'minted' });
      existingNulls.add(nullHex);
      existingTethNulls.add(nullHex);
      recovered++;
      _p(`recovered deposit #${idx} (${fmtAssetAmount(denomTacit, 8)} tETH)`);
      commitmentSet.delete(commitHex);
    }
    if (commitmentSet.size === 0) break;
  }

  const depositCount = Math.max(recovered, parseInt(localStorage.getItem(_BRIDGE_DEPOSIT_COUNT_KEY()) || '0', 10));
  localStorage.setItem(_BRIDGE_DEPOSIT_COUNT_KEY(), String(depositCount));

  // Scan for shielded UTXOs from auto-withdrawals, independent of Sepolia matching.
  // Iterates deposit indices and checks each stealth address for UTXOs.
  _p('scanning for shielded tETH UTXOs');
  let stealthFound = 0;
  const tethAid = bytesToHex(TETH_BRIDGE.assetId);
  for (let idx = 0; idx < Math.max(20, depositCount + 5); idx++) {
    const { secretEth, nullifierPreimageEth } = _deriveBridgeDepositKeys(wallet.priv, idx);
    const secretHex = bytesToHex(secretEth);
    const secret = secretEth, nullifierPreimage = nullifierPreimageEth;
    try {
      const stealthB = _deriveBridgeWithdrawStealthBlinding(wallet.priv, secretHex);
      const stealthPub = computeStealthCommit({ underlyingPub: wallet.pub, blinding: stealthB });
      const stealthAddr = p2wpkhAddress(stealthPub);
      await new Promise(r => setTimeout(r, 200));
      let utxos;
      try { utxos = await getUtxos(stealthAddr); } catch { utxos = []; }
      if (!utxos || utxos.length === 0) continue;
      for (const u of utxos) {
        const ck = `${u.txid}:${u.vout}`;
        const existing = getStealthCredit(u.txid, u.vout);
        if (existing) continue;
        const rLeafB = poseidonHash(secret, nullifierPreimage);
        const rLeafBig = bytes32ToBigint(rLeafB) % SECP_N;
        const _mr = loadMixerDeposits().find(r => (r.secretEthHex === secretHex || r.secretHex === secretHex) && r.assetIdHex === tethAid);
        if (!_mr) continue;
        const denomTacit = BigInt(_mr.denomination);
        recordStealthCredit({
          txidHex: u.txid, vout: u.vout,
          assetIdHex: tethAid,
          amount: denomTacit,
          amountBlinding: rLeafBig,
          stealthBlinding: stealthB,
          commitmentHex: null,
          senderPubHex: bytesToHex(wallet.pub),
          blockTime: null,
        });
        recordOpening(u.txid, u.vout, tethAid, denomTacit, rLeafBig);
        const nullHash = computeNullifierHash(nullifierPreimage);
        mixerMarkNullifierSpent(tethAid, denomTacit, nullHash, u.txid);
        const _nullHex = bytesToHex(nullHash);
        for (const g of (tethGenList().length ? tethGenList() : [{ address: TETH_BRIDGE.address }])) {
          const _nkey = _BRIDGE_TETH_NOTES_KEY_FOR(g.address);
          const _tethNotes = _getBridgeRecords(_nkey);
          let _chg = false;
          for (const n of _tethNotes) {
            if (n.nullifierHashHex === _nullHex) { n.autoWithdrawPending = false; n.status = 'withdrawn'; n.withdrawTxid = u.txid; _chg = true; }
          }
          if (_chg) localStorage.setItem(_nkey, JSON.stringify(_tethNotes));
        }
        stealthFound++;
        _p(`found shielded UTXO #${stealthFound} at index ${idx}`);
      }
    } catch { continue; }
  }

  _p('scanning for rotated bridge notes');
  let rotationsFound = 0;
  let importsFound = 0;
  try {
    if (WORKER_BASE) {
      const _recGens = tethGenList().length ? tethGenList().map(tethGenCtx) : [tethActiveCtx()].filter(Boolean);
      for (const denomWei of BRIDGE_DENOMINATIONS) {
        const denomTacit = denomWei / BRIDGE_UNIT_SCALE;
        for (const _rg of _recGens) {
        const _rgQS = _rg.gen ? `&gen=${encodeURIComponent(_rg.gen)}` : '';
        const _rgNotesKey = _BRIDGE_TETH_NOTES_KEY_FOR(_rg.address);
        try {
          const resp = await fetch(`${WORKER_BASE}/pools/${tethAid}/${denomTacit.toString()}?network=${NET.name}${_rgQS}`);
          const pd = await resp.json();
          const importLeaves = (pd.leaves || []).filter(l => l.source === 'bridge_import' && l.prev_txid);
          if (importLeaves.length) {
            const knownImport = new Set(_getBridgeRecords(_rgNotesKey).map(n => n.leafCommitmentHex));
            for (const l of importLeaves) {
              if (knownImport.has(l.leaf_commitment)) continue;
              try {
                const { secret, nullifierPreimage } = _deriveBridgeImportKeys(wallet.priv, hexToBytes(l.prev_txid), l.prev_vout >>> 0);
                const testHex = bytesToHex(computePoolLeafCommitment(secret, nullifierPreimage, denomTacit));
                if (testHex !== l.leaf_commitment) continue;
                _saveBridgeRecord(_rgNotesKey, {
                  assetIdHex: tethAid,
                  denomination: denomTacit.toString(),
                  secretHex: bytesToHex(secret),
                  nullifierPreimageHex: bytesToHex(nullifierPreimage),
                  leafCommitmentHex: testHex,
                  nullifierHashHex: bytesToHex(computeNullifierHash(nullifierPreimage)),
                  importTxid: l.deposit_txid,
                  gen: _rg.gen || '',
                  mixerAddress: _rg.address,
                  status: 'minted',
                  timestamp: Date.now(),
                  source: 'bridge_import',
                  recoveredAt: Date.now(),
                });
                importsFound++;
                _p('recovered imported note');
              } catch {}
            }
          }
          const rotateLeaves = (pd.leaves || []).filter(l => l.source === 'bridge_rotate');
          if (!rotateLeaves.length) continue;
          const currentTethNotes = _getBridgeRecords(_rgNotesKey);
          const knownCommits = new Set(currentTethNotes.map(n => n.leafCommitmentHex));
          const unmatched = rotateLeaves.filter(l => !knownCommits.has(l.leaf_commitment));
          if (!unmatched.length) continue;
          const commitSet = new Map(unmatched.map(l => [l.leaf_commitment, l]));
          const allRecs = [...loadMixerDeposits(), ...currentTethNotes];
          const senderPubs = new Set();
          for (const r of allRecs) { if (r.senderPubHex) senderPubs.add(r.senderPubHex); }
          if (wallet.pubHex) senderPubs.add(wallet.pubHex());
          const domain = new TextEncoder().encode('tacit-bridge-rotate-note-v1');
          for (const senderPub of senderPubs) {
            try {
              const shared = secp.getSharedSecret(wallet.priv, hexToBytes(senderPub));
              for (let nonce = 0; nonce < 20; nonce++) {
                const nonceBuf = new Uint8Array(4);
                new DataView(nonceBuf.buffer).setUint32(0, nonce, false);
                const secretSeed = new Uint8Array(hmac(sha256, shared, concatBytes(domain, nonceBuf, new Uint8Array([0]))));
                const nullSeed = new Uint8Array(hmac(sha256, shared, concatBytes(domain, nonceBuf, new Uint8Array([1]))));
                const testCommit = computePoolLeafCommitment(secretSeed, nullSeed, denomTacit);
                const testHex = bytesToHex(testCommit);
                const match = commitSet.get(testHex);
                if (!match) continue;
                const nullifierHash = computeNullifierHash(nullSeed);
                _saveBridgeRecord(_rgNotesKey, {
                  assetIdHex: tethAid,
                  denomination: denomTacit.toString(),
                  secretHex: bytesToHex(secretSeed),
                  nullifierPreimageHex: bytesToHex(nullSeed),
                  leafCommitmentHex: testHex,
                  nullifierHashHex: bytesToHex(nullifierHash),
                  rotateTxid: match.deposit_txid,
                  senderPubHex: senderPub,
                  gen: _rg.gen || '',
                  mixerAddress: _rg.address,
                  status: 'minted',
                  timestamp: Date.now(),
                  source: 'bridge_rotate',
                  recoveredAt: Date.now(),
                });
                rotationsFound++;
                commitSet.delete(testHex);
                _p(`recovered rotated note (nonce ${nonce})`);
              }
            } catch {}
          }
        } catch {}
        }
      }
    }
  } catch {}

  if (recovered > 0 || stealthFound > 0 || rotationsFound > 0) {
    try { _mixerPoolCacheUntil = 0; await refreshPoolsIfStale(); } catch {}
  }

  _p(`done — recovered ${recovered} deposits, ${stealthFound} shielded UTXOs, ${rotationsFound} rotations`);
  return { recovered, stealthFound, rotationsFound, importsFound };
}

// --- Ethereum tree management (fetch deposits, build Poseidon tree) ---

async function bridgeFetchEthDeposits(provider, denomination, gctx) {
  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  const _g = gctx || tethActiveCtx();
  const denomBig = BigInt(denomination);
  const poolId = keccak_256(concatBytes(
    hexToBytes(_pad32(bytesToHex(TETH_BRIDGE.assetId))),
    hexToBytes(_pad32(denomBig.toString(16))),
  ));
  const depositTopic = keccak_256(new TextEncoder().encode('Deposit(bytes32,bytes32,uint256,uint256)'));
  const poolIdTopic = '0x' + bytesToHex(poolId);

  // Try provider first, fall back to public RPC if it returns empty
  // (some MetaMask RPCs restrict eth_getLogs range)
  const params = [{
    address: _g.address,
    fromBlock: _g.deployBlock || '0x0',
    toBlock: 'latest',
    topics: ['0x' + bytesToHex(depositTopic), poolIdTopic],
  }];
  let logs;
  try {
    logs = await provider.request({ method: 'eth_getLogs', params });
  } catch { logs = []; }
  if (!logs || logs.length === 0) {
    try { logs = await _ethRpcCall('eth_getLogs', params) || []; } catch { logs = []; }
  }
  if (!logs) logs = [];

  return logs.map(log => {
    const commitment = log.topics[2];
    const leafIndex = parseInt(log.data.slice(0, 66), 16);
    return { commitment: commitment.replace(/^0x/, ''), leafIndex };
  });
}

function bridgeBuildEthTree(commitmentHexes) {
  const depth = 20;
  const n = commitmentHexes.length;
  const leaves = commitmentHexes.map(h => hexToBytes(h));

  const zeroLeaf = new Uint8Array(32);
  const zeros = [zeroLeaf];
  for (let d = 1; d < depth; d++) zeros.push(poseidonHash(zeros[d - 1], zeros[d - 1]));

  // Sparse tree: only store nodes that differ from the zero default.
  // For n leaves this is O(n * depth) nodes, not O(2^depth).
  const nodes = new Map();
  const nodeKey = (level, idx) => `${level}:${idx}`;
  const getNode = (level, idx) => nodes.get(nodeKey(level, idx)) || zeros[level];

  for (let i = 0; i < n; i++) nodes.set(nodeKey(0, i), leaves[i]);
  for (let d = 0; d < depth; d++) {
    const count = Math.ceil(n / (1 << d));
    for (let i = 0; i < count; i += 2) {
      const parent = Math.floor(i / 2);
      const left = getNode(d, i);
      const right = getNode(d, i + 1);
      nodes.set(nodeKey(d + 1, parent), poseidonHash(left, right));
    }
  }

  const root = getNode(depth, 0);

  return {
    root,
    leafCount: n,
    getProof(leafIndex) {
      const pathElements = [];
      const pathIndices = [];
      let idx = leafIndex;
      for (let d = 0; d < depth; d++) {
        const sibIdx = idx ^ 1;
        pathElements.push(bytes32ToBigint(getNode(d, sibIdx)));
        pathIndices.push(idx & 1);
        idx >>= 1;
      }
      return { pathElements, pathIndices, root: bytes32ToBigint(root) };
    },
  };
}

// --- Bridge mint: T_BRIDGE_DEPOSIT on Bitcoin (step 2) ---

async function buildAndBroadcastBridgeDeposit({ ethDepositRecord, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };

  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  const assetIdBytes = TETH_BRIDGE.assetId;
  const denomTacit = BigInt(ethDepositRecord.denomination);
  const denomWei = ethDepositRecord.denominationWei ? BigInt(ethDepositRecord.denominationWei) : denomTacit * BRIDGE_UNIT_SCALE;
  const denomWeiBytes = bigintToBytes32Strict(denomWei);
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  // The mint targets the generation the ETH deposit went into.
  const gctx = tethCtxForRecord(ethDepositRecord);
  if (!gctx) throw new Error('bridge not configured');

  _p('fetching Ethereum deposits');
  const provider = window.ethereum;
  if (!provider) throw new Error('Ethereum wallet required to fetch deposit tree');
  const deposits = await bridgeFetchEthDeposits(provider, denomWei, gctx);
  if (deposits.length === 0) throw new Error('no deposits found in Ethereum mixer');
  _p(`found ${deposits.length} deposits — locating yours`);

  let myCommitHex = ethDepositRecord.ethCommitmentHex || ethDepositRecord.commitmentHex;
  if (!myCommitHex) {
    const _sE = hexToBytes(ethDepositRecord.secretEthHex || ethDepositRecord.secretHex);
    const _nE = hexToBytes(ethDepositRecord.nullifierPreimageEthHex || ethDepositRecord.nullifierPreimageHex);
    myCommitHex = bytesToHex(computePoolLeafCommitment(_sE, _nE, denomTacit));
  }
  if (!myCommitHex) throw new Error('deposit record missing commitment — run Recover Notes');
  const myIndex = deposits.findIndex(d => d.commitment.toLowerCase() === myCommitHex.toLowerCase());
  if (myIndex < 0) throw new Error('your deposit commitment not found in Ethereum mixer tree — wait for more Ethereum confirmations');

  _p(`building merkle tree (${deposits.length} leaves, your deposit at index ${myIndex})`);
  const ethTree = bridgeBuildEthTree(deposits.map(d => d.commitment));
  const ethProof = ethTree.getProof(myIndex);

  const secretEth = hexToBytes(ethDepositRecord.secretEthHex || ethDepositRecord.secretHex);
  const nullifierPreimageEth = hexToBytes(ethDepositRecord.nullifierPreimageEthHex || ethDepositRecord.nullifierPreimageHex);
  if (!ethDepositRecord.secretPoolHex) {
    throw new Error('old-format deposit record (single secret pair) — run Recover Notes to re-derive with the two-secret format');
  }
  const secretPool = hexToBytes(ethDepositRecord.secretPoolHex);
  const nullifierPreimagePool = hexToBytes(ethDepositRecord.nullifierPreimagePoolHex);

  const ethRootBytes = ethProof.root instanceof Uint8Array ? ethProof.root : bigintToBytes32(ethProof.root);
  const built = await buildBridgeDepositEnvelope({
    networkTag, assetId: assetIdBytes, denomWei: denomWeiBytes,
    ethRoot: ethRootBytes,
    secretEth, nullifierPreimageEth,
    secretPool, nullifierPreimagePool,
    ethTreePathElements: ethProof.pathElements,
    ethTreePathIndices: ethProof.pathIndices,
    denomination: denomTacit,
  });

  _p('generating Groth16 proof');
  const { snarkjs } = await import('./vendor/tacit-mixer.min.js');
  const circuitHash = TACIT_DEFAULT_CEREMONY_HASH;
  const zkeyBytes = await ceremonyFetchHeadZkeyBytes(circuitHash);
  const wasmResp = await fetch(TACIT_WITHDRAW_WASM_PATH);
  if (!wasmResp.ok) throw new Error(`wasm fetch failed: HTTP ${wasmResp.status}`);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());

  const PROOF_TIMEOUT_MS = 180_000;
  const t0 = Date.now();
  let proof, publicSignals;
  try {
    const pp = snarkjs.groth16.fullProve(built.proofInput, wasmBytes, zkeyBytes);
    const tp = new Promise((_, rej) => setTimeout(() => rej(new Error('proof generation timed out')), PROOF_TIMEOUT_MS));
    ({ proof, publicSignals } = await Promise.race([pp, tp]));
  } catch (e) {
    throw new Error(`Groth16 proof failed: ${e.message || e}. Your ETH deposit record is safe in localStorage.`);
  }
  _p('proof:done', { ms: Date.now() - t0 });

  const proofBytes = _serializeGroth16Proof(proof);
  const denomTacitBytes = bigintToBytes32Strict(denomTacit);
  const fullPayload = encodeTBridgeDepositPayload({
    networkTag, assetId: assetIdBytes, denomWei: denomTacitBytes,
    ethRoot: ethRootBytes,
    nullifierHash: built.nullifierHash,
    recipientCommit: built.recipientCommit,
    leafHash: built.leafHash,
    rLeaf: built.rLeaf,
    bindHash: computeBridgeDepositBindHash(
      networkTag, assetIdBytes, denomTacitBytes, ethRootBytes,
      built.nullifierHash, built.recipientCommit, built.leafHash, built.rLeaf,
      gctx,
    ),
    proof: proofBytes,
  });

  // Build commit/reveal Taproot pair. Bridge mint envelopes (~517B) exceed
  // the 80B OP_RETURN cap on mainnet Bitcoin Core; Taproot reveal is the
  // mainnet-compatible path. Mirrors buildAndBroadcastBridgeBurn + the
  // existing buildAndBroadcastWithdraw template. Audit
  // ops/PLAN-bridge-op-return-standardness.md.
  _p('building Bitcoin transaction');
  const feeRate = await getFeeRate('priority');
  const wpkhSpk = p2wpkhScript(wallet.pub);

  const envelopeScript = encodeEnvelopeScript(wallet.xonly(), fullPayload);
  const leaf = tapLeafHash(envelopeScript);
  const { Q_xonly, parity } = tweakedOutputKey(TAP_NUMS, leaf);
  const p2trSpk = p2trScript(Q_xonly);
  const cb = controlBlock(TAP_NUMS, parity);

  const revealVb = Math.ceil((envelopeScript.length + 200) / 4) + 31 + 11;
  const revealFee = feeFor(revealVb, feeRate);
  const commitP2trValue = DUST + revealFee;

  const allUtxos = await getUtxos(wallet.address());
  const sats = await pickSafeCommitSats(allUtxos);
  const picked = []; let total = 0;
  let commitFee = 500;
  for (const u of sats) {
    picked.push(u); total += u.value;
    commitFee = feeFor(estCommitVb(picked.length), feeRate);
    if (total >= commitP2trValue + commitFee + DUST) break;
  }
  if (total < commitP2trValue + commitFee) {
    throw new Error(`insufficient sats (need ~${commitP2trValue + commitFee}, have ${total})`);
  }

  const change = total - commitP2trValue - commitFee;
  const commitOutputs = [{ value: commitP2trValue, script: p2trSpk }];
  if (change >= DUST) commitOutputs.push({ value: change, script: wpkhSpk });
  const commitTx = {
    version: 2, locktime: 0,
    inputs: picked.map(u => ({ txid: u.txid, vout: u.vout, sequence: 0xfffffffd, witness: [] })),
    outputs: commitOutputs,
  };
  signCommitInputs(commitTx, picked, wpkhSpk);
  const commitHex = bytesToHex(serializeTx(commitTx));
  const commitTxid_ = txid(commitTx);
  _p('broadcasting bridge deposit commit');
  await broadcast(commitHex);

  const revealTx = {
    version: 2, locktime: 0,
    inputs: [{ txid: commitTxid_, vout: 0, sequence: 0xfffffffd, witness: [] }],
    outputs: [{ value: DUST, script: wpkhSpk }],
  };
  const prevouts = [{ value: commitP2trValue, script: p2trSpk }];
  revealTx.inputs[0].witness = signTaprootScriptPathInput(revealTx, prevouts, envelopeScript, cb);
  const revealHex = bytesToHex(serializeTx(revealTx));
  const bridgeTxid = txid(revealTx);
  _p('broadcasting bridge deposit reveal');
  await broadcastWithRetry(revealHex);
  postHint(bridgeTxid, 0);

  const noteRecord = {
    ...built.tacitNoteRecord,
    bridgeDepositTxid: bridgeTxid,
    bridgeDepositCommitTxid: commitTxid_,
    ethDepositTxHash: ethDepositRecord.ethTxHash,
    status: 'minted',
    gen: gctx.gen || '',
    mixerAddress: gctx.address,
    // The notes key is scoped to network+mixer only, so every signed-in
    // account in this browser profile sees this record. Stamp the wallet
    // that made the deposit so the withdraw path can route the tETH to it
    // (or demand explicit consent) instead of silently minting to whichever
    // account happens to be signed in when the withdraw runs.
    ownerPubHex: wallet.pub ? bytesToHex(wallet.pub) : undefined,
  };
  _saveBridgeRecord(_BRIDGE_TETH_NOTES_KEY_FOR(gctx.address), noteRecord);
  saveMixerDepositRecord(noteRecord);
  _p('done');
  return noteRecord;
}

const _BRIDGE_WITHDRAW_STEALTH_DOMAIN = new TextEncoder().encode('tacit-bridge-withdraw-stealth-v1');

function _deriveBridgeWithdrawStealthBlinding(privkey, secretHex) {
  const secretBytes = hexToBytes(secretHex);
  const b = BigInt('0x' + bytesToHex(hmac(sha256, privkey, concatBytes(_BRIDGE_WITHDRAW_STEALTH_DOMAIN, secretBytes)))) % SECP_N;
  if (b === 0n) throw new Error('stealth blinding derived zero');
  return b;
}

// Resolve a note's canonical pool-tree merkle proof, healing the two
// drifts that otherwise dead-end at "leaf not in pool tree": (1) a stored
// leafCommitmentHex gone stale (legacy mint, partial recovery, manual
// import) while the note's secret/nullifier — the canonical source of
// truth — stay intact, and (2) a local tree lagging the indexer. It tries
// the stored commitment, then one re-derived straight from
// secret+nullifier+denom, forcing a fresh pool scan between rounds; a
// match via the derived value repairs the persisted record so the next op
// is instant. Throws a self-diagnosing error (target vs the canonical leaf
// set) when nothing matches, so a stuck withdraw shows why.
async function _resolveNoteLeafProof(noteRecord, assetIdHex, denomBig, gctx) {
  const _gen = (gctx && gctx.gen) || '';
  let derivedHex = null;
  try {
    if (noteRecord.secretHex && noteRecord.nullifierPreimageHex) {
      derivedHex = bytesToHex(computePoolLeafCommitment(
        hexToBytes(noteRecord.secretHex),
        hexToBytes(noteRecord.nullifierPreimageHex),
        denomBig,
      ));
    }
  } catch {}
  const attempt = () => {
    const seen = new Set();
    for (const hex of [noteRecord.leafCommitmentHex, derivedHex]) {
      if (!hex || !/^[0-9a-fA-F]{64}$/.test(hex)) continue;
      const lc = hex.toLowerCase();
      if (seen.has(lc)) continue;
      seen.add(lc);
      const mp = buildMixerMerkleProof(assetIdHex, denomBig, hexToBytes(hex), _gen);
      if (mp) return { mp, hex };
    }
    return null;
  };
  let hit = attempt();
  if (!hit) {
    _mixerPoolCacheUntil = 0;
    try { await refreshPoolsIfStale(); } catch {}
    hit = attempt();
  }
  if (!hit) {
    const tree = poolMerkleTrees.get(poolKey(assetIdHex, denomBig, _gen));
    const n = tree ? tree.leaves.length : 0;
    const canon = tree ? tree.leaves.slice(0, 8).map(l => bytesToHex(l).slice(0, 10)).join(', ') : 'no local tree';
    const tgt = (noteRecord.leafCommitmentHex || '?').slice(0, 10);
    const drv = derivedHex && derivedHex !== noteRecord.leafCommitmentHex ? ` (derived ${derivedHex.slice(0, 10)})` : '';
    throw new Error(`leaf ${tgt}${drv} not among ${n} ${n === 1 ? 'pool leaf' : 'pool leaves'} [${canon}] — indexer still catching up, retry shortly`);
  }
  // Heal a stale stored commitment so the next op skips the re-derive.
  if (hit.hex !== noteRecord.leafCommitmentHex) {
    noteRecord.leafCommitmentHex = hit.hex;
    try {
      const key = (gctx && gctx.address) ? _BRIDGE_TETH_NOTES_KEY_FOR(gctx.address) : _BRIDGE_TETH_NOTES_KEY();
      const recs = _getBridgeRecords(key);
      const r = recs.find(x => x.nullifierHashHex && x.nullifierHashHex === noteRecord.nullifierHashHex);
      if (r) { r.leafCommitmentHex = hit.hex; localStorage.setItem(key, JSON.stringify(recs)); }
    } catch {}
  }
  return { mp: hit.mp, leafBytes: hexToBytes(hit.hex) };
}

async function bridgeAutoWithdraw({ noteRecord, onProgress }) {
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  _p('withdrawing tETH to wallet');
  await ensurePrivkey();
  // The export below mints the tETH UTXO to the wallet signed in NOW, not
  // the one that made the deposit. Refuse to claim another account's note
  // unless the caller passed explicit consent (allowForeignClaim) — without
  // this, a retry under a different signed-in account silently routes the
  // funds to that account's wallet. Legacy notes without ownerPubHex keep
  // the old current-wallet behavior.
  if (noteRecord.ownerPubHex && wallet?.pub && !noteRecord.allowForeignClaim) {
    const _cur = bytesToHex(wallet.pub);
    if (_cur !== noteRecord.ownerPubHex) {
      throw new Error(
        `note owner: this deposit was made under a different signed-in account ` +
        `(deposited by ${noteRecord.ownerPubHex.slice(0, 12)}…, signed in ${_cur.slice(0, 12)}…). ` +
        `Switch back to that account to receive the tETH there, or confirm claiming it to this one.`
      );
    }
  }
  const _validHex = (s) => typeof s === 'string' && s !== 'undefined' && s.length > 0 && /^[0-9a-fA-F]+$/.test(s);
  if (!_validHex(noteRecord.secretHex) || !_validHex(noteRecord.nullifierPreimageHex)) {
    const mixerRecs = loadMixerDeposits().filter(r => _validHex(r.secretHex));
    const match = mixerRecs.find(r => r.leafCommitmentHex === noteRecord.leafCommitmentHex)
      || mixerRecs.find(r => r.assetIdHex === noteRecord.assetIdHex && r.denomination === noteRecord.denomination);
    if (match) {
      if (!_validHex(noteRecord.secretHex)) noteRecord.secretHex = match.secretHex;
      if (!_validHex(noteRecord.nullifierPreimageHex)) noteRecord.nullifierPreimageHex = match.nullifierPreimageHex;
      if (!_validHex(noteRecord.nullifierHashHex)) noteRecord.nullifierHashHex = match.nullifierHashHex;
      if (!_validHex(noteRecord.leafCommitmentHex)) noteRecord.leafCommitmentHex = match.leafCommitmentHex;
    }
    if (!_validHex(noteRecord.secretHex)) {
      throw new Error('note missing secretHex — run Recover Notes in the bridge modal to rebuild from your private key');
    }
  }
  // Route through bridge export (0x63) — the bridge-native path that emits
  // the spendable tETH UTXO at vout 1 with the bridge stealth-blinding
  // derivation (computeStealthCommit over wallet.pub +
  // _deriveBridgeWithdrawStealthBlinding) and handles recordStealthCredit +
  // recordOpening internally. The bridge guest also marks 0x2A nullifiers
  // (Taproot reveal dispatch in program/src/main.rs), so cross-ledger
  // double-claim is closed in either route; we still prefer 0x63 for the
  // bridge-aware accounting + UTXO layout the bridge UI tracks.
  const result = await buildAndBroadcastBridgeExport({ noteRecord, onProgress });

  noteRecord.autoWithdrawPending = false;
  noteRecord.withdrawTxid = result.exportTxid;
  _p('done');
  // Preserve `revealTxid` field for callers that hit it (UI link rendering, etc.).
  return { ...result, revealTxid: result.exportTxid };
}

// --- Quick withdraw: deposit tETH UTXO into pool + burn in one flow ---

async function bridgeQuickBurnFromHoldings({ assetIdHex, denomination, ethRecipient, onProgress }) {
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  if (!/^0x[0-9a-fA-F]{40}$/.test(ethRecipient)) throw new Error('invalid Ethereum recipient address');
  await ensurePrivkey();

  const tethAid = bytesToHex(TETH_BRIDGE.assetId);
  const denomBig = BigInt(denomination);

  const bridgeNotes = bridgeGetAllNotes();
  const mixerNotes = loadMixerDeposits().filter(r => r.assetIdHex === tethAid);
  const allNotes = [...bridgeNotes, ...mixerNotes];
  // Same liveness filter as the burn-box note list (setupBridgeModal): a note
  // that was accelerated/exported or whose nullifier is spent on-chain must
  // not short-circuit the wallet-UTXO import path — burning it just throws
  // "this note was already spent" while the wallet tETH sits untouched.
  const existingNote = allNotes.find(n => {
    if (n.assetIdHex !== assetIdHex || BigInt(n.denomination || 0) !== denomBig) return false;
    if (!n.secretHex || !n.nullifierPreimageHex || !n.leafCommitmentHex) return false;
    if (n.status === 'withdrawn' || n.status === 'burned' || n.status === 'rotated' || n.status === 'exported' || n.withdrawTxid) return false;
    try {
      const nh = n.nullifierHashHex ? hexToBytes(n.nullifierHashHex) : computeNullifierHash(hexToBytes(n.nullifierPreimageHex));
      return !mixerIsNullifierSpent(assetIdHex, denomBig, nh, n.gen || '');
    } catch { return true; }
  });

  if (existingNote) {
    _p('burning pool note');
    return await buildAndBroadcastBridgeBurn({
      noteRecord: existingNote,
      ethRecipient,
      onProgress,
    });
  }

  _p('no pool note — looking for tETH UTXO to import');
  const holdings = await scanHoldings();
  const tethHolding = holdings.get(assetIdHex);
  if (!tethHolding) throw new Error('no tETH in wallet — nothing to withdraw');
  // Holdings entries wrap the chain UTXO: { utxo: {txid, vout, …}, amount,
  // blinding, commitment } — the outpoint lives one level down.
  const matchUtxo = tethHolding.utxos?.find(u => BigInt(u.amount) === denomBig && u.utxo?.txid);
  if (!matchUtxo) throw new Error(`no ${denomBig} tETH UTXO found — try a different denomination or wait for confirmation`);

  _p('importing tETH UTXO into bridge pool');
  // Disambiguate the import builder's generic stage names — the quick-burn
  // progress map otherwise renders them with burn-flavored labels and the
  // user reads "burn broadcast" when only the import has gone out.
  const _importStage = (s) =>
    s === 'done' ? 'import broadcast'
    : s === 'building Bitcoin transaction' ? 'building import transaction'
    : s;
  const { noteRecord: importedNote } = await buildAndBroadcastBridgeImport({
    tethUtxo: { txid: matchUtxo.utxo.txid, vout: matchUtxo.utxo.vout, amount: matchUtxo.amount },
    onProgress: (s) => _p(_importStage(s)),
  });

  // Staged wait with live status: (1) the import reveal tx gains Bitcoin
  // confirmations, (2) the worker indexes the leaf into the pool tree. The
  // burn step that follows handles the separate prover-coverage wait. Each
  // phase reports a distinct, quantified line so an hour-long wait shows
  // forward motion instead of one frozen "waiting" label.
  // Worker marks a leaf 'included' (and thus indexable) at this Bitcoin
  // depth; the pool detail carries the live value, default 3.
  let _confTarget = 3;
  try {
    const _pd = await fetch(`${WORKER_BASE}/pools/${assetIdHex}/${denomBig}?network=${NET.name}`, { cache: 'no-store' }).then(r => r.json());
    if (Number.isInteger(_pd?.confirmation_depth) && _pd.confirmation_depth > 0) _confTarget = _pd.confirmation_depth;
  } catch {}
  const _leaf = hexToBytes(importedNote.leafCommitmentHex);
  await new Promise((resolve, reject) => {
    let attempts = 0;
    const poll = async () => {
      if (++attempts > 240) { reject(new Error('timed out waiting for import confirmation')); return; }
      // Phase 2 first: if the worker already has the leaf, we're done waiting.
      _mixerPoolCacheUntil = 0;
      try { await refreshPoolsIfStale(); } catch {}
      if (buildMixerMerkleProof(assetIdHex, denomBig, _leaf)) { resolve(); return; }
      // Phase 1: report Bitcoin confirmation depth of the import reveal tx.
      try {
        const [itx, tip] = await Promise.all([getTx(importedNote.importTxid), getTip()]);
        const h = itx?.status?.confirmed ? itx.status.block_height : null;
        if (!h) {
          _p('import in mempool — waiting for first confirmation');
        } else {
          const depth = tip && tip >= h ? (tip - h + 1) : 1;
          if (depth < _confTarget) _p(`import confirming — ${depth}/${_confTarget} blocks`);
          else _p('import confirmed — waiting for pool indexer');
        }
      } catch { _p('waiting for import confirmation'); }
      setTimeout(poll, 15000);
    };
    poll();
  });

  _p('import indexed — burning');
  return await buildAndBroadcastBridgeBurn({
    noteRecord: importedNote,
    ethRecipient,
    onProgress,
  });
}

// WD-3: pre-burn solvency pre-check. Reads the mixer's totalBalance via
// eth_call and refuses to burn if it's less than the leaf's denom (in wei).
// Harmless under the conservation invariant (sum(withdraws) ≤ sum(deposits))
// but catches the pathological edge case where on-chain state was somehow
// drained (or the user's RPC is reading a fork) — avoiding a doomed
// withdrawFromBurn after the BTC nullifier is already spent.
async function ensureTotalBalanceCoversBurn(mixerAddress, denomWei) {
  const balSel = bytesToHex(keccak_256(new TextEncoder().encode('totalBalance()'))).slice(0, 8);
  let balRaw;
  try { balRaw = await _ethRpcCall('eth_call', [{ to: mixerAddress, data: '0x' + balSel }, 'latest']); }
  catch { return; }
  if (!balRaw || balRaw === '0x') return;
  const bal = BigInt(balRaw);
  if (bal < BigInt(denomWei)) {
    throw new Error(
      `pre-burn safety: mixer totalBalance ${bal} wei < burn denom ${denomWei} wei. ` +
      `Burning would spend the BTC nullifier into an inevitable withdrawFromBurn revert (InsufficientBalance). ` +
      `If on-chain state is correct, the bridge has been drained — investigate before retrying.`
    );
  }
}

// Per-pool sync check (audit #2 sync-gate liveness fix): the dapp's local
// root for the SPECIFIC pool being burned must equal the verifier's
// last-proven root for that pool. Replaces the prior aggregate-poolsHash
// check that stalled redemptions whenever ANY pool advanced (a busy 0.001
// denom would block 100 ETH withdrawals). Per-pool keeps the omitted-leaf
// safety (a worker omitting a middle leaf in THIS pool still flips the
// root) while letting other pools' activity not block this burn.
//
// Requires the verifier deployed with the per-pool tail extension (Option B
// emission + verifier extension at SP1PoolRootVerifier.sol). On older
// verifiers, lastProvenPoolRoot returns 0 and this check no-ops gracefully.
// Returns:
//   'validated' — verifier matches local; no further check needed.
//   'noop'      — verifier doesn't expose per-pool root (pre-upgrade deploy
//                 or pre-first-proof), aggregate fallback should run.
//   (throws)    — mismatch; refuse to broadcast burn.
async function ensurePoolViewMatchesVerifier(assetIdHex, denomWei, gctx) {
  if (!_bridgeConfigured()) return 'noop';
  const _g = gctx || tethActiveCtx();
  const mixerAddress = _g && _g.address;
  if (!mixerAddress) return 'noop';
  const aidPad = _pad32(assetIdHex);

  // mixer.poolVerifiers(bytes32) → verifier addr
  const pid = keccak_256(concatBytes(hexToBytes(aidPad), bigintToBytes32Strict(BigInt(denomWei))));
  const pvSel = bytesToHex(keccak_256(new TextEncoder().encode('poolVerifiers(bytes32)'))).slice(0, 8);
  let verAddrRaw;
  // Fail closed: bridge is configured (guard above passed) but no RPC is reachable,
  // so we cannot cross-check the local pool root against the on-chain verifier. Refuse
  // rather than broadcast a burn that could spend a Bitcoin nullifier into a root SP1
  // never proved (LIVE-1). The note is unharmed; retry when an RPC is up.
  try { verAddrRaw = await _ethRpcCall('eth_call', [{ to: mixerAddress, data: '0x' + pvSel + bytesToHex(pid) }, 'latest']); }
  catch { throw new Error('pre-burn check: all Ethereum RPCs unreachable — refusing to broadcast. Retry when an RPC is up.'); }
  if (!verAddrRaw || verAddrRaw === '0x' || verAddrRaw.length < 42) return 'noop';
  const verifierAddress = ('0x' + verAddrRaw.slice(-40)).toLowerCase();
  if (/^0x0+$/.test(verifierAddress)) return 'noop';

  // Find denom index by scanning verifier.denominations(i)
  const ndSel = bytesToHex(keccak_256(new TextEncoder().encode('NUM_DENOMS()'))).slice(0, 8);
  const ndRaw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + ndSel }, 'latest']);
  if (!ndRaw) return 'noop';
  const numDenoms = parseInt(ndRaw, 16);
  if (!Number.isFinite(numDenoms) || numDenoms < 1 || numDenoms > 16) return 'noop';
  const denSel = bytesToHex(keccak_256(new TextEncoder().encode('denominations(uint256)'))).slice(0, 8);
  const denomTacit = BigInt(denomWei) / BigInt(BRIDGE_UNIT_SCALE);
  let denomIdx = -1;
  for (let i = 0; i < numDenoms; i++) {
    const idxHex = i.toString(16).padStart(64, '0');
    const raw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + denSel + idxHex }, 'latest']);
    if (raw && BigInt(raw) === denomTacit) { denomIdx = i; break; }
  }
  if (denomIdx < 0) return 'noop'; // denom not in this verifier; not our bridge

  // Compute local root for THIS pool
  // Pool trees are keyed by the tacit-unit denomination (mixerRegisterPool
  // is called with the worker's pool_denom), not the wei value — look up by
  // denomTacit, not denomWei.
  const tree = poolMerkleTrees.get(poolKey(assetIdHex, denomTacit, _g.gen || ''));
  if (!tree) {
    throw new Error(`pre-burn check: missing local pool data for denom ${denomTacit} tacit; refresh + retry`);
  }
  const localRoot = bytesToHex(computePoolRoot(tree.leaves)).toLowerCase();

  // Fetch verifier.lastProvenPoolRoot(uint8)
  const lprSel = bytesToHex(keccak_256(new TextEncoder().encode('lastProvenPoolRoot(uint8)'))).slice(0, 8);
  const lprIdx = denomIdx.toString(16).padStart(64, '0');
  let lprRaw;
  try { lprRaw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + lprSel + lprIdx }, 'latest']); }
  catch { throw new Error('pre-burn check: all Ethereum RPCs unreachable — refusing to broadcast. Retry when an RPC is up.'); }
  if (!lprRaw || lprRaw === '0x') return 'noop';
  const lprRoot = lprRaw.slice(2).toLowerCase();

  // If verifier has no proven root yet for this pool (all-zero), per-pool
  // check can't validate yet — let the aggregate fallback run.
  if (lprRoot === '0'.repeat(64)) return 'noop';

  if (localRoot !== lprRoot) {
    // Disambiguate before warning about divergence. The tree records every
    // append-root (rootHistory), so "proven root is a prior root of this
    // tree" proves the on-chain state is a strict prefix of the local view:
    // deposits confirmed after the prover's last cycle, nothing omitted or
    // reordered. That's routine right after a deposit (the prover scans
    // behind a confirmation gate) — report it as a sync wait the caller can
    // auto-retry, and keep the fund-LOCK warning for real divergence. When
    // the proven root is still inside the 32-deep ordered ring (tree.roots)
    // we can count exactly how many leaves await proving.
    const _emptyRoot = bytesToHex(computePoolRoot([])).toLowerCase();
    const _provenIsPrefix = lprRoot === _emptyRoot
      || (tree.rootHistory && tree.rootHistory.has(lprRoot));
    if (_provenIsPrefix) {
      let _pending = null;
      if (lprRoot === _emptyRoot) _pending = tree.leaves.length;
      else {
        const _ri = tree.roots.findIndex(r => bytesToHex(r) === lprRoot);
        if (_ri >= 0) _pending = tree.roots.length - 1 - _ri;
      }
      const _pendDesc = _pending === 1 ? 'a deposit' : _pending != null ? `${_pending} deposits` : 'newer deposits';
      throw new Error(
        `pool sync: ${_pendDesc} in this pool confirmed after the prover's last SP1 cycle. ` +
        `Withdrawals wait until the next proof covers them — usually under an hour. ` +
        `Funds are safe; nothing was broadcast.`
      );
    }
    throw new Error(
      `pre-burn safety: pool denom ${denomTacit} tacit local root 0x${localRoot.slice(0,16)}… ` +
      `differs from SP1 last-proven root 0x${lprRoot.slice(0,16)}… and the proven root is not a ` +
      `prior root of the local tree. Either the local view is stale (refresh and retry) or the ` +
      `indexer omitted/added a leaf in THIS pool. Burning now would spend the Bitcoin nullifier ` +
      `into UnprovenRoot — permanent fund-LOCK — so the withdraw was stopped before broadcast.`
    );
  }
  // Roots match, but a deposit still confirming will land in an earlier block
  // than this burn and advance the guest's pool state past the root the burn
  // binds; the guest seeds each proof cycle with only its resumed root, and
  // the 6-conf scan gate guarantees the confirming deposit is proven in an
  // earlier cycle than the burn — the burn's claim would be rejected on
  // chain. Defer until the pool has no confirming deposits; the pool-sync
  // retry ladder picks this up like any other sync wait.
  if (tree.pendingLeafCount > 0) {
    const _pn = tree.pendingLeafCount;
    throw new Error(
      `pool sync: ${_pn === 1 ? 'a deposit is' : `${_pn} deposits are`} still confirming in this pool, ` +
      `and a withdrawal broadcast now would bind a pool root the prover replaces before covering it. ` +
      `Withdrawals resume once the next proof lands — usually under an hour. ` +
      `Funds are safe; nothing was broadcast.`
    );
  }
  return 'validated';
}

// Pre-burn safety check (legacy aggregate, kept for older verifier deploys
// that don't have the per-pool tail extension): the local pool view (sum of
// all denoms' merkle roots, hashed in deploy order) must match what the SP1
// verifier has accepted as state. A hostile/buggy worker that OMITS a real
// middle leaf yields a local tree root SP1 has never proven — burning against
// that root spends a Bitcoin nullifier with no on-chain claim possible
// (permanent single-user fund-LOCK, `withdrawFromBurn` reverts `UnprovenRoot`
// forever). The integrity check catches FAKE leaves; this catches OMITTED real
// ones. Audit blocker #5.
//
// Throws (refuses to burn) on mismatch. Skips silently if the verifier can't
// be reached or the assetIdHex isn't a configured bridge asset.
async function ensurePoolsViewMatchesVerifier(assetIdHex, gctx) {
  if (!_bridgeConfigured()) return;
  const _g = gctx || tethActiveCtx();
  const mixerAddress = _g && _g.address;
  if (!mixerAddress) return;

  const aidPad = _pad32(assetIdHex);
  // mixer.poolVerifiers(bytes32 poolId) → verifier addr (uint160 in 32 bytes)
  const _someDenom = BigInt('1000000000000000'); // 0.001 ETH wei — any registered denom works
  const _someDenomBytes = bigintToBytes32Strict(_someDenom);
  const _somePid = keccak_256(concatBytes(hexToBytes(aidPad), _someDenomBytes));
  const pvSel = bytesToHex(keccak_256(new TextEncoder().encode('poolVerifiers(bytes32)'))).slice(0, 8);
  let verAddr32;
  try {
    verAddr32 = await _ethRpcCall('eth_call', [
      { to: mixerAddress, data: '0x' + pvSel + bytesToHex(_somePid) }, 'latest',
    ]);
  } catch { return; }
  if (!verAddr32 || verAddr32 === '0x' || verAddr32.length < 42) return;
  const verifierAddress = ('0x' + verAddr32.slice(-40)).toLowerCase();
  if (/^0x0+$/.test(verifierAddress)) return;

  // verifier.currentState() → (poolsHash, nullifierSetHash, stateHeight, lastBlockHash)
  const csSel = bytesToHex(keccak_256(new TextEncoder().encode('currentState()'))).slice(0, 8);
  let stateRaw;
  try { stateRaw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + csSel }, 'latest']); }
  catch { return; }
  if (!stateRaw || stateRaw.length < 2 + 64 * 4) return;
  const verifierPoolsHashHex = stateRaw.slice(2, 66).toLowerCase();

  // verifier.NUM_DENOMS() → uint8
  const ndSel = bytesToHex(keccak_256(new TextEncoder().encode('NUM_DENOMS()'))).slice(0, 8);
  let ndRaw;
  try { ndRaw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + ndSel }, 'latest']); }
  catch { return; }
  if (!ndRaw) return;
  const numDenoms = parseInt(ndRaw, 16);
  if (!Number.isFinite(numDenoms) || numDenoms < 1 || numDenoms > 16) return;

  // For each i: verifier.denominations(i) → bytes32 (denom packed as tacit-units)
  const denSel = bytesToHex(keccak_256(new TextEncoder().encode('denominations(uint256)'))).slice(0, 8);
  const roots = [];
  for (let i = 0; i < numDenoms; i++) {
    const idxHex = i.toString(16).padStart(64, '0');
    let denomRaw;
    try { denomRaw = await _ethRpcCall('eth_call', [{ to: verifierAddress, data: '0x' + denSel + idxHex }, 'latest']); }
    catch { return; }
    if (!denomRaw) return;
    const denomTacit = BigInt(denomRaw);
    const tree = poolMerkleTrees.get(poolKey(assetIdHex, denomTacit, _g.gen || ''));
    if (!tree) {
      throw new Error(
        `pre-burn safety check: missing local data for denom ${denomTacit} (tacit-units). ` +
        `Refresh all 8 denom pools before burning so the dapp's view matches the SP1 verifier — ` +
        `otherwise an omitted leaf in any pool produces a poolsHash the verifier rejects forever.`
      );
    }
    const rootBytes = computePoolRoot(tree.leaves);
    roots.push(rootBytes);
  }

  const localPoolsHashBytes = sha256(concatBytes(...roots));
  const localPoolsHashHex = bytesToHex(localPoolsHashBytes).toLowerCase();

  if (localPoolsHashHex !== verifierPoolsHashHex) {
    throw new Error(
      `pre-burn safety check FAILED: local pool view sha256 ${localPoolsHashHex.slice(0, 16)}… ` +
      `does not match on-chain SP1 verifier state ${verifierPoolsHashHex.slice(0, 16)}…. ` +
      `The indexer's view diverges from the SP1 prover's view — likely a missing or extra leaf in some pool. ` +
      `Refusing to broadcast: a burn against this view would consume a Bitcoin nullifier with no on-chain claim ` +
      `(permanent fund-LOCK; withdrawFromBurn would revert UnprovenRoot). ` +
      `Switch indexer + refresh, then retry.`
    );
  }
}

// --- Bridge burn: T_BRIDGE_BURN on Bitcoin (step 3) ---

async function buildAndBroadcastBridgeBurn({ noteRecord, ethRecipient, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };

  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  if (!/^0x[0-9a-fA-F]{40}$/.test(ethRecipient)) throw new Error('invalid Ethereum recipient address');

  const assetIdHex = noteRecord.assetIdHex;
  const denomBig = BigInt(noteRecord.denomination);
  const assetIdBytes = hexToBytes(assetIdHex);
  const denomTacitBytes = bigintToBytes32Strict(denomBig);
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  const ethRecipientBytes = hexToBytes(ethRecipient.replace(/^0x/, ''));
  // The note's home generation: its pool tree, mixer, and bind-hash constants.
  const gctx = tethCtxForRecord(noteRecord);
  if (!gctx) throw new Error('bridge not configured');
  const _gen = gctx.gen || '';

  if (!mixerIsPoolRegistered(assetIdHex, denomBig, _gen)) {
    await refreshPoolsIfStale();
    if (!mixerIsPoolRegistered(assetIdHex, denomBig, _gen)) throw new Error('tETH pool not registered locally — try refreshing');
  }

  const nhCheck = hexToBytes(noteRecord.nullifierHashHex || bytesToHex(computeNullifierHash(hexToBytes(noteRecord.nullifierPreimageHex))));
  if (mixerIsNullifierSpent(assetIdHex, denomBig, nhCheck, _gen)) throw new Error('this note was already spent');

  if (gctx.address) {
    try {
      const weiDenom = denomBig * BigInt(BRIDGE_UNIT_SCALE);
      const poolIdBytes = keccak_256(concatBytes(hexToBytes(_pad32(assetIdHex)), bigintToBytes32Strict(weiDenom)));
      const sel = bytesToHex(keccak_256(new TextEncoder().encode('isBurnNullifierSpent(bytes32,bytes32)'))).slice(0, 8);
      const data = '0x' + sel + bytesToHex(poolIdBytes) + bytesToHex(nhCheck);
      const result = await _ethRpcCall('eth_call', [{ to: gctx.address, data }, 'latest']);
      if (result && BigInt(result) === 1n) throw new Error('this note was already burned on Ethereum — use Resume to withdraw');
    } catch (e) {
      if (e.message.includes('already burned')) throw e;
    }
  }

  _p('building merkle proof');
  const { mp, leafBytes } = await _resolveNoteLeafProof(noteRecord, assetIdHex, denomBig, gctx);
  // Don't spend a Bitcoin nullifier into a pool whose local tree failed
  // integrity re-verification this scan (indexer served an invalid leaf, so the
  // tree may diverge from the SP1 guest and the op would strand at UnprovenRoot).
  {
    const _it = poolMerkleTrees.get(poolKey(assetIdHex, denomBig, _gen));
    if (_it && _it.integrityFailed) throw new Error('pool tree failed integrity re-verification (indexer served an invalid leaf) — refusing to spend; switch indexer and refresh');
  }

  // Audit blocker #5 (omitted-leaf) + #2 (sync-gate liveness): per-pool
  // check is the primary path — only the pool being burned needs to match
  // the verifier's last-proven root, so a busy unrelated pool can't stall
  // this burn. Falls through if the verifier doesn't yet expose per-pool
  // roots (pre-upgrade deploy); then the aggregate check runs as backstop.
  _p('verifying pool view matches on-chain SP1 state');
  const _denomWei = denomBig * BigInt(BRIDGE_UNIT_SCALE);
  const _ppResult = await ensurePoolViewMatchesVerifier(assetIdHex, _denomWei, gctx);
  // If per-pool validation succeeded, skip the aggregate (audit #2 fix:
  // unrelated pools' activity shouldn't stall this burn). Only run aggregate
  // when per-pool no-oped (older verifier without per-pool tail, or
  // pre-first-proof zero state).
  if (_ppResult !== 'validated') {
    await ensurePoolsViewMatchesVerifier(assetIdHex, gctx);
  }
  // WD-3: live mixer totalBalance must be ≥ this burn's denom.
  if (gctx.address) {
    await ensureTotalBalanceCoversBurn(gctx.address, _denomWei);
  }

  const secret = hexToBytes(noteRecord.secretHex);
  const nullifierPreimage = hexToBytes(noteRecord.nullifierPreimageHex);
  const rLeafBytes = poseidonHash(secret, nullifierPreimage);
  const rLeafBig = bytes32ToBigint(rLeafBytes) % SECP_N;
  const recipientCommit = pedersenCommit(denomBig, rLeafBig).toRawBytes(true);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const merkleRoot = bigintToBytes32(mp.root);

  const burnNonce = crypto.getRandomValues(new Uint8Array(32));
  const bindHash = computeBridgeBurnBindHash(
    networkTag, assetIdBytes, denomTacitBytes, merkleRoot,
    nullifierHash, recipientCommit, rLeafBytes, ethRecipientBytes, burnNonce,
    gctx,
  );

  const proverInput = {
    root: mp.root.toString(),
    nullifier_hash: bytes32ToBigint(nullifierHash).toString(),
    denomination: denomBig.toString(),
    r_leaf: bytes32ToBigint(rLeafBytes).toString(),
    bind_hash: bytes32ToBigint(bindHash).toString(),
    secret: bytes32ToBigint(secret).toString(),
    nullifier_preimage: bytes32ToBigint(nullifierPreimage).toString(),
    path_elements: mp.pathElements.map(e => (typeof e === 'bigint' ? e : bytes32ToBigint(e)).toString()),
    path_indices: mp.pathIndices,
  };

  _p('generating Groth16 proof');
  const { snarkjs } = await import('./vendor/tacit-mixer.min.js');
  const zkeyBytes = await ceremonyFetchHeadZkeyBytes(TACIT_DEFAULT_CEREMONY_HASH);
  const wasmResp = await fetch(TACIT_WITHDRAW_WASM_PATH);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());

  const t0 = Date.now();
  let proof;
  try {
    const pp = snarkjs.groth16.fullProve(proverInput, wasmBytes, zkeyBytes);
    const tp = new Promise((_, rej) => setTimeout(() => rej(new Error('proof generation timed out')), 180_000));
    ({ proof } = await Promise.race([pp, tp]));
  } catch (e) {
    throw new Error(`Groth16 proof failed: ${e.message || e}`);
  }
  _p('proof:done', { ms: Date.now() - t0 });

  const proofBytes = _serializeGroth16Proof(proof);
  const fullPayload = encodeTBridgeBurnPayload({
    networkTag, assetId: assetIdBytes, denomWei: denomTacitBytes, merkleRoot,
    nullifierHash, recipientCommit, rLeaf: rLeafBytes,
    ethRecipient: ethRecipientBytes, burnNonce, bindHash, proof: proofBytes,
  });

  // Build commit/reveal Taproot pair (the bridge envelope rides in the reveal
  // tx's witness item 1, not OP_RETURN). Mainnet Bitcoin Core caps OP_RETURN
  // at 80B; burn envelopes are ~537B, so the old bare-OP_RETURN path was
  // signet-only. See ops/PLAN-bridge-op-return-standardness.md. Pattern
  // mirrors buildAndBroadcastWithdraw (dapp/tacit.js:28118-28154). The
  // worker indexes either source (worker/src/index.js:20322); the SP1 guest
  // dispatches 0x60-0x64 from both Taproot and OP_RETURN
  // (contracts/sp1/program/src/main.rs Taproot bridge block).
  _p('building Bitcoin transaction');
  const feeRate = await getFeeRate('priority');
  const wpkhSpk = p2wpkhScript(wallet.pub);

  const envelopeScript = encodeEnvelopeScript(wallet.xonly(), fullPayload);
  const leaf = tapLeafHash(envelopeScript);
  const { Q_xonly, parity } = tweakedOutputKey(TAP_NUMS, leaf);
  const p2trSpk = p2trScript(Q_xonly);
  const cb = controlBlock(TAP_NUMS, parity);

  // Reveal tx vbyte estimate: 1 input (P2TR script-path spend with full
  // envelope script in witness) + 1 P2WPKH change output. The envelope
  // script's main bulk is the payload push, so vbyte scales ~ payloadLen/4.
  const revealVb = Math.ceil((envelopeScript.length + 200) / 4) + 31 + 11;
  const revealFee = feeFor(revealVb, feeRate);
  const commitP2trValue = DUST + revealFee;

  const allUtxos = await getUtxos(wallet.address());
  const sats = await pickSafeCommitSats(allUtxos);
  const picked = []; let total = 0;
  let commitFee = 500;
  for (const u of sats) {
    picked.push(u); total += u.value;
    commitFee = feeFor(estCommitVb(picked.length), feeRate);
    if (total >= commitP2trValue + commitFee + DUST) break;
  }
  if (total < commitP2trValue + commitFee) {
    throw new Error(`insufficient sats (need ~${commitP2trValue + commitFee}, have ${total})`);
  }

  const change = total - commitP2trValue - commitFee;
  const commitOutputs = [{ value: commitP2trValue, script: p2trSpk }];
  if (change >= DUST) commitOutputs.push({ value: change, script: wpkhSpk });
  const commitTx = {
    version: 2, locktime: 0,
    inputs: picked.map(u => ({ txid: u.txid, vout: u.vout, sequence: 0xfffffffd, witness: [] })),
    outputs: commitOutputs,
  };
  signCommitInputs(commitTx, picked, wpkhSpk);
  const commitHex = bytesToHex(serializeTx(commitTx));
  const commitTxid_ = txid(commitTx);
  _p('broadcasting bridge burn commit');
  await broadcast(commitHex);

  // Reveal: emits a single P2WPKH change to depositor (burn doesn't create a
  // spendable stealth note — the burn_claim record lives off-chain in SP1).
  const revealTx = {
    version: 2, locktime: 0,
    inputs: [{ txid: commitTxid_, vout: 0, sequence: 0xfffffffd, witness: [] }],
    outputs: [{ value: DUST, script: wpkhSpk }],
  };
  const prevouts = [{ value: commitP2trValue, script: p2trSpk }];
  revealTx.inputs[0].witness = signTaprootScriptPathInput(revealTx, prevouts, envelopeScript, cb);
  const revealHex = bytesToHex(serializeTx(revealTx));
  const burnTxid_ = txid(revealTx); // reveal txid is what worker/guest index
  _p('broadcasting bridge burn reveal');
  await broadcastWithRetry(revealHex);

  const burnRecord = {
    burnTxid: burnTxid_,
    commitTxid: commitTxid_,
    rawTxHex: revealHex,
    ethRecipient,
    denomination: denomBig.toString(),
    assetIdHex,
    nullifierHashHex: bytesToHex(nullifierHash),
    burnNonceHex: bytesToHex(burnNonce),
    gen: _gen,
    mixerAddress: gctx.address,
    timestamp: Date.now(),
    status: 'burned',
  };
  _saveBridgeRecord(_BRIDGE_BURN_RECORDS_KEY_FOR(gctx.address), burnRecord);
  _p('done');
  return burnRecord;
}

// --- Bridge export: pool note → tETH UTXO (enables CXFER/AMM) ---

async function buildAndBroadcastBridgeExport({ noteRecord, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  if (!_bridgeConfigured()) throw new Error('bridge not configured');

  const assetIdHex = noteRecord.assetIdHex;
  const denomBig = BigInt(noteRecord.denomination);
  const assetIdBytes = hexToBytes(assetIdHex);
  const denomTacitBytes = bigintToBytes32Strict(denomBig);
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  const gctx = tethCtxForRecord(noteRecord);
  if (!gctx) throw new Error('bridge not configured');
  const _gen = gctx.gen || '';

  _p('building merkle proof');
  const { mp, leafBytes } = await _resolveNoteLeafProof(noteRecord, assetIdHex, denomBig, gctx);
  // Don't spend a Bitcoin nullifier into a pool whose local tree failed
  // integrity re-verification this scan (indexer served an invalid leaf, so the
  // tree may diverge from the SP1 guest and the op would strand at UnprovenRoot).
  {
    const _it = poolMerkleTrees.get(poolKey(assetIdHex, denomBig, _gen));
    if (_it && _it.integrityFailed) throw new Error('pool tree failed integrity re-verification (indexer served an invalid leaf) — refusing to spend; switch indexer and refresh');
  }

  const secret = hexToBytes(noteRecord.secretHex);
  const nullifierPreimage = hexToBytes(noteRecord.nullifierPreimageHex);
  const rLeafBytes = poseidonHash(secret, nullifierPreimage);
  const rLeafBig = bytes32ToBigint(rLeafBytes) % SECP_N;
  const recipientCommit = pedersenCommit(denomBig, rLeafBig).toRawBytes(true);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const merkleRoot = bigintToBytes32(mp.root);

  // Audit blocker #5, extended to export. Export spends a Bitcoin nullifier
  // against a pool root exactly like burn, so it carries the identical
  // omitted-leaf wedge risk: a hostile/buggy indexer that drops a real leaf
  // yields a local root the SP1 guest never held → the guest skips this export
  // (root unknown) while the worker still records the nullifier → the note can
  // no longer be exported OR burned (both refuse on the now-"spent" nullifier).
  // Refuse to broadcast unless the local pool view matches the on-chain SP1 state.
  // Per-pool variant first (audit #2 sync-gate); aggregate fallback if the
  // verifier lacks per-pool tail (pre-upgrade) or pre-first-proof.
  _p('verifying pool view matches on-chain SP1 state');
  const _exportPpResult = await ensurePoolViewMatchesVerifier(assetIdHex, denomBig * BigInt(BRIDGE_UNIT_SCALE), gctx);
  if (_exportPpResult !== 'validated') {
    await ensurePoolsViewMatchesVerifier(assetIdHex, gctx);
  }

  const bindHash = computeBridgeExportBindHash(
    networkTag, assetIdBytes, denomTacitBytes, merkleRoot,
    nullifierHash, recipientCommit, rLeafBytes, gctx,
  );

  const proverInput = {
    root: mp.root.toString(),
    nullifier_hash: bytes32ToBigint(nullifierHash).toString(),
    denomination: denomBig.toString(),
    r_leaf: bytes32ToBigint(rLeafBytes).toString(),
    bind_hash: bytes32ToBigint(bindHash).toString(),
    secret: bytes32ToBigint(secret).toString(),
    nullifier_preimage: bytes32ToBigint(nullifierPreimage).toString(),
    path_elements: mp.pathElements.map(e => (typeof e === 'bigint' ? e : bytes32ToBigint(e)).toString()),
    path_indices: mp.pathIndices,
  };

  _p('generating Groth16 proof');
  const { snarkjs } = await import('./vendor/tacit-mixer.min.js');
  const zkeyBytes = await ceremonyFetchHeadZkeyBytes(TACIT_DEFAULT_CEREMONY_HASH);
  const wasmResp = await fetch(TACIT_WITHDRAW_WASM_PATH);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());

  const t0 = Date.now();
  let proof;
  try {
    const pp = snarkjs.groth16.fullProve(proverInput, wasmBytes, zkeyBytes);
    const tp = new Promise((_, rej) => setTimeout(() => rej(new Error('proof generation timed out')), 180_000));
    ({ proof } = await Promise.race([pp, tp]));
  } catch (e) {
    throw new Error(`Groth16 proof failed: ${e.message || e}`);
  }
  _p('proof:done', { ms: Date.now() - t0 });

  const proofBytes = _serializeGroth16Proof(proof);
  const fullPayload = encodeTBridgeExportPayload({
    networkTag, assetId: assetIdBytes, denomWei: denomTacitBytes, merkleRoot,
    nullifierHash, recipientCommit, rLeaf: rLeafBytes, bindHash, proof: proofBytes,
  });

  _p('building Bitcoin transaction');
  const feeRate = await getFeeRate('priority');
  const stealthBlinding = _deriveBridgeWithdrawStealthBlinding(wallet.priv, noteRecord.secretHex);
  const stealthPub = computeStealthCommit({ underlyingPub: wallet.pub, blinding: stealthBlinding });
  const recipSpk = p2wpkhScript(stealthPub);
  const wpkhSpk = p2wpkhScript(wallet.pub);

  // Commit/reveal Taproot pair: the export envelope (~485B) exceeds the 80B
  // OP_RETURN cap on mainnet Bitcoin Core. The reveal emits the spendable
  // stealth tETH UTXO at vout 0, where the guest registers the export UTXO
  // (utxo_set.push((revealTxid, 0, ...)) in main.rs's export handler).
  // Mirrors buildAndBroadcastWithdraw. See ops/PLAN-bridge-op-return-standardness.md.
  const envelopeScript = encodeEnvelopeScript(wallet.xonly(), fullPayload);
  const leaf = tapLeafHash(envelopeScript);
  const { Q_xonly, parity } = tweakedOutputKey(TAP_NUMS, leaf);
  const p2trSpk = p2trScript(Q_xonly);
  const cb = controlBlock(TAP_NUMS, parity);

  const revealVb = Math.ceil((envelopeScript.length + 200) / 4) + 31 + 11;
  const revealFee = feeFor(revealVb, feeRate);
  const commitP2trValue = DUST + revealFee;

  const allUtxos = await getUtxos(wallet.address());
  const sats = await pickSafeCommitSats(allUtxos);
  const picked = []; let total = 0;
  let commitFee = 500;
  for (const u of sats) {
    picked.push(u); total += u.value;
    commitFee = feeFor(estCommitVb(picked.length), feeRate);
    if (total >= commitP2trValue + commitFee + DUST) break;
  }
  if (total < commitP2trValue + commitFee) {
    throw new Error(`insufficient sats (need ~${commitP2trValue + commitFee}, have ${total})`);
  }

  const change = total - commitP2trValue - commitFee;
  const commitOutputs = [{ value: commitP2trValue, script: p2trSpk }];
  if (change >= DUST) commitOutputs.push({ value: change, script: wpkhSpk });
  const commitTx = {
    version: 2, locktime: 0,
    inputs: picked.map(u => ({ txid: u.txid, vout: u.vout, sequence: 0xfffffffd, witness: [] })),
    outputs: commitOutputs,
  };
  signCommitInputs(commitTx, picked, wpkhSpk);
  const commitHex = bytesToHex(serializeTx(commitTx));
  const commitTxid_ = txid(commitTx);
  _p('broadcasting bridge export commit');
  await broadcast(commitHex);

  // Reveal: vout 0 = the spendable stealth tETH UTXO (DUST). The bridge
  // envelope rides in the reveal input's witness, not an OP_RETURN output.
  const revealTx = {
    version: 2, locktime: 0,
    inputs: [{ txid: commitTxid_, vout: 0, sequence: 0xfffffffd, witness: [] }],
    outputs: [{ value: DUST, script: recipSpk }],
  };
  const prevouts = [{ value: commitP2trValue, script: p2trSpk }];
  revealTx.inputs[0].witness = signTaprootScriptPathInput(revealTx, prevouts, envelopeScript, cb);
  const revealHex = bytesToHex(serializeTx(revealTx));
  const exportTxid = txid(revealTx);
  _p('broadcasting bridge export reveal');
  await broadcastWithRetry(revealHex);

  recordStealthCredit({
    txidHex: exportTxid, vout: 0,
    assetIdHex,
    amount: denomBig,
    amountBlinding: rLeafBig,
    stealthBlinding,
    commitmentHex: bytesToHex(recipientCommit),
    senderPubHex: bytesToHex(wallet.pub),
    blockTime: null,
  });
  recordOpening(exportTxid, 0, assetIdHex, denomBig, rLeafBig);

  noteRecord.status = 'exported';
  noteRecord.exportTxid = exportTxid;
  noteRecord.exportCommitTxid = commitTxid_;
  noteRecord.withdrawTxid = exportTxid;
  noteRecord.autoWithdrawPending = false;
  // Persist the terminal state + mark the nullifier spent so the pending-note
  // surfaces (Holdings callout, bridge modal, mixer "TETH BRIDGE NOTES") stop
  // counting this note the moment the export broadcasts — without waiting for
  // the worker to index the nullifier on a later scan, and surviving a reload.
  try {
    const _nh = noteRecord.nullifierHashHex ||
      bytesToHex(computeNullifierHash(hexToBytes(noteRecord.nullifierPreimageHex)));
    try { mixerMarkNullifierSpent(assetIdHex, denomBig, hexToBytes(_nh), exportTxid, _gen); } catch {}
    const _nkey = _BRIDGE_TETH_NOTES_KEY_FOR(gctx.address);
    const _recs = _getBridgeRecords(_nkey);
    let _changed = false;
    for (const n of _recs) {
      if (n.nullifierHashHex === _nh) {
        n.status = 'exported'; n.exportTxid = exportTxid; n.withdrawTxid = exportTxid; n.autoWithdrawPending = false;
        _changed = true;
      }
    }
    if (_changed) localStorage.setItem(_nkey, JSON.stringify(_recs));
  } catch {}
  _p('done');
  return { exportTxid, txHex: revealHex, commitTxid: commitTxid_ };
}

// Pre-import check: confirm the prover already recognizes this tETH before the
// import goes out, the same way the redeem path checks pool state before a
// burn. The guest tracks tETH at vout 0 of a bridge export it accepted, so
// replay that acceptance here — the source must be an export for this
// asset/denom whose merkle root is a known pool root and whose Groth16 proof
// verifies against the canonical key. Resolves the generation context the
// export binds (the import's home generation), or throws a short reason.
async function ensureImportUtxoGuestTracked(tethUtxo, assetIdHex, denomBig) {
  if (tethUtxo.vout !== 0) {
    throw new Error('This tETH can only be redeemed from the export output it was sent to.');
  }
  // Load pool root history so the export's root can be recognized.
  try { await refreshPoolsIfStale(); } catch {}
  let tx;
  try { tx = await getTx(tethUtxo.txid); }
  catch { throw new Error('Could not reach the indexer to check this tETH — try again shortly.'); }
  if (!tx) throw new Error('Source transaction not found — try again shortly.');
  let payload = null;
  try {
    const w = tx?.vin?.[0]?.witness;
    if (Array.isArray(w) && w.length >= 2 && typeof w[1] === 'string') {
      const env = decodeEnvelopeScript(hexToBytes(w[1]));
      if (env && env.opcode === T_BRIDGE_EXPORT) payload = env.payload;
    }
  } catch {}
  if (!payload || payload.length < 485) {
    throw new Error('This tETH was not created by a bridge export, so it can’t be redeemed through the pool here.');
  }
  if (bytesToHex(payload.slice(2, 34)) !== assetIdHex.toLowerCase()) throw new Error('Source export asset mismatch.');
  if (BigInt('0x' + bytesToHex(payload.slice(34, 66))) !== denomBig) throw new Error('Source export amount mismatch.');
  // The export's bind hash commits to (chain_id, mixer) — it names the
  // generation whose guest registered this UTXO, so the import must target
  // that generation. Recompute per registry entry and take the match.
  const _expBindHex = bytesToHex(payload.slice(195, 227));
  const _netTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  let gctx = tethActiveCtx();
  {
    const _gens = tethGenList();
    if (_gens.length) {
      let matched = null;
      for (const g of _gens) {
        const cand = computeBridgeExportBindHash(
          _netTag, payload.slice(2, 34), payload.slice(34, 66), payload.slice(66, 98),
          payload.slice(98, 130), payload.slice(130, 163), payload.slice(163, 195), tethGenCtx(g),
        );
        if (bytesToHex(cand) === _expBindHex) { matched = g; break; }
      }
      if (!matched) throw new Error('The source export doesn’t match any known bridge generation — not importing.');
      gctx = tethGenCtx(matched);
    }
  }
  // The export's merkle root must be a root this pool actually had — the same
  // known-root condition the guest applies.
  const merkleRootHex = bytesToHex(payload.slice(66, 98));
  const tree = poolMerkleTrees.get(poolKey(assetIdHex, denomBig, gctx.gen || ''));
  if (!tree || !tree.rootHistory || !tree.rootHistory.has(merkleRootHex)) {
    throw new Error('The source export’s pool state isn’t recognized yet — refresh and try again.');
  }
  // Verify the export's Groth16 proof against the canonical key, with the same
  // public-input ordering the guest uses (mirrors the rotate re-verification).
  const proofLen = payload[227] | (payload[228] << 8);
  if (proofLen !== 256 || payload.length < 229 + 256) throw new Error('Source export proof is malformed.');
  const proof = payload.slice(229, 229 + 256);
  const publicInputs = [
    bytesToHex(payload.slice(66, 98)),    // merkleRoot
    bytesToHex(payload.slice(98, 130)),   // nullifier
    BigInt(denomBig).toString(),          // denomination
    bytesToHex(payload.slice(163, 195)),  // rLeaf
    (BigInt('0x' + bytesToHex(payload.slice(195, 227))) % BN254_FIELD_SIZE).toString(), // bindHash
  ];
  const pool = poolRegistry.get(poolKey(assetIdHex, denomBig, gctx.gen || ''));
  const vkCid = pool && pool.vkCid ? new TextDecoder().decode(pool.vkCid) : CANONICAL_VK_CID;
  let ok;
  try { ok = await verifyMixerProof({ vkCid, publicInputs, proof }); }
  catch { throw new Error('Could not verify the source export yet — try again shortly.'); }
  if (ok !== true) {
    throw new Error('This tETH could not be confirmed as redeemable — not importing.');
  }
  return gctx;
}

// --- Bridge import: tETH UTXO → pool note (enables non-depositor burn) ---

async function buildAndBroadcastBridgeImport({ tethUtxo, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  if (!_bridgeConfigured()) throw new Error('bridge not configured');

  const assetIdHex = bytesToHex(TETH_BRIDGE.assetId);
  const assetIdBytes = TETH_BRIDGE.assetId;
  const denomBig = BigInt(tethUtxo.amount);
  // Confirm the prover recognizes this tETH before broadcasting; the source
  // export's bind hash names the generation whose guest tracks the UTXO, and
  // the import note is created in THAT generation's pool.
  _p('verifying tETH is redeemable');
  const gctx = await ensureImportUtxoGuestTracked(tethUtxo, assetIdHex, denomBig);
  const _gen = (gctx && gctx.gen) || '';
  const denomTacitBytes = bigintToBytes32Strict(denomBig);
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;

  // Internal (chain) byte order — the guest matches env_prev_txid against
  // outpoints parsed from the raw reveal tx and its own compute_txid, both of
  // which are little-endian. Writing the display-order txid here makes the
  // guest's utxo_set lookup and found_input check miss, so it rejects the
  // import (note never created, tETH UTXO consumed). Reverse to chain order;
  // prevTxid also feeds the bind hash, so both stay consistent with the guest.
  const prevTxid = reverseBytes(hexToBytes(tethUtxo.txid));
  const prevVout = tethUtxo.vout;

  // Derive the new note from the spending key + consumed outpoint so a
  // localStorage wipe before redemption recovers it from the key alone, as
  // deposit and rotate notes already do. The reveal spends this tETH UTXO, so
  // (prevTxid, prevVout) is a unique, on-chain-recoverable salt.
  const { secret, nullifierPreimage } = _deriveBridgeImportKeys(wallet.priv, prevTxid, prevVout);
  const newCommitment = computePoolLeafCommitment(secret, nullifierPreimage, denomBig);

  const bindHash = computeBridgeImportBindHash(
    networkTag, assetIdBytes, denomTacitBytes, newCommitment, prevTxid, prevVout, gctx,
  );

  const fullPayload = encodeTBridgeImportPayload({
    networkTag, assetId: assetIdBytes, denomWei: denomTacitBytes,
    newCommitment, bindHash, prevTxid, prevVout,
  });

  _p('building Bitcoin transaction');
  const feeRate = await getFeeRate('priority');
  const wpkhSpk = p2wpkhScript(wallet.pub);

  // Locate the tETH UTXO being imported. It may live at a stealth address
  // (the common case — exports/CXFER receipts land on stealth keys) that
  // needs the stealth-tweaked key to spend.
  const allUtxos = await getUtxos(wallet.address());
  let tethInput = allUtxos.find(u => u.txid === tethUtxo.txid && u.vout === tethUtxo.vout);
  let tethStealthKey = null;
  if (!tethInput) {
    const credit = getStealthCredit(tethUtxo.txid, tethUtxo.vout);
    if (credit && credit.stealthBlindingHex) {
      // getStealthCredit returns the blinding as hex (stealthBlindingHex) —
      // the scalar form expected by computeStealthTweakedSk must be derived.
      const tweakedSk = computeStealthTweakedSk({
        underlyingPriv: wallet.priv,
        blinding: BigInt('0x' + credit.stealthBlindingHex),
      });
      const tweakedPub = secp.getPublicKey(tweakedSk, true);
      const stealthAddr = p2wpkhAddress(tweakedPub);
      const stealthUtxos = await getUtxos(stealthAddr);
      tethInput = stealthUtxos.find(u => u.txid === tethUtxo.txid && u.vout === tethUtxo.vout);
      if (tethInput) tethStealthKey = { priv: tweakedSk, pub: tweakedPub };
    }
  }
  if (!tethInput) throw new Error('tETH UTXO not found — already spent?');
  const tethSpk = tethStealthKey ? p2wpkhScript(tethStealthKey.pub) : wpkhSpk;

  // Commit/reveal Taproot pair (import envelope 164B > 80B OP_RETURN cap). The
  // guest requires the reveal tx to SPEND the imported tETH UTXO — it matches
  // env_prev_txid/prev_vout against the reveal's inputs (extract_input_outpoints)
  // — so the tETH UTXO rides as the reveal's second input alongside the commit
  // P2TR that carries the envelope witness. The commit is funded by separate
  // sats (the tETH UTXO is consumed by the reveal, not the commit). See
  // ops/PLAN-bridge-op-return-standardness.md + main.rs import handler.
  const envelopeScript = encodeEnvelopeScript(wallet.xonly(), fullPayload);
  const leaf = tapLeafHash(envelopeScript);
  const { Q_xonly, parity } = tweakedOutputKey(TAP_NUMS, leaf);
  const p2trSpk = p2trScript(Q_xonly);
  const cb = controlBlock(TAP_NUMS, parity);

  // Reveal carries 2 inputs (taproot script-path + the P2WPKH tETH UTXO) and
  // 1 change output, so budget an extra ~68 vb for the tETH input.
  const revealVb = Math.ceil((envelopeScript.length + 200) / 4) + 68 + 31 + 11;
  const revealFee = feeFor(revealVb, feeRate);
  const commitP2trValue = DUST + revealFee;

  const sats = (await pickSafeCommitSats(allUtxos)).filter(u => !(u.txid === tethInput.txid && u.vout === tethInput.vout));
  const picked = []; let total = 0;
  let commitFee = 500;
  for (const u of sats) {
    picked.push(u); total += u.value;
    commitFee = feeFor(estCommitVb(picked.length), feeRate);
    if (total >= commitP2trValue + commitFee + DUST) break;
  }
  if (total < commitP2trValue + commitFee) {
    throw new Error(`insufficient sats (need ~${commitP2trValue + commitFee}, have ${total})`);
  }

  const change = total - commitP2trValue - commitFee;
  const commitOutputs = [{ value: commitP2trValue, script: p2trSpk }];
  if (change >= DUST) commitOutputs.push({ value: change, script: wpkhSpk });
  const commitTx = {
    version: 2, locktime: 0,
    inputs: picked.map(u => ({ txid: u.txid, vout: u.vout, sequence: 0xfffffffd, witness: [] })),
    outputs: commitOutputs,
  };
  signCommitInputs(commitTx, picked, wpkhSpk);
  const commitHex = bytesToHex(serializeTx(commitTx));
  const commitTxid_ = txid(commitTx);
  _p('broadcasting bridge import commit');
  await broadcast(commitHex);

  // Reveal: vin[0] = commit P2TR (envelope script-path), vin[1] = the tETH
  // UTXO being imported (so the guest sees it consumed). Output = change.
  const revealTx = {
    version: 2, locktime: 0,
    inputs: [
      { txid: commitTxid_, vout: 0, sequence: 0xfffffffd, witness: [] },
      { txid: tethInput.txid, vout: tethInput.vout, sequence: 0xfffffffd, witness: [] },
    ],
    outputs: [{ value: commitP2trValue + tethInput.value - revealFee, script: wpkhSpk }],
  };
  const prevouts = [
    { value: commitP2trValue, script: p2trSpk },
    { value: tethInput.value, script: tethSpk },
  ];
  revealTx.inputs[0].witness = signTaprootScriptPathInput(revealTx, prevouts, envelopeScript, cb);
  revealTx.inputs[1].witness = tethStealthKey
    ? signP2wpkhInputWithKey(revealTx, 1, tethInput.value, tethStealthKey.priv, tethStealthKey.pub)
    : signP2wpkhInput(revealTx, 1, tethInput.value);
  const txHex = bytesToHex(serializeTx(revealTx));
  const importTxid = txid(revealTx);
  _p('broadcasting bridge import reveal');
  await broadcastWithRetry(txHex);

  const noteRecord = {
    assetIdHex,
    denomination: denomBig.toString(),
    secretHex: bytesToHex(secret),
    nullifierPreimageHex: bytesToHex(nullifierPreimage),
    nullifierHashHex: bytesToHex(computeNullifierHash(nullifierPreimage)),
    leafCommitmentHex: bytesToHex(newCommitment),
    importTxid,
    importCommitTxid: commitTxid_,
    gen: _gen,
    mixerAddress: gctx ? gctx.address : TETH_BRIDGE.address,
    timestamp: Date.now(),
    status: 'minted',
    source: 'bridge_import',
  };
  _saveBridgeRecord(_BRIDGE_TETH_NOTES_KEY_FOR(gctx ? gctx.address : TETH_BRIDGE.address), noteRecord);
  saveMixerDepositRecord(noteRecord);
  _p('done');
  return { importTxid, noteRecord };
}

// --- Bridge rotate: spend old pool note, create new pool note (step 3a — transfer) ---

async function buildAndBroadcastBridgeRotate({ noteRecord, newCommitmentHex, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };

  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  const assetIdHex = noteRecord.assetIdHex;
  const denomBig = BigInt(noteRecord.denomination);
  const assetIdBytes = hexToBytes(assetIdHex);
  const denomTacitBytes = bigintToBytes32Strict(denomBig);
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  const newCommitment = hexToBytes(newCommitmentHex);
  // Rotate spends and re-creates a note inside ONE pool, so the new note
  // inherits the source note's generation.
  const gctx = tethCtxForRecord(noteRecord);
  if (!gctx) throw new Error('bridge not configured');
  const _gen = gctx.gen || '';

  _p('building merkle proof');
  const { mp, leafBytes } = await _resolveNoteLeafProof(noteRecord, assetIdHex, denomBig, gctx);
  // Don't spend a Bitcoin nullifier into a pool whose local tree failed
  // integrity re-verification this scan (indexer served an invalid leaf, so the
  // tree may diverge from the SP1 guest and the op would strand at UnprovenRoot).
  {
    const _it = poolMerkleTrees.get(poolKey(assetIdHex, denomBig, _gen));
    if (_it && _it.integrityFailed) throw new Error('pool tree failed integrity re-verification (indexer served an invalid leaf) — refusing to spend; switch indexer and refresh');
  }

  const secret = hexToBytes(noteRecord.secretHex);
  const nullifierPreimage = hexToBytes(noteRecord.nullifierPreimageHex);
  const rLeafBytes = poseidonHash(secret, nullifierPreimage);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const merkleRoot = bigintToBytes32(mp.root);

  // Audit blocker #5, extended to rotate (the whole-note send path). Rotate
  // spends a Bitcoin nullifier against a pool root exactly like burn/export, so
  // an omitted-leaf indexer can wedge the note the same way (guest skips the
  // rotate on an unknown root while the worker records the nullifier → the note
  // can't be re-sent or burned). Refuse to broadcast on a divergent pool view.
  // Per-pool first (audit #2 sync-gate); aggregate fallback when unavailable.
  _p('verifying pool view matches on-chain SP1 state');
  const _rotatePpResult = await ensurePoolViewMatchesVerifier(assetIdHex, denomBig * BigInt(BRIDGE_UNIT_SCALE), gctx);
  if (_rotatePpResult !== 'validated') {
    await ensurePoolsViewMatchesVerifier(assetIdHex, gctx);
  }

  const bindHash = computeBridgeRotateBindHash(
    networkTag, assetIdBytes, denomTacitBytes, merkleRoot,
    nullifierHash, newCommitment, rLeafBytes, gctx,
  );

  _p('generating Groth16 proof');
  const proverInput = {
    root: mp.root.toString(),
    nullifier_hash: bytes32ToBigint(nullifierHash).toString(),
    denomination: denomBig.toString(),
    r_leaf: bytes32ToBigint(rLeafBytes).toString(),
    bind_hash: bytes32ToBigint(bindHash).toString(),
    secret: bytes32ToBigint(secret).toString(),
    nullifier_preimage: bytes32ToBigint(nullifierPreimage).toString(),
    path_elements: mp.pathElements.map(e => (typeof e === 'bigint' ? e : bytes32ToBigint(e)).toString()),
    path_indices: mp.pathIndices,
  };

  const { snarkjs } = await import('./vendor/tacit-mixer.min.js');
  const zkeyBytes = await ceremonyFetchHeadZkeyBytes(TACIT_DEFAULT_CEREMONY_HASH);
  const wasmResp = await fetch(TACIT_WITHDRAW_WASM_PATH);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());

  const t0 = Date.now();
  let proof;
  try {
    const pp = snarkjs.groth16.fullProve(proverInput, wasmBytes, zkeyBytes);
    const tp = new Promise((_, rej) => setTimeout(() => rej(new Error('proof generation timed out')), 180_000));
    ({ proof } = await Promise.race([pp, tp]));
  } catch (e) {
    throw new Error(`Groth16 proof failed: ${e.message || e}`);
  }
  _p('proof:done', { ms: Date.now() - t0 });

  const proofBytes = _serializeGroth16Proof(proof);
  const fullPayload = encodeTBridgeRotatePayload({
    networkTag, assetId: assetIdBytes, denomWei: denomTacitBytes, merkleRoot,
    nullifierHash, newCommitment, rLeaf: rLeafBytes, bindHash, proof: proofBytes,
  });

  // Commit/reveal Taproot pair (rotate envelope ~484B > 80B OP_RETURN cap).
  // Rotate creates no Bitcoin output — the new pool note lives off-chain in
  // SP1 — so the reveal just emits change to self. Mirrors the burn builder.
  // See ops/PLAN-bridge-op-return-standardness.md + main.rs rotate handler.
  _p('building Bitcoin transaction');
  const feeRate = await getFeeRate('priority');
  const wpkhSpk = p2wpkhScript(wallet.pub);

  const envelopeScript = encodeEnvelopeScript(wallet.xonly(), fullPayload);
  const leaf = tapLeafHash(envelopeScript);
  const { Q_xonly, parity } = tweakedOutputKey(TAP_NUMS, leaf);
  const p2trSpk = p2trScript(Q_xonly);
  const cb = controlBlock(TAP_NUMS, parity);

  const revealVb = Math.ceil((envelopeScript.length + 200) / 4) + 31 + 11;
  const revealFee = feeFor(revealVb, feeRate);
  const commitP2trValue = DUST + revealFee;

  const allUtxos = await getUtxos(wallet.address());
  const sats = await pickSafeCommitSats(allUtxos);
  const picked = []; let total = 0;
  let commitFee = 500;
  for (const u of sats) {
    picked.push(u); total += u.value;
    commitFee = feeFor(estCommitVb(picked.length), feeRate);
    if (total >= commitP2trValue + commitFee + DUST) break;
  }
  if (total < commitP2trValue + commitFee) {
    throw new Error(`insufficient sats (need ~${commitP2trValue + commitFee}, have ${total})`);
  }

  const change = total - commitP2trValue - commitFee;
  const commitOutputs = [{ value: commitP2trValue, script: p2trSpk }];
  if (change >= DUST) commitOutputs.push({ value: change, script: wpkhSpk });
  const commitTx = {
    version: 2, locktime: 0,
    inputs: picked.map(u => ({ txid: u.txid, vout: u.vout, sequence: 0xfffffffd, witness: [] })),
    outputs: commitOutputs,
  };
  signCommitInputs(commitTx, picked, wpkhSpk);
  const commitHex = bytesToHex(serializeTx(commitTx));
  const commitTxid_ = txid(commitTx);
  _p('broadcasting bridge rotation commit');
  await broadcast(commitHex);

  const revealTx = {
    version: 2, locktime: 0,
    inputs: [{ txid: commitTxid_, vout: 0, sequence: 0xfffffffd, witness: [] }],
    outputs: [{ value: DUST, script: wpkhSpk }],
  };
  const prevouts = [{ value: commitP2trValue, script: p2trSpk }];
  revealTx.inputs[0].witness = signTaprootScriptPathInput(revealTx, prevouts, envelopeScript, cb);
  const txHex = bytesToHex(serializeTx(revealTx));
  const rotateTxid = txid(revealTx);
  _p('broadcasting bridge rotation reveal');
  await broadcastWithRetry(txHex);

  noteRecord.status = 'rotated';
  _p('done');
  return { rotateTxid, txHex, commitTxid: commitTxid_, newCommitmentHex };
}

function _getNextBridgeRotateNonce(recipientPubHex) {
  const k = `tacit-bridge-rotate-nonce:${currentNetworkName()}:${recipientPubHex}`;
  const n = parseInt(localStorage.getItem(k) || '0', 10);
  localStorage.setItem(k, String(n + 1));
  return n;
}

async function bridgeSendViaRotation({ noteRecord, recipientPubHex, onProgress }) {
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  await ensurePrivkey();

  const denomBig = BigInt(noteRecord.denomination);
  const recipientPub = hexToBytes(recipientPubHex);
  const shared = secp.getSharedSecret(wallet.priv, recipientPub);
  const rotateNonce = _getNextBridgeRotateNonce(recipientPubHex);
  const nonceBuf = new Uint8Array(4);
  new DataView(nonceBuf.buffer).setUint32(0, rotateNonce, false);
  const domain = new TextEncoder().encode('tacit-bridge-rotate-note-v1');
  const secretSeed = new Uint8Array(hmac(sha256, shared, concatBytes(domain, nonceBuf, new Uint8Array([0]))));
  const nullSeed = new Uint8Array(hmac(sha256, shared, concatBytes(domain, nonceBuf, new Uint8Array([1]))));
  const newCommitment = computePoolLeafCommitment(secretSeed, nullSeed, denomBig);
  const newCommitmentHex = bytesToHex(newCommitment);

  _p('rotating pool note to recipient');
  const result = await buildAndBroadcastBridgeRotate({
    noteRecord,
    newCommitmentHex,
    onProgress,
  });

  _p('done');
  return { ...result, newCommitmentHex };
}

// Exact decimal-ETH → wei. parseFloat(x)*1e18 loses precision, which would make
// bridgeDecompose leave non-zero dust and reject otherwise-clean denominations.
function _bridgeEthToWei(s) {
  s = String(s == null ? '' : s).trim();
  if (!/^\d+(\.\d+)?$/.test(s)) throw new Error('invalid ETH amount');
  const [intPart, fracRaw = ''] = s.split('.');
  const frac = (fracRaw + '0'.repeat(18)).slice(0, 18);
  return BigInt(intPart) * (10n ** 18n) + BigInt(frac || '0');
}

// --- Bridge fractional send: split a pool note and send PART of it ---
//
// Whole-note send is bridgeSendViaRotation (rotates the note in place). A pool
// note is single-denomination, so to send a fraction we compose three mature
// builders: EXPORT (0x63) the note → a tETH UTXO Alice owns; CXFER-split that
// UTXO → one output per redeemable denomination to the recipient (change auto
// to self); the recipient redeems via the existing bridgeQuickBurnFromHoldings
// (import 0x64 → burn 0x61 → withdrawFromBurn). The recipient flow is unchanged.
// Conservation is enforced by the CXFER Pedersen kernel; this only orchestrates.
// NOTE: requires a signet end-to-end round-trip before mainnet (untested in CI).
async function bridgeSendFractional({ noteRecord, recipientPubHex, recipientStealthAddress, amountWei, onProgress }) {
  await ensurePrivkey();
  const _p = (s, info) => { try { onProgress?.(s, info); } catch {} };
  if (!_bridgeConfigured()) throw new Error('bridge not configured');

  const assetIdHex = noteRecord.assetIdHex;
  const denomBig = BigInt(noteRecord.denomination);            // tacit units (8-dec)
  const noteWei = denomBig * BigInt(BRIDGE_UNIT_SCALE);         // note value in wei

  amountWei = BigInt(amountWei);
  if (amountWei <= 0n) throw new Error('amount must be greater than 0');
  if (amountWei > noteWei) throw new Error(`amount exceeds note value (${noteWei} wei)`);

  const { chunks, dust } = bridgeDecompose(amountWei);
  if (dust !== 0n) {
    throw new Error('amount not redeemable — tETH redeems only in whole denominations (100 / 10 / 1 / 0.1 / 0.01 / 0.001 / 0.0001 / 0.00001 ETH); use a sum of these');
  }
  if (chunks.length === 0) throw new Error('amount too small — minimum 0.00001 ETH');
  if (chunks.length > 7) {
    throw new Error(`amount too granular — needs ${chunks.length} denomination outputs but a single send carries at most 7; send fewer/larger denominations`);
  }

  // Recipient shape per buildAndBroadcastCXfer: stealthAddress takes precedence,
  // else { pubHex } (validated on-curve inside buildAndBroadcastCXferMulti).
  let recipientBase;
  if (recipientStealthAddress && String(recipientStealthAddress).length > 0) {
    recipientBase = { stealthAddress: String(recipientStealthAddress) };
  } else {
    const pubHex = String(recipientPubHex || '').trim().toLowerCase().replace(/\s/g, '');
    if (!/^(02|03)[0-9a-f]{64}$/.test(pubHex)) throw new Error('invalid recipient: provide a shielded address or a 33-byte compressed pubkey (02/03…)');
    recipientBase = { pubHex };
  }

  // 1. EXPORT the source note → tETH UTXO at (exportTxid, vout=0). The Taproot
  //    export reveal puts the spendable stealth output at vout 0 (the envelope
  //    rides in the reveal witness, not an OP_RETURN output).
  _p('exporting pool note to a spendable tETH UTXO');
  const { exportTxid } = await buildAndBroadcastBridgeExport({ noteRecord, onProgress });

  // 2. Wait for the export to confirm and surface in tETH holdings before
  //    spending it (mirrors the import-confirm wait in bridgeQuickBurnFromHoldings).
  _p('waiting for export confirmation');
  let exportUtxo = null;
  await new Promise((resolve, reject) => {
    let attempts = 0;
    const poll = async () => {
      if (++attempts > 120) { reject(new Error('timed out waiting for export confirmation')); return; }
      try {
        const info = await apiJson(`/tx/${exportTxid}`).catch(() => null);
        if (info?.status?.confirmed) {
          const holdings = await scanHoldings(true);
          const h = holdings.get(assetIdHex);
          const u = h?.utxos?.find(x => x.utxo.txid === exportTxid && x.utxo.vout === 0);
          if (u) { exportUtxo = u; resolve(); return; }
        }
      } catch {}
      setTimeout(poll, 15000);
    };
    poll();
  });
  if (!exportUtxo) throw new Error('exported tETH UTXO did not surface in holdings');
  if (BigInt(exportUtxo.amount) !== denomBig) {
    throw new Error(`internal: exported UTXO amount ${exportUtxo.amount} != note denom ${denomBig}`);
  }

  // 3. CXFER-split: one recipient entry per denom chunk, amount in TACIT units
  //    (chunkWei / BRIDGE_UNIT_SCALE; each denom is an exact multiple of the
  //    scale). Change (noteWei − amountWei) returns to self automatically.
  const recipients = chunks.map(chunkWei => ({
    ...recipientBase,
    amount: BigInt(chunkWei) / BigInt(BRIDGE_UNIT_SCALE),
  }));
  _p('splitting tETH to recipient');
  const splitResult = await buildAndBroadcastCXferMulti({
    assetIdHex,
    recipients,
    forceUtxos: [exportUtxo],
    allowDuplicateRecipients: recipients.length > 1,
    onProgress: (stage) => _p(`cxfer-${stage}`),
  });

  _p('done');
  return { exportTxid, cxferTxid: splitResult.revealTxid, chunks };
}

// --- Ethereum withdrawal: submit burn proof to contract (step 4) ---

async function bridgeWithdrawETH({ provider, burnRecord, onProgress }) {
  if (!_bridgeConfigured()) throw new Error('bridge not configured');
  const _p = (s) => { try { onProgress?.(s); } catch {} };
  // The claim goes to the mixer whose constants the burn's bind hash committed
  // to — the burn record's home generation.
  const gctx = tethCtxForRecord(burnRecord) || tethActiveCtx();

  _p('fetching burn transaction');
  const rawTxHex = burnRecord.rawTxHex || burnRecord.rawRevealHex;
  if (!rawTxHex) {
    _p('fetching raw tx from mempool API');
    const txResp = await fetch(`https://mempool.space/${currentNetworkName() === 'signet' ? 'signet/' : ''}api/tx/${burnRecord.burnTxid}/hex`);
    if (!txResp.ok) throw new Error('burn record missing raw tx hex and mempool fetch failed');
    burnRecord.rawTxHex = await txResp.text();
  }
  const finalRawTxHex = burnRecord.rawTxHex || rawTxHex;
  const rawTxBytes = hexToBytes(finalRawTxHex);

  _p('fetching Bitcoin block info');
  const txInfo = await apiJson(`/tx/${burnRecord.burnTxid}`);
  if (!txInfo?.status?.confirmed) throw new Error('burn transaction not yet confirmed');
  const burnBlockHash = txInfo.status.block_hash;
  const burnBlockHeight = txInfo.status.block_height;

  const txids = await apiJson(`/block/${burnBlockHash}/txids`);
  const txIndex = txids.indexOf(burnRecord.burnTxid);
  if (txIndex < 0) throw new Error('burn txid not found in block');

  _p('computing Bitcoin merkle proof');
  const btcMerkleProof = _computeBtcBlockMerkleProof(txids, txIndex);

  _p('fetching relay proof headers');
  const confirmDepth = 6;
  const mempoolBase = currentNetworkName() === 'signet' ? 'https://mempool.space/signet/api' : 'https://mempool.space/api';
  const ethRpc = gctx.chainId === 11155111 ? 'https://ethereum-sepolia-rpc.publicnode.com' : 'https://ethereum-rpc.publicnode.com';
  const relayAddr = await provider.request({ method: 'eth_call', params: [{ to: gctx.address, data: '0x' + bytesToHex(keccak_256(new TextEncoder().encode('HEADER_RELAY()'))).slice(0, 8) }, 'latest'] });
  const relayAddress = '0x' + relayAddr.slice(26);
  const tipHeightHex = await provider.request({ method: 'eth_call', params: [{ to: relayAddress, data: '0x' + bytesToHex(keccak_256(new TextEncoder().encode('tipHeight()'))).slice(0, 8) }, 'latest'] });
  const endHeight = parseInt(tipHeightHex, 16);
  const headerCount = endHeight - burnBlockHeight + 1;
  if (headerCount < 1 + confirmDepth) throw new Error(`need ${1 + confirmDepth} confirmations, burn has ${headerCount - 1} — wait for more blocks`);
  let proofHeadersHex = '';
  for (let h = burnBlockHeight; h <= endHeight; h++) {
    const bh = await (await fetch(`${mempoolBase}/block-height/${h}`)).text();
    const hdr = await (await fetch(`${mempoolBase}/block/${bh}/header`)).text();
    proofHeadersHex += hdr;
  }
  const proofHeadersBytes = hexToBytes(proofHeadersHex);

  _p('encoding Ethereum transaction');
  const [account] = await provider.request({ method: 'eth_requestAccounts' });

  const sel = keccak_256(new TextEncoder().encode('withdrawFromBurn(bytes,bytes,uint256,bytes32[],uint256)'));
  const proofCount = btcMerkleProof.siblings.length;
  const rawTxPadded = Math.ceil(rawTxBytes.length / 32) * 32;
  const proofHdrPadded = Math.ceil(proofHeadersBytes.length / 32) * 32;

  let calldata = '0x';
  calldata += bytesToHex(sel).slice(0, 8);
  // 5 params: rawBtcTx(offset), proofHeaders(offset), burnBlockHeight, txMerkleProof(offset), txIndex
  const dynStart = 160; // 5 * 32
  const rawTxOffset = dynStart;
  const proofHdrOffset = rawTxOffset + 32 + rawTxPadded;
  const merkleOffset = proofHdrOffset + 32 + proofHdrPadded;
  calldata += _pad32(rawTxOffset.toString(16));
  calldata += _pad32(proofHdrOffset.toString(16));
  calldata += _pad32(burnBlockHeight.toString(16));
  calldata += _pad32(merkleOffset.toString(16));
  calldata += _pad32(txIndex.toString(16));
  // rawBtcTx bytes
  calldata += _pad32(rawTxBytes.length.toString(16));
  const rawPad = new Uint8Array(rawTxPadded); rawPad.set(rawTxBytes);
  calldata += bytesToHex(rawPad);
  // proofHeaders bytes
  calldata += _pad32(proofHeadersBytes.length.toString(16));
  const hdrPad = new Uint8Array(proofHdrPadded); hdrPad.set(proofHeadersBytes);
  calldata += bytesToHex(hdrPad);
  // txMerkleProof bytes32[]
  calldata += _pad32(proofCount.toString(16));
  for (const sib of btcMerkleProof.siblings) {
    calldata += bytesToHex(sib);
  }

  _p('awaiting wallet signature');
  const txHash = await provider.request({
    method: 'eth_sendTransaction',
    params: [{
      from: account,
      to: gctx.address,
      data: calldata,
    }],
  });

  burnRecord.ethWithdrawTxHash = txHash;
  burnRecord.status = 'withdrawn';
  const _bkey = _BRIDGE_BURN_RECORDS_KEY_FOR(gctx.address);
  const allBurns = _getBridgeRecords(_bkey);
  const idx = allBurns.findIndex(r => r.burnTxid === burnRecord.burnTxid);
  if (idx >= 0) { allBurns[idx] = burnRecord; localStorage.setItem(_bkey, JSON.stringify(allBurns)); }

  _p('done');
  return { txHash };
}

function _computeBtcBlockMerkleProof(txids, txIndex) {
  let layer = txids.map(t => {
    const bytes = hexToBytes(t);
    bytes.reverse();
    return bytes;
  });
  const siblings = [];
  let idx = txIndex;

  while (layer.length > 1) {
    if (layer.length & 1) layer.push(layer[layer.length - 1]);
    const sibIdx = idx ^ 1;
    siblings.push(layer[sibIdx]);
    const next = [];
    for (let i = 0; i < layer.length; i += 2) {
      const combined = concatBytes(layer[i], layer[i + 1]);
      const hash = sha256(sha256(combined));
      next.push(hash);
    }
    layer = next;
    idx >>= 1;
  }
  return { siblings, root: layer[0] };
}


// ============== SLOT-SECRET DETERMINISTIC DERIVATION (SPEC-CBTC-ZK §5.21-§5.25) ==============
//
// Slot UTXOs sit at K_btc P2TR addresses, NOT at wallet.address(). So the
// standard scanHoldings flow doesn't see them. Recovery requires re-deriving
// (secret, nullifierPreimage) — and hence K_btc — from priv + chain alone.
//
// These helpers replace `crypto.getRandomValues` at the 8 slot-builder call
// sites in dapp/tacit.js (MINT / BURN / ROTATE / SPLIT / MERGE). The derived
// secrets are byte-identical across calls so a fresh wallet can re-derive
// them given (priv, anchorOutpoint, outputIndex), then compute K_btc via the
// existing deriveSlotKbtc + slotXOnly pipeline.
//
// Anchor schema:
//   MINT       — anchorOutpoint = first commit-funding input outpoint (36 B:
//                txid_LE || vout_LE). The user re-discovers this by walking
//                their wallet's outgoing spends; the funding tx is in their
//                history. outputIndex = 0 (single new slot).
//   ROTATE 1→1 — anchorOutpoint = input slot's K_btc outpoint. outputIndex = 0.
//   SPLIT 1→N  — anchorOutpoint = input slot's K_btc outpoint, outputIndex = i
//                (0..N-1). Each output slot has distinct secrets so they
//                spend independently.
//   MERGE N→1  — anchorOutpoint = canonical "first" input slot's K_btc
//                outpoint (sorted lexicographically). outputIndex = 0.
//   BURN       — no new slot; helpers not used.
//
// Domain tags are distinct between secret and nullifier so the two derived
// values are computationally independent under HMAC's PRF property — same
// property the existing deriveSlotRBtc relies on (different SHA domain tag
// → independent scalar from the same (secret, ν) pair).
//
// Rejection sampling: 32-byte HMAC output occasionally exceeds the slot's
// effective scalar field. Since slot scalars are reduced via Poseidon/SHA
// downstream (deriveSlotRBtc, leaf-commitment), we don't reject here. The
// caller's downstream reduction handles the curve-order modulus.
//
// Recovery (`scanSlots()`, to be added in a follow-up): iterate the user's
// outgoing-spend history. For each spent UTXO, treat its outpoint as a
// candidate anchorOutpoint, derive (secret, ν), and check whether any
// chain-confirmed tx in the descendant set produced a K_btc P2TR output.
// If yes → that's the user's slot. Asset metadata + denomination are read
// off the slot reveal tx's envelope.
const _SLOT_SECRET_DOMAIN     = new TextEncoder().encode('tacit-slot-secret-v1');
const _SLOT_NULLIFIER_DOMAIN  = new TextEncoder().encode('tacit-slot-nullifier-v1');

function _deriveSlotSecret({ privkey, anchorOutpoint, outputIndex = 0 }) {
  if (!(privkey instanceof Uint8Array) || privkey.length !== 32) throw new Error('privkey must be 32 bytes');
  if (!(anchorOutpoint instanceof Uint8Array) || anchorOutpoint.length !== 36) throw new Error('anchorOutpoint must be 36 bytes (txid_LE 32 + vout_LE 4)');
  if (!Number.isInteger(outputIndex) || outputIndex < 0 || outputIndex > 0xff) throw new Error('outputIndex must be u8 (0..255)');
  return hmac(sha256, privkey, concatBytes(
    _SLOT_SECRET_DOMAIN, anchorOutpoint, new Uint8Array([outputIndex & 0xff]),
  ));
}

function _deriveSlotNullifierPreimage({ privkey, anchorOutpoint, outputIndex = 0 }) {
  if (!(privkey instanceof Uint8Array) || privkey.length !== 32) throw new Error('privkey must be 32 bytes');
  if (!(anchorOutpoint instanceof Uint8Array) || anchorOutpoint.length !== 36) throw new Error('anchorOutpoint must be 36 bytes (txid_LE 32 + vout_LE 4)');
  if (!Number.isInteger(outputIndex) || outputIndex < 0 || outputIndex > 0xff) throw new Error('outputIndex must be u8 (0..255)');
  return hmac(sha256, privkey, concatBytes(
    _SLOT_NULLIFIER_DOMAIN, anchorOutpoint, new Uint8Array([outputIndex & 0xff]),
  ));
}

// Convenience: build the 36-byte outpoint (txid_LE || vout_LE) used as anchor.
// The chain stores txids in their natural (little-endian) byte order on disk;
// the dapp's existing helpers (cf. _SHARE_SLASH_CLAIM_BLIND_DOMAIN anchor
// construction at tacit.js search "reverseBytes(hexToBytes(firstBurn.txid))")
// reverse the displayed txid hex to LE before concat. Mirrors that pattern.
function _slotOutpointBytes(txidHex, vout) {
  if (typeof txidHex !== 'string' || !/^[0-9a-f]{64}$/i.test(txidHex)) {
    throw new Error('txidHex must be 64 hex chars');
  }
  if (!Number.isInteger(vout) || vout < 0 || vout > 0xffffffff) {
    throw new Error('vout must be u32');
  }
  const txidLE = reverseBytes(hexToBytes(txidHex.toLowerCase()));
  const voutLE = new Uint8Array(4);
  new DataView(voutLE.buffer).setUint32(0, vout >>> 0, true);
  return concatBytes(txidLE, voutLE);
}

// ============== MIXER + AXINTENT DETERMINISTIC DERIVATION ==============
//
// Same priv-anchored HMAC pattern the slot system uses, applied to two
// recovery surfaces that historically generated random secrets stored
// only in localStorage:
//
//   1. Bare mixer deposit (T_DEPOSIT) — pair (secret, ν) for the zk
//      withdrawal proof. Domain tags '-secret-' and '-nullifier-' so the
//      two are computationally independent under HMAC's PRF property.
//      Anchor = asset input UTXO outpoint, which the worker binds into
//      kernel_msg (so the depositor can recompute (secret, ν) given priv
//      + the funding UTXO outpoint, both of which are on-chain or in
//      the depositor's spend history).
//
//   2. Maker-side axintent commit blinding — used to commit the maker's
//      reserved amount in publishAxferIntent. ECDH(priv, taker_pub) isn't
//      available at commit time (the taker isn't known yet), so the
//      maker must produce their own blinding. Random + localStorage was
//      the historical answer; this anchors the blinding to priv + the
//      maker's spent UTXO outpoint instead.
//
// All three functions take `anchorOutpoint` as a 36-byte
// (txid_LE || vout_LE) value built via _slotOutpointBytes; the chain
// commits to this same 36-byte value via the spent-input set, so the
// scanner can iterate the wallet's outgoing-spend history and reproduce
// the derivation. Pattern matches _deriveSlotSecret / _deriveSlotNullifierPreimage.
const _MIXER_DEPOSIT_SECRET_DOMAIN     = new TextEncoder().encode('tacit-mixer-deposit-secret-v1');
const _MIXER_DEPOSIT_NULLIFIER_DOMAIN  = new TextEncoder().encode('tacit-mixer-deposit-nullifier-v1');
const _AXINTENT_MAKER_BLIND_DOMAIN     = new TextEncoder().encode('tacit-axintent-maker-blind-v1');

function _deriveMixerDepositSecret({ privkey, anchorOutpoint }) {
  if (!(privkey instanceof Uint8Array) || privkey.length !== 32) throw new Error('privkey must be 32 bytes');
  if (!(anchorOutpoint instanceof Uint8Array) || anchorOutpoint.length !== 36) throw new Error('anchorOutpoint must be 36 bytes (txid_LE 32 + vout_LE 4)');
  return hmac(sha256, privkey, concatBytes(_MIXER_DEPOSIT_SECRET_DOMAIN, anchorOutpoint));
}

function _deriveMixerDepositNullifierPreimage({ privkey, anchorOutpoint }) {
  if (!(privkey instanceof Uint8Array) || privkey.length !== 32) throw new Error('privkey must be 32 bytes');
  if (!(anchorOutpoint instanceof Uint8Array) || anchorOutpoint.length !== 36) throw new Error('anchorOutpoint must be 36 bytes (txid_LE 32 + vout_LE 4)');
  return hmac(sha256, privkey, concatBytes(_MIXER_DEPOSIT_NULLIFIER_DOMAIN, anchorOutpoint));
}

// Returns a BigInt scalar in [1, SECP_N). Rejection-resamples on r=0
// (statistically impossible but defensively bounded).
function _deriveAxintentMakerBlinding({ privkey, anchorOutpoint }) {
  if (!(privkey instanceof Uint8Array) || privkey.length !== 32) throw new Error('privkey must be 32 bytes');
  if (!(anchorOutpoint instanceof Uint8Array) || anchorOutpoint.length !== 36) throw new Error('anchorOutpoint must be 36 bytes (txid_LE 32 + vout_LE 4)');
  const base = concatBytes(_AXINTENT_MAKER_BLIND_DOMAIN, anchorOutpoint);
  let seed = hmac(sha256, privkey, base);
  let r = bytes32ToBigint(seed) % SECP_N;
  for (let counter = 1; r === 0n && counter < 256; counter++) {
    seed = hmac(sha256, privkey, concatBytes(base, new Uint8Array([counter & 0xff])));
    r = bytes32ToBigint(seed) % SECP_N;
  }
  if (r === 0n) throw new Error('axintent maker blinding: rejection sampling exhausted (statistically impossible)');
  return r;
}


// ============== T_SWAP_VAR WIRE PRIMITIVES (SPEC-SWAP-VAR-AMENDMENT §5.16.3) ==============
//
// Per-trade variable-amount AMM swap. Wire format (matches worker byte-for-byte):
//   envelope_version(1) || opcode(1) || pool_id(32) || direction(1)
//   || R_A_pre(8) || R_B_pre(8) || delta_in(8) || delta_in_min(8)
//   || delta_in_max(8) || delta_out(8) || min_out(8) || tip_amount(8)
//   || tip_asset(1) || expiry_height(4) || trader_pubkey(33)
//   || C_in_secp(33) || C_change_or_sentinel(33) || C_receipt_secp(33)
//   || r_receipt(32) || rangeproof_len(2) || range_proof(VAR)
//   || kernel_sig(64) || intent_sig(64)
//
// envelope_hash = SHA256(payload). vout[0] OP_RETURN(envelope_hash) is the
// on-chain binding.
function encodeTSwapVarPayload({
  poolId, direction,
  R_A_pre, R_B_pre, deltaIn, deltaInMin, deltaInMax,
  deltaOut, minOut, tipAmount, tipAsset, expiryHeight,
  traderPubkey, cInSecp, cChangeOrSentinel, cReceiptSecp,
  rReceipt, rangeProof, kernelSig, intentSig,
}) {
  if (!(poolId instanceof Uint8Array) || poolId.length !== 32) throw new Error('pool_id 32 bytes');
  if (direction !== 0 && direction !== 1) throw new Error('direction must be 0|1');
  if (tipAsset !== 0 && tipAsset !== 1) throw new Error('tip_asset must be 0|1');
  if (!(traderPubkey instanceof Uint8Array) || traderPubkey.length !== 33) throw new Error('trader_pubkey 33 bytes');
  if (!(cInSecp instanceof Uint8Array) || cInSecp.length !== 33) throw new Error('c_in_secp 33 bytes');
  if (!(cChangeOrSentinel instanceof Uint8Array) || cChangeOrSentinel.length !== 33) {
    throw new Error('c_change_or_sentinel 33 bytes');
  }
  if (!(cReceiptSecp instanceof Uint8Array) || cReceiptSecp.length !== 33) throw new Error('c_receipt_secp 33 bytes');
  if (!(rReceipt instanceof Uint8Array) || rReceipt.length !== 32) throw new Error('r_receipt 32 bytes');
  if (!(rangeProof instanceof Uint8Array) || rangeProof.length === 0 || rangeProof.length > 0xffff) {
    throw new Error('range_proof len 1..65535');
  }
  if (!(kernelSig instanceof Uint8Array) || kernelSig.length !== 64) throw new Error('kernel_sig 64 bytes');
  if (!(intentSig instanceof Uint8Array) || intentSig.length !== 64) throw new Error('intent_sig 64 bytes');
  function u64LE(n) {
    const b = new Uint8Array(8);
    let x = BigInt(n);
    if (x < 0n || x >= 1n << 64n) throw new Error('u64 overflow');
    for (let i = 0; i < 8; i++) { b[i] = Number(x & 0xffn); x >>= 8n; }
    return b;
  }
  function u32LE(n) {
    const b = new Uint8Array(4);
    new DataView(b.buffer).setUint32(0, n >>> 0, true);
    return b;
  }
  function u16LE(n) {
    const b = new Uint8Array(2);
    new DataView(b.buffer).setUint16(0, n & 0xffff, true);
    return b;
  }
  return concatBytes(
    new Uint8Array([T_SWAP_VAR]),
    poolId,
    new Uint8Array([direction & 0xff]),
    u64LE(R_A_pre), u64LE(R_B_pre),
    u64LE(deltaIn), u64LE(deltaInMin), u64LE(deltaInMax),
    u64LE(deltaOut), u64LE(minOut), u64LE(tipAmount),
    new Uint8Array([tipAsset & 0xff]),
    u32LE(expiryHeight),
    traderPubkey, cInSecp, cChangeOrSentinel, cReceiptSecp, rReceipt,
    u16LE(rangeProof.length), rangeProof,
    kernelSig, intentSig,
  );
}

// ============== T_SWAP_ROUTE wire + msg helpers ==============
//
// Mirror tests/swap-route.mjs byte-for-byte so the dapp emits envelopes
// the worker scan-loop validator accepts. Helpers are kept inline (not
// imported) so the dapp build stays single-bundle.

const _SWAP_ROUTE_INTENT_DOMAIN = new TextEncoder().encode('tacit-swap-route-v1');
const _SWAP_ROUTE_KERNEL_DOMAIN = new TextEncoder().encode('tacit-kernel-v1');

function _swapRouteU64LE(n) {
  const b = new Uint8Array(8);
  let x = BigInt(n);
  if (x < 0n || x >= 1n << 64n) throw new Error('u64 overflow');
  for (let i = 0; i < 8; i++) { b[i] = Number(x & 0xffn); x >>= 8n; }
  return b;
}
function _swapRouteU32LE(n) {
  const b = new Uint8Array(4);
  new DataView(b.buffer).setUint32(0, n >>> 0, true);
  return b;
}
function _swapRouteU16LE(n) {
  const b = new Uint8Array(2);
  new DataView(b.buffer).setUint16(0, n & 0xffff, true);
  return b;
}

// Per-hop block (67 bytes): pool_id(32) || direction(1) || fee_bps(2) ||
// R_A_pre(8) || R_B_pre(8) || delta_a_net_mag(8) || delta_b_net_mag(8).
function _encodeSwapRouteHop(hop) {
  if (!(hop.poolId instanceof Uint8Array) || hop.poolId.length !== 32) {
    throw new Error('hop.poolId must be 32 bytes');
  }
  if (hop.direction !== 0 && hop.direction !== 1) {
    throw new Error('hop.direction must be 0|1');
  }
  if (!Number.isInteger(hop.feeBps) || hop.feeBps < 0 || hop.feeBps > 1000) {
    throw new Error('hop.feeBps must be 0..1000');
  }
  return concatBytes(
    hop.poolId,
    new Uint8Array([hop.direction & 0xff]),
    _swapRouteU16LE(hop.feeBps),
    _swapRouteU64LE(hop.R_A_pre),
    _swapRouteU64LE(hop.R_B_pre),
    _swapRouteU64LE(hop.deltaANetMag),
    _swapRouteU64LE(hop.deltaBNetMag),
  );
}

function _hashSwapRouteHops(hops) {
  return sha256(concatBytes(...hops.map(_encodeSwapRouteHop)));
}

// route_msg per SPEC-SWAP-ROUTE-AMENDMENT §"Intent message + signature".
function buildSwapRouteIntentMsg({
  traderPubkey, traderInputAssetId, traderOutputAssetId,
  minOut, expiryHeight, hops, cInSecp, cReceiptSecp,
}) {
  if (!Array.isArray(hops) || hops.length < 2 || hops.length > SWAP_ROUTE_N_HOPS_MAX) {
    throw new Error(`hops length must be 2..${SWAP_ROUTE_N_HOPS_MAX}`);
  }
  return sha256(concatBytes(
    _SWAP_ROUTE_INTENT_DOMAIN,
    traderPubkey, traderInputAssetId, traderOutputAssetId,
    _swapRouteU64LE(minOut), _swapRouteU32LE(expiryHeight),
    new Uint8Array([hops.length & 0xff]),
    ...hops.map(_encodeSwapRouteHop),
    cInSecp, cReceiptSecp,
  ));
}

// kernel_msg per SPEC-SWAP-ROUTE-AMENDMENT §"Kernel message + signature".
// Closes the trader's net asset flow input→output across the whole route.
function buildSwapRouteKernelMsg({
  traderInputAssetId, traderOutputAssetId,
  traderInputOutpointTxidBE, traderInputOutpointVout,
  deltaIn0, deltaOutLast, cReceiptSecp, hopsHash,
}) {
  return sha256(concatBytes(
    _SWAP_ROUTE_KERNEL_DOMAIN,
    traderInputAssetId, traderOutputAssetId,
    new Uint8Array([0x01]),
    traderInputOutpointTxidBE,
    _swapRouteU32LE(traderInputOutpointVout),
    cReceiptSecp,
    _swapRouteU64LE(deltaIn0),
    _swapRouteU64LE(deltaOutLast),
    hopsHash,
  ));
}

function encodeTSwapRoutePayload({
  traderInputAssetId, traderOutputAssetId,
  minOut, expiryHeight, traderPubkey,
  hops,
  traderInputOutpointTxidBE, traderInputOutpointVout,
  cInSecp, cReceiptSecp, rReceipt,
  rangeProof, kernelSig, intentSig,
}) {
  if (!Array.isArray(hops) || hops.length < 2 || hops.length > SWAP_ROUTE_N_HOPS_MAX) {
    throw new Error(`hops length must be 2..${SWAP_ROUTE_N_HOPS_MAX}`);
  }
  if (!(traderInputAssetId instanceof Uint8Array) || traderInputAssetId.length !== 32) throw new Error('trader_input_asset_id 32 bytes');
  if (!(traderOutputAssetId instanceof Uint8Array) || traderOutputAssetId.length !== 32) throw new Error('trader_output_asset_id 32 bytes');
  if (!(traderPubkey instanceof Uint8Array) || traderPubkey.length !== 33) throw new Error('trader_pubkey 33 bytes');
  if (!(traderInputOutpointTxidBE instanceof Uint8Array) || traderInputOutpointTxidBE.length !== 32) throw new Error('trader_input_outpoint_txid_be 32 bytes');
  if (!(cInSecp instanceof Uint8Array) || cInSecp.length !== 33) throw new Error('c_in_secp 33 bytes');
  if (!(cReceiptSecp instanceof Uint8Array) || cReceiptSecp.length !== 33) throw new Error('c_receipt_secp 33 bytes');
  if (!(rReceipt instanceof Uint8Array) || rReceipt.length !== 32) throw new Error('r_receipt 32 bytes');
  if (!(rangeProof instanceof Uint8Array) || rangeProof.length === 0 || rangeProof.length > 0xffff) {
    throw new Error('range_proof len 1..65535');
  }
  if (!(kernelSig instanceof Uint8Array) || kernelSig.length !== 64) throw new Error('kernel_sig 64 bytes');
  if (!(intentSig instanceof Uint8Array) || intentSig.length !== 64) throw new Error('intent_sig 64 bytes');

  return concatBytes(
    new Uint8Array([T_SWAP_ROUTE, hops.length & 0xff]),
    traderInputAssetId, traderOutputAssetId,
    _swapRouteU64LE(minOut), _swapRouteU32LE(expiryHeight),
    traderPubkey,
    ...hops.map(_encodeSwapRouteHop),
    traderInputOutpointTxidBE,
    _swapRouteU32LE(traderInputOutpointVout),
    cInSecp, cReceiptSecp, rReceipt,
    _swapRouteU16LE(rangeProof.length), rangeProof,
    kernelSig, intentSig,
  );
}

function computeSwapRouteEnvelopeHash(payload) { return sha256(payload); }

// Decoder for T_SWAP_ROUTE (opcode 0x33). Returns the decoded route object
// or null on any structural mismatch. Byte-format-equivalent to worker's
// decodeTSwapRoutePayload and tests/swap-route.mjs::decodeSwapRoute.
function decodeTSwapRoutePayload(payload) {
  if (!payload) return null;
  // Min size: header(36) + N=2 hops(134) + outpoint(36) + cIn+cReceipt+rReceipt(98)
  //         + rpLen(2) + 2 sigs(128). ≈ 434 floor.
  if (payload.length < 434) return null;
  let p = 0;
  const opcode = payload[p]; p += 1;
  if (opcode !== T_SWAP_ROUTE) return null;
  const nHops = payload[p]; p += 1;
  if (nHops < 2 || nHops > SWAP_ROUTE_N_HOPS_MAX) return null;

  const traderInputAssetId = payload.slice(p, p + 32); p += 32;
  const traderOutputAssetId = payload.slice(p, p + 32); p += 32;
  let sameAsset = true;
  for (let i = 0; i < 32; i++) {
    if (traderInputAssetId[i] !== traderOutputAssetId[i]) { sameAsset = false; break; }
  }
  if (sameAsset) return null;

  const dv = new DataView(payload.buffer, payload.byteOffset);
  function readU64() {
    const lo = BigInt(dv.getUint32(p, true));
    const hi = BigInt(dv.getUint32(p + 4, true));
    p += 8;
    return (hi << 32n) | lo;
  }
  const minOut = readU64();
  const expiryHeight = dv.getUint32(p, true); p += 4;
  const traderPubkey = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(traderPubkey); } catch { return null; }

  if (p + nHops * SWAP_ROUTE_HOP_BYTES > payload.length) return null;
  const hops = [];
  for (let k = 0; k < nHops; k++) {
    const poolId = payload.slice(p, p + 32); p += 32;
    const direction = payload[p]; p += 1;
    if (direction !== 0 && direction !== 1) return null;
    const feeBps = dv.getUint16(p, true); p += 2;
    if (feeBps > 1000) return null;
    const R_A_pre = readU64();
    const R_B_pre = readU64();
    const deltaANetMag = readU64();
    const deltaBNetMag = readU64();
    hops.push({ poolId, direction, feeBps, R_A_pre, R_B_pre, deltaANetMag, deltaBNetMag });
  }

  if (p + 36 > payload.length) return null;
  const traderInputTxidBE = payload.slice(p, p + 32); p += 32;
  const traderInputVout = dv.getUint32(p, true); p += 4;

  if (p + 33 + 33 + 32 + 2 > payload.length) return null;
  const cInSecp = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(cInSecp); } catch { return null; }
  const cReceiptSecp = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(cReceiptSecp); } catch { return null; }
  const rReceipt = payload.slice(p, p + 32); p += 32;

  const rpLen = dv.getUint16(p, true); p += 2;
  if (rpLen === 0) return null;
  if (p + rpLen + 64 + 64 > payload.length) return null;
  const rangeProof = payload.slice(p, p + rpLen); p += rpLen;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const intentSig = payload.slice(p, p + 64); p += 64;
  if (p !== payload.length) return null;

  return {
    kind: 'swap_route',
    opcode, nHops,
    traderInputAssetId, traderOutputAssetId,
    minOut, expiryHeight, traderPubkey,
    hops,
    traderInputTxidBE, traderInputVout,
    cInSecp, cReceiptSecp, rReceipt,
    rangeProof, kernelSig, intentSig,
  };
}

function decodeTSwapVarPayload(payload) {
  if (!payload) return null;
  if (payload.length < 297) return null;
  let p = 0;
  const opcode = payload[p]; p += 1;
  if (opcode !== T_SWAP_VAR) return null;
  const poolId = payload.slice(p, p + 32); p += 32;
  const direction = payload[p]; p += 1;
  if (direction !== 0 && direction !== 1) return null;
  // Bound the DataView to the payload so any over-read throws deterministically rather than reading
  // into sibling bytes of a shared ArrayBuffer (payload may be a subarray).
  const dv = new DataView(payload.buffer, payload.byteOffset, payload.length);
  function readU64() {
    const lo = BigInt(dv.getUint32(p, true));
    const hi = BigInt(dv.getUint32(p + 4, true));
    p += 8;
    return (hi << 32n) | lo;
  }
  const R_A_pre = readU64();
  const R_B_pre = readU64();
  const deltaIn = readU64();
  const deltaInMin = readU64();
  const deltaInMax = readU64();
  const deltaOut = readU64();
  const minOut = readU64();
  // Range discipline (defense-in-depth; the intent_sig already binds all five, but reject a malformed
  // envelope before any consumer trusts the unsigned-looking fields): din must be within [min,max] and
  // the curve output must clear the trader's slippage floor.
  if (deltaInMin > deltaIn || deltaIn > deltaInMax) return null;
  if (deltaOut < minOut) return null;
  const tipAmount = readU64();
  const tipAsset = payload[p]; p += 1;
  if (tipAsset !== 0 && tipAsset !== 1) return null;
  const expiryHeight = dv.getUint32(p, true); p += 4;
  const traderPubkey = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(traderPubkey); } catch { return null; }
  const cInSecp = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(cInSecp); } catch { return null; }
  const cChangeOrSentinel = payload.slice(p, p + 33); p += 33;
  let isSentinel = true;
  for (let i = 0; i < 33; i++) if (cChangeOrSentinel[i] !== 0) { isSentinel = false; break; }
  if (!isSentinel) {
    try { bytesToPoint(cChangeOrSentinel); } catch { return null; }
  }
  const cReceiptSecp = payload.slice(p, p + 33); p += 33;
  try { bytesToPoint(cReceiptSecp); } catch { return null; }
  const rReceipt = payload.slice(p, p + 32); p += 32;
  if (p + 2 > payload.length) return null;
  const rpLen = dv.getUint16(p, true); p += 2;
  if (rpLen === 0) return null;
  if (p + rpLen + 64 + 64 > payload.length) return null;
  const rangeProof = payload.slice(p, p + rpLen); p += rpLen;
  const kernelSig = payload.slice(p, p + 64); p += 64;
  const intentSig = payload.slice(p, p + 64); p += 64;
  if (p !== payload.length) return null;
  return {
    kind: 'swap_var',
    opcode,
    poolId, direction,
    R_A_pre, R_B_pre, deltaIn, deltaInMin, deltaInMax, deltaOut, minOut, tipAmount, tipAsset,
    expiryHeight,
    traderPubkey, cInSecp, cChangeOrSentinel, cReceiptSecp,
    rReceipt, rangeProof, kernelSig, intentSig,
  };
}

// x · y = k constant-product curve with fee_bps deducted from delta_in.
// MUST agree byte-for-byte with worker's ammCurveDeltaOut + reference
// tests/swap-var.mjs curveDeltaOut. Floor delta_out.
function swapVarCurveDeltaOut(direction, R_A_pre, R_B_pre, deltaIn, feeBps) {
  const ra = BigInt(R_A_pre);
  const rb = BigInt(R_B_pre);
  const din = BigInt(deltaIn);
  const fbps = BigInt(feeBps);
  if (ra <= 0n || rb <= 0n) throw new Error('reserves must be > 0');
  if (din <= 0n) throw new Error('delta_in must be > 0');
  if (fbps < 0n || fbps > 1000n) throw new Error('fee_bps out of range');
  if (ra >= 1n << 64n || rb >= 1n << 64n || din >= 1n << 64n) throw new Error('values must fit u64');
  const gNum = 10000n - fbps;
  const gDen = 10000n;
  let num, den, deltaOut, raPost, rbPost;
  if (direction === 0) {
    num = rb * gNum * din;
    den = ra * gDen + gNum * din;
    deltaOut = num / den;
    raPost = ra + din;
    rbPost = rb - deltaOut;
  } else if (direction === 1) {
    num = ra * gNum * din;
    den = rb * gDen + gNum * din;
    deltaOut = num / den;
    raPost = ra - deltaOut;
    rbPost = rb + din;
  } else {
    throw new Error('direction must be 0 or 1');
  }
  if (deltaOut >= 1n << 64n) throw new Error('delta_out overflows u64');
  if (raPost <= 0n || rbPost <= 0n) throw new Error('post-reserve non-positive');
  if (raPost >= 1n << 64n) throw new Error('post-reserve_A overflows u64');
  if (rbPost >= 1n << 64n) throw new Error('post-reserve_B overflows u64');
  return { deltaOut, raPost, rbPost };
}

// SHA256 of envelope payload. The Bitcoin tx's vout[0] OP_RETURN MUST
// carry this 32-byte hash; worker validator binds them together.
function computeSwapVarEnvelopeHash(payload) {
  return sha256(payload);
}

// Pool ID derivation matching worker's ammDerivePoolId. Caller supplies
// canonically-ordered assets (use lexCanonicalAssetPair below) and the
// pool's fee_bps + capability_flags.
const _AMM_POOL_ID_DOMAIN_DAPP = new TextEncoder().encode('tacit-amm-pool-v1');
function lexCanonicalAssetPair(idA, idB) {
  const a = idA instanceof Uint8Array ? idA : hexToBytes(idA);
  const b = idB instanceof Uint8Array ? idB : hexToBytes(idB);
  if (a.length !== 32 || b.length !== 32) throw new Error('asset_id must be 32 bytes');
  for (let i = 0; i < 32; i++) {
    if (a[i] < b[i]) return [a, b];
    if (a[i] > b[i]) return [b, a];
  }
  throw new Error('canonical pair: identical asset_ids');
}
const _AMM_ZERO_PROTOCOL_FEE_ADDRESS = new Uint8Array(33);
function _ammIsZeroProtocolFeeAddress(b) {
  for (let i = 0; i < b.length; i++) if (b[i] !== 0) return false;
  return true;
}
function ammDerivePoolIdDapp(idA, idB, feeBps, capabilityFlags, protocolFeeAddress, protocolFeeBps) {
  const [low, high] = lexCanonicalAssetPair(idA, idB);
  if (!Number.isInteger(feeBps) || feeBps < 0 || feeBps > 1000) {
    throw new Error(`fee_bps out of range [0, 1000]: ${feeBps}`);
  }
  if (!Number.isInteger(capabilityFlags) || capabilityFlags < 0 || capabilityFlags > 255) {
    throw new Error(`capability_flags out of range u8: ${capabilityFlags}`);
  }
  const feeBpsLE = new Uint8Array(2);
  new DataView(feeBpsLE.buffer).setUint16(0, feeBps, true);
  const flagsByte = new Uint8Array([capabilityFlags]);

  const pfBps = protocolFeeBps == null ? 0 : protocolFeeBps;
  // 1000 (10%) product-policy cap, matching amm-asset.js / amm-envelope / worker AMM_PROTOCOL_FEE_BPS_MAX.
  // (The contract/guest hard limit is the looser < 10000; the off-chain stack stays at the tighter 1000.)
  if (!Number.isInteger(pfBps) || pfBps < 0 || pfBps > 1000) {
    throw new Error(`protocol_fee_bps out of range [0, 1000]: ${pfBps}`);
  }
  let pfAddr;
  if (protocolFeeAddress == null) {
    pfAddr = _AMM_ZERO_PROTOCOL_FEE_ADDRESS;
  } else {
    pfAddr = protocolFeeAddress instanceof Uint8Array ? protocolFeeAddress : hexToBytes(protocolFeeAddress);
    if (pfAddr.length !== 33) throw new Error(`protocol_fee_address must be 33 bytes: got ${pfAddr.length}`);
  }
  const pfAddrZero = _ammIsZeroProtocolFeeAddress(pfAddr);
  if ((pfBps === 0) !== pfAddrZero) {
    throw new Error('protocol_fee_address and protocol_fee_bps must be joint-zero or joint-non-zero');
  }
  if (pfBps === 0) {
    return sha256(concatBytes(_AMM_POOL_ID_DOMAIN_DAPP, low, high, feeBpsLE, flagsByte));
  }
  const pfBpsLE = new Uint8Array(2);
  new DataView(pfBpsLE.buffer).setUint16(0, pfBps, true);
  return sha256(concatBytes(_AMM_POOL_ID_DOMAIN_DAPP, low, high, feeBpsLE, flagsByte, pfAddr, pfBpsLE));
}

// Kernel message for T_DEPOSIT (SPEC §5.10). Domain-separated by 'tacit-deposit-v1'
// to make cross-opcode replay against, say, a CXFER kernel sig structurally
// impossible.
function computeDepositKernelMsg(assetId, denomination, inputTxidBE, inputVout, leafCommitment) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  if (inputTxidBE.length !== 32) throw new Error('input_txid_BE 32 bytes');
  if (leafCommitment.length !== 32) throw new Error('leaf_commitment 32 bytes');
  const d = BigInt(denomination);
  const denomLE = new Uint8Array(8);
  {
    const v = new DataView(denomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const voutLE = new Uint8Array(4);
  new DataView(voutLE.buffer).setUint32(0, inputVout >>> 0, true);
  return sha256(concatBytes(DEPOSIT_DOMAIN, assetId, denomLE, inputTxidBE, voutLE, leafCommitment));
}

// Init message for POOL_INIT (SPEC §5.10.1).
function computePoolInitMsg(assetId, poolDenom, vkCid, ceremonyCid) {
  if (assetId.length !== 32) throw new Error('asset_id 32 bytes');
  const d = BigInt(poolDenom);
  const poolDenomLE = new Uint8Array(8);
  {
    const v = new DataView(poolDenomLE.buffer);
    v.setUint32(0, Number(d & 0xffffffffn), true);
    v.setUint32(4, Number((d >> 32n) & 0xffffffffn), true);
  }
  const vkBytes = (typeof vkCid === 'string') ? new TextEncoder().encode(vkCid) : vkCid;
  const ceBytes = (typeof ceremonyCid === 'string') ? new TextEncoder().encode(ceremonyCid) : ceremonyCid;
  return sha256(concatBytes(POOL_INIT_DOMAIN, assetId, poolDenomLE, vkBytes, ceBytes));
}

// ============== POOL STATE (in-memory, network-scoped) ==============
// Pool state is maintained by a canonical-order chain scan (`scanPools`)
// keyed off the active network. Three Maps:
//
//   poolRegistry:    poolKey -> { vkCid, ceremonyCid, initHeight, initTxid }
//   poolMerkleTrees: poolKey -> { leaves:      [...32-byte leaves...],
//                                 roots:       [...last 32 roots...],
//                                 rootHistory: Set<every canonical root hex> }
//   poolNullifiers:  poolKey -> Set<nullifier_hash_hex>
//
// `roots` is the broadcast-freshness window (last 32) a *new* withdraw proof
// must target so other indexers accept it. `rootHistory` is every prefix root
// the canonical leaf sequence has ever had — used to re-validate an *already-
// confirmed* withdraw UTXO held in the wallet, whose bound root may be far
// older than 32 deposits in an active pool (e.g. mainnet TAC). See
// mixerHasRecentRoot vs mixerHasHistoricalRoot.
//
// poolKey is `${assetIdHex}:${denominationDecString}` so cross-asset and
// cross-denomination pools stay isolated.
const poolRegistry    = new Map();
const poolMerkleTrees = new Map();
const poolNullifiers  = new Map();

// `gen` is the tETH generation segment ('' = the original keyspace, so the
// Bitcoin-side mixer pools and the pilot bridge generation are untouched;
// 'g1' = alpha). Mirrors the worker's gen-segmented pool keys.
function poolKey(assetIdHex, denomination, gen = '') {
  const base = `${assetIdHex}:${BigInt(denomination).toString()}`;
  return gen ? `${base}:${gen}` : base;
}

function mixerRegisterPool(assetIdHex, poolDenom, vkCid, ceremonyCid, initHeight, initTxid, gen = '') {
  const k = poolKey(assetIdHex, poolDenom, gen);
  // First-confirmed-wins (SPEC §5.10.1). Subsequent POOL_INITs for the same
  // (asset_id, denomination) are silently ignored.
  if (poolRegistry.has(k)) return false;
  poolRegistry.set(k, { vkCid, ceremonyCid, initHeight, initTxid });
  poolMerkleTrees.set(k, { leaves: [], roots: [], rootHistory: new Set() });
  // Nullifier registry tracks the canonical OWNER (withdraw txid) of each
  // claimed nullifier — not just "claimed by someone." Without owner
  // tracking, scanPools preloading worker-supplied nullifiers would cause
  // validateOutpoint to spuriously reject the user's own legitimate
  // withdraw (its nullifier "already spent" by the same canonical tx that
  // produced the UTXO being validated). The double-spend gate becomes
  // "claimed by someone OTHER than the tx we're validating," not "claimed
  // by anyone at all."
  poolNullifiers.set(k, new Map());
  return true;
}

function mixerIsPoolRegistered(assetIdHex, denomination, gen = '') {
  return poolRegistry.has(poolKey(assetIdHex, denomination, gen));
}

// Canonical-pool gate. A POOL_INIT can declare ANY vk_cid + ceremony_cid, and
// the first-confirmed-wins rule (SPEC §5.10.1) means anyone can front-run
// canonical pool creation for a popular (asset_id, denomination) with their
// own non-canonical setup. If a non-canonical pool is honored by the dapp's
// validator, an attacker who retained the MPC trapdoor of the fake setup
// can forge unlimited withdraw proofs against their own vk and inflate the
// asset_id's supply for the cost of a single real deposit (one real deposit
// is required to populate the pool's recent-roots window; after that, the
// trapdoor lets the attacker pick arbitrary nullifiers and root entries from
// the window indefinitely). Tacit has exactly one canonical Phase-1+Phase-2
// trusted setup (CANONICAL_VK_CID, CANONICAL_CEREMONY_CID); pools that
// declare anything else are out-of-protocol and the validator MUST refuse
// to credit their withdrawals. The UI also hides non-canonical pools from
// deposit selectors so honest users don't fund them by mistake.
function isPoolCanonical(info) {
  if (!info) return false;
  let vkStr, ceStr;
  try { vkStr = (info.vkCid instanceof Uint8Array) ? new TextDecoder().decode(info.vkCid) : String(info.vkCid || ''); }
  catch { return false; }
  try { ceStr = (info.ceremonyCid instanceof Uint8Array) ? new TextDecoder().decode(info.ceremonyCid) : String(info.ceremonyCid || ''); }
  catch { return false; }
  return vkStr === CANONICAL_VK_CID && ceStr === CANONICAL_CEREMONY_CID;
}

function mixerIsPoolCanonical(assetIdHex, denomination) {
  const info = poolRegistry.get(poolKey(assetIdHex, denomination));
  return isPoolCanonical(info);
}

// Append a leaf to the per-pool tree and roll the recent-roots cache.
// Caller MUST invoke this in canonical chain order (block height, then
// (tx_index, vin[1].outpoint) within block).
// Recent-roots ring buffer depth. SPEC §5.11. Withdraw proofs may bind any
// root in this window — a deposit landing between proof-build and broadcast
// would otherwise invalidate every in-flight proof. 32 covers ~5 hours of
// Bitcoin block time at typical 10-min cadence and is well past any realistic
// deep-reorg risk on either signet or mainnet (deepest historical mainnet
// reorg: 4 blocks; signet is permissioned so reorgs are operator-bounded).
// Tornado Cash uses ~30 for the same reason. If the pool is rapidly active
// and proofs frequently land against expired roots, raise this; if memory
// pressure is the constraint, lower it. Each root is 32 bytes so 32 roots is
// ~1KB per pool — non-issue on the scale of millions of pools.
const POOL_RECENT_ROOTS_WINDOW = 32;
function mixerAppendLeaf(assetIdHex, denomination, leafCommitment, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const tree = poolMerkleTrees.get(k);
  if (!tree) return false;
  if (tree.leaves.length >= (1 << POOL_TREE_DEPTH)) return false; // pool full
  tree.leaves.push(leafCommitment);
  const newRoot = computePoolRoot(tree.leaves);
  tree.roots.push(newRoot);
  if (tree.roots.length > POOL_RECENT_ROOTS_WINDOW) tree.roots.shift();
  // Append-only full history (reuses newRoot — no extra hashing). The recent-
  // roots ring buffer above evicts after 32 deposits, which is correct for
  // gating fresh broadcasts but wrong for re-validating a confirmed withdraw
  // UTXO whose bound root is older than that. One ~64-char hex string per
  // deposit; bounded by the pool's leaf count (≤ 2^POOL_TREE_DEPTH), so even a
  // very active pool stays in the hundreds-of-KB range.
  if (!tree.rootHistory) tree.rootHistory = new Set();
  tree.rootHistory.add(bytesToHex(newRoot));
  return true;
}

// Broadcast-freshness window: is `root` among the last 32 canonical roots?
// A *new* withdraw proof must target one of these so other indexers (whose
// windows are also ~32 deep) accept it on broadcast. NOT the right gate for
// re-validating a confirmed UTXO already in the wallet — use
// mixerHasHistoricalRoot for that.
function mixerHasRecentRoot(assetIdHex, denomination, root, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const tree = poolMerkleTrees.get(k);
  if (!tree) return false;
  for (const r of tree.roots) {
    if (r.length !== root.length) continue;
    let eq = true;
    for (let i = 0; i < r.length; i++) if (r[i] !== root[i]) { eq = false; break; }
    if (eq) return true;
  }
  return false;
}

// Was `root` EVER a canonical root of this pool? An already-confirmed
// T_WITHDRAW UTXO held in the wallet bound its proof to the root at proof-gen
// time; in an active pool (mainnet TAC) that root is evicted from the 32-deep
// recent window after 32 more deposits, but the withdraw is still valid
// forever. Membership here is over the full append-only prefix-root history,
// so holdings re-validation survives reload / cold restore / for-other
// receipt regardless of how far the pool has advanced since. Soundness is
// unchanged: rootHistory is populated only from computePoolRoot over the
// canonically-ordered, kernel-re-verified leaf sequence scanPools mirrors,
// and double-spend is gated separately by the nullifier set.
function mixerHasHistoricalRoot(assetIdHex, denomination, root, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const tree = poolMerkleTrees.get(k);
  if (!tree || !tree.rootHistory) return false;
  return tree.rootHistory.has(bytesToHex(root));
}

function mixerIsNullifierSpent(assetIdHex, denomination, nullifierHash, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const m = poolNullifiers.get(k);
  if (!m) return false;
  return m.has(bytesToHex(nullifierHash));
}

// Owner-aware double-spend gate. Returns true iff the nullifier has been
// claimed by a canonical withdraw OTHER than `ourTxidHex`. Used by
// validateOutpoint(T_WITHDRAW.txid, 0) so the canonical owner can re-
// validate their own UTXO against a Set/Map that already records their
// claim — without it, scanPools' worker-mirroring step would cause
// legitimate self-withdraws to disappear from the user's balance after
// a Mixer-tab visit. SPEC §5.11.4 invariant 3 — Non-double-spend.
function mixerIsNullifierSpentByOther(assetIdHex, denomination, nullifierHash, ourTxidHex, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const m = poolNullifiers.get(k);
  if (!m) return false;
  const owner = m.get(bytesToHex(nullifierHash));
  if (owner === undefined) return false;
  return owner.toLowerCase() !== String(ourTxidHex || '').toLowerCase();
}

// Record canonical ownership of a nullifier. First-write-wins: if the
// nullifier is already in the map, the existing owner is preserved. This
// matches the chain-canonical rule (only the first canonical T_WITHDRAW
// for a given nullifier is the "owner"; subsequent attempts are double-
// spends). `ownerTxidHex` may be omitted for legacy callers — they get
// the empty string, which still fails the "by-other" check against any
// real txid.
function mixerMarkNullifierSpent(assetIdHex, denomination, nullifierHash, ownerTxidHex = '', gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  let m = poolNullifiers.get(k);
  if (!m) { m = new Map(); poolNullifiers.set(k, m); }
  const key = bytesToHex(nullifierHash);
  if (!m.has(key)) m.set(key, String(ownerTxidHex || '').toLowerCase());
}

// Read the recorded canonical owner (withdraw txid) of a nullifier, or null
// if the nullifier is not in the spent-set. Used by the validator to re-verify
// a conflicting owner on chain before honoring it as a double-spend.
function mixerGetNullifierOwner(assetIdHex, denomination, nullifierHash, gen = '') {
  const m = poolNullifiers.get(poolKey(assetIdHex, denomination, gen));
  if (!m) return null;
  const owner = m.get(bytesToHex(nullifierHash));
  return owner === undefined ? null : owner;
}

// Overwrite the recorded owner of a nullifier (mixerMarkNullifierSpent is
// first-write-wins). The validator calls this ONLY after verifyWithdrawOwnerOnChain
// proved the prior owner is not a genuine on-chain spend — re-pointing to the
// real owner can't double-spend (the set stays keyed by nullifier_hash, one entry).
function mixerForceNullifierOwner(assetIdHex, denomination, nullifierHash, ownerTxidHex, gen = '') {
  const m = poolNullifiers.get(poolKey(assetIdHex, denomination, gen));
  if (!m) return;
  m.set(bytesToHex(nullifierHash), String(ownerTxidHex || '').toLowerCase());
}

function mixerGetPoolStats(assetIdHex, denomination, gen = '') {
  const k = poolKey(assetIdHex, denomination, gen);
  const tree = poolMerkleTrees.get(k);
  const m = poolNullifiers.get(k);
  if (!tree) return null;
  const totalLeaves = tree.leaves.length;
  const spentNullifiers = m ? m.size : 0;
  // Anonymity-set proxy: total deposits minus total withdrawals so far.
  // Real anonymity set is "leaves whose nullifiers haven't been published",
  // which is the same number absent operator-side leakage of (s, ν) pairs.
  const anonymitySet = totalLeaves - spentNullifiers;
  const latestRoot = tree.roots.length ? tree.roots[tree.roots.length - 1] : poolEmptyLeaf();
  return { totalLeaves, spentNullifiers, anonymitySet, latestRoot };
}

// Pool-reserve floor (SPEC §5.11.4 invariant 1, Conservation). Returns true if
// crediting a T_WITHDRAW that spends `nullifierHashHex` would push the pool's
// distinct spent-nullifier count above its leaf count — i.e. drive the reserve
// (# leaves − # spent) negative. One deposit appends one leaf and one withdraw
// burns one note, so on an honest pool this can only happen via a forged proof
// (a retained per-pool ceremony trapdoor); the validator refuses such a
// withdraw to bound a ceremony compromise to the pool's real deposits instead
// of unbounded minting. Two properties keep it from ever false-rejecting a live
// withdraw:
//   • The leaf bound takes the larger of the locally-applied tree and the
//     worker's authoritative included-leaf count (canonicalLeafCount). The
//     kernel-reverify apply loop in scanPools can stop early on a transient
//     fetch failure and resume next refresh, so the local tree may briefly lag
//     while the nullifier set (mirrored unconditionally) is complete; the
//     canonical count never under-counts the real included set across that gap.
//   • The projected count folds in our own nullifier idempotently — a nullifier
//     already in the spent-set (the pool's genuine final withdraw, mirrored by
//     scanPools) does not re-increment, so re-validating it still passes while a
//     brand-new nullifier past the reserve is rejected.
function mixerReserveWouldBreach(assetIdHex, denomination, nullifierHashHex) {
  const k = poolKey(assetIdHex, denomination);
  const tree = poolMerkleTrees.get(k);
  const spent = poolNullifiers.get(k);
  const leafBound = Math.max(
    tree ? tree.leaves.length : 0,
    tree && Number.isInteger(tree.canonicalLeafCount) ? tree.canonicalLeafCount : 0,
  );
  const nullKey = String(nullifierHashHex || '').toLowerCase();
  const alreadyCounted = spent ? spent.has(nullKey) : false;
  const projectedSpent = (spent ? spent.size : 0) + (alreadyCounted ? 0 : 1);
  return projectedSpent > leafBound;
}

// ============== GROTH16 VERIFY ==============
// SPEC §5.11. Real Groth16 verification under the per-pool verifying key
// (vk) declared at POOL_INIT time. Three pieces:
//
//   1. Lazy-load snarkjs from vendor/tacit-mixer.min.js. Separate bundle so
//      users who never touch the Mixer tab don't pay snarkjs's ~440 KB cost.
//      Cached after first load.
//   2. Fetch the vk from IPFS using `vkCid` from the pool registry. Cached
//      per-CID across calls. Content-addressed → no integrity check needed.
//   3. Parse the 256-byte proof bytes into snarkjs's expected JSON object,
//      format public inputs as decimal strings, call snarkjs.groth16.verify.
//
// Wire-format proof layout (256 bytes total): for Groth16 over BN254,
//   pi_a (G1):  x(32) || y(32)
//   pi_b (G2):  x[0](32) || x[1](32) || y[0](32) || y[1](32)
//   pi_c (G1):  x(32) || y(32)
// All field elements are 32-byte big-endian. Snarkjs's verifier accepts
// affine coordinates with z=1 implicit (G1) or z=[1,0] (G2); we add those
// in when reconstructing the JSON object.

let _mixerSnarkjs = null;
const _mixerVkCache = new Map(); // vkCid → Promise<vk_json>

async function _loadSnarkjs() {
  if (_mixerSnarkjs) return _mixerSnarkjs;
  // Dynamic import → esbuild-emitted ESM module sits at this path. Vite/
  // serve-static treat it as a regular asset; no special bundler config
  // needed at the dApp layer.
  _mixerSnarkjs = (await import('./vendor/tacit-mixer.min.js')).snarkjs;
  return _mixerSnarkjs;
}

async function _fetchMixerVk(vkCid) {
  if (!vkCid) return null;
  if (vkCid === CANONICAL_VK_CID) return _CANONICAL_VK_INLINE;
  if (_mixerVkCache.has(vkCid)) return _mixerVkCache.get(vkCid);
  const _vkGateways = [
    IPFS_GATEWAY,
    'https://content.wrappr.wtf/ipfs/',
    'https://ipfs.filebase.io/ipfs/',
    'https://ipfs.io/ipfs/',
    'https://dweb.link/ipfs/',
    'https://gateway.pinata.cloud/ipfs/',
    'https://w3s.link/ipfs/',
  ];
  const promise = (async () => {
    for (const gw of _vkGateways) {
      try {
        const url = `${gw}${vkCid}`;
        const resp = await fetch(url, { cache: 'force-cache' });
        if (!resp.ok) continue;
        const raw = new Uint8Array(await resp.arrayBuffer());
        if (await _ipfsCidMatches(vkCid, raw)) {
          return JSON.parse(new TextDecoder().decode(raw));
        }
      } catch { continue; }
    }
    if (vkCid === CANONICAL_VK_CID) return _CANONICAL_VK_INLINE;
    throw new Error(`vk fetch failed: all IPFS gateways returned invalid content for ${vkCid}`);
  })();
  _mixerVkCache.set(vkCid, promise);
  // If the fetch fails (or content-hash check rejects), drop the entry so a
  // future call retries rather than wedging on a permanent failure cache.
  promise.catch(() => _mixerVkCache.delete(vkCid));
  return promise;
}

// Verify that `bytes` hash to the multihash embedded in the given CID.
// Returns true on match, false on mismatch OR on unsupported codec/hash so
// the caller can decide its policy. We support CIDv0 (Qm... base58,
// dag-pb, sha256) and CIDv1 raw/dag-pb with sha256 — covers >99% of files
// pinned by Pinata / web3.storage / Filecoin in practice. Other multihashes
// return false rather than throwing so the caller gets a clear "couldn't
// verify" signal.
async function _ipfsCidMatches(cid, bytes) {
  try {
    if (typeof cid !== 'string' || cid.length === 0) return false;
    // CIDv0: base58-encoded multihash starting with "Qm" (sha256, 32 bytes
    // of digest, prefix 0x12 0x20). 46 chars total.
    if (cid.startsWith('Qm') && cid.length === 46) {
      const digest = sha256(bytes);
      // Construct the expected CIDv0 from the digest and string-compare.
      const mh = new Uint8Array(34);
      mh[0] = 0x12; mh[1] = 0x20;
      mh.set(digest, 2);
      const expected = base58.encode(mh);
      return expected === cid;
    }
    // CIDv1: base32 lower-case, starts with "b". For the common shapes
    // (raw or dag-pb, sha256 hash) we can re-encode and compare. Anything
    // else (CIDv1 with non-sha256 multihash) returns false.
    if (cid.startsWith('b') && cid.length > 32) {
      let raw;
      try { raw = base32.decode(cid.slice(1).toUpperCase()); } catch { return false; }
      // Layout: version(varint=1) + codec(varint) + multihash(varint=hash_code, varint=length, digest)
      // Common: codec 0x55 (raw) or 0x70 (dag-pb), hash 0x12 (sha256), len 0x20 (32).
      if (raw.length < 4 || raw[0] !== 0x01) return false;
      const codec = raw[1];
      if (codec !== 0x55 && codec !== 0x70) return false;
      if (raw[2] !== 0x12 || raw[3] !== 0x20 || raw.length !== 36) return false;
      const expectedDigest = raw.slice(4);
      const actualDigest = sha256(bytes);
      for (let i = 0; i < 32; i++) if (expectedDigest[i] !== actualDigest[i]) return false;
      return true;
    }
    return false;
  } catch (e) {
    if (typeof console !== 'undefined') console.warn('[mixer] vk CID verification failed', e);
    return false;
  }
}

// Convert one 32-byte big-endian field element to a decimal string —
// snarkjs's verify expects G1/G2 coords as base-10 BigInt strings.
function _be32ToDecimal(bytes) {
  let v = 0n;
  for (let i = 0; i < 32; i++) v = (v << 8n) | BigInt(bytes[i]);
  return v.toString();
}

// Public inputs are passed in as a mix of hex strings (32-byte fields) and
// decimal strings (denomination). snarkjs wants ALL decimal. Normalize.
function _publicInputsToDecimal(inputs) {
  return inputs.map(s => {
    if (typeof s !== 'string') s = String(s);
    if (s.startsWith('0x')) return BigInt(s).toString();
    // hex strings without 0x prefix vs decimal: hex when even-length and
    // contains hex chars; otherwise decimal pass-through.
    if (/^[0-9a-fA-F]+$/.test(s) && s.length === 64) return BigInt('0x' + s).toString();
    return s;
  });
}

// Parse 256 raw bytes into a snarkjs-compatible Groth16 proof object.
function _parseGroth16Proof(proofBytes) {
  if (!(proofBytes instanceof Uint8Array) || proofBytes.length !== 256) return null;
  const slice = (off) => proofBytes.slice(off, off + 32);
  return {
    pi_a: [
      _be32ToDecimal(slice(0)),
      _be32ToDecimal(slice(32)),
      '1',
    ],
    pi_b: [
      [_be32ToDecimal(slice(64)),  _be32ToDecimal(slice(96))],
      [_be32ToDecimal(slice(128)), _be32ToDecimal(slice(160))],
      ['1', '0'],
    ],
    pi_c: [
      _be32ToDecimal(slice(192)),
      _be32ToDecimal(slice(224)),
      '1',
    ],
    protocol: 'groth16',
    curve: 'bn128',
  };
}

async function verifyMixerProof({ vkCid, publicInputs, proof }) {
  // Structural prechecks — fail fast before paying the lazy-load + fetch cost.
  if (!proof || proof.length !== 256) return false;
  if (!Array.isArray(publicInputs) || publicInputs.length !== 5) return false;
  if (!vkCid) return false;

  let snarkjs, vk, proofObj, decInputs;
  try {
    [snarkjs, vk] = await Promise.all([_loadSnarkjs(), _fetchMixerVk(vkCid)]);
  } catch (e) {
    // vk fetch or snarkjs load failure — return false (treat as unverified)
    // rather than throwing into the recursive validator, which would mark
    // the entire UTXO ancestry as invalid.
    if (typeof console !== 'undefined') console.warn('[mixer] verify load:', e.message || e);
    return false;
  }
  if (!vk || !snarkjs?.groth16?.verify) return false;

  proofObj = _parseGroth16Proof(proof);
  if (!proofObj) return false;
  decInputs = _publicInputsToDecimal(publicInputs);

  try {
    return await snarkjs.groth16.verify(vk, decInputs, proofObj);
  } catch (e) {
    if (typeof console !== 'undefined') console.warn('[mixer] verify:', e.message || e);
    return false;
  }
}

// ============== AMM GROTH16 VERIFY ==============
// Parallel to verifyMixerProof above but for the three AMM circuits. Activates
// when CANONICAL_AMM_VK_CID is pinned (post-ceremony). Before that, scanHoldings's
// AMM branches keep their pre-ceremony "always-valid + worker-public-amount-check"
// posture; once the constant flips, this verifier runs on every LP_ADD /
// LP_REMOVE / SWAP_BATCH envelope walked during ancestry validation.
//
// Wrapper shape (matches what /pin-amm-vk validates + accepts):
//   { schema: "tacit-amm-vk-wrapper-v1", lp_add: {...}, lp_remove: {...}, swap_batch: {...} }
//
// The wrapper is content-addressed (same _ipfsCidMatches check as mixer vk)
// so a gateway can't substitute a malicious bundle. Cached per-CID.
const _ammVkWrapperCache = new Map(); // vkCid → Promise<wrapper>
async function _fetchAmmVkWrapper(vkCid) {
  if (!vkCid) return null;
  if (vkCid === CANONICAL_AMM_VK_CID) return _CANONICAL_AMM_VK_INLINE;
  if (_ammVkWrapperCache.has(vkCid)) return _ammVkWrapperCache.get(vkCid);
  const promise = (async () => {
    const url = `${IPFS_GATEWAY}${vkCid}`;
    const resp = await fetch(url, { cache: 'force-cache' });
    if (!resp.ok) throw new Error(`amm vk fetch ${vkCid}: HTTP ${resp.status}`);
    const raw = new Uint8Array(await resp.arrayBuffer());
    if (!(await _ipfsCidMatches(vkCid, raw))) {
      throw new Error(`amm vk content does not match CID ${vkCid} — gateway substitution detected`);
    }
    const wrapper = JSON.parse(new TextDecoder().decode(raw));
    if (wrapper?.schema !== 'tacit-amm-vk-wrapper-v1') {
      throw new Error('amm vk wrapper missing schema "tacit-amm-vk-wrapper-v1"');
    }
    for (const k of ['lp_add', 'lp_remove', 'swap_batch']) {
      if (!wrapper[k] || wrapper[k].protocol !== 'groth16') {
        throw new Error(`amm vk wrapper missing or malformed "${k}"`);
      }
    }
    return wrapper;
  })();
  _ammVkWrapperCache.set(vkCid, promise);
  promise.catch(() => _ammVkWrapperCache.delete(vkCid));
  return promise;
}

// pool_id_fr = SHA256(pool_id_bytes) mod p_Fr (BN254 scalar field). The AMM
// circuits take pool_id_fr as a public input so a proof for one pool can't
// be replayed against another. Helper kept here so the verifier + the prover
// share the same byte-for-byte derivation.
function _ammPoolIdFr(poolIdBytes) {
  const bytes = poolIdBytes instanceof Uint8Array ? poolIdBytes : hexToBytes(poolIdBytes);
  if (bytes.length !== 32) throw new Error('pool_id must be 32 bytes');
  const digest = sha256(bytes);
  let v = 0n;
  for (let i = 0; i < 32; i++) v = (v << 8n) | BigInt(digest[i]);
  return v % ammBjjMod.P_FR;
}

// Unpack a 32-byte BJJ commitment (compressed `packPoint` form) into (u, v)
// coordinates. The circuits take packed u + v as separate public inputs;
// failing to unpack here means the on-chain commitment isn't a valid BJJ
// subgroup point and the verifier short-circuits to false.
function _ammBjjCoords(cBJJBytes) {
  const pt = ammBjjMod.unpackPoint(cBJJBytes);
  if (!pt) return null;
  return { u: pt[0], v: pt[1] };
}

async function verifyAmmProof({ circuitKey, vkCid, publicInputs, proof }) {
  if (!proof || proof.length !== 256) return false;
  if (!Array.isArray(publicInputs)) return false;
  if (!vkCid) return false;
  if (circuitKey !== 'lp_add' && circuitKey !== 'lp_remove' && circuitKey !== 'swap_batch') return false;
  let snarkjs, wrapper;
  try {
    [snarkjs, wrapper] = await Promise.all([_loadSnarkjs(), _fetchAmmVkWrapper(vkCid)]);
  } catch (e) {
    if (typeof console !== 'undefined') console.warn('[amm] verify load:', e.message || e);
    return false;
  }
  if (!wrapper?.[circuitKey] || !snarkjs?.groth16?.verify) return false;
  const proofObj = _parseGroth16Proof(proof);
  if (!proofObj) return false;
  const decInputs = _publicInputsToDecimal(publicInputs);
  try {
    return await snarkjs.groth16.verify(wrapper[circuitKey], decInputs, proofObj);
  } catch (e) {
    if (typeof console !== 'undefined') console.warn('[amm] verify:', e.message || e);
    return false;
  }
}

// AMM Groth16 prover wiring. Loads the per-circuit zkey on demand from
// IPFS (the canonical wrapper directory pins all three under predictable
// names — `amm_lp_add_final.zkey`, etc.); the wasm is bundled at the dapp
// build step (vendor/amm_lp_add.wasm / vendor/amm_lp_remove.wasm). Returns
// a 256-byte canonical Groth16 proof matching the envelope wire format.
// Falls back to a placeholder 256-byte buffer when CANONICAL_AMM_VK_CID is
// null (pre-ceremony — worker only enforces public-amount math, the proof
// field is structural-only). Caching: zkeys per-CID across calls.
const TACIT_AMM_LP_ADD_WASM_PATH    = './vendor/amm_lp_add.wasm';
const TACIT_AMM_LP_REMOVE_WASM_PATH = './vendor/amm_lp_remove.wasm';
const _ammZkeyCache = new Map(); // ipfsPath → Promise<Uint8Array>
async function _fetchAmmZkey(circuitKey) {
  if (!CANONICAL_AMM_VK_CID) return null;
  // The finalized AMM proving zkeys live at the ceremony chain HEAD (the
  // beacon-applied head_cid in GET /ceremony/<circuit_hash>), exactly like the
  // mixer's — NOT in the VK-only CANONICAL_AMM_CEREMONY_CID bundle, which holds
  // only the *_vk.json + ptau. Fetch from the head (its VK == CANONICAL_AMM_VK_CID
  // by construction); fall back to the bundle path only if the chain is
  // unreachable (and a coordinator later co-pins the zkey there).
  const circuitName = circuitKey === 'lp_add'     ? 'amm_lp_add'
                    : circuitKey === 'lp_remove'  ? 'amm_lp_remove'
                    : circuitKey === 'swap_batch' ? 'amm_swap_batch'
                    : null;
  if (!circuitName) return null;
  const entry = AMM_CEREMONY_CIRCUIT_HASHES.find(e => e.key === circuitName);
  if (!entry) return null;
  const cacheKey = `head:${entry.hash}`;
  if (_ammZkeyCache.has(cacheKey)) return _ammZkeyCache.get(cacheKey);
  const promise = (async () => {
    try {
      return await ceremonyFetchHeadZkeyBytes(entry.hash);
    } catch (headErr) {
      // Fallback: the legacy bundle-directory path (empty today, but harmless to try).
      const dirCid = CANONICAL_AMM_CEREMONY_CID;
      if (!dirCid) throw headErr;
      const fileName = `${circuitName}_final.zkey`;
      const resp = await fetch(`${IPFS_GATEWAY}${dirCid}/${fileName}`, { cache: 'force-cache' });
      if (!resp.ok) throw new Error(`amm zkey: ceremony head failed (${headErr.message}); bundle ${fileName} HTTP ${resp.status}`);
      const bytes = new Uint8Array(await resp.arrayBuffer());
      if (bytes.length < 1024 || bytes[0] !== 0x7a || bytes[1] !== 0x6b || bytes[2] !== 0x65 || bytes[3] !== 0x79) {
        throw new Error('amm zkey bundle fallback: bad/short content');
      }
      return bytes;
    }
  })();
  _ammZkeyCache.set(cacheKey, promise);
  promise.catch(() => _ammZkeyCache.delete(cacheKey));
  return promise;
}
// Sibling constant to CANONICAL_AMM_VK_CID for the bundle directory. Pin
// both together post-ceremony so the prover can find the zkeys.
const CANONICAL_AMM_CEREMONY_CID = 'bafybeiheww2ndia2gld4mu7x2h7iwzawv6likpmfpklm6x5kj3btaniuam';
// Provers key on ceremony finality, not the per-network AMM_DEPLOYMENTS
// switch: any envelope built once the vk is pinned must carry a real proof
// (a pre-activation POOL_INIT broadcast with a placeholder would fail
// validateOutpoint forever once that network's gate opens).
async function _ammProveLpAdd({ poolIdBytes, variant, shareAmount, shareCBJJBytes, rShareBJJ }) {
  if (!_isAmmCeremonyFinalized()) return new Uint8Array(256);
  const snarkjs = await _loadSnarkjs();
  const wasmResp = await fetch(TACIT_AMM_LP_ADD_WASM_PATH);
  if (!wasmResp.ok) throw new Error(`amm lp_add wasm fetch: HTTP ${wasmResp.status}`);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());
  const zkeyBytes = await _fetchAmmZkey('lp_add');
  if (!zkeyBytes) throw new Error('amm lp_add zkey not available');
  const coords = _ammBjjCoords(shareCBJJBytes);
  if (!coords) throw new Error('amm lp_add: shareCBJJ not on curve');
  const input = {
    pool_id_fr:     _ammPoolIdFr(poolIdBytes).toString(),
    variant:        String(variant | 0),
    share_amount:   BigInt(shareAmount).toString(),
    C_share_BJJ_u:  coords.u.toString(),
    C_share_BJJ_v:  coords.v.toString(),
    r_share_BJJ:    BigInt(rShareBJJ).toString(),
  };
  const { proof } = await snarkjs.groth16.fullProve(input, wasmBytes, zkeyBytes);
  return _serializeGroth16Proof(proof);
}
async function _ammProveLpRemove({ poolIdBytes, shareAmount, deltaA, deltaB, recvACBJJBytes, recvBCBJJBytes, rRecvABJJ, rRecvBBJJ }) {
  if (!_isAmmCeremonyFinalized()) return new Uint8Array(256);
  const snarkjs = await _loadSnarkjs();
  const wasmResp = await fetch(TACIT_AMM_LP_REMOVE_WASM_PATH);
  if (!wasmResp.ok) throw new Error(`amm lp_remove wasm fetch: HTTP ${wasmResp.status}`);
  const wasmBytes = new Uint8Array(await wasmResp.arrayBuffer());
  const zkeyBytes = await _fetchAmmZkey('lp_remove');
  if (!zkeyBytes) throw new Error('amm lp_remove zkey not available');
  const coordsA = _ammBjjCoords(recvACBJJBytes);
  const coordsB = _ammBjjCoords(recvBCBJJBytes);
  if (!coordsA || !coordsB) throw new Error('amm lp_remove: receipt BJJ commits not on curve');
  const input = {
    pool_id_fr:     _ammPoolIdFr(poolIdBytes).toString(),
    share_amount:   BigInt(shareAmount).toString(),
    delta_A:        BigInt(deltaA).toString(),
    delta_B:        BigInt(deltaB).toString(),
    recv_A_BJJ_u:   coordsA.u.toString(),
    recv_A_BJJ_v:   coordsA.v.toString(),
    recv_B_BJJ_u:   coordsB.u.toString(),
    recv_B_BJJ_v:   coordsB.v.toString(),
    r_recv_A_BJJ:   BigInt(rRecvABJJ).toString(),
    r_recv_B_BJJ:   BigInt(rRecvBBJJ).toString(),
  };
  const { proof } = await snarkjs.groth16.fullProve(input, wasmBytes, zkeyBytes);
  return _serializeGroth16Proof(proof);
}

// ============== WALLET FLOWS ==============
// Higher-level helpers a caller uses to generate the wire-level envelopes
// for the three mixer operations. Callers handle the actual Bitcoin tx
// construction (commit/reveal pattern) elsewhere — these just produce the
// envelope payload bytes, kernel sigs, and helper output for share-link UX.

// Generate a (secret, nullifier_preimage) pair for a mixer deposit. If a
// 36-byte `assetInputAnchor` is supplied (the asset input UTXO outpoint
// in txid_LE || vout_LE form, which the kernel sig binds to via
// kernel_msg), derive both via priv-anchored HMAC so the pair is
// reconstructible from priv + chain alone. Otherwise fall back to CSPRNG
// for unit tests / callers that don't have an anchor at hand.
//
// Pre-derivation: losing (secret, ν) meant losing the deposit (no chain-
// side recovery possible — it's a zk system). With deterministic
// derivation, a depositor's priv + the funding UTXO outpoint (visible in
// their outgoing-spend history) are sufficient to recover the withdrawal
// secrets. The slot wrapper (cBTC.zk) layers on top of this — its Phase 2
// recovery becomes load-bearing once the bare mixer flow also recovers.
function mixerGenerateDepositSecrets({ privkey = null, assetInputAnchor = null } = {}) {
  if (privkey && assetInputAnchor) {
    return {
      secret: _deriveMixerDepositSecret({ privkey, anchorOutpoint: assetInputAnchor }),
      nullifierPreimage: _deriveMixerDepositNullifierPreimage({ privkey, anchorOutpoint: assetInputAnchor }),
    };
  }
  // Back-compat fallback for callers that don't supply an anchor.
  const secret = new Uint8Array(32);
  const nullifierPreimage = new Uint8Array(32);
  crypto.getRandomValues(secret);
  crypto.getRandomValues(nullifierPreimage);
  return { secret, nullifierPreimage };
}

// Verify a T_DEPOSIT's kernel signature given only its txid and the on-chain
// envelope fields. Mirrors the worker's verifyMixerDepositKernel (worker/src/
// index.js) byte-for-byte. Used by scanPools as defense-in-depth before
// applying a worker-supplied leaf to the local merkle tree.
//
// SPEC §5.10 / §5.11.4 invariant 1 — Conservation. A leaf is only a real
// deposit if the BIP-340 sig over kernel_msg verifies under
// (C_in − denomination·H).x_only(), i.e., exactly `denomination` of asset
// value was consumed. Without this, a malicious depositor could publish a
// well-formed envelope with a chosen (secret, ν) and garbage kernel_sig,
// then withdraw their own leaf to steal pool value (free inflation).
//
// Returns true on verified, false on permanent rejection (malformed tx,
// asset_id/denom/leaf mismatch, sig invalid, claimed height disagrees with
// chain — leaf can never be valid), null on transient fetch failure
// (mempool.space hiccup — caller should retry on next refresh, not log a
// security warning). Caller treats non-true as "do not apply this leaf";
// the tri-state is purely so the caller can distinguish "cried wolf" from
// a real bogus leaf.
//
// `expectedHeight` (optional): if provided, the on-chain tx's confirmed
// block_height MUST match. This is the dapp's defense against a worker
// that lies about a leaf's canonical position — the canonical sort is
// (height, tx_index, txid), and if the height the worker reports doesn't
// match chain, every position derivation downstream is poisoned. Pass
// null/undefined to skip (back-compat with callers that don't carry the
// claimed height). The companion check on `tx_index` lives in
// verifyTxIndexInBlock below; together they pin all three components of
// the canonical sort key against L1.
const _bridgeProofCache = new Map();
async function _verifyBridgeDepositProof(leaf, aidHex, denom, getTx, gctx) {
  const _g = gctx || tethActiveCtx();
  const _gen = (_g && _g.gen) || '';
  const txid = leaf.deposit_txid;
  if (!txid) return null;
  const cacheKey = `${txid}:${leaf.leaf_commitment}`;
  if (_bridgeProofCache.has(cacheKey)) return _bridgeProofCache.get(cacheKey);
  let tx;
  try { tx = await getTx(txid); } catch { return null; }
  if (!tx?.vout) return null;
  // The T_BRIDGE_DEPOSIT envelope rides in the reveal input's Taproot
  // script-path witness (vin[0].witness[1]) — the same commit+reveal shape
  // every other tacit op uses. It can't live in an OP_RETURN: the 80-byte
  // standardness cap won't hold the 256-byte Groth16 proof. Decode the
  // witness script first; keep an OP_RETURN scan only as a legacy fallback.
  let envelope = null;
  try {
    const w = tx?.vin?.[0]?.witness;
    if (Array.isArray(w) && w.length >= 2 && typeof w[1] === 'string') {
      const env = decodeEnvelopeScript(hexToBytes(w[1]));
      if (env && env.opcode === T_BRIDGE_DEPOSIT) envelope = decodeTBridgeDepositPayload(env.payload);
    }
  } catch {}
  if (!envelope) {
    for (const o of tx.vout) {
      if (o.scriptpubkey_type !== 'op_return') continue;
      const sp = o.scriptpubkey;
      if (!sp || sp.length < 12) continue;
      let payloadHex;
      const push = sp.slice(2, 4);
      if (push === '4d') { const dl = parseInt(sp.slice(6, 8) + sp.slice(4, 6), 16); payloadHex = sp.slice(8, 8 + dl * 2); }
      else if (push === '4c') { const dl = parseInt(sp.slice(4, 6), 16); payloadHex = sp.slice(6, 6 + dl * 2); }
      else { const dl = parseInt(push, 16); payloadHex = sp.slice(4, 4 + dl * 2); }
      if (payloadHex && payloadHex.length >= 4 && parseInt(payloadHex.slice(0, 2), 16) === T_BRIDGE_DEPOSIT) {
        try { envelope = decodeTBridgeDepositPayload(hexToBytes(payloadHex)); } catch {}
        break;
      }
    }
  }
  if (!envelope || !envelope.proof || envelope.proof.length !== 256) {
    _bridgeProofCache.set(cacheKey, false);
    return false;
  }
  const denomBig = BigInt('0x' + bytesToHex(envelope.denomWei));
  const publicInputs = [
    bytesToHex(envelope.ethRoot),
    bytesToHex(envelope.nullifierHash),
    denomBig.toString(),
    bytesToHex(envelope.rLeaf),
    (bytes32ToBigint(envelope.bindHash) % BN254_FIELD_SIZE).toString(),
  ];
  const pool = poolRegistry.get(poolKey(aidHex, denom, _gen));
  const vkCid = pool ? new TextDecoder().decode(pool.vkCid) : null;
  if (!vkCid) { _bridgeProofCache.set(cacheKey, null); return null; }
  let ok;
  try { ok = await verifyMixerProof({ vkCid, publicInputs, proof: envelope.proof }); }
  catch { ok = null; }
  if (ok === false) { _bridgeProofCache.set(cacheKey, false); return false; }
  if (ok !== true) return null; // transient verify failure (e.g. vk fetch) — retry next refresh, don't poison the cache

  if (_bridgeConfigured() && _g) {
    try {
      const denomWeiForPoolId = denomBig * BRIDGE_UNIT_SCALE;
      const poolId = bytesToHex(keccak_256(concatBytes(
        hexToBytes(_pad32(bytesToHex(TETH_BRIDGE.assetId))),
        hexToBytes(_pad32(denomWeiForPoolId.toString(16))),
      )));
      const ethRootHex = bytesToHex(envelope.ethRoot);
      const calldata = '0xe5f99a21' + _pad32(poolId) + _pad32(ethRootHex);
      const result = await _ethRpcCall('eth_call', [{ to: _g.address, data: calldata }, 'latest']);
      const rootKnown = result && result !== '0x' + '0'.repeat(64);
      if (!rootKnown) {
        _bridgeProofCache.set(cacheKey, false);
        return false;
      }
    } catch {
      // All Ethereum RPCs failed — don't reject, let SP1 handle it later
    }
  }

  _bridgeProofCache.set(cacheKey, true);
  return true;
}

// Re-verifier for bridge_rotate (0x62) and bridge_import (0x64) pool leaves,
// the counterpart to _verifyBridgeDepositProof for the two other leaf kinds
// the worker emits into a bridge pool tree. These envelopes ride in the Taproot
// reveal witness (like deposits) but are NOT the T_DEPOSIT Mimblewimble-kernel
// shape, so they must NOT go through verifyMixerDepositKernelOnChain. The local
// tree has to track the guest's leaf
// set exactly: rotate carries a Groth16 proof the guest re-verifies, so we
// re-verify it (mirroring deposit); import has no proof (the guest gates it on
// UTXO existence, which the client cannot replay), so we check only envelope
// well-formedness + the new commitment and rely on the SP1 guest as the
// arbiter. Tri-state like the sibling verifiers: true = apply, false =
// cryptographic reject, null = transient (caller retries next refresh).
async function _verifyBridgeRotateImportLeaf(leaf, aidHex, denom, getTx, kind, gctx) {
  const _gen = (gctx && gctx.gen) || '';
  const txid = leaf.deposit_txid;
  if (!txid) return null;
  let tx;
  try { tx = await getTx(txid); } catch { return null; }
  if (!tx) return null;
  const opcode = kind === 'bridge_rotate' ? T_BRIDGE_ROTATE : T_BRIDGE_IMPORT;
  // Like deposits, rotate (0x62) and import (0x64) ride their envelope in the
  // reveal input's Taproot script-path witness (vin[0].witness[1]) — both
  // exceed the 80-byte OP_RETURN cap (rotate ~484B carries a Groth16 proof).
  // Decode the witness first; keep an OP_RETURN scan only as a legacy fallback.
  let payload = null;
  try {
    const w = tx?.vin?.[0]?.witness;
    if (Array.isArray(w) && w.length >= 2 && typeof w[1] === 'string') {
      const env = decodeEnvelopeScript(hexToBytes(w[1]));
      if (env && env.opcode === opcode) payload = env.payload;
    }
  } catch {}
  if (!payload && Array.isArray(tx.vout)) {
    for (const o of tx.vout) {
      if (o.scriptpubkey_type !== 'op_return') continue;
      const sp = o.scriptpubkey;
      if (!sp || sp.length < 12) continue;
      let payloadHex;
      const push = sp.slice(2, 4);
      if (push === '4d') { const dl = parseInt(sp.slice(6, 8) + sp.slice(4, 6), 16); payloadHex = sp.slice(8, 8 + dl * 2); }
      else if (push === '4c') { const dl = parseInt(sp.slice(4, 6), 16); payloadHex = sp.slice(6, 6 + dl * 2); }
      else { const dl = parseInt(push, 16); payloadHex = sp.slice(4, 4 + dl * 2); }
      if (payloadHex && payloadHex.length >= 4 && parseInt(payloadHex.slice(0, 2), 16) === opcode) {
        payload = hexToBytes(payloadHex);
        break;
      }
    }
  }
  if (!payload) return false;
  // Shared header: [0]=opcode [1]=networkTag [2..34]=assetId [34..66]=denom (8-decimal tacit units).
  const networkTag = currentNetworkName() === 'signet' ? 0x01 : 0x00;
  if (payload[1] !== networkTag) return false;
  if (bytesToHex(payload.slice(2, 34)) !== aidHex.toLowerCase()) return false;
  if (BigInt('0x' + bytesToHex(payload.slice(34, 66))) !== BigInt(denom)) return false;
  const leafHex = String(leaf.leaf_commitment || '').toLowerCase();

  if (kind === 'bridge_import') {
    // import layout: [66..98]=newCommitment [98..130]=bindHash [130..162]=prevTxid [162..164]=prevVout.
    if (payload.length < 164) return false;
    return bytesToHex(payload.slice(66, 98)) === leafHex;
  }

  // rotate layout: [66..98]=poolRoot [98..130]=nullifier [130..162]=newCommitment
  //                [162..194]=rLeaf [194..226]=bindHash [226..228]=proofLen [228..]=proof.
  if (payload.length < 484) return false;
  if (bytesToHex(payload.slice(130, 162)) !== leafHex) return false;
  const proofLen = payload[226] | (payload[227] << 8);
  if (proofLen !== 256 || payload.length < 228 + proofLen) return false;
  const proof = payload.slice(228, 228 + proofLen);
  const publicInputs = [
    bytesToHex(payload.slice(66, 98)),
    bytesToHex(payload.slice(98, 130)),
    BigInt(denom).toString(),
    bytesToHex(payload.slice(162, 194)),
    (BigInt('0x' + bytesToHex(payload.slice(194, 226))) % BN254_FIELD_SIZE).toString(),
  ];
  const pool = poolRegistry.get(poolKey(aidHex, denom, _gen));
  const vkCid = pool ? new TextDecoder().decode(pool.vkCid) : null;
  if (!vkCid) return null;
  let ok;
  try { ok = await verifyMixerProof({ vkCid, publicInputs, proof }); }
  catch { return null; }
  return ok === true ? true : (ok === false ? false : null);
}

async function verifyMixerDepositKernelOnChain(depositTxidHex, expectedAssetIdHex, expectedDenom, leafCommitmentBytes, fetchTx, expectedHeight) {
  if (typeof fetchTx !== 'function') return false;
  const tx = await fetchTx(depositTxidHex);
  // getTx returns null on network error and on missing txs; we can't tell
  // them apart, so treat both as transient. A genuinely-missing deposit tx
  // would be a worker bug (it just told us this leaf is included).
  if (!tx) return null;
  if (Number.isInteger(expectedHeight)) {
    // mempool.space sets status.block_height only on confirmed txs. A
    // worker emitting `deposited_at_height` for an unconfirmed tx is a
    // bug or an attack; either way we refuse the leaf.
    if (!tx.status || tx.status.confirmed !== true) return false;
    if (Number(tx.status.block_height) !== Number(expectedHeight)) return false;
  }
  if (!Array.isArray(tx.vin) || tx.vin.length < 2) return false;
  const inp = tx.vin[1];
  if (!inp || typeof inp.txid !== 'string' || typeof inp.vout !== 'number') return false;
  // Decode envelope from the deposit tx itself to recover kernel_sig.
  const wit = tx.vin?.[0]?.witness;
  if (!Array.isArray(wit) || wit.length < 3) return false;
  let env;
  try { env = decodeEnvelopeScript(hexToBytes(wit[1])); } catch { return false; }
  if (!env || env.opcode !== T_DEPOSIT) return false;
  const dec = decodeTDepositPayload(env.payload);
  if (!dec || dec.kind !== 'deposit') return false;
  if (bytesToHex(dec.assetId) !== expectedAssetIdHex.toLowerCase()) return false;
  if (BigInt(dec.denomination) !== BigInt(expectedDenom)) return false;
  if (bytesToHex(dec.leafCommitment) !== bytesToHex(leafCommitmentBytes)) return false;
  // Walk vin[1] to recover C_in.
  const parent = await fetchTx(inp.txid);
  if (!parent) return null;
  const pwit = parent?.vin?.[0]?.witness;
  if (!Array.isArray(pwit) || pwit.length < 3) return false;
  let parentEnv;
  try { parentEnv = decodeEnvelopeScript(hexToBytes(pwit[1])); } catch { return false; }
  if (!parentEnv) return false;
  const pd = await getParentEnvelopeData(parentEnv, inp.vout, inp.txid);
  if (!pd || pd.assetIdHex !== expectedAssetIdHex.toLowerCase()) return false;
  let CinPoint;
  try { CinPoint = bytesToPoint(pd.commitment); } catch { return false; }
  const denomBig = BigInt(expectedDenom);
  const denomH = denomBig === 0n ? ZERO : safeMult(H, denomBig);
  const EPrime = CinPoint.add(denomH.negate());
  if (EPrime.equals(ZERO)) return false;
  const ExBytes = EPrime.toRawBytes(true).slice(1);
  const inputTxidBE = hexToBytes(inp.txid).reverse();
  const kernelMsg = computeDepositKernelMsg(
    dec.assetId, denomBig, inputTxidBE, inp.vout, dec.leafCommitment,
  );
  return verifySchnorr(dec.kernelSig, kernelMsg, ExBytes);
}

// Re-verify a nullifier's recorded owner (a worker-mirrored withdraw txid) is a
// still-confirmed on-chain T_WITHDRAW that genuinely spends this nullifier.
// Tri-state, parity with verifyMixerDepositKernelOnChain: true = genuine owner
// (block our re-claim); false = NOT a real matching on-chain withdraw (forged/
// stale owner-txid → our withdraw must not be bricked); null = transient/
// unfetchable → caller MUST fail closed. Groth16 is intentionally skipped: only
// the note-holder can produce a matching envelope for a nullifier, so a
// confirmed matching envelope is a genuine owner — and skipping it avoids
// conflating verifyMixerProof's infra-failure `false` with an invalid-proof one.
async function verifyWithdrawOwnerOnChain(ownerTxidHex, assetIdHex, denomination, nullifierHashBytes, fetchTx) {
  if (typeof fetchTx !== 'function') return null;
  // Empty / legacy / malformed owner string is not a real on-chain claim.
  if (!ownerTxidHex || !/^[0-9a-fA-F]{64}$/.test(ownerTxidHex)) return false;
  let tx;
  try { tx = await fetchTx(ownerTxidHex); } catch { return null; }
  if (!tx) {
    // Clean 404 (indexer says the tx never existed — reorged-out/forged owner)
    // → false (allow our withdraw). Transient 5xx/network (not 404-cached) →
    // null (fail closed). The negative cache is the only signal that separates
    // "gone" from "unreachable" off a single fetch.
    return _txIsRecentlyNotFound(String(ownerTxidHex).toLowerCase()) ? false : null;
  }
  if (!tx.status || tx.status.confirmed !== true) return null; // unconfirmed → transient → fail closed
  const wit = tx.vin?.[0]?.witness;
  if (!Array.isArray(wit) || wit.length < 3) return false;
  let env;
  try { env = decodeEnvelopeScript(hexToBytes(wit[1])); } catch { return false; }
  if (!env || env.opcode !== T_WITHDRAW) return false;
  // decodeTWithdrawPayload recomputes + checks bind_hash internally (null on mismatch).
  const dec = decodeTWithdrawPayload(env.payload);
  if (!dec) return false;
  if (bytesToHex(dec.assetId) !== assetIdHex.toLowerCase()) return false;
  if (BigInt(dec.denomination) !== BigInt(denomination)) return false;
  if (bytesToHex(dec.nullifierHash) !== bytesToHex(nullifierHashBytes)) return false;
  // External Pedersen opening must hold (recipient_commit == denom·H + r_leaf·G).
  try {
    const rLeafBig = bytes32ToBigint(dec.rLeaf) % SECP_N;
    if (!pedersenCommit(dec.denomination, rLeafBig).equals(bytesToPoint(dec.recipientCommitment))) return false;
  } catch { return false; }
  // The owner must belong to the canonical pool (a non-canonical pool's
  // withdraw is never creditable, so it cannot be a legitimate owner).
  if (!isPoolCanonical(poolRegistry.get(poolKey(assetIdHex, denomination)))) return false;
  return true;
}

// Conflict resolver for the T_WITHDRAW double-spend gate. Returns true if the
// nullifier is genuinely claimed by some OTHER on-chain withdraw (so our claim
// must be rejected), false if there is no genuine conflicting on-chain owner
// (so we may proceed and re-point ownership to ourselves). Fails CLOSED: any
// transient/unverifiable result keeps the gate strict (returns true), so a
// network blip can never relax double-spend protection.
async function mixerWithdrawConflictBlocks(assetIdHex, denomination, nullifierHash, ourTxidHex, fetchTx) {
  if (!mixerIsNullifierSpentByOther(assetIdHex, denomination, nullifierHash, ourTxidHex)) return false;
  const ownerTxid = mixerGetNullifierOwner(assetIdHex, denomination, nullifierHash);
  const ownerReal = await verifyWithdrawOwnerOnChain(ownerTxid, assetIdHex, denomination, nullifierHash, fetchTx);
  if (ownerReal !== false) return true;  // genuine owner (true) OR transient (null) → fail closed
  // The recorded owner is not a genuine matching on-chain withdraw (forged /
  // stale worker record). Re-point ownership to our confirmed withdraw so this
  // (and future) validations of our own UTXO are not bricked by it.
  mixerForceNullifierOwner(assetIdHex, denomination, nullifierHash, ourTxidHex);
  return false;
}

// Slot-leaf re-verifier — counterpart to verifyMixerDepositKernelOnChain
// for slot-derived pool leaves (SPEC-CBTC-ZK §5.21–§5.23 and FUNGIBILITY
// §5.24–§5.25). Each cBTC.zk pool leaf carries a `kind` of 'slot_mint',
// 'slot_rotate_new', 'slot_split_new', or 'slot_merge_new' instead of the
// T_DEPOSIT shape, so the Mimblewimble conservation check does not apply;
// instead we mirror the worker's slot-op gates: envelope decode, asset_id
// + denom + leaf_hash match, inner Schnorr signature, vout shape + value.
//
// Same tri-state contract as verifyMixerDepositKernelOnChain — true on
// full pass, false on cryptographic rejection (caller logs + breaks the
// apply-loop), null on transient fetch failure (caller silently retries).
async function verifySlotLeafOnChain(leafRec, expectedAssetIdHex, expectedDenom, leafCommitmentBytes, fetchTx, expectedHeight) {
  if (typeof fetchTx !== 'function') return false;
  if (!leafRec || typeof leafRec.deposit_txid !== 'string') return false;
  const tx = await fetchTx(leafRec.deposit_txid);
  if (!tx) return null;
  if (Number.isInteger(expectedHeight)) {
    if (!tx.status || tx.status.confirmed !== true) return false;
    if (Number(tx.status.block_height) !== Number(expectedHeight)) return false;
  }
  const wit = tx.vin?.[0]?.witness;
  if (!Array.isArray(wit) || wit.length < 3) return false;
  let env;
  try { env = decodeEnvelopeScript(hexToBytes(wit[1])); } catch { return false; }
  if (!env) return false;

  const aidLower = expectedAssetIdHex.toLowerCase();
  const lcHex = bytesToHex(leafCommitmentBytes).toLowerCase();
  const denomBig = BigInt(expectedDenom);
  const _xonlyFromPubkey = (pk33) => {
    try { return bytesToPoint(pk33).toRawBytes(true).slice(1); } catch { return null; }
  };

  if (leafRec.kind === 'slot_mint') {
    if (env.opcode !== T_SLOT_MINT) return false;
    const sm = decodeTSlotMintPayload(env.payload);
    if (!sm) return false;
    if (bytesToHex(sm.assetId).toLowerCase() !== aidLower) return false;
    if (sm.denomination !== denomBig) return false;
    if (bytesToHex(sm.leafHash).toLowerCase() !== lcHex) return false;
    const minterMsg = computeSlotMintMsg(
      sm.networkTag, sm.assetId, sm.denomination, sm.recipientCommit,
      sm.leafHash, sm.paymentAssetId, sm.paymentAmount, sm.kBtcXOnly,
    );
    const minterXOnly = _xonlyFromPubkey(sm.minterPubkey);
    if (!minterXOnly) return false;
    if (!verifySchnorr(sm.minterSig, minterMsg, minterXOnly)) return false;
    const expectedSpk = p2trScript(sm.kBtcXOnly);
    const vout0Spk = tx.vout?.[0]?.scriptpubkey;
    if (typeof vout0Spk !== 'string' || vout0Spk.toLowerCase() !== bytesToHex(expectedSpk)) return false;
    const vout0Val = tx.vout?.[0]?.value;
    if (typeof vout0Val !== 'number' || BigInt(vout0Val) !== denomBig) return false;
    return true;
  }

  if (leafRec.kind === 'slot_rotate_new') {
    if (env.opcode !== T_SLOT_ROTATE) return false;
    const sr = decodeTSlotRotatePayload(env.payload);
    if (!sr) return false;
    if (bytesToHex(sr.assetId).toLowerCase() !== aidLower) return false;
    if (sr.denomination !== denomBig) return false;
    if (bytesToHex(sr.newLeafHash).toLowerCase() !== lcHex) return false;
    const rotateMsg = computeSlotRotateMsg(
      sr.networkTag, sr.assetId, sr.denomination, sr.oldNullifierHash,
      sr.newRecipientCommit, sr.newLeafHash, sr.paymentAssetId, sr.paymentAmount, sr.newKBtcXOnly,
    );
    const ownerXOnly = _xonlyFromPubkey(sr.oldOwnerPubkey);
    if (!ownerXOnly) return false;
    if (!verifySchnorr(sr.oldOwnerSig, rotateMsg, ownerXOnly)) return false;
    const expectedSpk = p2trScript(sr.newKBtcXOnly);
    const vout0Spk = tx.vout?.[0]?.scriptpubkey;
    if (typeof vout0Spk !== 'string' || vout0Spk.toLowerCase() !== bytesToHex(expectedSpk)) return false;
    const vout0Val = tx.vout?.[0]?.value;
    if (typeof vout0Val !== 'number' || BigInt(vout0Val) !== denomBig) return false;
    return true;
  }

  if (leafRec.kind === 'slot_split_new') {
    if (env.opcode !== T_SLOT_SPLIT) return false;
    const ss = decodeTSlotSplitPayload(env.payload);
    if (!ss) return false;
    const idx = leafRec.split_vout_index;
    if (!Number.isInteger(idx) || idx < 0 || idx >= ss.outputs.length) return false;
    const out = ss.outputs[idx];
    if (bytesToHex(out.assetIdNew).toLowerCase() !== aidLower) return false;
    if (out.denomNew !== denomBig) return false;
    if (bytesToHex(out.newLeafHash).toLowerCase() !== lcHex) return false;
    const splitMsg = computeSlotSplitMsg(
      ss.networkTag, ss.assetIdOld, ss.denomOld, ss.oldNullifierHash,
      ss.outputs.map(o => ({
        assetIdNew: o.assetIdNew,
        denomNew: o.denomNew,
        newRecipientCommit: o.newRecipientCommit,
        newLeafHash: o.newLeafHash,
      })),
    );
    const ownerXOnly = _xonlyFromPubkey(ss.oldOwnerPubkey);
    if (!ownerXOnly) return false;
    if (!verifySchnorr(ss.oldOwnerSig, splitMsg, ownerXOnly)) return false;
    const voutI = tx.vout?.[idx];
    if (!voutI || typeof voutI.value !== 'number') return false;
    if (BigInt(voutI.value) !== denomBig) return false;
    const spkLower = (voutI.scriptpubkey || '').toLowerCase();
    if (spkLower.length !== 68 || !spkLower.startsWith('5120')) return false;
    return true;
  }

  if (leafRec.kind === 'slot_merge_new') {
    if (env.opcode !== T_SLOT_MERGE) return false;
    const smg = decodeTSlotMergePayload(env.payload);
    if (!smg) return false;
    if (bytesToHex(smg.assetIdNew).toLowerCase() !== aidLower) return false;
    if (smg.denomNew !== denomBig) return false;
    if (bytesToHex(smg.newLeafHash).toLowerCase() !== lcHex) return false;
    const mergeMsg = computeSlotMergeMsg(
      smg.networkTag,
      smg.inputs.map(inp => ({
        assetIdOld: inp.assetIdOld,
        denomOld: inp.denomOld,
        oldNullifierHash: inp.oldNullifierHash,
      })),
      smg.assetIdNew, smg.denomNew, smg.newRecipientCommit, smg.newLeafHash,
    );
    const ownerXOnly = _xonlyFromPubkey(smg.newOwnerPubkey);
    if (!ownerXOnly) return false;
    if (!verifySchnorr(smg.newOwnerSig, mergeMsg, ownerXOnly)) return false;
    const vout0 = tx.vout?.[0];
    if (!vout0 || typeof vout0.value !== 'number') return false;
    if (BigInt(vout0.value) !== denomBig) return false;
    const spkLower = (vout0.scriptpubkey || '').toLowerCase();
    if (spkLower.length !== 68 || !spkLower.startsWith('5120')) return false;
    return true;
  }

  return false;
}

// In-memory cache of (block_hash → ordered txid list). Block contents are
// immutable past confirmation depth so no invalidation is needed; the cache
// is per-session (no localStorage — a single block's txids array can be
// 100KB+, not worth burning quota across reloads). Multiple deposits in
// the same block share a fetch.
const _blockTxidsCache = new Map();
const _blockTxidsInFlight = new Map();

// Fetch the ordered list of txids in a block from the configured Esplora
// endpoint (mempool.space `/block/:hash/txids` returns a JSON array of
// txid hex strings in their canonical block-position order — vendored API
// contract: index in the array = tx_index in the block).
//
// Returns the array on success, or null on transient fetch failure (so the
// caller can distinguish "couldn't tell" from "definitely doesn't match" —
// same tri-state contract verifyMixerDepositKernelOnChain uses).
async function fetchBlockTxids(blockHash) {
  if (typeof blockHash !== 'string' || !/^[0-9a-f]{64}$/i.test(blockHash)) return null;
  const key = blockHash.toLowerCase();
  const cached = _blockTxidsCache.get(key);
  if (cached) return cached;
  const inflight = _blockTxidsInFlight.get(key);
  if (inflight) return inflight;
  const p = (async () => {
    try {
      const txids = await apiJson(`/block/${key}/txids`);
      if (!Array.isArray(txids)) return null;
      _blockTxidsCache.set(key, txids);
      return txids;
    } catch { return null; }
  })().finally(() => { _blockTxidsInFlight.delete(key); });
  _blockTxidsInFlight.set(key, p);
  return p;
}

// Verify that `depositTxidHex` is at position `claimedTxIndex` in the block
// identified by `blockHash`. This closes the residual canonical-position
// attack surface left open by verifyMixerDepositKernelOnChain's height
// pin: a worker that tells the truth about height could still lie about
// `tx_index`, swapping the order of two same-block deposits. The dapp
// would compute a merkle root no honest indexer's recent-roots window
// contains and broadcast a doomed T_WITHDRAW (DoS only — Conservation is
// already closed — but cheap to fix completely).
//
// Returns:
//   true  — txid is at claimedTxIndex in its block
//   false — definitely not at that index (worker lied or wrong block)
//   null  — couldn't fetch the block's txid list (transient; retry later)
async function verifyTxIndexInBlock(depositTxidHex, blockHash, claimedTxIndex, fetchTxids) {
  if (typeof depositTxidHex !== 'string' || !/^[0-9a-f]{64}$/i.test(depositTxidHex)) return false;
  if (!Number.isInteger(claimedTxIndex) || claimedTxIndex < 0) return false;
  const fetcher = typeof fetchTxids === 'function' ? fetchTxids : fetchBlockTxids;
  const txids = await fetcher(blockHash);
  if (!Array.isArray(txids)) return null;
  if (claimedTxIndex >= txids.length) return false;
  const got = txids[claimedTxIndex];
  if (typeof got !== 'string') return false;
  return got.toLowerCase() === depositTxidHex.toLowerCase();
}

// Build the deposit envelope payload + kernel sig, given a chosen UTXO and
// a fresh (secret, nullifier_preimage) pair.
//
// Inputs:
//   - assetId        Uint8Array(32)
//   - denomination   bigint | number | string (must equal input UTXO's amount)
//   - inputTxidBE    Uint8Array(32)
//   - inputVout      number
//   - inputBlinding  bigint  (the holder's r_in for that UTXO)
//   - holderPriv     Uint8Array(32)  (signs the kernel sig)
//   - secret, nullifierPreimage  Uint8Array(32) each
//
// Returns:
//   { payload, leafCommitment, nullifierHash, depositRecord }
// where depositRecord is the JSON the depositor must back up to be able to
// withdraw later (without it, the deposit is lost).
async function buildMixerDepositEnvelope({
  assetId, denomination, inputTxidBE, inputVout,
  inputBlinding, holderPriv, secret, nullifierPreimage,
}) {
  const leafCommitment = computePoolLeafCommitment(secret, nullifierPreimage, denomination);
  const nullifierHash = computeNullifierHash(nullifierPreimage);
  const kernelMsg = computeDepositKernelMsg(assetId, denomination, inputTxidBE, inputVout, leafCommitment);
  // Sign under the input's blinding scalar (equivalent excess for a single-input
  // single-output zero-net kernel: excess = 0 - (-r_in) = r_in). The verifier
  // checks the sig under (C_in - denom·H).x_only(), which equals r_in·G if
  // amounts balance. SPEC §5.10.
  const excessHex = inputBlinding.toString(16).padStart(64, '0');
  const excessBytes = hexToBytes(excessHex);
  const kernelSig = signSchnorr(kernelMsg, excessBytes);
  const payload = encodeTDepositPayload({ assetId, denomination, leafCommitment, kernelSig });
  return {
    payload,
    leafCommitment,
    nullifierHash,
    depositRecord: {
      assetIdHex: bytesToHex(assetId),
      denomination: BigInt(denomination).toString(),
      secretHex: bytesToHex(secret),
      nullifierPreimageHex: bytesToHex(nullifierPreimage),
      leafCommitmentHex: bytesToHex(leafCommitment),
      nullifierHashHex: bytesToHex(nullifierHash),
      depositedAt: Date.now(),
    },
  };
}

// Build the withdraw envelope payload, given the depositor's saved record
// + a Groth16 proof (generated externally — proof generation requires the
// circom witness, snarkjs prover, etc., produced by dapp/circuits/build.sh).
//
// SPEC §5.11. r_leaf is computed deterministically from the depositor's
// (secret, ν) pair, exposed as a public input to the circuit, and published
// in cleartext on chain. The validator's external Pedersen check closes the
// inflation-attack vector. No share-link is needed — the recipient (whoever
// owns vout[0]'s P2WPKH) reads (denomination, r_leaf) directly from chain.
//
// Inputs:
//   - depositRecord  the JSON object returned by buildMixerDepositEnvelope
//   - merkleRoot     Uint8Array(32) — must match a recent canonical root
//   - proof          Uint8Array — Groth16 proof from the prover
//
// Returns:
//   { payload, recipientCommitment, rLeaf }
async function buildMixerWithdrawEnvelope({
  depositRecord, merkleRoot, proof,
}) {
  const assetId = hexToBytes(depositRecord.assetIdHex);
  const denomination = BigInt(depositRecord.denomination);
  const nullifierHash = hexToBytes(depositRecord.nullifierHashHex);
  const secret = hexToBytes(depositRecord.secretHex);
  const nullifierPreimage = hexToBytes(depositRecord.nullifierPreimageHex);
  // r_leaf = poseidon2(secret, nullifier_preimage). Forced by the circuit;
  // re-computed here so the off-chain build matches the in-circuit witness.
  const rLeaf = poseidonHash(secret, nullifierPreimage);
  const rLeafBigint = bytes32ToBigint(rLeaf) % SECP_N;
  const recipientCommitment = pedersenCommit(denomination, rLeafBigint).toRawBytes(true);
  const bindHash = computeWithdrawBindHash(assetId, denomination, nullifierHash, recipientCommitment, rLeaf);
  const payload = encodeTWithdrawPayload({
    assetId, denomination, merkleRoot, nullifierHash,
    recipientCommitment, rLeaf, bindHash, proof,
  });
  return { payload, recipientCommitment, rLeaf };
}

// Build a POOL_INIT envelope payload + signature.
// Pool initialization is permissionless — any pubkey can sign. The signing
// key becomes the on-chain attribution for the init event but has no special
// privilege thereafter; pool consumers verify the IPFS-pinned vk + ceremony
// transcripts directly.
async function buildMixerPoolInitEnvelope({
  assetId, poolDenom, vkCid, ceremonyCid, initSignerPriv,
}) {
  const initMsg = computePoolInitMsg(assetId, poolDenom, vkCid, ceremonyCid);
  const initSig = signSchnorr(initMsg, initSignerPriv);
  const payload = encodeTPoolInitPayload({ assetId, poolDenom, vkCid, ceremonyCid, initSig });
  return { payload, initSig };
}

function parseMixerShareLink(hashFragment) {
  if (!hashFragment) return null;
  const m = hashFragment.match(/#mix=(.+)$/);
  if (!m) return null;
  const params = new URLSearchParams(m[1]);
  const assetIdHex = (params.get('a') || '').toLowerCase();
  const denomination = params.get('d') || '';
  const secretHex = (params.get('s') || '').toLowerCase();
  const nullifierPreimageHex = (params.get('n') || '').toLowerCase();
  // Reject malformed links so the caller's "could not parse share-link" alert
  // fires instead of hexToBytes(null) throwing an uncaught error.
  if (!/^[0-9a-f]{64}$/.test(assetIdHex)) return null;
  if (!/^\d+$/.test(denomination)) return null;
  if (!/^[0-9a-f]{64}$/.test(secretHex)) return null;
  if (!/^[0-9a-f]{64}$/.test(nullifierPreimageHex)) return null;
  return { assetIdHex, denomination, secretHex, nullifierPreimageHex };
}

// Inverse of parseMixerShareLink. Produces a `#mix=…` URL fragment carrying
// just the four fields the recipient needs to reconstruct a withdraw record
// (asset_id, denomination, secret, nullifier_preimage). The depositor sends
// this to a recipient out-of-band (Signal / Tor / paper); the recipient
// pastes it into the dapp's "Import share-link" field and withdraws to a
// fresh address. Keeping the format minimal (no commit/reveal txids, no
// timestamps) means a leaked link doesn't disclose anything the chain
// doesn't already publish.
function buildMixerShareLink(record, { absoluteUrl = false } = {}) {
  if (!record) return '';
  const params = new URLSearchParams();
  params.set('a', String(record.assetIdHex || '').toLowerCase());
  params.set('d', String(record.denomination || ''));
  params.set('s', String(record.secretHex || '').toLowerCase());
  params.set('n', String(record.nullifierPreimageHex || '').toLowerCase());
  const fragment = `#mix=${params.toString()}`;
  if (!absoluteUrl) return fragment;
  try {
    const base = `${location.origin}${location.pathname}`;
    return `${base}${fragment}`;
  } catch {
    return fragment;
  }
}

// Tornado-style compact note format: `tacit-{ticker}-{denom}-{network}-0x{hex}`
// where hex = secret(32B) || nullifier_preimage(32B). Asset is identified by
// (ticker, network) — the dapp's local registry resolves ticker → asset_id
// at parse time (with optional asset_id fallback embedded in the trailing
// hex if needed in future). Ticker case is normalized lowercase. Compact
// enough to tweet (~150 chars vs ~280 for the URL share-link).
//
// Tradeoff vs share-link: the compact note carries TICKER (human label)
// not asset_id (32-byte cryptographic identifier), so it relies on the
// recipient's wallet having the ticker registered. If the recipient is on
// the same network and has seen the asset's CETCH/PETCH, the resolver
// works. For unfamiliar assets, fall back to the share-link.
function buildMixerCompactNote(record) {
  if (!record) return '';
  const meta = getAssetMeta(String(record.assetIdHex || '').toLowerCase());
  // Without a known ticker we can't build a compact note; caller should
  // fall back to share-link in that case.
  if (!meta || !meta.ticker) return '';
  const ticker = String(meta.ticker).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!ticker) return '';
  const secret = String(record.secretHex || '').toLowerCase();
  const nu     = String(record.nullifierPreimageHex || '').toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(secret) || !/^[0-9a-f]{64}$/.test(nu)) return '';
  return `tacit-${ticker}-${record.denomination}-${NET.name}-0x${secret}${nu}`;
}

// Parse a compact note. Returns { assetIdHex, denomination, secretHex,
// nullifierPreimageHex } or null. Resolves ticker → asset_id via the
// local registry; if the recipient hasn't seen the asset's CETCH/PETCH,
// the resolver fails and the caller should ask them to import via
// share-link instead.
function parseMixerCompactNote(s) {
  if (typeof s !== 'string') return null;
  const m = s.trim().match(/^tacit-([a-z0-9]+)-(\d+)-([a-z]+)-0x([0-9a-fA-F]{128})$/i);
  if (!m) return null;
  const [, ticker, denom, network, hex] = m;
  // Network mismatch is a hard fail — the recipient is on a different
  // network than the depositor, the asset_id wouldn't exist locally.
  if (network.toLowerCase() !== NET.name) return null;
  // Resolve ticker → asset_id by scanning the local registry. Lower-case
  // compare for tolerance.
  const tickerLower = ticker.toLowerCase();
  let assetIdHex = null;
  try {
    const reg = JSON.parse(localStorage.getItem(regKey()) || '{}');
    for (const [aid, meta] of Object.entries(reg)) {
      if (String(meta?.ticker || '').toLowerCase().replace(/[^a-z0-9]/g, '') === tickerLower) {
        assetIdHex = aid;
        break;
      }
    }
  } catch {}
  if (!assetIdHex) return null;
  return {
    assetIdHex,
    denomination: denom,
    secretHex: hex.slice(0, 64).toLowerCase(),
    nullifierPreimageHex: hex.slice(64, 128).toLowerCase(),
  };
}

// ============== STORAGE ==============
// Both the asset-metadata registry and the per-UTXO opening cache are
// network-namespaced. asset_ids and txids can't collide cross-network
// (asset_id derives from a chain-specific txid), so this is a UX cleanup
// rather than a security boundary — but with per-network wallet keys, it
// keeps the dApp's view consistent: switching to mainnet doesn't surface
// stale signet entries.
//
// Crash-safe: a corrupt blob (manual edit, partial write, future schema
// bump) must not brick init(). Fall back to empty and log so the user can
// recover by re-scanning, rather than throwing during module load.
const REG_KEY_BASE  = 'tacit-registry-v1';
const OPEN_KEY_BASE = 'tacit-openings-v1';
function regKey()  { return `${REG_KEY_BASE}:${NET.name}`; }
function openKey() { return `${OPEN_KEY_BASE}:${NET.name}`; }
// In-memory write-through caches for the registry (asset_id → meta) and the
// openings (txid:vout → { amount, blinding, assetIdHex }). Without these,
// every getAssetMeta / getOpening call did a JSON.parse over localStorage;
// scanHoldings hits getAssetMeta ~7×/UTXO + getOpening once, so a 100-UTXO
// scan was paying ~700 redundant parses. The caches live on the JS module;
// a network flip (which changes the storage key) does location.reload() so
// stale state from one network can never be read against another's key.
let _registryCache = null;
let _openingsCache = null;

// Discover tab badge inputs. Both lists render in parallel (CETCH +
// public-mint), each one calling _bumpDiscoverBadge() once it knows its own
// count. The badge shows the sum. Tracked separately so a slow load on one
// side doesn't reset the other side's already-shown contribution.
let _lastDiscoverCetchCount = 0;
let _lastDiscoverPetchCount = 0;
// Memoized HTML from the last petch tile render. Compared byte-for-byte
// against the next render's computed tiles string to skip the innerHTML
// rewrite when nothing has changed since the prior 30s auto-poll —
// rewriting destroys event handlers, nukes click-state on the Mint
// buttons, and resets tile-flash animations for no visual gain.
let _lastPetchTilesHtml = null;
function _bumpDiscoverBadge() {
  if (typeof setTabBadge !== 'function') return;
  setTabBadge('discover', _lastDiscoverCetchCount + _lastDiscoverPetchCount);
}
const loadRegistry = () => {
  if (_registryCache) return _registryCache;
  try { _registryCache = JSON.parse(localStorage.getItem(regKey()) || '{}') || {}; }
  catch (e) { console.warn('registry parse failed; resetting to empty', e); _registryCache = {}; }
  return _registryCache;
};
const saveRegistry = r => {
  _registryCache = r;
  try { localStorage.setItem(regKey(), JSON.stringify(r)); } catch {}
};
function registerAsset(meta) {
  const r = loadRegistry();
  r[meta.assetIdHex] = { ...r[meta.assetIdHex], ...meta };
  saveRegistry(r);
}
function getAssetMeta(assetIdHex) {
  const r = loadRegistry();
  const explicit = r[assetIdHex] || null;
  if (explicit) return explicit;
  // Synthetic meta for AMM LP shares. The Pool tab populates
  // _lpAssetIdLookup whenever it fetches the worker pool list; this lets
  // the Holdings tab render LP UTXOs with a meaningful ticker (e.g.
  // "LP·<assetA-short>/<assetB-short>·30bps") instead of an opaque hex
  // asset_id. Without this, LP shares show up untickered after a
  // POOL_INIT / LP_ADD until the registry caches up.
  return _lpSyntheticMeta(assetIdHex);
}
// LP-share synthetic meta. Populated lazily by fetchAmmPools — every time
// the dapp fetches the worker pool list (Pool tab render, periodic refresh),
// we update this cache so the Holdings tab can render LP UTXOs with a
// meaningful ticker. Without this, an LP_ADD-minted share UTXO appears as
// an unknown asset_id in the Holdings view until the worker pool list is
// fetched (which only happens when the user opens the Pool tab).
let _lpAssetIdLookup = new Map();  // lp_asset_id_hex → { pool_id_hex, asset_a, asset_b, fee_bps }
function _lpAssetIdLookupRefresh(pools) {
  if (!Array.isArray(pools)) return;
  const next = new Map();
  for (const p of pools) {
    const aid = p?.lp_asset_id;
    if (typeof aid !== 'string' || !/^[0-9a-f]{64}$/i.test(aid)) continue;
    next.set(aid.toLowerCase(), {
      pool_id_hex: String(p.pool_id || ''),
      asset_a: String(p.asset_a || ''),
      asset_b: String(p.asset_b || ''),
      fee_bps: Number(p.fee_bps || 0),
    });
  }
  _lpAssetIdLookup = next;
}
// Reverse lookups against _lpAssetIdLookup keyed by pool_id_hex /
// canonical (asset_a, asset_b). Used by scanHoldings recovery for
// T_LP_ADD variant=0, T_LP_REMOVE, and T_SWAP_VAR — all three carry
// pool/asset references that resolve through the cached pool registry
// (refreshPoolsIfStale runs at scan start so the map is populated).
function _scanPoolEntryByPoolId(poolIdHex) {
  if (typeof poolIdHex !== 'string') return null;
  const needle = poolIdHex.toLowerCase();
  for (const entry of _lpAssetIdLookup.values()) {
    if (entry.pool_id_hex.toLowerCase() === needle) return entry;
  }
  return null;
}
function _scanLpAddPoolId(dec) {
  // Variant 1: feeBps + capabilityFlags + protocol-fee fields are in the envelope; derive directly.
  if (dec.variant === 1) {
    try {
      return ammAssetMod.derivePoolId(dec.assetA, dec.assetB, dec.feeBps, dec.poolCapabilityFlags, dec.protocolFeeAddress, dec.protocolFeeBps);
    } catch { return null; }
  }
  // Variant 0: pool registry lookup by canonical (assetA, assetB). Returns
  // the first matching pool's id; if multiple fee tiers exist for the same
  // pair, the recovery loop tries each candidate.
  const candidates = _scanLpAddPoolIdCandidates(dec);
  return candidates[0] || null;
}
function _scanLpAddPoolIdCandidates(dec) {
  if (dec.variant === 1) {
    try { return [ammAssetMod.derivePoolId(dec.assetA, dec.assetB, dec.feeBps, dec.poolCapabilityFlags, dec.protocolFeeAddress, dec.protocolFeeBps)]; }
    catch { return []; }
  }
  const out = [];
  const aHex = bytesToHex(dec.assetA);
  const bHex = bytesToHex(dec.assetB);
  for (const entry of _lpAssetIdLookup.values()) {
    if (entry.asset_a.toLowerCase() === aHex && entry.asset_b.toLowerCase() === bHex) {
      try { out.push(hexToBytes(entry.pool_id_hex)); } catch {}
    }
  }
  return out;
}
function _scanLpRemovePoolIdCandidates(dec) {
  const out = [];
  const aHex = bytesToHex(dec.assetA);
  const bHex = bytesToHex(dec.assetB);
  for (const entry of _lpAssetIdLookup.values()) {
    if (entry.asset_a.toLowerCase() === aHex && entry.asset_b.toLowerCase() === bHex) {
      try { out.push(hexToBytes(entry.pool_id_hex)); } catch {}
    }
  }
  return out;
}
function _lpSyntheticMeta(assetIdHex) {
  if (typeof assetIdHex !== 'string' || !/^[0-9a-f]{64}$/i.test(assetIdHex)) return null;
  const entry = _lpAssetIdLookup.get(assetIdHex.toLowerCase());
  if (!entry) return null;
  // Use short hex prefixes for the constituent assets. Resolving them all
  // the way to tickers would mean recursing through getAssetMeta, which
  // pulls the synchronous registry — fine for cBTC.tac variants (lookup
  // is O(1) against a fixed map) but would loop for LP-of-LP composite
  // pools. Short hex is fine for V1 display; can upgrade to recursive
  // resolution once nested pools land.
  const aHexShort = entry.asset_a.slice(0, 8);
  const bHexShort = entry.asset_b.slice(0, 8);
  // Try to resolve to real tickers — bail to hex if unresolvable.
  const aMetaTicker = (() => {
    if (entry.asset_a === assetIdHex) return aHexShort;  // self-ref guard
    try {
      const reg = loadRegistry();
      if (reg[entry.asset_a]?.ticker) return reg[entry.asset_a].ticker;
    } catch {}
    return aHexShort;
  })();
  const bMetaTicker = (() => {
    if (entry.asset_b === assetIdHex) return bHexShort;
    try {
      const reg = loadRegistry();
      if (reg[entry.asset_b]?.ticker) return reg[entry.asset_b].ticker;
    } catch {}
    return bHexShort;
  })();
  return {
    assetIdHex,
    ticker: `LP·${aMetaTicker}/${bMetaTicker}·${entry.fee_bps}bps`,
    name: `AMM LP shares for ${aMetaTicker}/${bMetaTicker} at ${entry.fee_bps} bps`,
    // LP shares are integer counts — decimals=0 is the most defensible
    // default since share value is a function of pool reserves at burn
    // time, not a fixed unit precision.
    decimals: 0,
    syntheticLpAsset: true,
    poolIdHex: entry.pool_id_hex,
    poolAssetA: entry.asset_a,
    poolAssetB: entry.asset_b,
    poolFeeBps: entry.fee_bps,
  };
}
// Per-UTXO openings: "txid:vout" -> { assetIdHex, amount: string, blinding: hex }
const loadOpenings = () => {
  if (_openingsCache) return _openingsCache;
  try { _openingsCache = JSON.parse(localStorage.getItem(openKey()) || '{}') || {}; }
  catch (e) { console.warn('openings parse failed; resetting to empty', e); _openingsCache = {}; }
  return _openingsCache;
};
// Persist the cache to localStorage. Used by both immediate-write paths
// (broadcast handlers calling recordOpening once) and the debounced flush
// path (scanHoldings discovering many openings in a tight loop).
function _writeOpeningsNow() {
  if (!_openingsCache) return;
  try { localStorage.setItem(openKey(), JSON.stringify(_openingsCache)); } catch {}
}
// Debounced flush: when a burst of recordOpening calls happens (e.g., a fresh
