  // specified circuit directly. Override is one-shot (cleared on use).
  let target;
  if (_ammContribForcedCircuit) {
    target = _ammContribForcedCircuit;
    _ammContribForcedCircuit = null;
  } else {
    target = pickShortestAmmCircuit();
  }
  if (contributorPubkeyHex) {
    try {
      const statusResp = await fetch(
        `${WORKER_BASE}/ceremony/${target.hash}/pubkey-status/${contributorPubkeyHex.toLowerCase()}`,
        { cache: 'no-store' },
      );
      if (statusResp.ok) {
        const sj = await statusResp.json();
        if (sj.contributed) {
          const others = AMM_CEREMONY_CIRCUIT_HASHES.filter(c => c.hash !== target.hash);
          const checks = await Promise.all(others.map(async (c) => {
            try {
              const r = await fetch(
                `${WORKER_BASE}/ceremony/${c.hash}/pubkey-status/${contributorPubkeyHex.toLowerCase()}`,
                { cache: 'no-store' },
              );
              if (r.ok) { const j = await r.json(); return { ...c, contributed: !!j.contributed }; }
            } catch {}
            return { ...c, contributed: false };
          }));
          const remaining = checks.filter(c => !c.contributed);
          if (remaining.length === 0) {
            resultEl.style.display = 'block';
            resultEl.style.color = 'var(--ink-mid)';
            resultEl.textContent = 'You\'ve already contributed to all three AMM circuits. Thank you!';
            return;
          }
          const next = remaining[0];
          resultEl.style.display = 'block';
          resultEl.style.color = 'var(--red)';
          resultEl.textContent =
            `This wallet already contributed to ${target.label} (slot #${sj.slot}). `
            + `Switching to ${next.label} — click CONTRIBUTE to start.`;
          _ammContribForcedCircuit = next;
          return;
        }
      }
    } catch {}
  }
  const origLabel = goBtn.textContent;
  goBtn.disabled = true;
  if (cancelBtn) cancelBtn.disabled = true;
  goBtn.textContent = 'Working…';
  progEl.style.display = 'block';
