    const reopen = () => {
      _ammMiniChipHide();
      try { openAmmCeremonyDrawer(); } catch (e) { console.warn('[amm-mini-chip] reopen failed', e?.message); }
    };
    miniChip.onclick = reopen;
    miniChip.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); reopen(); } };
