            if (mm) innerCid = mm[1];
            else if (/^Qm[1-9A-HJ-NP-Za-km-z]{44}$/.test(innerRaw)) innerCid = innerRaw;
            else if (/^baf[a-z0-9]{50,80}$/i.test(innerRaw)) innerCid = innerRaw;
