    if (!a?.asset_id) continue;
    const dec = Number.isInteger(a.decimals) && a.decimals >= 0 && a.decimals <= 8 ? a.decimals : 0;
    const ticker = a.ticker || 'token';
    // 0) Worker's canonical mark_price — present on responses from a
