  // computed from the synchronous _marketCache + _bidCachePeek data
  // available in this scope. Uses the same 0.2×/5× mark-band outlier
  // guard as the depth chart and _populateBidAskSpread so a dust ask
  // priced 0.5 sats doesn't anchor the divider's "best ask" reading.
  // Both ladders' inner row widths stay the same — this row spans
  // them like a CEX orderbook midline. When either side is unknown
  // (cold cache, no bids, etc.) the row collapses to just the side
  // that's present so the divider still functions as a visual
  // separator without lying about data we don't have.
  const _spreadRowHtml = (() => {
    const aidForSpread = _marketView.assetId;
    const decForSpread = Number.isInteger(_assetForBids?.decimals) ? _assetForBids.decimals : 0;
    const tickerForSpread = _assetForBids?.ticker || '?';
    const markUnit = Number(_assetForBids?.mark_price?.unit);
    const markValid = Number.isFinite(markUnit) && markUnit > 0;
    const bandLo = markValid ? markUnit * 0.2 : 0;
    const bandHi = markValid ? markUnit * 5 : Infinity;
    const nowSec = Math.floor(Date.now() / 1000);
    const expiryGuard = nowSec + 60;
    // Cheapest in-band preauth ask. Mirror of _populateBidAskSpread's
    // ask-side scan but reading from `rows` (the filtered set the user
    // sees) rather than the global cache — keeps the divider honest to
    // what the visible ladder claims.
    let cheapestAsk = null;
    let cheapestAskSats = null;
    let cheapestAskAmt = null;
    for (const l of rows) {
      if (l.kind !== 'preauth') continue;
      if (l.expired) continue;
      if (l._takenPending) continue;  // sold-pending; not a real best ask
      if (Number(l.expiry || 0) <= expiryGuard) continue;
      const amt = l.asset_opening?.amount;
      const ps = Number(l.min_price_sats || 0);
      const u = unitPriceSats(ps, BigInt(amt || 0), decForSpread);
      if (u == null || !(u > 0)) continue;
      if (markValid && (u < bandLo || u > bandHi)) continue;
      if (cheapestAsk == null || u < cheapestAsk) {
        cheapestAsk = u;
        cheapestAskSats = ps;
        cheapestAskAmt = amt;
      }
    }
    // Highest in-band fillable bid. Pulled from the sync bid cache so
    // this composes inline. Variable-fill bids whose remaining slipped
    // below min_fill are excluded — they're orphaned and unfillable
    // (matches the depth chart's logic).
    let highestBid = null;
    let highestBidSats = null;
    let highestBidAmt = null;
    const cachedBids = (typeof _bidCachePeek === 'function') ? _bidCachePeek(aidForSpread) : null;
    if (Array.isArray(cachedBids)) {
      for (const b of cachedBids) {
        if (b._isReserved) continue;
        if (Number(b.expiry || 0) <= nowSec) continue;
        const isVar = !!(b.min_fill_amount && b.min_fill_amount !== '0');
        if (isVar) {
          let rem = 0n, mf = 0n;
          try { rem = BigInt(b.remaining_amount || b.amount || '0'); } catch {}
          try { mf = BigInt(b.min_fill_amount || '0'); } catch {}
          if (rem < mf) continue;
        }
        const amtBig = (() => { try { return BigInt(b.amount || '0'); } catch { return 0n; } })();
        if (amtBig <= 0n) continue;
        const u = unitPriceSats(Number(b.price_sats || 0), amtBig, decForSpread);
        if (u == null || !(u > 0)) continue;
        if (markValid && (u < bandLo || u > bandHi)) continue;
        if (highestBid == null || u > highestBid) {
          highestBid = u;
          highestBidSats = Number(b.price_sats || 0);
          highestBidAmt = String(b.amount || '0');
        }
      }
    }
    // Skip the divider entirely when we have neither side — nothing
    // useful to anchor against. Single-side renders still show.
    if (highestBid == null && cheapestAsk == null) return '';
    const spreadAbs = (highestBid != null && cheapestAsk != null) ? (cheapestAsk - highestBid) : null;
    const midpoint = (highestBid != null && cheapestAsk != null) ? (cheapestAsk + highestBid) / 2 : null;
    const spreadPct = (spreadAbs != null && midpoint != null && midpoint > 0) ? (spreadAbs / midpoint) * 100 : null;
    const isCrossed = spreadAbs != null && spreadAbs < 0;
    // Color: amber for crossed (book anomaly), green for tight (< 1%
    // spread = fillable midpoint), neutral otherwise. Matches the
    // existing stats-strip spread colors so the two surfaces agree.
    const spreadColor = isCrossed ? '#c97a1a' : (spreadPct != null && spreadPct < 1 ? 'var(--green)' : 'var(--ink-mid)');
    // Both best-price chips are clickable — they prime the Swap tile
    // above with the matching side and the corresponding cap. Saves a
    // scroll + a click for the common "buy at this price / sell at this
    // price" intent. Wired in applyMarketFilters's post-render bind pass
    // by data-act="market-spread-prime".
    const bestBidHtml = highestBid != null
      ? `<button type="button" data-act="market-spread-prime" data-side="sell" data-cap-unit="${escapeHtml(String(highestBid))}" data-amt-base="${escapeHtml(String(highestBidAmt || '0'))}" data-aid="${escapeHtml(aidForSpread)}" title="Sell into the top bid (${fmtUnitPriceSats(highestBid)} sats/${escapeHtml(tickerForSpread)}). Clicking primes the Swap tile above in Sell mode with this price as the floor." style="background:none;border:none;padding:0;font:inherit;cursor:pointer;color:inherit;display:inline-flex;align-items:center;gap:4px;border-bottom:1px dotted var(--green);"><strong style="color:var(--green);">${fmtUnitPriceSats(highestBid)}</strong> <span class="muted" style="font-size:9px;">best bid ↑</span></button>`
      : `<span class="muted" style="font-size:10px;">no bids</span>`;
    const bestAskHtml = cheapestAsk != null
      ? `<button type="button" data-act="market-spread-prime" data-side="buy" data-cap-unit="${escapeHtml(String(cheapestAsk))}" data-amt-base="${escapeHtml(String(cheapestAskAmt || '0'))}" data-aid="${escapeHtml(aidForSpread)}" title="Buy the cheapest ask (${fmtUnitPriceSats(cheapestAsk)} sats/${escapeHtml(tickerForSpread)}). Clicking primes the Swap tile above in Buy mode with this price as the cap." style="background:none;border:none;padding:0;font:inherit;cursor:pointer;color:inherit;display:inline-flex;align-items:center;gap:4px;border-bottom:1px dotted var(--red);"><strong style="color:var(--red);">${fmtUnitPriceSats(cheapestAsk)}</strong> <span class="muted" style="font-size:9px;">best ask ↓</span></button>`
      : `<span class="muted" style="font-size:10px;">no asks</span>`;
    const spreadMidHtml = spreadAbs != null
      ? (isCrossed
          ? `<span style="color:${spreadColor};font-weight:700;letter-spacing:0.04em;" title="Best in-band bid exceeds best in-band ask — arbitrage opportunity (also shown on the depth chart).">CROSSED ${fmtUnitPriceSats(Math.abs(spreadAbs))}${spreadPct != null ? ` · ${Math.abs(spreadPct).toFixed(1)}%` : ''}</span>`
          : `<span style="color:${spreadColor};" title="Bid-ask spread in sats per ${escapeHtml(tickerForSpread)} (and as a percent of the midpoint). Tighter spread = the book agrees on price.">spread ${fmtUnitPriceSats(spreadAbs)}${spreadPct != null ? ` · ${spreadPct.toFixed(2)}%` : ''}</span>`)
      : `<span class="muted" style="font-size:10px;">spread —</span>`;
    // When the book is crossed, the worker's last-trade-based mark is
    // necessarily stale relative to live liquidity — the asks ladder's
    // "vs mark" column would invert (cheapest ask reads as a -57% dust
    // outlier when it's actually the real clearing price). Surface the
    // midpoint prominently in this case so the user has a usable
    // reference price; the asks/bids ladders below switch their "vs
    // mark" coloring to "vs mid" too (see _vsRefAsk in the per-tile
    // builder). Non-crossed books keep the standard "mark X" display.
    const markHtml = isCrossed && midpoint != null
      ? `<span style="font-size:10px;font-weight:700;color:#7a4d00;background:#fff3cf;padding:1px 6px;border:1px solid #c97a1a;" title="Book is crossed so the worker\'s last-trade mark (${fmtUnitPriceSats(markUnit)} sats/${escapeHtml(tickerForSpread)}) is stale. Midpoint = (best bid + best ask) / 2 — the realistic clearing price right now. The asks/bids ladders below recolor &quot;vs mark&quot; to &quot;vs mid&quot; while the book stays crossed.">mid ${fmtUnitPriceSats(midpoint)}</span>${markValid ? ` <span class="muted" style="font-size:9px;opacity:0.55;text-decoration:line-through;" title="Stale last-trade mark; book is crossed so this is no longer a useful reference.">mark ${fmtUnitPriceSats(markUnit)}</span>` : ''}`
      : (markValid
          ? `<span class="muted" style="font-size:10px;" title="Outlier-guarded reference price from recent trades (same value the price chart and depth chart anchor on).">mark ${fmtUnitPriceSats(markUnit)}</span>`
          : '');
    // Recent-trades sub-strip: last 5 prints inline at the spread, so the
    // "what just happened" question doesn't require a tab switch. Pulled
    // from asset.trades (full ring, has size + price) when available;
    // falls back to asset.price_summary (compact, price + ts only) on
    // cold caches. Each pill shows price → size (if known) → relative
    // age. Click any pill → Activity tab (delegated handler reads
    // data-act). Skipped when there's no trade data at all so the strip
    // collapses cleanly on never-traded assets.
    const _recentTrades = (() => {
      const full = Array.isArray(_assetForBids?.trades) ? _assetForBids.trades : null;
      if (full && full.length > 0) {
        return full.slice(0, 5).map(t => {
          const ps = Number(t.price_sats) || 0;
          const ts = Number(t.ts) || 0;
          let amtBig = 0n; try { amtBig = BigInt(t.amount || '0'); } catch {}
          if (ps <= 0 || ts <= 0 || amtBig <= 0n) return null;
          const u = unitPriceSats(ps, amtBig, decForSpread);
          return u != null ? { u, ts, amtBig, hasSize: true } : null;
        }).filter(Boolean);
      }
      const summary = Array.isArray(_assetForBids?.price_summary) ? _assetForBids.price_summary : [];
      if (summary.length === 0) return [];
      // price_summary is newest-first per worker (see /assets handler).
      return summary.slice(0, 5).map(p => ({
        u: Number(p?.u) || 0, ts: Number(p?.ts) || 0, amtBig: 0n, hasSize: false,
      })).filter(p => p.u > 0 && p.ts > 0);
    })();
    const _ageShort = (ts) => {
      const s = Math.max(0, nowSec - ts);
      if (s < 60)    return `${s}s`;
      if (s < 3600)  return `${Math.floor(s / 60)}m`;
      if (s < 86400) return `${Math.floor(s / 3600)}h`;
      return `${Math.floor(s / 86400)}d`;
    };
    const _recentTradesHtml = _recentTrades.length > 0
      ? `<div data-market-recent-trades style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding-top:8px;margin-top:8px;border-top:1px dashed var(--ink-faint);font-size:10px;">
           <span class="muted" style="font-size:9px;text-transform:uppercase;letter-spacing:0.06em;flex:0 0 auto;">Recent</span>
           ${_recentTrades.map(t => {
             // Color: green when the print is above mark (buyer paid up),
             // red when below (seller dumped). Matches the
             // vs-mark column convention on the ladders.
             const _diffCls = markValid
               ? (t.u >= markUnit ? 'var(--green)' : 'var(--red)')
               : 'var(--ink)';
             const _sizeStr = t.hasSize
               ? ` <span class="muted" style="font-size:9px;">· ${escapeHtml(fmtAssetAmountCompact(t.amtBig, decForSpread))}</span>`
               : '';
             return `<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 6px;background:var(--bg);border:1px solid var(--ink-faint);border-radius:2px;font-family:var(--mono);" title="${markValid ? (t.u >= markUnit ? 'Print above mark — buyer paid up' : 'Print below mark — seller discounted') : 'Recent trade'}. Click to jump to Activity tab."><strong style="color:${_diffCls};">${escapeHtml(fmtUnitPriceSats(t.u))}</strong>${_sizeStr}<span class="muted" style="font-size:9px;">· ${escapeHtml(_ageShort(t.ts))} ago</span></span>`;
           }).join('')}
           <button data-act="market-jump-activity" type="button" style="background:none;border:none;color:var(--ink-mid);padding:0 4px;font:inherit;text-decoration:underline;text-decoration-style:dotted;cursor:pointer;font-size:10px;" title="See the full trade history">all →</button>
         </div>`
      : '';
    return `<div data-market-spread-row class="market-spread-divider" style="display:block;padding:8px 0;margin:8px 0 4px;border-top:1px dashed var(--ink-faint);font-family:var(--mono);font-size:11px;">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          ${bestBidHtml}
          <span class="muted" style="font-size:10px;">↕</span>
          ${bestAskHtml}
        </div>
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end;">
          ${spreadMidHtml}
          ${markHtml}
        </div>
      </div>
      ${_recentTradesHtml}
    </div>`;
  })();
  // Classic CEX orderbook layout (Coinbase / Binance / Bybit vertical
  // mode): asks above, spread divider in the middle, bids below.
  // Reading top-to-bottom:
  //   asks (descending within page → most expensive of page 1 at the
  //         top of the asks panel, best ask = cheapest at the bottom
  //         of the panel adjacent to the spread divider)
  //   spread divider (explicit best-bid / best-ask / spread / mark)
  //   bids (descending → best bid at the top of the bids panel
  //         adjacent to the spread divider, lower bids fall away)
  //
  // Both best prices meet at the spread divider — the visual "pinch
  // point" both sides flow into. Asks-on-top also co-locates the
  // orderbook's take-side with the Swap tile above (which routes
  // through asks for the dominant buyer-intent flow), making the
  // page read as one continuous "buy stack": amount → route → spread
  // → demand context. Pagination still selects cheapest-first
  // (page 1 = the 12 most-relevant asks); the WITHIN-PAGE render
  // iteration reverses so best-ask lands adjacent to the spread.
  // Bids stay sorted descending in populateMarketBidsLadder so best
  // bid sits at the top of the bids panel.
  //
  // Your-open-orders panel stays at the very top so a maker managing
  // their own active orders sees them before either ladder.
  // Column-header row for the asks ladder. Only meaningful in rows-mode
  // (cards-mode tiles don't share a grid alignment with a header). Mirrors
  // the bids-side `market-bids-row-head` styling so both ladders read as
  // paired halves of the same two-sided book — same column count, same
  // black header background, same uppercase letter-spaced labels. Hidden
  // in cards-mode and when there are no asks to show.
  const _asksRefForHeader = _ladderReferenceUnit(_marketView?.assetId, _assetForBids);
  const _marketAsksRefLabel = (_asksRefForHeader?.label === 'mid') ? 'vs mid' : 'vs mark';
  const _asksHeaderRowHtml = (_marketLadderView === 'rows' && rowsForGrid.length > 0)
    ? `<div class="market-listing-grid market-listing-rows-mode market-listing-header-only">
         <div class="market-listing-tile market-listing-row-head" role="row" aria-hidden="true">
           <span>price ↑</span>
           <span style="text-align:right;">qty</span>
           <span>Total</span>
           <span style="text-align:right;" title="Percentage premium (red) or discount (green) versus the asset's mark price. When the book is crossed the column header reads &quot;vs mid&quot; — the midpoint of best bid / best ask is the honest clearing reference while mark (last-trade) is stale. YOU pill on your own asks.">${_marketAsksRefLabel}</span>
           <span>Expires</span>
           <span>${_marketRowActionsHidden ? '' : 'Action'}</span>
         </div>
       </div>`
    : '';
  // Mobile-only asks/bids tab toggle. Both ladders stacked on a phone
  // is ~2-3 viewport heights of scroll on intent-heavy markets like
  // TAC (26+ bid rows alone). A 2-tab switcher above the orderbook
  // halves the vertical real estate — desktop layout is untouched
  // since the tabs are hidden via @media (min-width: 521px).
  // data-orderbook-active flips the visibility of the asks vs bids
  // sub-sections; the spread row + your-orders panel stay visible on
  // both tabs (they're not inside either side wrapper).
  const _asksHidden = _asksHeaderRowHtml === ''
    ? rowsForGrid.length === 0
    : false;
  const _bidsTabCount = (() => {
    const peek = (typeof _bidCachePeek === 'function') ? _bidCachePeek(_marketView.assetId) : null;
    if (!Array.isArray(peek)) return null;
    const ns = Math.floor(Date.now() / 1000);
    return peek.filter(b => !b._isReserved && Number(b.expiry || 0) > ns).length;
  })();
  const _mobileOrderbookActive = _loadMarketOrderbookSide(_userHoldsAsset ? 'bids' : 'asks');
  const _mobileTabsHtml = `
    <div class="orderbook-mobile-tabs" role="tablist" aria-label="Orderbook side">
      <button role="tab" data-act="orderbook-mobile-tab" data-side="asks" aria-selected="${_mobileOrderbookActive === 'asks' ? 'true' : 'false'}">Buy from asks${rowsForGrid.length ? ` · ${rowsForGrid.length}` : ''}</button>
      <button role="tab" data-act="orderbook-mobile-tab" data-side="bids" aria-selected="${_mobileOrderbookActive === 'bids' ? 'true' : 'false'}">Sell into bids${_bidsTabCount != null ? ` · ${_bidsTabCount}` : ''}</button>
    </div>`;
  // Pager moved ABOVE the grid in the classic-CEX layout: with asks
  // rendered descending (worst at top, best ask at the bottom),
  // putting the pager below the grid would sit it between the best
  // ask and the spread divider — breaking the adjacency that's the
  // whole point of the flip. Above the grid, it reads as a toolbar
  // for the asks panel.
  const _asksPagerHtml = marketListingPagerHtml(totalAskRows, _marketListingPage, totalAskPages, askShowingStart, askShowingEnd);
  const _offerGalleryHtml = (() => {
    const dec = Number.isInteger(_assetForBids?.decimals) && _assetForBids.decimals >= 0 && _assetForBids.decimals <= 8 ? _assetForBids.decimals : 0;
    const ticker = _assetForBids?.ticker || 'token';
    const nowSec = Math.floor(Date.now() / 1000);
    const expiryGuard = nowSec + 60;
    const minePub = myPubHexForMarket;
    const seen = new Set();
    const offers = [];
    for (const l of rowsFull) {
      if (l.kind !== 'preauth' && l.kind !== 'intent') continue;
      if (l.expired || l._takenPending) continue;
      if (Number(l.expiry || 0) <= expiryGuard) continue;
      const ownerPub = l.kind === 'preauth' ? (l.seller_pubkey || '') : (l.maker_pubkey || '');
      if (minePub && ownerPub === minePub) continue;
      const amt = (() => { try { return BigInt(marketListingAmount(l) || '0'); } catch { return 0n; } })();
      const ps = Number(marketListingPriceSats(l) || 0);
      const unit = amt > 0n ? unitPriceSats(ps, amt, dec) : null;
      if (!(Number.isFinite(unit) && unit > 0 && ps > 0 && amt > 0n)) continue;
      const key = marketListingKey(l, _assetForBids);
      if (seen.has(key)) continue;
      seen.add(key);
      offers.push({ l, amt, ps, unit, key });
    }
    offers.sort((a, b) => {
      const ka = a.l.kind === 'preauth' ? 0 : 1;
      const kb = b.l.kind === 'preauth' ? 0 : 1;
      return ka - kb || a.unit - b.unit || (marketListingTimestamp(b.l) - marketListingTimestamp(a.l));
    });
    const top = offers.slice(0, 8);
    if (!top.length) return '';
    const hidden = offers.length - top.length;
    const instantCount = offers.filter(o => o.l.kind === 'preauth').length;
    const intentCount = offers.length - instantCount;
    const cards = top.map((o, idx) => {
      const l = o.l;
      const isPreauth = l.kind === 'preauth';
      const expRel = Number(l.expiry || 0) > nowSec ? relativeUntil(Number(l.expiry || 0)) : '';
      const amountText = fmtAssetAmountCompact(o.amt, dec);
      const id = marketListingDisplayId(l);
      const sid = l.sale_id || '';
      const iid = l.intent_id || '';
      const minTake = String(l.min_take_amount || '');
      const fillAttrs = isPreauth
        ? ` data-fill-aid="${escapeHtml(_marketView.assetId)}" data-fill-amount="${escapeHtml(o.amt.toString())}" data-fill-dec="${dec}" data-fill-ticker="${escapeHtml(ticker)}" data-fill-direction="buy" data-fill-unit="${escapeHtml(String(o.unit))}"`
        : '';
      const action = isPreauth
        ? `<button data-act="market-take-preauth" data-aid="${escapeHtml(_marketView.assetId)}" data-sid="${escapeHtml(sid)}" data-price="${o.ps}" data-ticker="${escapeHtml(ticker)}" data-amount="${escapeHtml(o.amt.toString())}" data-dec="${dec}" data-expiry="${Number(l.expiry || 0)}" type="button" title="Take this exact listing atomically on Bitcoin.">Take</button>`
        : `<button data-act="market-claim-intent" data-aid="${escapeHtml(_marketView.assetId)}" data-iid="${escapeHtml(iid)}" data-price="${o.ps}" data-ticker="${escapeHtml(ticker)}" data-amount="${escapeHtml(o.amt.toString())}" data-dec="${dec}" data-min-take="${escapeHtml(minTake)}" data-expiry="${Number(l.expiry || 0)}" type="button" title="Claim this atomic order, then wait for maker fulfilment before final take.">${minTake ? 'Buy...' : 'Claim'}</button>`;
      const kindText = isPreauth ? 'instant' : 'claim';
      const priceTitle = `${fmtUnitPriceSats(o.unit)} sats/${ticker} · total ${o.ps.toLocaleString('en-US')} sats · listing ${id}`;
      const note = isPreauth
        ? (idx === 0 ? 'best instant lot' : 'click row to load swap')
        : 'maker fulfil required';
      return `<div class="mkt-offer-card" data-offer-kind="${escapeHtml(l.kind)}"${fillAttrs} tabindex="0" role="button" title="${escapeHtml(isPreauth ? 'Click card to size the Swap tile, or Take listing to fill this exact lot.' : 'Atomic intent: click Claim order to reserve it.')}">
        <div class="mkt-offer-card-main">
          <span class="mkt-offer-size" title="${escapeHtml(fmtAssetAmount(o.amt, dec))} ${escapeHtml(ticker)}">${escapeHtml(amountText)} ${escapeHtml(ticker)}</span>
          <span class="mkt-offer-kind">${escapeHtml(kindText)}</span>
        </div>
        <div class="mkt-offer-price" title="${escapeHtml(priceTitle)}">${escapeHtml(fmtUnitPriceSats(o.unit))} sats/${escapeHtml(ticker)}</div>
        <div class="mkt-offer-meta">
          <span>${o.ps.toLocaleString('en-US')} sats total</span>
          <span>${expRel ? `in ${escapeHtml(expRel)}` : 'open'}</span>
        </div>
        <div class="mkt-offer-note">${escapeHtml(note)}</div>
        ${action}
      </div>`;
    }).join('');
    return `<section class="mkt-offer-gallery" data-mkt-offer-gallery>
      <div class="mkt-offer-gallery-head">
        <strong>Live offers</strong>
        <span>${instantCount.toLocaleString('en-US')} instant · ${intentCount.toLocaleString('en-US')} claimable${hidden > 0 ? ` · ${hidden.toLocaleString('en-US')} more below` : ''}</span>
      </div>
      <div class="mkt-offer-gallery-grid">${cards}</div>
    </section>`;
  })();
  // design.html-shaped unified market tile. Order: hero → swap → depth
  // (with spread strip inline) → two-col asks|bids → tape (with → all
  // trades link to modal) → tiny footer. Listed/Activity tabs are gone
  // from the DOM entirely (no marketAssetTabsHtml wrap). The detail
  // stats block (richStatsHtml) also drops out of default DOM —
  // disclosures for 24h high/low · supply · charts · alert can return
  // as a separate `▾ more details` toggle later if needed.
  //
  // Your-open-orders: rendered inside a closed <details> disclosure so
  // the panel is reachable but doesn't bloat default vertical. Returns
  // '' when user has no orders so the disclosure collapses entirely.
  const _yourOrdersDisclose = _yourOrdersHtml
    ? `<details class="mkt-your-orders-disclose" data-mkt-your-orders-disclose${_yourOrdersDiscloseOpenAttr()}><summary><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--green);vertical-align:middle;margin-right:5px;"></span>▾ your open orders</summary>${_yourOrdersHtml}</details>`
    : '';
  // Inline activity section — collapsed <details> below the orderbook/tape
  // so the table is reachable without a modal overlay. The tape's
  // `N trades today →` button expands this section and scrolls it into
  // view (see tape post-render binding). Wrap in a marked container so
  // we can target it from the tape handler regardless of nesting.
  const _activityDiscloseHtml = `<details class="mkt-activity-disclose" data-mkt-activity-disclose><summary>▾ activity &middot; <span class="muted" style="text-transform:none;letter-spacing:0;font-weight:400;">recent trades &amp; listings</span></summary>${activityPanelHtml}</details>`;
