  const _askRowPct = _askFillableAmts.map(a => _askMaxAmt > 0 ? Math.min(100, (a / _askMaxAmt) * 100) : 0);
  const _askFillableCount = _askFillableAmts.reduce((s, a) => s + (a > 0 ? 1 : 0), 0);
