  const _fillableBidCount = ladder.length;
  if (countEl) countEl.textContent = String(_fillableBidCount);
  if (mobileBidsTab) mobileBidsTab.textContent = `Sell into bids · ${_fillableBidCount}`;
  if (toggleBtn && list) toggleBtn.textContent = list.hidden ? `Show bids${_fillableBidCount ? ` (${_fillableBidCount})` : ''}` : 'Hide bids';
